local P = LoreForeverPacks.Begin("LoreForever_Voice_Female_MoreQuests1")
P.transportVersion = 1
P.transport = {}
P.transport["quest:1001"] = {
  hash = "7f8d04",
  fullHash = "7f8d04",
  text = "Buzzbox 411. Along Darkshore, Buzzbox 411 waits for thresher eyes to bring it back into service. Wizbang Cranktoggle, an eccentric and intoxicated gnome inventor, reaches it through a mechanical relay network. After you repair Buzzbox 827 farther south, Wizbang Cranktoggle's voice crackles through the transmitter again. Hidden from sight, the gnome inventor directs you north along Darkshore's beach to the damaged Buzzbox 411. His words break with hiccups and praise for crawler wine. He says local aquatic predators carry what his coastal apparatus needs to work. Thresher eyes must go into Buzzbox 411's hatch to restore the machine. Darkshore threshers prowl the shallows off Auberdine, and Wizbang says their eyes can recalibrate the device. Feed the eyes to the apparatus, and it jolts back to life. Then the line opens for another assignment, delivered in an even slurrier voice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1001-8b7c86629df5082a671e/1-0000.mp3", duration = 57.3126531, start = 0},
  },
}
P.transport["quest:1002"] = {
  hash = "69923c",
  fullHash = "69923c",
  text = "Buzzbox 323. Wizbang Cranktoggle’s fieldwork now reaches the third Buzzbox along Darkshore’s coast. You gather six Moonstalker fangs and feed them to the machine north of Auberdine. After you operate Buzzbox 411 farther south, Wizbang Cranktoggle’s voice crackles through the speaker. Drink has muddled his directions, but he points you north of Auberdine, to Buzzbox 323 near a road bridge. His research calls for six Moonstalker fangs from the fierce hunters roaming Darkshore’s forests. Before you begin, Buzzbox 323 chatters with static and faint muttering. Place the requested fangs in its intake hopper, and the machine rattles as it grinds the teeth to dust. Then Wizbang’s boozy voice returns through the transceiver, pleased with your delivery. He points you toward the next machine in his scattered network.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1002-9a74aad0d88b4c0a792d/1-0000.mp3", duration = 51.2522449, start = 0},
  },
}
P.transport["quest:1003"] = {
  hash = "138a80",
  fullHash = "138a80",
  text = "Buzzbox 525. Along Darkshore's coast, Wizbang Cranktoggle's scattered machines await the last of his strange requests. Buzzbox 525 calls for animal remnants and stranger materials. Once Buzzbox 323 is serviced, its rattling speakers carry Wizbang Cranktoggle's garbled instructions. His words slur through drunken chuckles and rambling directions. He sends his helpers far south along Darkshore's main road. There, he asks them to hunt grizzled thistle bears and place four thick scalps in Buzzbox 525's compartment. The machine is concealed behind a fence in the brush beside the road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1003-87c0852272ee7f97ce23/1-0000.mp3", duration = 37.6685714, start = 0},
  },
}
P.transport["quest:1008"] = {
  hash = "313940",
  fullHash = "313940",
  text = "The Zoram Strand. Naga now threaten Ashenvale at The Zoram Strand. Shindrell Swiftfire of Astranaar sends Alliance champions to scour the northwestern coast, where an ancient city lies in ruins. Stopping the naga guards the forest against a haunting echo of the night elves’ distant past. At Ashenvale’s northwestern edge, the Zoram Strand meets the Veiled Sea. The shore lies northwest of Astranaar, where forest canopy gives way to coast. For ages, the beach lay quiet, its stones left by a civilization shattered ten millennia ago. Now Wrathtail naga surge from the dark tides. They have made a hostile beachhead on night elven borders and threaten to press inland. The city of Zoram lies shattered beneath the surf, submerged during the Great Sundering. For ages, the kaldorei left it abandoned and nearly forgotten. Now the naga’s arrival among its ruins stirs bitter memories among Astranaar’s defenders. Sentinels such as Shindrell Swiftfire know the invaders as twisted cousins, born of their own ancient catastrophe. They will not let the depths claim the shore again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1008-b383b359104165983735/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["quest:102"] = {
  hash = "013d3a",
  fullHash = "013d3a",
  text = "Patrolling Westfall. Gnoll packs threaten the people still living on Westfall’s grasslands. From Sentinel Hill, Captain Danuvin calls on volunteers to hunt them, fearing they work with thieves in the Deadmines. Sentinel Hill is Westfall’s main defense, held by local volunteers instead of royal troops. With Stormwind sending no soldiers to protect the outer farmlands, the people formed the People’s Militia. Captain Danuvin once farmed in Westfall. Now he leads the militia and refuses to abandon his homeland.\n\nThe militia depends on travelers passing through to help hold its perimeter against dangers gathering across the plains. Gnolls threaten the refugees and squatters struggling to survive in Westfall. Danuvin’s scouts believe the packs work with bandits based in the Deadmines. So he sends hunters to collect gnoll paws. He hopes to curb the packs’ growing patrols and break any cooperation between the beasts and the outlaws.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_102-5c32ce4729d49b178cbd/1-0000.mp3", duration = 55.8236735, start = 0},
  },
}
P.transport["quest:103"] = {
  hash = "b516d8",
  fullHash = "b516d8",
  text = "Keeper of the Flame. At Westfall Lighthouse, Captain Grayson keeps watch over the coast. He seeks oil to keep the beacon burning after murlocs killed the living keepers, guiding ships safely past the reefs. Westfall Lighthouse stands on a rocky islet off Westfall’s southwest shore. Its light once guided sailors through the Great Sea’s shallow waters. That duty ended when Old Murk-Eye led a murloc attack and killed the keeper and his family. Captain Grayson died in the waters by these rocks and now watches over the tower as a ghost. He could not stop the slaughter in life, but he will not let the lighthouse go dark. No living keeper remains to tend the flame, so Captain Grayson needs an unusual fuel. Harvest Watchers roam Westfall’s abandoned farmlands, carrying flasks of machinery oil inside their rusted bodies. Grayson sends you ashore to recover the oil from these broken constructs. With it, the beacon can keep burning and guide captains past the reefs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_103-b94c30e2031a9439bd89/1-0000.mp3", duration = 61.44, start = 0},
  },
}
P.transport["quest:1061"] = {
  hash = "76a5ea",
  fullHash = "76a5ea",
  text = "The Spirits of Stonetalon. Unrest stirs among the spirits of Stonetalon, and Zor Lonetree sends Horde champions west to learn why. From Orgrimmar, you pass the Crossroads and report to Seereth Stonebreak near Greatwood Vale. In Grommash Hold, Zor Lonetree listens to the natural world and feels deep distress from the Stonetalon Mountains. The elemental spirits of its rocky peaks rage as logging cuts into their forests. Horde shamans hear their unrest and fear that the devastation in the western highlands will upset Kalimdor's spiritual balance. The Venture Company is an unscrupulous goblin syndicate cutting timber in Greatwood Vale. Its crews use aggressive machinery, saws, and muscle to butcher the ancient woodland instead of harvesting it sustainably. So the Horde sent Seereth Stonebreak, a young shaman, to watch the forest from the frontier and rally defenders against the ravagers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1061-3137d45cce579d9eceea/1-0000.mp3", duration = 54.9877551, start = 0},
  },
}
P.transport["quest:1062"] = {
  hash = "3f74fe",
  fullHash = "3f74fe",
  text = "Goblin Invaders. At the Barrens and Stonetalon border, Goblin Invaders strike at the mountains' ancient woodlands. Seereth Stonebreak sends the Horde against Venture Company loggers in Windshear Crag. Venture Company loggers cut deep into the Stonetalon Mountains. They strip the hillsides and burn the underbrush, leaving scorched ground behind. For tauren and their allies, the harm reaches beyond the forests. The primal spirits bound to Stonetalon howl in torment.\n\nSeereth Stonebreak watches from the mountain border. She sees the goblins' assault has left the spirits blind with agony and fury. Profit is all the Venture Company's executives and hirelings heed. Reason will not sway them. So Seereth sends you past Greatwood Vale and into Windshear Crag to kill fifteen loggers.\n\nThe Horde meets the company's greed with force. The blow is meant to halt the deforestation and give tauren elders time to soothe the land's agitated spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1062-33d661db0a70e531d6ba/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["quest:1063"] = {
  hash = "e9eb10",
  fullHash = "e9eb10",
  text = "The Elder Crone. Seereth Stonebreak sends word from Stonetalon to Thunder Bluff. Goblin deforestation and mining have enraged the mountain's elements, and Seereth seeks spiritual guidance from Magatha Grimtotem on Elder Rise. In Stonetalon Mountains, goblin deforestation and mining have enraged the elemental spirits. Seereth Stonebreak sees that force alone cannot ease the land's anguish. So Seereth turns to elder shamans for wisdom. Few tribal leaders are known to Seereth by name, but Magatha Grimtotem is known for her wisdom and commanding presence. Magatha Grimtotem holds court atop Elder Rise in Thunder Bluff, where shamanic and spiritual affairs gather. Her tribe's ties with Cairne Bloodhoof's leadership are tense and often confrontational. Even so, Magatha is a formidable elder whose counsel carries great weight across the Horde. You bring her Stonetalon's troubles and seek her guidance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1063-a36c81cadd28b378e7c8/1-0000.mp3", duration = 58.0440816, start = 0},
  },
}
P.transport["quest:1064"] = {
  hash = "adc4dd",
  fullHash = "adc4dd",
  text = "Forsaken Aid. In Thunder Bluff, Magatha Grimtotem seeks Forsaken Aid for the blighted spirits of Stonetalon. She turns to Apothecary Zamah in the Pools of Vision, hoping tauren and undead knowledge can help the suffering land. Magatha Grimtotem sees practical value in the Forsaken alliance. Word reaches Thunder Bluff of corrupted elemental spirits and suffering land in the Stonetalon Mountains, so she turns to the undead for help. She believes those who understand disease may help cure it. Rather than seek traditional druidic remedies, she sends you to the Royal Apothecary Society. Apothecary Zamah represents Undercity interests on Kalimdor from the Pools of Vision beneath Spirit Rise. Tauren shamans, priests, and seers use the cavern as a sacred retreat. Zamah's presence brings Forsaken work into their midst. Magatha sends a serpent messenger ahead of you to alert Zamah, opening a direct line to the Forsaken's alchemical researchers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1064-083f773ff97583db0077/1-0000.mp3", duration = 60.1861224, start = 0},
  },
}
P.transport["quest:1065"] = {
  hash = "874f6a",
  fullHash = "874f6a",
  text = "Journey to Tarren Mill. Apothecary Zamah seeks a way to drive the Venture Company from Stonetalon Mountains without open war. She sends you across the sea to Apothecary Lydon in Tarren Mill, where the Royal Apothecary Society works in Lordaeron. In Thunder Bluff, Apothecary Zamah links the Forsaken with the Earth Mother's children. The Venture Company cuts timber and mines the sacred lands of Stonetalon Mountains, and ordinary means have failed to stop them. So Zamah turns to her peers in the Royal Apothecary Society for a chemical deterrent. She hopes their alchemy can drive the company away without a drawn-out war. You cross the sea from Kalimdor by zeppelin toward Lordaeron and the Undercity. From Tirisfal Glades, the road runs south through Silverpine Forest and into the contested Hillsbrad Foothills. Tarren Mill lies near human farmsteads and ruins. Once a human hamlet, it is now a Forsaken stronghold where the Royal Apothecary Society carries out its research.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1065-a3c8f021a39a8d4b4ffb/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["quest:109"] = {
  hash = "7b2706",
  fullHash = "7b2706",
  text = "Report to Gryan Stoutmantle. At Sentinel Hill, Gryan Stoutmantle gathers Westfall's defenders against threats to the farms. Guards along the Elwynn border and farmers driven west both send capable travelers toward Sentinel Hill. Those who answer join a defense built from local volunteers. No royal battalions come to their aid. From the stone tower atop Sentinel Hill, Gryan Stoutmantle organizes farmers, retired veterans, and mercenaries into the People's Militia. You join their bitter guerrilla war to keep Westfall's farmlands from falling into lawlessness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_109-f4429b7e759a44b8e09b/1-0000.mp3", duration = 35.7355102, start = 0},
  },
}
P.transport["quest:1097"] = {
  hash = "7d4745",
  fullHash = "7d4745",
  text = "Elmore's Task. Smith Argus sends you from Goldshire to Stormwind, where Grimand Elmore awaits help with a delivery. The weaponsmith needs it carried to his kin in Khaz Modan, and Argus trusts you with the road ahead. Smith Argus watches for travelers he can trust with work beyond wolves and kobolds. Grimand Elmore has sent word from Stormwind and asks for help carrying a delivery to his kin in Khaz Modan. The city gates open the way to Elmore's call. Stormwind and Ironforge rely on open trade and goodwill to keep both realms supplied and united. Argus says Elwynn Forest needs defenders, yet promises to the dwarves matter too. In northeastern Stormwind, the Dwarven District leads you to Elmore's shop. There, a journey beyond the forest begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1097-f3d07eaa21d985082926/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["quest:1099"] = {
  hash = "0ddcef",
  fullHash = "0ddcef",
  text = "Goblins Win!. In Thousand Needles, the goblin race decides who wins a goblin prize box. Goblins Win! names the result for whoever holds the winning ticket. You hold the goblin race ticket while the goblins' side is decided. If they win, the ticket earns you a goblin prize box. The gnome ticket counts for the other side.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1099-6fabc6c74a0fe27aa414/1-0000.mp3", duration = 20.8718367, start = 0},
  },
}
P.transport["quest:11"] = {
  hash = "4350b7",
  fullHash = "4350b7",
  text = "Riverpaw Gnoll Bounty. In western Elwynn, Riverpaw Gnoll Bounty calls for help against gnolls pressing the border. Deputy Rainer offers a reward at Westbrook Garrison for painted armbands taken from Riverpaw packs in the woods and by the water. Westbrook Garrison guards Elwynn Forest's border with Westfall. Its depleted forces struggle to contain the growing Riverpaw presence. The gnolls camp south of the guard tower and farther east around Stone Cairn Lake. From those camps, they threaten travelers and nearby homesteads. Deputy Rainer cannot spare regular infantry to sweep the woods, so he offers a bounty on the raiders. He requires painted armbands from slain gnolls as proof of each kill. Wandering adventurers and recruits are hired to thin the pack before the Riverpaws overrun the western marches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_11-bc417b0bfb3cf46627db/1-0000.mp3", duration = 48.6922449, start = 0},
  },
}
P.transport["quest:111"] = {
  hash = "63bfce",
  fullHash = "63bfce",
  text = "Speak with Gramma. Tommy Joe Stonefield asks Gramma Stonefield for a way to reach Maybell Maclure. Their families keep them apart, and he hopes to meet her without drawing their kin into conflict. Tommy Joe and Maybell hide their love from their families. He turns to Gramma Stonefield, hoping she can find them a chance to meet in secret. Their kin must not discover the romance and turn old hostility into violence. Gramma Stonefield knows the families cannot truly unite while their bad blood remains. Still, she will not let that end the young couple's hopes. She begins seeking small chances to bring Tommy Joe and Maybell together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_111-c0a860eac6c0f4f398b6/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["quest:112"] = {
  hash = "324ad9",
  fullHash = "324ad9",
  text = "Collecting Kelp. In Goldshire, Maybell Maclure seeks to visit Tommy Joe Stonefield unseen. William Pestle needs rare crystal kelp to brew her an invisibility liquor. The feud between the Stonefield and Maclure families keeps Maybell Maclure and Tommy Joe Stonefield from meeting openly. Maybell wants to see the one she loves without bringing their kin into an armed clash. So she seeks a way to cross the valley unseen. William Pestle, an herbalist and apothecary at the Lion's Pride Inn in Goldshire, plans to brew an invisibility liquor, but its rare ingredients are not in the inn's cupboards. William Pestle needs crystal kelp as the catalyst for his brew. Its fronds usually grow far out in saltwater oceans, but tribal murlocs have carried stashes inland to their crude camps along Crystal Lake, just east of Goldshire. Their peculiar instincts draw them to haul the marine plants to the freshwater shore. You need to recover enough fronds from the murlocs before returning to Goldshire with them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_112-5fe5f2312faefec2950a/1-0000.mp3", duration = 61.7273469, start = 0},
  },
}
P.transport["quest:1138"] = {
  hash = "6cba9f",
  fullHash = "6cba9f",
  text = "Fruit of the Sea. Along Darkshore, Auberdine fisherman Gubber Blump asks you to gather crab meat. He keeps to the docks and dreams of dishes for his catch. Gubber Blump fishes from Auberdine's long wooden piers, thinking of crab meat. He calls crabs the ocean's true bounty and imagines them baked, barbecued, or boiled. His recipes include whipper root crab and Ironforge surprise crab. Gubber cannot leave his fishing rod, so he asks you to gather ingredients from Darkshore's beaches. Reef crawlers and encrusted tide crawlers move among the breakers, offering meat for a coastal cook. Mind their claws as you gather the fine crab chunks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1138-8029c389e7d81418a9f4/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["quest:114"] = {
  hash = "292bc5",
  fullHash = "292bc5",
  text = "The Escape. Maybell Maclure seeks a way to leave her family and meet Tommy Joe Stonefield. You bring her William Pestle's Invisibility Liquor, brewed with crystal kelp gathered across the region. The Maclures and Stonefields have feuded for generations, leaving no room for courtship. Gramma Stonefield asks William Pestle, an alchemist at the Lion's Pride Inn in Goldshire, for help. Crystal kelp from nearby lakes gives Pestle what he needs to brew Invisibility Liquor. The brew can hide Maybell's escape from the Maclure homestead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_114-5d91959917b01c318b8a/1-0000.mp3", duration = 33.0971429, start = 0},
  },
}
P.transport["quest:1141"] = {
  hash = "bc9447",
  fullHash = "bc9447",
  text = "The Family and the Fishing Pole. On Auberdine's docks, Gubber Blump waits with his heirloom Fishing Pole for a catch. Hostile murlocs keep the town's small fishing boats ashore, so he seeks help catching native Darkshore grouper from the coast. Gubber Blump takes pride in his family's skill with a fishing line. Night elves make up most of Auberdine, though dwarves and gnomes have settled around its docks and port. Gubber spends his days gazing over the Veiled Sea instead of digging into stone. He hopes to bring in the local catch. Darkshore grouper thrive along the coast and make versatile food. They put up a lively fight on the line. Local fishermen usually row small boats into deeper waters to catch them, but aggressive murlocs now prowl the coast. The boats stay ashore, and Gubber fears the creatures are eating the local fish. So he asks travelers to fish from shore. Gubber gives a Blump Family Fishing Pole to anyone who brings him a hearty catch. He believes that landing a batch of feisty groupers proves an angler worthy of his family's legendary fishers, including his cousin Graun Blump. For Gubber, handing over a family rod is the highest mark of respect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1141-4d806cd459535e27d804/1-0000.mp3", duration = 70.5828571, start = 0},
  },
}
P.transport["quest:116"] = {
  hash = "2969d4",
  fullHash = "2969d4",
  text = "Dry Times. Lakeshire's inn is running short of drink as Blackrock orcs keep the town under siege. The roads are unsafe, and the usual supplies have stopped coming. Blackrock orcs descend from Stonewatch Keep and press Lakeshire hard. With supply lines cut and roads unsafe, the inn is running low on drink. Barkeep Daniels turns to travelers who can cross the blocked roads and bring supplies back for frightened villagers and the town guards. Daniels needs drink from across Stormwind's lands. You can find Merlot in the capital and Sweet Rum at the Lion's Pride Inn in Goldshire. Moonshine comes from Darkshire in Duskwood, and Grimbooze Thunderbrew brews Thunderbrew Lager in the hills of Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_116-46d5a794acd20de41e36/1-0000.mp3", duration = 46.0277551, start = 0},
  },
}
P.transport["quest:117"] = {
  hash = "28267e",
  fullHash = "28267e",
  text = "Thunderbrew. In Westfall, Grimbooze Thunderbrew gathers fresh hops for his next batch. Without them, his ale may turn thick as stew, so he shares kegs with those who bring what he needs. Far from Dun Morogh, Grimbooze keeps his family's brewing tradition alive. He insists on proper hops for his current brew, or it may turn to thick stew instead of refreshing ale. Grimbooze praises hops, barley, yeast, and malt in cheerful rhymes. Fresh hops let him finish fermentation on the spot. In return, he shares whole kegs of Thunderbrew Lager, known for its forceful taste.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_117-1e7465aae4f248860909/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["quest:1174"] = {
  hash = "8f2b13",
  fullHash = "8f2b13",
  text = "Gnomes Win!. In Thousand Needles, the gnomes' victory decides which ticket pays out. The holder of the winning ticket gets a prize box. When the gnomes win, the holder of the Gnome Race Ticket gets the prize box. The goblin ticket counts for the other side of the race.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1174-43d564aa9cb9da0fd7dd/1-0000.mp3", duration = 16.9273469, start = 0},
  },
}
P.transport["quest:118"] = {
  hash = "4a804a",
  fullHash = "4a804a",
  text = "The Price of Shoes. Verner Osgood has no iron left in Lakeshire, and the guards need constant repairs. He sends you west through Elwynn Forest to ask Smith Argus in Goldshire for horseshoes. Lakeshire faces gnolls, orcs, and murlocs, while Stormwind sends little help. The garrison fights each day to keep the town standing, and battle wears down its gear. Verner Osgood spends nearly every waking hour repairing dented breastplates, reshaping dulled swords, and keeping the guards clad in iron. Now his raw materials are gone. Without iron, even ordinary work in a frontier town can stop. Horses without shoes cannot carry messengers swiftly or haul supplies along Redridge's rocky paths. Verner swallows his pride and sends you west along the Three Corners road to Goldshire. Smith Argus there has regular access to the kingdom's mineral stores.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_118-8f61e29810633d356419/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["quest:119"] = {
  hash = "ebf555",
  fullHash = "ebf555",
  text = "Return to Verner. Smith Argus has finished fifty horseshoes, and you carry them from Goldshire to Verner Osgood in Lakeshire. Redridge needs them for its hard-pressed mounts. You carry the crate east across the border into Redridge. There, supply shortages and gnoll attacks threaten the town. The fifty iron shoes keep horses and draft animals working on rugged mountain roads, which Redridge needs to face those dangers. Verner Osgood is relieved when the horseshoes arrive. Then he finds the bill Smith Argus attached to the crate. Verner is annoyed that the Goldshire smith expects payment. With dangers pressing around Redridge, there is little time to argue over the charge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_119-0f4f8bb92b065e7b3686/1-0000.mp3", duration = 41.0644898, start = 0},
  },
}
P.transport["quest:12"] = {
  hash = "da5a66",
  fullHash = "da5a66",
  text = "The People's Militia. At Sentinel Hill, Gryan Stoutmantle puts the People's Militia to the test against outlaws in Westfall's northern fields and mines. Local volunteers defend the region from the Defias Brotherhood while Stormwind's throne is distracted and its army absent. Gryan Stoutmantle founded the People's Militia, and he does not take just anyone. Anyone seeking its badge must prove they can fight and protect innocent settlers. He calls for decisive action to reclaim Westfall from the outlaws, vagrants, and thieves overrunning the region. Before Gryan Stoutmantle trusts new recruits with deeper operations, he sends them against Defias forces near the northern homesteads. Defias Trappers and Smugglers work openly near Jangolode Mine, Molsen Farm, and Furlbrow's Pumpkin Patch. They pillage stores and ambush travelers. Driving them out disrupts their foraging and shows Stoutmantle's scouts you have the grit for a long fight against crime.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_12-98fa9c6ba538e93b8f2b/1-0000.mp3", duration = 59.7420408, start = 0},
  },
}
P.transport["quest:120"] = {
  hash = "e2c0fe",
  fullHash = "e2c0fe",
  text = "Messenger to Stormwind. In Lakeshire, Magistrate Solomon sends an urgent plea to Stormwind. Gnolls and Blackrock orcs press around the town, and he cannot spare garrison troops for the journey. He entrusts you with The State of Lakeshire for General Marcus Jonathan in Stormwind City. Gnolls contest every road from Lakeshire, while Blackrock orcs raid from the north. The town's guardsmen are stretched thin. Magistrate Solomon cannot spare fighting men for the days-long ride to the capital, so you carry his official plea for regular troops to the city gates. General Marcus Jonathan commands Stormwind's defense. Solomon's report reaches him, and he respects the magistrate's leadership and sees the urgency. Yet army protocol bars him from mobilizing troops without a royal directive. Redridge's defense must wait while he consults the young King Anduin and the regency council.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_120-8d2b06a7676ffae70956/1-0000.mp3", duration = 54.4653061, start = 0},
  },
}
P.transport["quest:1205"] = {
  hash = "c873e0",
  fullHash = "c873e0",
  text = "Deadmire. In Dustwallow Marsh, hunters seek Deadmire in the waterways north of the Stonemaul Ruins. Melor Stonehoof asks you to bring back a tooth from the ancient crocolisk. The hunt teaches tracking and mercy. From Hunter Rise in Thunder Bluff, Melor Stonehoof sends you east to Dustwallow Marsh. He teaches promising trackers the spiritual traditions of the hunt. Tauren hunters seek reverence and a bond with the natural world, not slaughter or trophies. There, you are to find Deadmire, an ancient crocolisk whose long life has become a burden. North of the Stonemaul Ruins, Deadmire prowls the waterways as a massive, pale crocolisk. His strength and fury still flare in sudden bursts, but age has worn down his body. Grinding bones bring unrelenting pain. Melor asks you to grant him a swift, honorable end and bring back one tooth as a token of his release.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1205-205151bc51c8dbac59db/1-0000.mp3", duration = 54.7004082, start = 0},
  },
}
P.transport["quest:121"] = {
  hash = "32c9f7",
  fullHash = "32c9f7",
  text = "Messenger to Stormwind. In Stormwind, you carry General Marcus Jonathan's reply to Lakeshire, where Blackrock orcs and gnolls threaten the town. The capital sends no troops while its leaders delay, leaving the settlement exposed. You brought Magistrate Solomon's plea for reinforcements to General Marcus Jonathan in Stormwind. Now you carry his first reply back to Redridge while he waits for the throne's approval. Without royal permission, the General cannot commit the army. Lakeshire's citizens still have no city guards, and each day brings the settlement closer to falling to the Blackrock clan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_121-c6619f0566b794b18b8d/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["quest:122"] = {
  hash = "fe5c56",
  fullHash = "fe5c56",
  text = "Underbelly Scales. In Redridge, Verner Osgood needs black dragon whelp scales to pay his debt to Smith Argus of Goldshire. You gather them from young drakes south of Lakeshire, and the scales settle Verner’s account with raw hide left for a piece of gear. Verner Osgood runs a forge outside Lakeshire and trades with craftsmen beyond the Redridge Mountains. Smith Argus of Goldshire sent him horseshoes, but Verner lacks the coin to pay. Argus asks for dragonhide instead: the softer underbelly scales of the black dragon whelps in the region. Without them, collectors may come from Elwynn Forest to claim the debt. Black dragon whelps trouble the defenders of the Redridge Mountains. Gnolls and orcs contest the roads, while the Black Dragonflight nests in the high peaks. Its brood wanders the skies south of Lake Everstill. The young predators’ underbelly scales are tough yet pliable, prized by armorers, smiths, and leatherworkers across the kingdom who dare to harvest them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_122-4d7635d7f55d89c673ea/1-0000.mp3", duration = 61.2310204, start = 0},
  },
}
P.transport["quest:123"] = {
  hash = "e119ae",
  fullHash = "e119ae",
  text = "The Collector. In Elwynn Forest, gold shipments leave the abandoned mines under cover of gnoll raids. An intercepted dispatch names their overseer as 'The Collector' and points to an organized operation near Stormwind's garrison. Riverpaw gnolls in western Elwynn Forest carry a parchment called the Gold Pickup Schedule. It sets dates and times for gold taken from local mines. The intercepted note directs each shipment to an overseer known only as 'The Collector.' At the Lion's Pride Inn, Marshal Dughan learns that gold is still being mined and moved. Official mines across Elwynn have been closed for months because of gnoll attacks, kobold infestations, and roaming bandits. Gnolls with shipping schedules point to an organized criminal network stealing the kingdom's wealth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_123-dbb7dbfd65e2a7f102ed/1-0000.mp3", duration = 48.9534694, start = 0},
  },
}
P.transport["quest:125"] = {
  hash = "f9157b",
  fullHash = "f9157b",
  text = "The Lost Tools. Blackrock fire has sunk Foreman Oslow's tools in Lake Everstill. Lakeshire is under pressure, and its builders need the shipment from Goldshire to repair the Great Bridge. The Great Bridge no longer joins Lakeshire to Elwynn Forest. A replacement shipment of stonework and carpentry tools came overland from Goldshire, but the wagons could not reach town. So the crew loaded the supplies into a rowboat to cross Lake Everstill. A Blackrock orc catapult struck the boat. It broke apart, and Oslow's heavy ironbound toolbox sank to the lake floor. Lake Everstill is dangerous below the surface. Aggressive murloc tribes prowl the shallows, while predatory threshers hunt in the murky depths. Foreman Oslow needs his tools to resume repairs on the bridge. Without them, Lakeshire risks falling further into ruin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_125-faf3ecc4c223e260bc56/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["quest:129"] = {
  hash = "51900f",
  fullHash = "51900f",
  text = "A Free Lunch. Darcy has a meal ready for Guard Parker on the southern road from Lakeshire. Gnolls and Blackrock orcs threaten the approaches, while the town's guards are stretched thin. Darcy, the cook in Lakeshire, has packed a meal for Guard Parker. She cannot carry it beyond town herself. Redridge gnolls and roaming orc warbands make the roads outside the gates too dangerous for a civilian. So she asks passing travelers to carry the food toward Darkshire, where Parker keeps watch. Guard Parker watches the southern road from Lakeshire toward Duskwood. Redridge has too few reinforcements from the Stormwind army to face the growing gnoll packs and the Blackrock clan in the mountains. Sentries like Parker keep watch alone in hostile country. A hot meal from town can lift their spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_129-ee16c87fe8df2b5270c2/1-0000.mp3", duration = 48.5877551, start = 0},
  },
}
P.transport["quest:13"] = {
  hash = "9df28d",
  fullHash = "9df28d",
  text = "The People's Militia. Westfall's volunteers face a growing Defias threat. Led by Gryan Stoutmantle, The People's Militia now confronts thieves who have moved beyond highway robbery to ransack Moonbrook and the Gold Coast Quarry. The Militia calls for harsher retaliation. Defias attacks have spread from the roads to Westfall's economic centers. Defias Looters and Pillagers, who hurl fire, occupy Moonbrook and the Gold Coast Quarry. They strip the Alexston Farmstead as well. Gryan Stoutmantle sees what their hold on these places could mean: Westfall may become impossible to reclaim without a formal royal army. Stormwind has sent Gryan Stoutmantle neither soldiers nor supplies. So he calls on the Holy Light and the resolve of Westfall's remaining farmers. Volunteers carry the fight into Defias strongholds, wearing down the Brotherhood. Driving out the looters will deny them resources and show fearful residents that defenders still fight for Westfall's peace and prosperity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_13-a7db0989e8b64c75be11/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["quest:130"] = {
  hash = "070c7a",
  fullHash = "070c7a",
  text = "Visit the Herbalist. Guard Parker asks you to buy flowers for Darcy in Lakeshire. He wants the gift kept secret before you return to the inn. Guard Parker watches Lakeshire's southern approach for blackrock orcs and gnolls. You bring him a warm meal from Darcy at the Lakeshire Inn. Grateful for her kindness, he asks you to buy flowers for her at the herbalist shop on the west end of town. Parker asks you to keep the order private when you visit Martie Jainrose, Lakeshire's herbalist. The town is small, and he does not want Martie to know who sent the flowers or who will receive them. At the shop, Martie teases you, guessing you have already found a sweetheart in town. Orc incursions and brigands trouble Redridge, so a small gesture of romance brings welcome relief.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_130-e716329d428721e28312/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["quest:131"] = {
  hash = "0dcbc1",
  fullHash = "0dcbc1",
  text = "Delivering Daffodils. In Lakeshire, Delivering Daffodils brings you from Guard Parker's thanks to an uneasy exchange at the inn. First you take Parker his lunch, then carry flowers from Martie Jainrose to Darcy. Guard Parker thanks you for bringing his lunch. Darcy, the cook who prepared it, is owed a kindness, so Parker asks you to fetch flowers from Martie Jainrose. Martie arranges a bouquet of daffodils, her own favorite flowers. She does not know who will receive them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_131-8c96118391d1662ac744/1-0000.mp3", duration = 28.4734694, start = 0},
  },
}
P.transport["quest:132"] = {
  hash = "7b753d",
  fullHash = "7b753d",
  text = "The Defias Brotherhood. At the edges of Redridge and Westfall, Wiley the Black warns Gryan Stoutmantle. His intelligence shows the Defias threat reaches beyond banditry, and Gryan needs to learn how far it extends. Wiley the Black says sharing what he knows could cost him his life. His sealed note describes how the Brotherhood has coordinated groups across the countryside, though those groups are usually hostile to one another. Wiley warns that the Defias has drawn an alarming network around itself. The red-masked outlaws have enlisted gnoll packs, kobold diggers, and goblin engineers instead of working alone. Their brutal muscle, burrowing labor, and mechanical cunning point to an enterprise beyond what the People's Militia first expected. Gryan Stoutmantle has little love for Wiley. He openly laments that he did not leave the rogue to rot when he had the chance. Yet Westfall cannot afford pride. The People's Militia must take useful intelligence wherever it can find it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_132-25a807eab1d74be4c961/1-0000.mp3", duration = 61.4661224, start = 0},
  },
}
P.transport["quest:1338"] = {
  hash = "a41dd5",
  fullHash = "a41dd5",
  text = "Stormpike's Order. In Loch Modan, Mountaineer Stormpike sends a shield order south to Stormwind City. He asks you to carry it to Furen Longbeard, the armorsmith he trusts. Stormpike trusts no other smith with his shield. He offers good pay to place the commission in Furen Longbeard’s hands, though Stormwind City lies far south of Loch Modan. Stormpike wonders why Furen works so far from Ironforge and the Great Forge, where many dwarves make their home. He suspects Stormwind’s humans pay the smith a king’s ransom.\n\nWhen the order reaches Furen at his anvil, he takes pride in hearing from the prestigious Stormpike clan. He eagerly prepares to forge the shield.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1338-dce887a5ec8d9bdf657b/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:1339"] = {
  hash = "26a9fc",
  fullHash = "26a9fc",
  text = "Mountaineer Stormpike's Task. At his post in Loch Modan, Mountaineer Stormpike needs a runner for urgent business beyond the valley. Mountaineer Kadrell sends you to find him, since Stormpike cannot leave his watch. The northern guard tower is Stormpike’s post, and his watch keeps him from leaving Loch Modan. The Mountaineers are stretched thin by troggs and roaming wildlife. So Kadrell directs capable travelers to guards who cannot abandon their duties. Stormpike needs a messenger for business far beyond the region’s borders. You find Stormpike atop the northern guard tower, looking out over the valley. He belongs to the prominent Stormpike clan and has affairs beyond Thelsamar’s frontier defenses. Carrying his message and supplies takes you across regional borders on his behalf. Your road leads from the loch onto the highways of Khaz Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1339-f97cd81f31c0f2512914/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["quest:135"] = {
  hash = "0168f5",
  fullHash = "0168f5",
  text = "The Defias Brotherhood. In Westfall, Gryan Stoutmantle suspects the Defias Brotherhood has ties to Stormwind's old Stonemasons Guild. He sends you there with Wiley's Note. Wiley's mention of the Stonemasons catches Gryan's attention. The guild rebuilt Stormwind City after the First War, but many believe it scattered or dissolved. If the Defias are linked to the guild, Westfall's rural insurgency may be more than a band of outlaws. Gryan cannot test his suspicions from Sentinel Hill, so he sends you to Master Mathias Shaw, head of Stormwind's covert intelligence wing, SI:7. Shaw works from the Barracks in Old Town, gathering whispers and secrets from across the realm. He may untangle the Defias Brotherhood's origins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_135-70dc7b6ff7c7f84973d4/1-0000.mp3", duration = 47.3338776, start = 0},
  },
}
P.transport["quest:1358"] = {
  hash = "64dee3",
  fullHash = "64dee3",
  text = "Sample for Helbrim. At the Crossroads, Apothecary Helbrim waits for a wolf heart sent from across the sea. Apothecary Zinge has sent it from the Undercity to support the Forsaken's research in central Kalimdor. Apothecary Zinge sends a Wolf Heart Sample from the Undercity to Apothecary Helbrim in the Barrens. The Royal Apothecary Society's experiments now reach beyond Lordaeron's ruins. Apothecary Renferrel in Silverpine sent tainted organs before Zinge sought to carry their research across the world. Now a courier bears the sample over the sea to Helbrim, an alchemist stationed in the Barrens' dry savanna. At the Crossroads, Apothecary Helbrim studies how Kalimdor's native beasts react to compounds from the Plaguelands. The wolf heart may show how those toxins affect local creatures. Helbrim believes that dissecting and testing it alongside them will help the Forsaken master poisons and unnatural afflictions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1358-0d6ec1a4209fb6a07776/1-0000.mp3", duration = 59.115102, start = 0},
  },
}
P.transport["quest:1359"] = {
  hash = "109462",
  fullHash = "109462",
  text = "Zinge's Delivery. From the Sepulcher, Apothecary Renferrel sends strange wolf hearts to the Undercity. Their toxins should have killed the beasts, and Apothecary Zinge receives them for the Royal Apothecary Society to study. In Silverpine Forest's ruined woods, Apothecary Renferrel found wolves with a deadly trait. Toxins in their hearts were so powerful they should have killed them. He preserved several tissue samples and packed them for his colleagues at the Apothecarium in the Undercity. At the Undercity's underground headquarters of the Royal Apothecary Society, Apothecary Zinge receives the preserved organs. The society seeks potent plagues and new alchemical compounds, so poisons that leave their hosts alive draw its notice. Zinge welcomes the samples for further trials in laboratories across the Forsaken alchemical network.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1359-682f5177be39744ea3f2/1-0000.mp3", duration = 51.2522449, start = 0},
  },
}
P.transport["quest:136"] = {
  hash = "d3ad01",
  fullHash = "d3ad01",
  text = "Captain Sanders' Hidden Treasure. Along Westfall's shore, Captain Sanders' Hidden Treasure begins with a battered parchment map. It sends you searching for his personal footlocker, then onward toward his hidden plunder across the region. Captain Sanders was an old seafarer who met a watery grave off Westfall's western coast. He left cryptic instructions so his hard-won fortune would not be lost to the Great Sea or taken by scavengers. You can retrace the trail he left behind. Shipwrecks and the restless spirits of drowned sailors mark the western shore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_136-1917a60efac4ee67958f/1-0000.mp3", duration = 31.9738776, start = 0},
  },
}
P.transport["quest:138"] = {
  hash = "722eb0",
  fullHash = "722eb0",
  text = "Captain Sanders' Hidden Treasure. Along Westfall's shore, Captain Sanders' Hidden Treasure sends you inland. You leave the coast and follow the next mark in his scattered trail. Captain Sanders left riddles across the countryside instead of marking one cache by the beach. The solved cipher points beyond rocky bluffs toward Westfall's main roads. Among the roadside ruins, an old chimney marks the next stop. A discarded, weathered barrel nearby holds another message, and the ruined farmstead gives Sanders a landmark for his trail.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_138-453624bfcfb09fa0dd67/1-0000.mp3", duration = 31.7387755, start = 0},
  },
}
P.transport["quest:139"] = {
  hash = "c75f15",
  fullHash = "c75f15",
  text = "Captain Sanders' Hidden Treasure. A broken barrel on Westfall's western shore begins Captain Sanders' Hidden Treasure trail. Its clue points north to an old jug beside a coastal windmill, one step closer to the late pirate's riches. Captain Sanders left clues that point only to the next hiding place. No single parchment shows where his plunder lies, so the trail stays unresolved until you find each message. The parchment sends you due north from the barrel to the sea cliffs. An isolated windmill stands on the bluffs, with another clue in an abandoned jug beside it. Murlocs and Defias scavengers roam the coast, making the way perilous.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_139-fd280937f8d961728c74/1-0000.mp3", duration = 38.0604082, start = 0},
  },
}
P.transport["quest:14"] = {
  hash = "b7a19b",
  fullHash = "b7a19b",
  text = "The People's Militia. In southern Westfall, volunteers of The People's Militia press their fight against the Defias. The seasoned brigands hold the Dagger Hills, and Gryan Stoutmantle leads a campaign to clear the roads and farms. Complete the patrols, and you earn full induction at Sentinel Hill. The Defias Brotherhood has brought great hardship to Westfall's northern farmlands. Those who escaped Gryan Stoutmantle's first sweeps fled south to the rocky Dagger Hills. From there, Defias Highwaymen, Pathstalkers, and Knuckledusters still raid homesteads and waylay travelers. You join hardened recruits sent into the hills to break the brigands' hold over southern Westfall. After returning from the fight against the Scourge in Lordaeron, Gryan Stoutmantle found Westfall abandoned by Stormwind's royal garrison. A criminal syndicate went unchecked, and hunger drove farmers from their land. So he rallied local volunteers to take up arms. Complete this final patrol, and Stoutmantle blesses you in the Light as he formally inducts you into the militia. The fight against the Brotherhood deepens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_14-d2b2a5ffbd517c6f8aab/1-0000.mp3", duration = 66.8734694, start = 0},
  },
}
P.transport["quest:140"] = {
  hash = "5fd483",
  fullHash = "5fd483",
  text = "Captain Sanders' Hidden Treasure. A whiskey-soaked clue sends you west from Westfall's shore and out across the Great Sea. Captain Sanders' trail ends at a remote islet, where his hidden prize waits. Captain Sanders left clues along Westfall's coast for you to piece together. The last parchment came from the dregs of his favorite whiskey jug. It gives the final bearing: head west to the water's edge, then swim into the waves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_140-84b5914003289df1eb42/1-0000.mp3", duration = 25.2081633, start = 0},
  },
}
P.transport["quest:141"] = {
  hash = "0c9991",
  fullHash = "0c9991",
  text = "The Defias Brotherhood. From Stormwind, Mathias Shaw sends Gryan Stoutmantle a confidential report at Sentinel Hill. Shaw investigated the former Stonemasons Guild to help Stoutmantle uncover the Defias Brotherhood's origins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_141-11d964713fca0f15812c/1-0000.mp3", duration = 13.2179592, start = 0},
  },
}
P.transport["quest:142"] = {
  hash = "c5aee6",
  fullHash = "c5aee6",
  text = "The Defias Brotherhood. Gryan Stoutmantle sends you after an elusive Defias courier, hoping to learn how the Brotherhood directs its forces. Gryan Stoutmantle's scouts have seen an elusive Defias Messenger traveling between Moonbrook, the Gold Coast Quarry, and the Jangolode Mine. Unlike the thugs who hold the countryside, this courier carries written orders across the region. Stoutmantle wants him captured or killed so the People's Militia can read his satchel and learn where the brotherhood directs its forces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_142-0966a57f0e8c980f3b18/1-0000.mp3", duration = 29.1265306, start = 0},
  },
}
P.transport["quest:143"] = {
  hash = "20c9fe",
  fullHash = "20c9fe",
  text = "Messenger to Westfall. In Lakeshire, Magistrate Solomon sends word west for help against the Blackrock orcs and gnolls. With Stormwind's forces absent, he hopes Gryan Stoutmantle's People's Militia can aid Redridge. Blackrock orcs and gnolls besiege Lakeshire, but the Stormwind Army has not arrived in force. Magistrate Solomon knows the town guards and irregulars cannot hold the Redridge Mountains alone. No royal reserves are in sight, so he writes a formal plea for help. Word has reached him of a citizen defense group forming west of Elwynn Forest, and he sends his appeal there. Gryan Stoutmantle is a veteran commander rallying volunteer fighters under the People's Militia banner. Solomon sends his dispatch across the kingdom, hoping Westfall's volunteers can reinforce Lakeshire's borders until the Crown's armies mobilize. Yet Westfall is fighting its own desperate struggle against the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_143-33e3d27beceecaa6d8b6/1-0000.mp3", duration = 57.9657143, start = 0},
  },
}
P.transport["quest:144"] = {
  hash = "8cbbd3",
  fullHash = "8cbbd3",
  text = "Messenger to Westfall. In Lakeshire, Magistrate Solomon receives a hard answer from Westfall. He asked Gryan Stoutmantle for soldiers to defend Redridge, but Westfall faces troubles of its own. Magistrate Solomon faces growing troubles in the Redridge Mountains without Stormwind's royal garrison. So he writes to Gryan Stoutmantle, commander of the People's Militia in Westfall, and asks the southern frontier for help. Solomon hopes the volunteers at Sentinel Hill can spare fighters to strengthen Lakeshire's defenses. He does not know how hard pressed the western plains are. Gryan Stoutmantle refuses, though the answer weighs heavily on him. Westfall fights the Defias Brotherhood and marauding gnolls because the House of Nobles and the crown have abandoned the kingdom's breadbasket. The People's Militia formed to help the people survive. Its ranks lose good men each day, and Stoutmantle cannot spare a single fighter for Redridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_144-475fd31710be63f00b24/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["quest:145"] = {
  hash = "17d12a",
  fullHash = "17d12a",
  text = "Messenger to Darkshire. In Lakeshire, Magistrate Solomon sends an urgent plea to Darkshire for aid. Blackrock orcs and gnolls threaten Redridge, and Solomon seeks military support from his neighbor. A courier must cross Duskwood to deliver the letter to Lord Ello Ebonlocke, Darkshire's mayor. Blackrock orcs and gnoll packs press Redridge, while Lakeshire's guards are stretched thin. Stormwind's royal court has ignored Magistrate Solomon's pleas, and Westfall is caught in its own insurrection. With little help nearby, Solomon writes to Mayor Ello Ebonlocke in Duskwood. He hopes Darkshire can lend or hire its Night Watch to strengthen Lakeshire's defenses. Solomon's letter travels south through Duskwood, a forest under supernatural gloom. He warns you to keep to the roads because the wilderness between Lakeshire and Darkshire is perilous. The letter is bound for Town Hall, where Lord Ebonlocke can receive it. Whether Duskwood can spare any forces remains uncertain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_145-2e2aeee5fa723a51fa80/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["quest:1453"] = {
  hash = "06ca50",
  fullHash = "06ca50",
  text = "Reclaimers' Business in Desolace. Roetten Stonehammer sends travelers from Ironforge across the sea to Desolace for paid work with the Reclaimers. At Nijel's Point, Kreldig Ungor needs help recovering lost treasures and relics. Beyond the sea, Desolace is a harsh stretch of Kalimdor ruled by warring centaur clans. The Reclaimers seek profit among its forgotten ruins and barren lands. For those willing to face the danger, the journey may pay well. The route runs west through the Stonetalon Mountains and into northern Desolace. High among the cliffs, Nijel's Point is an Alliance outpost where Kreldig Ungor welcomes new hands. The Reclaimers recover heirlooms, magical artifacts, and family treasures lost across the war-torn world. For the right price, Kreldig and his associates retrieve those valuables from the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1453-55f7b693e8f1b1ee45ec/1-0000.mp3", duration = 51.2522449, start = 0},
  },
}
P.transport["quest:146"] = {
  hash = "37a9f2",
  fullHash = "37a9f2",
  text = "Messenger to Darkshire. In Darkshire, Lord Ello Ebonlocke answers a plea for help from Lakeshire. Blackrock orcs and gnolls press against the town, but the plea cannot be granted. Magistrate Solomon of Redridge asks his old peer in Duskwood for troops. Blackrock orcs and gnolls are closing in on his town. Lord Ello Ebonlocke answers in anger. Darkshire struggles against the living dead, ravenous beasts, and cursed magic on every side. Ebonlocke says the Night Watch exists because Stormwind abandoned Duskwood. Without its defenders, Darkshire would fall before a patrol could cross the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_146-fd42edacd9513d1e2957/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["quest:1462"] = {
  hash = "e8e8aa",
  fullHash = "e8e8aa",
  text = "Earth Sapta. At Camp Narache, Seer Ravenfeather prepares another Earth Sapta for a young shaman whose brew was lost before the rite was complete. The draught opens a novice’s sight to the spirits of stone, so the trial can continue. Young shaman begin by learning to sense forces beyond ordinary sight. To meet Mulgore’s earth elementals, an initiate drinks a sapta made from natural essences of stone and soil. The Earth Sapta lifts the veil between the physical and spiritual realms. Then a novice can see and commune with the spirits of the land. A novice may lose or spill the brew before reaching the stone monument for communion. Seer Ravenfeather waits at Camp Narache and prepares another vessel when a pupil needs one. With the draught restored, the novice can continue the rite and face the spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1462-0344599322ad6085312a/1-0000.mp3", duration = 50.4685714, start = 0},
  },
}
P.transport["quest:1463"] = {
  hash = "0c0d45",
  fullHash = "0c0d45",
  text = "Earth Sapta. In the Valley of Trials, Earth Sapta is lost, and an initiate can ask Canaga Earthcaller for another. The replacement lets the young shaman commune with the spirits of the land, with a warning to guard sacred draughts carefully. An initiate who loses the Earth Sapta may lose the chance to commune with the spirits of stone and soil. Rituals prepare the elemental brew, which thins the veil between the physical realm and the spirits. If the draught is lost or spilled while traveling through Durotar, Canaga Earthcaller prepares another in good faith. He warns the novice to guard sacred gifts with greater care. Canaga Earthcaller watches over fledgling shamans emerging from the Den in the Valley of Trials. Young orcs and trolls can stumble amid their early trials, but elemental spirits do not take kindly to negligence. Accepting a second sapta brings a small lesson in humility. Power granted by the earth must be guarded and respected.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1463-5874d6ac61cf059f3ada/1-0000.mp3", duration = 58.2008163, start = 0},
  },
}
P.transport["quest:147"] = {
  hash = "6ed1d1",
  fullHash = "6ed1d1",
  text = "Manhunt. In Elwynn Forest, Marshal Dughan sends you to find the Collector, a Defias bagman. He works from the overrun Brackwell Pumpkin Patch and sends stolen gold from the forest's mines to the Brotherhood. Marshal Dughan sends you to Brackwell Pumpkin Patch after Elwynn's gnolls are found carrying a schedule for gold pickups. Defias bandits and gnolls have taken over the once quiet homestead. The Collector hides among its overgrown vines, skimming ore from the kingdom's mines and arranging shipments for the growing rebellion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_147-f3c143fe7ccf91f2f96d/1-0000.mp3", duration = 32.1828571, start = 0},
  },
}
P.transport["quest:1470"] = {
  hash = "7e50b1",
  fullHash = "7e50b1",
  text = "Piercing the Veil. In Deathknell, Venya Marthand tests a novice warlock's resolve. Newly risen Forsaken gather skulls from nearby mindless skeletons to earn the knowledge to summon and bind an imp. Venya Marthand teaches newly awakened Forsaken warlocks in Deathknell that strength comes through knowledge and mastery of chaotic powers. She sends them to gather skulls from Rattlecage Skeletons near Deathknell's abandoned smithy. The trial tests whether they can focus enough to command powers beyond this world and subdue nether beings. Venya accepts the skulls as proof that a novice can overcome mindless undead and face the bleak truths of warlock craft. Then she teaches the rituals to summon and bind an imp. Small as it is, the demon brings cunning and fire, and makes a dangerous ally.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1470-0877b0779f21080e07e6/1-0000.mp3", duration = 48.875102, start = 0},
  },
}
P.transport["quest:1471"] = {
  hash = "0105cb",
  fullHash = "0105cb",
  text = "The Binding. In the Undercity's Magic Quarter, Forsaken warlocks seek power over a voidwalker they can summon and command forever. Carendin Halgar oversees the rite that grants them this power. Forsaken warlocks must prove they can master a voidwalker before they may summon one. Minor imps are easily drawn into pacts by dark magic. Creatures of the Void despise reality and wield formidable physical might. In the Magic Quarter, mentor Carendin Halgar provides the mystic runes that tear a voidwalker from the Nether into the physical realm. Beneath Carendin Halgar's dais, a glowing summoning circle is etched into the floor. Activate the runes, and an unbound voidwalker appears in fury. Diplomacy cannot subdue it; arcane force and raw will must break it. Only when the creature is thoroughly crushed does Carendin reveal the true summoning formula, binding its essence to you indefinitely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1471-01066a4ba7be8452bca4/1-0000.mp3", duration = 58.8277551, start = 0},
  },
}
P.transport["quest:1473"] = {
  hash = "2978f2",
  fullHash = "2978f2",
  text = "Creature of the Void. In the Undercity, Forsaken warlocks seek the grimoire needed to summon a voidwalker. They must recover Egalin's Grimoire from the Scarlet Crusade in western Tirisfal Glades to learn how to summon and bind one. Carendin Halgar guides Forsaken summoners in the Temple of the Damned. When an acolyte can wield more than the power of petty imps, Halgar points them toward a voidwalker. The creature is forged from pure shadow and chaos. Forsaken warlocks depend on the careful research of Egalin, Halgar's former master, who wrote the rituals for subduing such beings. Egalin's Grimoire holds the methods for channeling the volatile magic needed to master a voidwalker. Perrine, a Scarlet Crusade zealot, stole the book and keeps it in an outpost tower to the west. The Crusade may regard it only as blasphemous contraband to seize and hoard. Recovering it gives the Forsaken the ritual secrets they need before they try to tear open the veil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1473-61a67871a4e42825b829/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["quest:1478"] = {
  hash = "46f5a0",
  fullHash = "46f5a0",
  text = "Halgar's Summons. In Undercity, Halgar's Summons calls promising Forsaken warlocks to advanced training. Carendin Halgar awaits those who have mastered the first fel arts in the Magic Quarter, where dangerous beings from the Nether test their skill. A warlock's command of basic fel energies earns notice in Brill or the Tirisfal wilderness. Ageron Kargal, a senior practitioner who recognizes talent, sends word to those who show promise. Carendin Halgar's summons is a rare privilege and a perilous step in a warlock's training. Basic imps and petty curses no longer suffice. Carendin Halgar oversees warlock rites in Undercity's Magic Quarter, near the Temple of the Damned. Forsaken darkcasters lack the moral restraint of the living, but summoning across the planes still demands discipline. Halgar tolerates neither hesitation nor sentiment. Those called to him are expected to show deference and face the hostile horrors of the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1478-b94fb3d13c2d9bf18a47/1-0000.mp3", duration = 58.9322449, start = 0},
  },
}
P.transport["quest:1485"] = {
  hash = "e89c87",
  fullHash = "e89c87",
  text = "Vile Familiars. Near the Den, Vile Familiars threaten warlocks who seek the power of demons. Ruzan asks you to prove your strength by bringing back their heads. This is the first dangerous step toward mastering fel power under the Horde’s watchful eyes. Warlocks have an uneasy place in Thrall’s new Horde. Demonic corruption and blood pacts once brought ruin to the orcs, leaving deep scars and distrust. Durotar tolerates fel magic, but its practitioners are neither loved nor welcomed. Many warlocks live apart and practice in shadowed places like the Den, away from prying eyes. There, they teach the few initiates daring enough to follow their path. Ruzan asks you to prove your strength before he teaches you the dangerous rites for bending an imp to your will. Vile Familiars lurk near a cave northeast of the Den and hurl bolts of flame at those who approach. Slay these lesser demons and bring their heads back to Ruzan. They will show him you can overcome the fiery creatures you hope to control. Only then can you face the danger of the magic you seek to command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1485-c2bded8f1e6d8c4b4acf/1-0000.mp3", duration = 64.7053061, start = 0},
  },
}
P.transport["quest:1486"] = {
  hash = "d847c4",
  fullHash = "d847c4",
  text = "Deviate Hides. At the Wailing Caverns, Nalpak seeks a use for the strange properties of deviate hides. A disciple of Naralex, he keeps watch above the entrance while his teacher lies trapped in a twisted nightmare. Beneath the Barrens, mutated beasts roam, and Nalpak hopes their skins can serve a practical purpose. Naralex sought to awaken the springs beneath the Barrens and restore life to the dry plains. Instead, the Wailing Caverns became dangerous. The night elf druid's mind slipped into a terrifying nightmare, and that nightmare reached the waking world. Raptors, crocolisks, vipers, and shambling horrors turned vicious and misshapen, warped by emerald corruption leaking from their dreaming master. From the rock above the cavern mouth, Nalpak watches the disaster with dread and practical curiosity. He knows the deviate beasts are malignant and unnatural, yet their corrupted forms may yield useful materials. Their tough, warped pelts could help skilled leatherworkers. Nalpak hopes to make durable equipment from the fruits of a tragic nightmare.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1486-d89d294b18cc5585508f/1-0000.mp3", duration = 66.8473469, start = 0},
  },
}
P.transport["quest:1489"] = {
  hash = "17cc8b",
  fullHash = "17cc8b",
  text = "Hamuul Runetotem. Tonga Runetotem sends you to Thunder Bluff as a strange taint spreads through the Barrens. He suspects the Wailing Caverns lie at its heart and seeks Archdruid Hamuul Runetotem’s counsel. Near the Barrens’ oases, Tonga Runetotem found creatures marked by a strange affliction. An unnatural taint covered their shells, and Tonga came to believe the land itself was caught in a troubled dream. He suspects the waters flowing from the Wailing Caverns are to blame. Entering those caverns calls for more wisdom than one naturalist can offer. Tonga sends you to Thunder Bluff for counsel from his kin, Archdruid Hamuul Runetotem. Hamuul is the highest-ranking tauren druid and a revered spiritual leader of the Cenarion Circle in Mulgore. From Elder Rise, he watches for disturbances across Kalimdor. He confirms the nightmare spreading through the Barrens is a dire threat, calling for the full might of Horde champions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1489-ceee384d3794cbd7012b/1-0000.mp3", duration = 58.6710204, start = 0},
  },
}
P.transport["quest:1490"] = {
  hash = "b50c14",
  fullHash = "b50c14",
  text = "Nara Wildmane. In Thunder Bluff, Nara Wildmane helps the Horde grasp the danger in the Wailing Caverns. Arch Druid Hamuul Runetotem saw corruption in the Emerald Dream but could not endure it, so he sent travelers to his young disciple. Nara saw the nightmare taking hold of their kin. Unnatural signs spread across the Barrens, and Arch Druid Hamuul Runetotem entered the Emerald Dream to find their cause. There he found a druidic cult that had once hoped to restore life to the dry savannah. A vile taint had driven its members mad.\n\nAge kept Hamuul from enduring the nightmare’s assault, so he fled to the waking world. His younger disciple, Nara Wildmane, refused to leave so soon. Her fierce resolve kept her in the dreamscape, where she saw the transformed cult for herself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1490-e6af9023bf6a46529691/1-0000.mp3", duration = 52.0097959, start = 0},
  },
}
P.transport["quest:1491"] = {
  hash = "92343b",
  fullHash = "92343b",
  text = "Smart Drinks. In Ratchet, Mebok Mizzyrix seeks a new formula for his drink. His brew of powdered Sunscale raptor horns disappointed him, so he now wants ectoplasmic residue from the Wailing Caverns. Mebok Mizzyrix sells goods in Ratchet and hopes to make a fortune with a drink that sharpens the mind. His first formula used powdered Sunscale raptor horns, but the brew disappointed him. Now he has turned to the strange essence seeping from the Wailing Caverns, hoping it will make his drink succeed. Strange changes have come to the Barrens. New oases have appeared, and local wildlife has grown aggressive and warped. Mebok suspects a substance he calls Wailing Essence is behind them. He sends you into the cavern labyrinth to destroy its oozing ectoplasms and gather their glowing fluid in bottles for his formula.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1491-9028b2b2106455ea62f5/1-0000.mp3", duration = 49.8938776, start = 0},
  },
}
P.transport["quest:1492"] = {
  hash = "30f2e0",
  fullHash = "30f2e0",
  text = "Wharfmaster Dizzywig. At Ratchet's pier, Wharfmaster Dizzywig finds passage for a crate of alchemy supplies. It is bound for the Old World aboard a ship sailing to Blackwater Cove. A crate of potions and reagents waits at the Barrens port for colleagues in the Old World. The caravans that could have carried it have already left. So you are asked to bring the secure shipment to Ratchet's water's edge. From there, ships cross the Great Sea between Kalimdor and the Eastern Kingdoms. Cargo passes through Wharfmaster Dizzywig's hands on Ratchet's wooden piers. He records each shipment in ledgers and manifests, then finds room aboard vessels sailing east across the Great Sea. This crate is booked for a ship bound for Blackwater Cove.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1492-541d2108ecc5d422ed92/1-0000.mp3", duration = 43.2587755, start = 0},
  },
}
P.transport["quest:1498"] = {
  hash = "d3a6c2",
  fullHash = "d3a6c2",
  text = "Path of Defense. At the Far Watch Post, Uzzek teaches young Horde warriors to defend those who cannot defend themselves. He sends them to Thunder Ridge to test their endurance against its electric beasts. At the Far Watch Post, Uzzek teaches young warriors that the Horde has a duty to defend. The post lies on the border between the Barrens and Durotar. He says a warrior’s highest calling is to stand between danger and those unable to defend themselves. They take the blows so the Horde can endure. Uzzek sends the novices to Thunder Ridge, north across the Southfury River in Durotar, to test their stamina and resolve. Thunder lizards and lightning hides roam the canyon. The initiates must endure the beasts’ jolts and gather their singed scales. That trial shows they have the fortitude to hold the front line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1498-e32ea15ff811911877d4/1-0000.mp3", duration = 49.0057143, start = 0},
  },
}
P.transport["quest:1499"] = {
  hash = "502878",
  fullHash = "502878",
  text = "Vile Familiars. In the Valley of Trials, Ruzan tests warlock initiates against vile familiars. After you slay them, you report to Zureetha Fargaze, who directs the effort against the Burning Blade. Warriors and scouts in the Valley of Trials answer to Zureetha Fargaze. She sends them to curb the Burning Blade Coven. Warlock initiates answer first to Ruzan, their shadowy mentor. He demands proof that you can master lesser demons before sending you back to aid the Horde's defense. Your work helps the warlocks and keeps the Den safe. Zureetha Fargaze watches the northern cavern above the Valley of Trials. Vile familiars hide within, the weakest pets of the Burning Blade cultists. Their presence insults the orcs and threatens the sacred training grounds. When you report your success, you show that those who practice fel magic are ready to defend Durotar from corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1499-ccb2ea41da5b1a464aca/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["quest:15"] = {
  hash = "495d1d",
  fullHash = "495d1d",
  text = "Investigate Echo Ridge. Kobolds gather in force at Echo Ridge Mine, so Marshal McBride sends you north. The mine supplies ore and raw materials to Northshire Abbey and the Stormwind guard stationed there. Scattered vermin have troubled the valley's forested edge near Northshire. Now the scouts report a more organized gathering. At the entrance, you face kobold workers and see how deeply they have settled into the mine. The kobolds have seized the tunnels and stopped the digging. Their presence strains the Northshire brotherhood's defenses. McBride asks you to cull ten workers, but the infestation reaches farther into the shafts than a surface patrol can reach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_15-fb55f2c0665db0ecca79/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["quest:1501"] = {
  hash = "d5b711",
  fullHash = "d5b711",
  text = "Creature of the Void. In Orgrimmar, Gan'rul Bloodeye sends a young warlock to recover the stolen Tablet of Verga. Burning Blade cultists have carried it to their cavern at Skull Rock, where its runes are needed to summon a voidwalker. Gan'rul Bloodeye trains Horde warlocks in the Cleft of Shadow. Thrall's new realm distrusts fel magic because of the orcish clans' dark history. Few true warlocks remain in the Horde, Gan'rul says, yet their perilous skills are needed for its survival. To serve the Warchief, an initiate must master more than an imp's chaotic fire. They must command beings of pure shadow and endurance. The runes for summoning a voidwalker are carved on the Tablet of Verga. The Burning Blade, a fanatical shadow cult, stole the relic and hides in a cavern at Skull Rock, beneath the Warchief's nose. Gan'rul sends you into their den to recover it and strike a bloody blow against renegades who stain the name of every warlock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1501-99e3d498126eb8128294/1-0000.mp3", duration = 58.4881633, start = 0},
  },
}
P.transport["quest:1502"] = {
  hash = "4e65a2",
  fullHash = "4e65a2",
  text = "Thun'grim Firegaze. Atop Thorn Hill, a lone forge draws warriors to Thun'grim Firegaze. After their first lessons in defense, Horde warriors cross the Barrens seeking steel suited to their growing skill. After you demonstrate skill in the defensive arts under veteran trainers such as Uzzek, you are sent to sharpen your fighting with suitable steel. Ordinary armories can carry a frontline fighter only so far. True mastery calls for a personal weapon from a smith of renown. In the Barrens, that smith is Thun'grim Firegaze, an aging orc who left settlement life behind for an isolated forge high above the plains. Thun'grim Firegaze lives atop Thorn Hill, a jagged rise east of the Crossroads. Wild raptors and hostile quilboar roam there, far from the protection of town walls. He spends his solitary hours shaping metal. Decades gazing into blistering forge flames have ruined his eyesight, though his instincts remain sharp. When you climb the heights and disturb his solitude, he knows why: a warrior has come seeking forged steel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1502-b1b695837075ac374199/1-0000.mp3", duration = 65.2016327, start = 0},
  },
}
P.transport["quest:1503"] = {
  hash = "4d60e9",
  fullHash = "4d60e9",
  text = "Forged Steel. In the eastern Barrens, Thun'grim Firegaze waits for the steel stolen from his camp. He will forge a weapon for the warrior who brings it back. Thun'grim Firegaze keeps a smithy in the eastern Barrens, far from Orgrimmar. Years at the forge have dimmed his sight. The nearby Razormane quilboar used that weakness to steal an iron chest from his camp. Some snorted and made noise on one side to draw his gaze while others slipped in from the other and carried off his forged steel bars. Thun'grim is angry at the theft, but doubts the Razormanes can use the steel. Quilboar craft with stone, tusks and thorny roots, not refined metal. The heavy chest remains near a broken wagon in their camp, untouched and useless to them. For Thun'grim, its steel is the stock he needs to forge weapons for young Horde warriors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1503-ddf631e0a6089a1943b0/1-0000.mp3", duration = 51.722449, start = 0},
  },
}
P.transport["quest:1504"] = {
  hash = "1ef6d7",
  fullHash = "1ef6d7",
  text = "The Binding. In Orgrimmar, The Binding marks young Horde warlocks' final initiation ritual. Gan'rul Bloodeye directs each petitioner to use glyphs from the Tablet of Verga in Neeru Fireblade's summoning circle. You face your first true test of will when you summon a voidwalker. An imp is child's play by comparison. Warlocks do not make pacts with these creatures or commune with them. You pull them across dimensions by force and bind them to serve. Gan'rul Bloodeye directs you to use glyphs from the Tablet of Verga and call the voidwalker into Neeru Fireblade's ritual circle, to break it there in single combat. Defeating the voidwalker in physical and magical combat is only half the struggle. Gan'rul Bloodeye warns that a bound voidwalker never truly accepts its enslavement. Even while it guards its master in battle as a durable, shadowy bulwark, it waits for a lapse in your concentration. If your hold over your servant ever falters, it will consume the soul of the one who bound it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1504-6c0b81c64e57181c43ac/1-0000.mp3", duration = 62.3020408, start = 0},
  },
}
P.transport["quest:1506"] = {
  hash = "8ba208",
  fullHash = "8ba208",
  text = "Gan'rul's Summons. Ophek brings Gan'rul's Summons to young Horde warlocks in Razor Hill. Gan'rul Bloodeye calls them to the Cleft of Shadow to advance their training. There, they take the first step toward summoning a voidwalker. In Durotar, novice warlocks do not go unnoticed for long. When a practitioner shows enough mastery over an initial imp, word reaches the deep caverns beneath Orgrimmar. Ophek carries messages for the senior dark casters from his post in Durotar. He finds warlocks with an urgent demand to leave their work and report to the Cleft of Shadow. Gan'rul Bloodeye oversees the training of young orc warlocks within the Horde. From the hidden caverns beneath Orgrimmar, he hones their lethal fel power while keeping these dangerous arts from the Warchief's disapproving gaze. A call to his circle means simple fire spells and imps are no longer enough. The apprentice is ready to bind a creature from the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1506-22a8a0650a0c4a7ac3fa/1-0000.mp3", duration = 58.1485714, start = 0},
  },
}
P.transport["quest:151"] = {
  hash = "972de0",
  fullHash = "972de0",
  text = "Poor Old Blanchy. On Westfall's road, Poor Old Blanchy waits with the stranded Furlbrows, worn out and hungry. Their wagon broke as they fled, and Verna asks you to find oats at nearby abandoned farms to feed the mare. Verna and Farmer Furlbrow are stranded beside Westfall's main road. Bandits and rogue mechanical harvest golems have driven families like theirs from their homes. The Furlbrows tried to carry their belongings to safety, but their wagon broke down, leaving them marooned in open country. Old Blanchy has plowed and hauled for the Furlbrow family through many seasons. Now the delay has left the gentle mare exhausted and starving. Verna asks you to search nearby overrun farmsteads for sacks of oats. Hostile threshers and gnoll scavengers threaten there, but the grain could give the faithful mare a decent meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_151-8aa052013985ff008835/1-0000.mp3", duration = 51.5134694, start = 0},
  },
}
P.transport["quest:1516"] = {
  hash = "5c326a",
  fullHash = "5c326a",
  text = "Call of Earth. In the Valley of Trials, Canaga Earthcaller tests novice Horde shamans through endurance and patience. Their hunt for felstalkers prepares a ritual sapta. A shaman first learns to bond with each element. For orcs and trolls, that path begins with earth, the bedrock of life, endurance, and patience. In the Valley of Trials, Canaga Earthcaller guides new shamans. He teaches them that earth demands respect and steadfastness before it grants protection. North of the Valley of Trials, the Burning Blade cult works dark magic in the ravines. Its spells summon felstalkers, corrupt hounds from beyond this plane. Hunting them tests whether a shaman can defend the land from unnatural decay. Canaga uses their hooves to brew an Earth Sapta, a sacred draft that opens mortal eyes to the elemental plane.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1516-5cafe131d280d5d79a9e/1-0000.mp3", duration = 51.722449, start = 0},
  },
}
P.transport["quest:1517"] = {
  hash = "c814da",
  fullHash = "c814da",
  text = "Call of Earth. At Spirit Rock, Canaga Earthcaller guides young shaman through their first communion with the elements. An Earth Sapta lets them see the Minor Manifestation of Earth on sacred ground. A sapta is a rare draught known to only a few shaman masters. Elemental magic lets it bridge mortal sight and the spiritual plane, granting Sapta Sight to the strong-willed. Since it binds the drinker's spirit directly to an element, tradition forbids drinking it outside consecrated holy ground. To commune with earth, you leave the Valley of Trials and climb the Hidden Path into Durotar's southern crags. Spirit Rock waits at the trail's end, an elevated sanctuary above the rugged wasteland. Drink the sapta there, and you can see what ordinary eyes cannot: an elemental presence among the stone. The Minor Manifestation of Earth asks for neither bloodshed nor submission. It asks only that you stand humbly before the world. Fire, water, and air bear turbulent, volatile, often chaotic spirits, while earth teaches steadiness. Mountains endure, and plains teach boundless patience.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1517-9ff72656e2d4196ac138/1-0000.mp3", duration = 69.2244898, start = 0},
  },
}
P.transport["quest:1518"] = {
  hash = "b24e22",
  fullHash = "b24e22",
  text = "Call of Earth. In Durotar, you seek the earth spirit’s favor and return to Canaga Earthcaller with rough quartz. He shapes it into your first elemental totem. A novice shaman seeks the earth through patience and humility. Brute strength will not win the spirit’s favor. The Minor Manifestation of Earth gives you rough quartz. That small stone proves the spirit has accepted your pledge, and it holds the seed of power. You complete the trial when you bring the quartz to Canaga Earthcaller in the Valley of Trials. Canaga shapes it into an Earth Totem, the focus through which you channel the ground’s steadfast protection and strength.\n\nEarth begins your path through the four elemental disciplines. The rite lays the foundation for a lifetime of communion with the natural world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1518-ac13fe06433d2adc359a/1-0000.mp3", duration = 47.0726531, start = 0},
  },
}
P.transport["quest:152"] = {
  hash = "0ac868",
  fullHash = "0ac868",
  text = "The Coast Isn't Clear. Shipwrecked sailors struggle to reach Westfall's western shore as murlocs close in. Captain Grayson calls on you to clear the beaches so survivors can land safely. Reefs, squalls, and jagged rocks drive ships onto Westfall's shoals. Survivors cling to wreckage and crawl onto the sand, hoping help will come. They find murloc tribes along the shore instead, and the murlocs show no mercy to castaways. Captain Grayson watches from a lonely outcropping southwest of the mainland. Though dead, he remains bound to the lighthouse and to his duty toward passing ships and lost sailors. Coastrunners hold the northern shore. Farther south, Tidehunters, Warriors, and Oracles gather.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_152-69bf3d885276bda74a74/1-0000.mp3", duration = 45.4791837, start = 0},
  },
}
P.transport["quest:1520"] = {
  hash = "8c1301",
  fullHash = "8c1301",
  text = "Call of Earth. At Kodo Rock, you seek communion with earth through a sacred tauren rite. Drink an Earth Sapta to see a Minor Manifestation of Earth. Shamanic elders brew a sapta to join an initiate’s mortal spirit to a primal element. Ancestral magic guards the recipe, known to only a few tauren. Drink the draught at a sacred site, and your mind opens beyond the physical world. The veil parts, revealing the elements in their raw form. East of Camp Narache, Kodo Rock rises as a stone pillar and holy sanctuary. Drink the sapta there, and a Minor Manifestation of Earth appears before you. Other aspects of nature along the shaman’s path are volatile, fiery, or raging. Earth asks for quiet humility. Honor the land, and its spirit grants you the mountain’s enduring strength and the plains’ calm patience.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1520-914fc79c711abf750f8b/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:1521"] = {
  hash = "90dc94",
  fullHash = "90dc94",
  text = "Call of Earth. In Mulgore, a young tauren shaman returns to Camp Narache bearing a gift from the earth. The Earth Sapta lets the initiate speak with a spirit and receive raw stone, beginning the path through the four elements. After drinking the Earth Sapta, you meet the Minor Manifestation of Earth on the crags near Red Cloud Mesa. The spirit gives you Rough Quartz, a plain stone that marks your pact with the element and its endurance. Patience and strength are the virtues earth demands. Through mutual respect, the spirit promises harmony with the land. At Camp Narache, Seer Ravenfeather shapes the gifted quartz into your first Earth Totem. More than a mark of status, it is a lasting anchor for body and spirit. Through this carved focus, you channel the earth’s grounding and protective magic. It is your first true step along the fourfold elemental path.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1521-e8fbfafdb215207e15bd/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["quest:1524"] = {
  hash = "ce0de5",
  fullHash = "ce0de5",
  text = "Call of Fire. In the Barrens, Kranal Fiss sends an aspiring shaman toward the next trial for communion with fire. The initiate crosses the Southfury River to a secluded mountaintop shrine in Durotar, carrying an unlit Torch of the Dormant Flame. Kranal Fiss entrusts you with the Torch of the Dormant Flame. Raw mystical strength cannot meet fire’s demands; the trial calls for temperance, focus, and respect. The torch is both a ritual instrument and proof to the shrine’s keeper that you are judged ready to attempt the trial. The shrine lies across the Southfury River, among Durotar’s southern crags. A weathered stone carved with a fire rune marks an obscure path climbing toward one of the region’s highest peaks. At the summit, Telf Joolam, a troll hermit, watches over the Shrine of the Dormant Flame. He turns away curious travelers and treasure hunters, keeping the sacred brazier from ordinary eyes until a petitioner arrives with the unlit torch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1524-c4147d6b4c173a68a4ae/1-0000.mp3", duration = 60.5257143, start = 0},
  },
}
P.transport["quest:1525"] = {
  hash = "f57efc",
  fullHash = "f57efc",
  text = "Call of Fire. Telf Joolam sends you through Durotar and the eastern Barrens to gather what he needs for a Fire Sapta. The draught prepares an initiate to see and speak with fire spirits. A Fire Sapta opens a shaman’s senses to the Eternal Flame. Like the draught for earth, it lets you see and speak with spirits hidden from mortal sight. Telf Joolam sends you across Durotar and into the eastern Barrens for ingredients bound to heat and flame. Razormane quilboar spellcasters in the eastern Barrens carry fire tar, made in their earthy rituals. Burning Blade cultists carry the other ingredient in Dustwind Cave, in the ravines northeast of Razor Hill. They use fire for destruction and demonic chaos, yet the reagents in their pouches have a natural tie to the element.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1525-42769afef22ac4b6b0b9/1-0000.mp3", duration = 47.7518367, start = 0},
  },
}
P.transport["quest:1526"] = {
  hash = "06d98e",
  fullHash = "06d98e",
  text = "Call of Fire. On Durotar's peaks, Call of Fire puts a shaman to a trial of flame. Telf Joolam sends the initiate to drink fire sapta, face a Minor Manifestation of Fire, and claim its ember. On Durotar's summit, fire spirits remain hidden from untrained eyes. Drink fire sapta, a draught made from reagents gathered across the barrens and coast, and your senses sharpen to the unseen. Minor spirits and manifestations appear among the summit crags. A Minor Manifestation of Fire waits atop the mountain. Once the sapta takes hold, it knows you can see it and awaits your challenge. Fire answers strength and decisive action, so strike without delay. The longer the fight lasts, the more fiercely the elemental fire burns.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1526-9d92f0ccd50bd9bd16b3/1-0000.mp3", duration = 48.1436735, start = 0},
  },
}
P.transport["quest:153"] = {
  hash = "029417",
  fullHash = "029417",
  text = "Red Leather Bandanas. At Sentinel Hill, Red Leather Bandanas mark the Defias fight. Scout Galiaan seeks the red masks worn by outlaws as the People's Militia struggles to track them across Westfall. Across Westfall, a red bandana marks the Defias Brotherhood. Cutpurses, looters, and traitors from many walks of life join the gang, then rally beneath the same crimson sign. At Sentinel Hill, Scout Galiaan and the People's Militia collect the cloth as proof that bandits have fallen. The bandanas also help them follow the Defias as its fronts shift across the countryside. Stormwind has denied Westfall proper military support, leaving the People's Militia to chart Defias activity with seasoned observers like Scout Galiaan. From Sentinel Hill, Galiaan watches outlaw patrols and tracks their movements. Passing adventurers and militia volunteers take on the dangerous work of bringing down the highwaymen who drove honest farmers from their land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_153-5dbbb957793456aacc34/1-0000.mp3", duration = 59.2457143, start = 0},
  },
}
P.transport["quest:155"] = {
  hash = "3f98f0",
  fullHash = "3f98f0",
  text = "The Defias Brotherhood. In Westfall, the People's Militia seeks the Defias Brotherhood's hidden base. A captured brigand will guide you there in exchange for protection, leading through Moonbrook to Edwin VanCleef's inner sanctum. The Defias Traitor fears execution or assassination by his former brothers. So he bargains with the People's Militia: escort him safely through hostile territory, and he will reveal where Edwin VanCleef and his ringleaders hide. The thieves' network silences those who speak out, and the turncoat needs armed protection along the road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_155-bd2f81810784783b4ace/1-0000.mp3", duration = 34.7167347, start = 0},
  },
}
P.transport["quest:1578"] = {
  hash = "930d00",
  fullHash = "930d00",
  text = "Supplying the Front. In Loch Modan, Mountaineers need fresh arms as trogg attacks threaten their defenses. Tormus Deepforge sends apprentice smiths east to supply them. Excavations have opened ruins and caverns across the border. Troggs now strike the Mountaineers without warning. Their lines need fresh blades, belts, and fittings to hold against the attacks. Tormus sends apprentices east while veteran smiths stay at Ironforge’s city forges. His colleague Thorvald Deepforge keeps a field armory in the southern guard tower. There, sturdy copper axes and copper chain belts prove a smith’s reliability and earn advanced smithing techniques.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1578-6ee1af86f5caef371d38/1-0000.mp3", duration = 40.5420408, start = 0},
  },
}
P.transport["quest:1579"] = {
  hash = "1d2193",
  fullHash = "1d2193",
  text = "Gaffer Jacks. Near Auberdine, Wizbang Cranktoggle needs his lost gaffer jacks. He lost a box of hardware overboard on his voyage from Ironforge, and the parts lie somewhere along Darkshore's coast. Wizbang Cranktoggle crossed the Great Sea from Ironforge seeking quiet in Darkshore. The gnome inventor drank too much on the voyage. In a drunken haze, he leaned over the rail and lost a crate of specialized metal parts called gaffer jacks in the water near Auberdine. Wizbang says gaffer jacks are essential precision tools. Without them, he cannot tune his stintle pegs or continue his delicate tinkering. He will not wade into the cold surf himself, so he asks local anglers to cast along Darkshore's shore and fish up the scattered parts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1579-2d7e5e97ff66b018c0d3/1-0000.mp3", duration = 47.7518367, start = 0},
  },
}
P.transport["quest:1580"] = {
  hash = "0dd6e7",
  fullHash = "0dd6e7",
  text = "Electropellers. In Darkshore, Wizbang Cranktoggle wants his lost electropellers back. A mishap with an explosive duck decoy scattered the prototype parts in freshwater streams. Wizbang Cranktoggle went inland one evening to find a place to test his latest invention. The gnome tinkerer, based in Auberdine, had built a self-propelled duck decoy that explodes. He drank too much and blacked out. Hours later, he woke in town with singed hair and an empty pack; his bag of electropellers had fallen into one of the coastal rivers. Wizbang asks local fishermen to dredge Darkshore's freshwater streams, for he will not brave the wilds himself. Anglers on the Wildbend River and Cliffspring River can snag the buoyant metal parts along with local fish. Once the components are back, Wizbang can resume his erratic waterfowl experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1580-1531f923fc68f7055200/1-0000.mp3", duration = 51.4612245, start = 0},
  },
}
P.transport["quest:1581"] = {
  hash = "172329",
  fullHash = "172329",
  text = "Elixirs for the Bladeleafs. In Dolanaar, Syral Bladeleaf seeks help supplying her family's busy trade. Her husband spends nearly all his time brewing, and fresh elixirs could ease his burden while bringing him uncommon herbs. Dolanaar sees travelers, sentinels, and druids crossing Teldrassil. Syral Bladeleaf and her husband have built a thriving herb and alchemy trade to serve them. Demand keeps him at vials and cauldrons for nearly all his waking hours. The work leaves little time for the two of them. Syral asks passing herbalists and brewers to ease her husband's workload. She seeks Elixirs of Lion's Strength and Minor Defense, and offers freshly gathered, uncommon herbs in exchange. For a budding alchemist beneath the Great Tree, the trade brings a bundle of herbs and a chance to turn common forest plants into prized local wares.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1581-12138b0d7927260699f7/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["quest:1582"] = {
  hash = "e886da",
  fullHash = "e886da",
  text = "Moonglow Vest. In Darnassus, Lotherias prepares leather gear for young adventurers setting out across Kalimdor. She offers a night elf pattern in return for shipments of embossed leather goods. Darnassus leatherworkers outfit sentinels and young scouts. Night elves and allied wanderers leave Teldrassil for Kalimdor's wilds, where sturdy armor is in demand. Lotherias is a master leatherworker who supplies them with gear. Lotherias asks apprentices to bring matching embossed gloves, boots, and cloaks to show their skill. Those who fulfill her order earn her trust. She teaches them a night elf pattern for a vest that protects while allowing free movement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1582-99b3cde9d6637288f3e9/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:1598"] = {
  hash = "6da5ac",
  fullHash = "6da5ac",
  text = "The Stolen Tome. At Northshire Abbey, Drusilla La Salle seeks a stolen tome from the Defias camp in the vineyards. Powers of the Void could aid her teaching, and bringing it back will prove your skill. Warlocks in Stormwind's lands keep their craft and their research from prying eyes. Northshire Abbey guards forbidden grimoires in its archives. Drusilla cannot risk suspicion from the clerics and paladins by entering the protected wing herself. She covets Powers of the Void and needs another to retrieve it. An abbey novice joined the Defias Brotherhood and stole several valuable texts as he left. He fled to the Northshire Vineyards and took refuge near the Defias campsite. The thieves keep their prize in a field tent, unaware of the danger in the book's dark arts. Recovering Powers of the Void tests your nerve and opens the way to darker knowledge. Returning the tome satisfies Drusilla's ambition and proves you are ready to practice the dark arts. She rewards you with the rites to summon and bind an imp, the first demon an apprentice learns to command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1598-5849655a6e544d16cb1e/1-0000.mp3", duration = 65.515102, start = 0},
  },
}
P.transport["quest:1599"] = {
  hash = "25dff9",
  fullHash = "25dff9",
  text = "Beginnings. In Dun Morogh, Alamar Grimm tests Alliance warlock novices before teaching them to summon an imp. First, they must take feather charms from Frostmane troll novices. Influential voices have noticed a recruit with promise, and their attention draws Alamar Grimm from his occult research. Though reluctant, the warlock comes to assess the novice. Before teaching a novice to enslave lesser demons, Grimm demands proof of endurance and magical affinity. Frostmane troll novices carry feather charms in a cave southwest of Anvilmar. Subtle primal magic runs through the charms, and taking them proves the novice can overcome a magical foe. The curious specimens also serve Grimm's research. The charms persuade Grimm that the novice has the will to survive. He teaches the summoning of an imp, a warlock's most basic minion. Its chaotic fire magic can overpower a master who lacks discipline.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1599-2e6c5a573152dfb62486/1-0000.mp3", duration = 58.4359184, start = 0},
  },
}
P.transport["quest:16"] = {
  hash = "404434",
  fullHash = "404434",
  text = "Give Gerard a Drink. At the Maclure Vineyards, Gerard Tiller works long days in the fields and needs fresh spring water. Passing travelers bring water and trade it for apples. Elwynn's farms supply grain, fruit, and vegetables to Stormwind's townsfolk and garrisons. The work is hot beneath the open sky. At the Maclure Vineyards, Gerard Tiller tends the crops, keeps pests away, and manages the harvest. With little time to reach the town wells, he depends on passing recruits to bring clean spring water so he can keep working. Gerard trades provisions for water instead of coin. Travelers with extra flasks of Refreshing Spring Water can exchange them for fresh apples from his orchard. The kingdom stretches its resources to keep order and feed its army. So barter between smallholders and recruits remains a practical way to get by in rural Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_16-09299614ace62bb8be1f/1-0000.mp3", duration = 51.4873469, start = 0},
  },
}
P.transport["quest:161"] = {
  hash = "3aeee0",
  fullHash = "3aeee0",
  text = "A Dark Threat Looms. At Stonewrought Dam, Chief Engineer Hinderweir the Seventh suspects sabotage and sends a powder sample north for examination. A courier must carry it through the Wetlands to demolition expert Ashlan Stonesmirk at Dun Modr. A suspicious barrel near the dam’s eastern ramp held a strange-smelling powder. Hinderweir had seen Dark Iron sappers nearby, and suspects the powder is a refined explosive meant to shatter dwarven masonry. The dam has no specialized equipment to test it. Before he can be certain, he needs a military demolitionist to examine the sample. The road runs through the Algaz Gate and down into the sodden lowlands of the Wetlands. Hostile wildlife, aggressive dragonkin, and Dark Iron infiltrators make the way dangerous. Hinderweir urges couriers to keep to the cobbled road to Dun Modr. The pillaged dwarven town stands at the southern approach to the Thandol Span, where an Ironforge regiment still keeps watch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_161-3a893f8cb69f04d95790/1-0000.mp3", duration = 62.2497959, start = 0},
  },
}
P.transport["quest:1618"] = {
  hash = "9cf5d0",
  fullHash = "9cf5d0",
  text = "Gearing Redridge. In Lakeshire, a hard pressed garrison needs sturdy copper gear from Ironforge. Tormus Deepforge asks aspiring Alliance smiths to forge it and aid Verner Osgood as he helps defend the region from hostile orcs and gnolls. The Great Forge sends help beyond Dun Morogh, where the Alliance's front line is under strain. In the Redridge Mountains, Lakeshire faces repeated attacks from Blackrock orcs marching from Stonewatch Keep and gnolls roaming the northern ridges. Stormwind's royal reinforcements are slow to arrive, and local supplies are dangerously low. Verner Osgood, Lakeshire's resident blacksmith, works nearly alone at his outdoor forge. He mends shattered armor and replaces broken weapons. Seeing his human counterpart under strain, Tormus Deepforge asks developing smiths to bring four Runed Copper Belts and four Heavy Copper Mauls to Lakeshire. The gear strengthens the militia's reserves, and Verner teaches traveling craftsmen finer trade techniques.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1618-aace6c2141edc6ac8fab/1-0000.mp3", duration = 59.9510204, start = 0},
  },
}
P.transport["quest:1638"] = {
  hash = "150110",
  fullHash = "150110",
  text = "A Warrior's Training. Lyria Du Lac sends young warriors from Goldshire to Stormwind for lessons in battlefield endurance. At the Pig and Whistle Tavern in Old Town, veteran Harry Burlguard puts them through seasoned instruction. When you have shown your skill against threats across Elwynn Forest, Goldshire's trainers have little more to teach. So Lyria Du Lac sends you to Stormwind and the rough district of Old Town. Veteran fighters gather there to share what combat has taught them, far from the royal garrison's rigid ways. Harry Burlguard is an aged battle veteran who keeps his quarters at the Pig and Whistle Tavern. He tests your mettle with drink and practical trials of stamina, not parade-ground drills. Before teaching defensive moves for dangerous campaigns, Harry expects you to match his appetite for drink and face the tavern's local brawlers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1638-ebda6248fdcad5fc25fb/1-0000.mp3", duration = 52.4538776, start = 0},
  },
}
P.transport["quest:1639"] = {
  hash = "293f57",
  fullHash = "293f57",
  text = "Bartleby the Drunk. In the Pig and Whistle Tavern, Bartleby the Drunk faces Harry Burlguard’s test. An aspiring Alliance warrior must take Bartleby’s prized mug before Harry teaches deeper combat skills. Harry Burlguard asks you to prove your backbone before he teaches deeper combat skills in the Pig and Whistle Tavern. Across the room, Bartleby nurses his drinks at the far end of the counter. Harry wants you to take the man’s mug, knowing Bartleby would rather fight than surrender his ale. The challenge tests your resolve. Soldiers, laborers, and rough locals fill the Pig and Whistle, where polished manners count for little. Bartleby mocks newcomers as too prissy for a tavern scuffle instead of answering politely. The exchange leads to a brawl on the floorboards. In Stormwind, a warrior’s training begins with a test of basic barroom fighting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1639-6c5877cf9e3603fccf5e/1-0000.mp3", duration = 52.3493878, start = 0},
  },
}
P.transport["quest:1640"] = {
  hash = "1b4e50",
  fullHash = "1b4e50",
  text = "Beat Bartleby. In Stormwind, Beat Bartleby keeps a prized mug from the warrior instructors. He will not give it up, so a recruit must win it in a brawl. The warrior instructors make no claim that combat is noble or grand. Bartleby swears no one will take his prized mug without prying it from his cold, dead fingers. So you settle the matter with your fists. For a fledgling warrior, words give way to a brawl. Bartleby boasts that he will fight to the death, but a thorough thrashing sobers him. Bruised admiration replaces his bravado when he sees your strength, and he yields peacefully. You can take the mug to the training hall and complete your trial.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1640-f9babcc0ad0d36c6cf1f/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["quest:1641"] = {
  hash = "b8bcdd",
  fullHash = "b8bcdd",
  text = "The Tome of Divinity. In Stormwind's Cathedral of Light, Duthorian Rall guides you through a solemn rite for young paladins. Its teachings test your virtue and devotion to the Holy Light. Your training now reaches beyond arms and the order's rites. Duthorian's trials ask you to weigh a paladin's moral duties and grasp the deeper promise your calling demands. Those who depend on the Holy Light need defenders who understand what that duty means. The Book of Divinity binds you to service and self-sacrifice. Duthorian asks you to study its holy text and learn what the Light demands of its defenders. Its lessons prepare you to oppose the Scourge's creeping horrors and protect common folk. Virtue and compassion must guide your power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1641-083d77d2e7190e7132b1/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["quest:1645"] = {
  hash = "77bfad",
  fullHash = "77bfad",
  text = "The Tome of Divinity. In Ironforge, Tiza Battleforge puts the Tome of Divinity into a dwarven paladin's hands. Its teachings begin trials of devotion to the Light and readiness to defend Azeroth from dark forces such as the Scourge. From across the eastern kingdoms, promising paladin initiates come to Ironforge's Hall of Mysteries after mastering the martial and spiritual basics. There, young dwarven paladins learn what sets a champion of the Holy Light apart from an ordinary warrior. Taking up this calling means pledging a life to duty, self-sacrifice, and spiritual discipline. The novice receives the Book of Divinity as a guide to its duties, virtues, and spiritual teachings. Its words show how sacred power can be wielded against wicked threats. Yet study is only the first step. The initiate must carry those lessons into acts of faith across Khaz Modan and beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1645-b3a281d8300d05261aaf/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["quest:1665"] = {
  hash = "3dc21d",
  fullHash = "3dc21d",
  text = "Bartleby's Mug. In Stormwind's Pig and Whistle Tavern, Bartleby faces a young warrior's trial. After you best him, you take his drinking mug to your trainer, Harry Burlguard. In Old Town, Harry Burlguard tests young warriors with a brawl. He sends you to face Bartleby, a stubborn drunk at the bar of the Pig and Whistle Tavern. Once subdued, Bartleby reluctantly gives up his prized drinking mug. First, he takes one last swig to drain the dregs. When you return the mug, Harry Burlguard accepts it as proof of your novice trial. He sees that you can win another's compliance through force and judges you ready to learn defense. Then he points you toward Marshal Haggard, a seasoned veteran in Elwynn Forest, for further instruction on the battlefield.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1665-2f3b4cf5a217bded7575/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["quest:1666"] = {
  hash = "675be4",
  fullHash = "675be4",
  text = "Marshal Haggard. At Eastvale, Marshal Haggard keeps the arms he gathered over a lifetime of service. Harry Burlguard sends novice warriors from Stormwind City to meet the retired marshal and seek better weapons. Stormwind's novice warriors need more than skill to face danger beyond the city. Harry Burlguard sends promising fighters east through Elwynn Forest to meet Marshal Haggard, a retired officer who served the realm for years. Over a lifetime in the field, Haggard gathered a personal armory. His home near the Eastvale Logging Camp holds weapons for young warriors seeking better arms. Marshal Haggard lives in a secluded manor near the Eastvale Logging Camp. Years of service have weakened his sight, and he sometimes mistakes approaching travelers for prowling riverpaw gnolls. Age keeps him in this quiet corner of eastern Elwynn. Even so, Stormwind's guards and trainers still respect the old marshal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1666-ca3eaeb6b24cab443ec3/1-0000.mp3", duration = 57.2865306, start = 0},
  },
}
P.transport["quest:1667"] = {
  hash = "3a323e",
  fullHash = "3a323e",
  text = "Dead-tooth Jack. In eastern Elwynn Forest, retired Marshal Haggard needs your help: Dead-tooth Jack tricked him into giving up his badge. Jack wore a Stormwind tabard and pretended to be Marshal Dughan. Haggard fears the Defias Brotherhood will use the badge to impersonate Stormwind officials. At night, a figure wearing a Stormwind tabard came to Haggard's isolated cottage on Elwynn's eastern ridges. The stranger claimed to have official business and asked for Haggard's old marshal's badge. Haggard believed he was handing it to a fellow officer, so he gave it over. The figure laughed and vanished into the woods. He was a Defias rogue called Dead-tooth Jack. Marshal Haggard has retired, but his badge still carries Stormwind's legal authority. Defias bandits are creeping across Elwynn, Westfall, and Redridge. With the badge, they could pass guard checkpoints, redirect patrols, or take command of supplies. Jack retreated to a camp to the south and locked the badge in a strongbox. Haggard needs it back before the Defias cause serious harm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1667-b5a0cf18affce6c00a4d/1-0000.mp3", duration = 63.8955102, start = 0},
  },
}
P.transport["quest:1679"] = {
  hash = "b742ca",
  fullHash = "b742ca",
  text = "Muren Stormpike. In Ironforge, Muren Stormpike awaits warriors sent from Kharanos for formal training. Granis Swiftaxe sends recruits who have proved their mettle in Dun Morogh to the city's Military Ward. Granis Swiftaxe sends promising warriors from Kharanos to Ironforge after they face local threats in Dun Morogh. He knows rough skirmishes can teach only so much. In the Military Ward, senior fighters oversee formal training for those bound for battle. At the Hall of Arms, you meet Muren Stormpike, a veteran of a storied dwarven clan. He wants proof that his new charges can endure real combat, not tavern tales. Reporting to him opens the way to learn defensive arts, control an enemy's aggression, and earn iron arms for the front line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1679-06691e055e25331c9d5a/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["quest:168"] = {
  hash = "98bd83",
  fullHash = "98bd83",
  text = "Collecting Memories. In Stormwind City, Wilder Thistlenettle asks you to remember the miners lost beneath Moonbrook. He wants their Miners' Union Cards returned to their grieving families. Before the Defias Brotherhood brought lawlessness to Moonbrook, Westfall's mines supported many working-class families. Wilder Thistlenettle survived when a cave-in buried one wing of the tunnels. Many friends and fellow miners died underground, beyond the reach of rescue. Their families in Stormwind never learned for certain what became of them. The miners killed in the collapse now wander the tunnels outside the main iron works as undead. You search those haunted passages for their Miners' Union Cards and face the remains of the men Wilder worked beside. Bring the cards back to Stormwind so their families can learn what happened and Wilder can honor his fallen companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_168-6565ce36a4fad33a3a3b/1-0000.mp3", duration = 53.6032653, start = 0},
  },
}
P.transport["quest:1681"] = {
  hash = "a33a6b",
  fullHash = "a33a6b",
  text = "Ironband's Compound. At Ironband's Compound, Tormus Deepforge seeks vengeance for his slain mentor, Sturgy Ironband. Rare umbral ore drew the Dark Iron dwarves to the outpost and brought it down. South of Helm's Bed Lake, Sturgy Ironband taught smithing at a compound away from the Great Forge's crowded anvils. Promising pupils came there to train under a master revered across Ironforge as an unmatched instructor. Then one student acquired an unfamiliar mineral called umbral ore, and Sturgy chose to experiment with it. He did not know that its presence had marked his school for ruin. Soon after the umbral ore arrived, Dark Iron dwarves attacked the compound. They killed Sturgy Ironband and every apprentice in his care, then took over the grounds. Tormus Deepforge, one of Ironband's surviving protégés in the capital, refuses to let the massacre go unanswered. He sends Alliance travelers to avenge his teacher and recover the ore that brought destruction to the outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1681-44bf8a12e831f4f4b93f/1-0000.mp3", duration = 62.0146939, start = 0},
  },
}
P.transport["quest:1683"] = {
  hash = "b69f30",
  fullHash = "b69f30",
  text = "Vorlus Vilehoof. In Darnassus, Elanaria sets young night elf warriors a trial. They must hunt a satyr defiling a hidden moonwell near the Ban'ethil Barrow Den. Elanaria asks you to prove your dedication and discipline before she teaches advanced martial techniques. Those who defend Kalimdor must offer more than words. A guardian must face corruption and cleanse the sacred boughs of Teldrassil. Your trial leads to a moonwell in the mountains southeast of Ban'ethil Barrow Den. There, Vorlus Vilehoof hides. Satyrs were ancient betrayers, twisted by demonic influence, and they hate sacred Kaldorei relics. Vorlus bathes in the moonwell, fouling its blessed waters and mocking Elune's grace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1683-ff8eacc5f303ec80ef46/1-0000.mp3", duration = 44.5910204, start = 0},
  },
}
P.transport["quest:1685"] = {
  hash = "2901af",
  fullHash = "2901af",
  text = "Gakin's Summons. In Stormwind, Gakin's Summons draws promising warlocks beneath the Slaughtered Lamb. Remen Marcot brings Gakin the Darkbinder's message, sending fledgling practitioners to the crypts under the tavern in the Mage Quarter for further occult training. Demonology is forbidden in Stormwind's settled districts, yet its practitioners work near the city guard. When a warlock shows skill with introductory imps, word reaches senior warlocks in secret. Remen Marcot carries their message quietly and urges new practitioners to keep the meeting place private as they make their way beneath the Mage Quarter. Cellars and hidden catacombs lie behind the Slaughtered Lamb's modest front. Gakin the Darkbinder teaches Stormwind's warlocks there, beyond the reach of Kirin Tor mages and the Cathedral's inquisitors. Under his guidance, warlocks learn to command a voidwalker. The rite demands dangerous stolen reagents and perilous summoning circles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1685-4894f49c59b6bca33171/1-0000.mp3", duration = 59.5591837, start = 0},
  },
}
P.transport["quest:1686"] = {
  hash = "356a42",
  fullHash = "356a42",
  text = "The Shade of Elura. Elanaria sends young night elf warriors beneath Auberdine's waves to lay Elura to rest. They seek her medallion and Elunite ore for a weapon Smith Mathiel will forge. Long ago, a ship laden with rare Elunite ore struck rocks near the Auberdine lighthouse and sank. Its captain, Elura, cursed her own soul in despair and from unwavering duty. Bound to the wreck beneath the waves, her shade guards the lost cargo from anyone who would disturb it. Elanaria sends young night elf warriors into Darkshore's surf to defeat Elura and recover her medallion and ore. Both are needed to put the captain to rest, and the metal goes to Smith Mathiel's forge. The trial tests their martial skill and respect for the fallen. It also provides ore for a crafted weapon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1686-2750c5463167027425d3/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["quest:1688"] = {
  hash = "5f3bc0",
  fullHash = "5f3bc0",
  text = "Surena Caledon. Beneath the Slaughtered Lamb in Stormwind, Gakin seeks his former pupil and the bloodstone choker she carries. He sends a new apprentice after Surena Caledon, who betrayed him and joined the Defias Brotherhood. Beneath the Slaughtered Lamb in Stormwind's Mage Quarter, Gakin the Darkbinder teaches novices the forbidden arts of fel summoning. Once, he took Surena Caledon as his pupil. He admired her natural magical talent and her beauty. But Surena left her studies and Gakin's favor, then fled Stormwind with her lover, Erlan Drudgemoor, to join the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1688-31336c9dcab8f70343ab/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["quest:1689"] = {
  hash = "667b2d",
  fullHash = "667b2d",
  text = "The Binding. Beneath Stormwind, Gakin the Darkbinder sets you a final trial. With his recovered Bloodstone Choker, you draw a voidwalker into a hidden circle and force it to submit. Below the Slaughtered Lamb in Stormwind's Mage Quarter lie catacombs beyond the watch of the Silver Hand and Kirin Tor magistrates. Gakin teaches that dark magic takes more than power. It demands mastery over beings from beyond this world. You recovered his stolen Bloodstone Choker from Surena Caledon. Now he asks you to summon a voidwalker beneath the tavern. A voidwalker will not bargain with you. The Bloodstone Choker opens a rift and draws the shadow creature into the mortal world. You batter it with magic and force until its will breaks. Then its essence binds to you, giving you a durable shadowy protector that can endure punishment in the battles ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1689-c55081aba41b37a57eb7/1-0000.mp3", duration = 52.8195918, start = 0},
  },
}
P.transport["quest:1692"] = {
  hash = "fa0114",
  fullHash = "fa0114",
  text = "Smith Mathiel. In Darnassus, sacred elunite ore is on its way to the forge. After you recover it from the haunted shipwreck off Auberdine, Elanaria sends you to Mathiel to shape it into a weapon for the Kaldorei. Elanaria sends you across Darnassus's Warrior's Terrace with the elunite ore you recovered from the haunted shipwreck off Auberdine. The warrior trainer packs the ore in a sturdy case and directs you to Mathiel, one of the capital's finest smiths. He can shape the metal into a weapon worthy of your calling. Mathiel treats smithing as an act of devotion. Elunite bears the sacred blessing of Elune, the Moon Goddess, and he accepts the case as an honor. He will shape the holy metal into arms to defend the young boughs of Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1692-f2e92ef6efa072f023da/1-0000.mp3", duration = 46.9420408, start = 0},
  },
}
P.transport["quest:1693"] = {
  hash = "181d4b",
  fullHash = "181d4b",
  text = "Weapons of Elunite. In Darnassus, Weapons of Elunite brings a young warrior's rite of passage to its end. You carry ore blessed by Elune to Mathiel, who forges it into arms for a defender of Kalimdor. Night elf warriors defend Teldrassil and the kaldorei people. Promising young warriors gather elunite, a mineral blessed by the Moon Goddess, to arm themselves beyond ordinary steel. Its ore needs a smith skilled in metalcraft and mindful of Elune's gift. Mathiel works in Darnassus, shaping blessed elunite into weapons of war. He considers the work an honor, not routine metalcraft. Bring him the ore, and he forges arms to suit your style. For your service, he gives you weapons blessed by your goddess.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1693-da427f1dc74648d397a8/1-0000.mp3", duration = 45.7404082, start = 0},
  },
}
P.transport["quest:170"] = {
  hash = "8c4184",
  fullHash = "8c4184",
  text = "A New Threat. Balir Frosthammer calls for aid as Rockjaw troggs surge through Coldridge Valley and threaten its settlements and camps. Rockjaw troggs claw up from below in growing numbers. Reports reach Anvilmar of troggs swarming the frozen lake and nearby foothills. They disrupt patrols and cut supply routes through the valley pass. For young dwarven warriors and mountaineers, this valley has long been a place to train. Now the threat reaches it. A coordinated trogg attack has overrun a dwarven camp west of the valley. The mountaineers retreated and left their posts. Ironforge cannot spare full battle regiments, so Balir Frosthammer calls on newly recruited adventurers to fight through the Rockjaw ranks. The hills must be secured before the creatures reach Anvilmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_170-fb68066e30e94f44dd5c/1-0000.mp3", duration = 49.1885714, start = 0},
  },
}
P.transport["quest:1715"] = {
  hash = "643dd0",
  fullHash = "643dd0",
  text = "The Slaughtered Lamb. Gnome warlocks from Ironforge now seek their training in Stormwind. The Slaughtered Lamb gives them a place to learn from human warlocks, while King Magni Bronzebeard keeps watch over dark practitioners at home. Before Gnomeregan fell, Khaz Modan's aspiring warlocks studied with tinker-mages and demonic scholars in the techno-city. Then disaster scattered those schools and drove the gnomes into exile. The survivors crowded into Ironforge's underground caverns, where King Magni Bronzebeard and the dwarven guard watch them. They cannot openly practice demonic arts or perform dangerous rituals, so senior instructors like Lago Blackwrench send students away. From Ironforge, gnome students travel south to the Slaughtered Lamb in Stormwind's Mage Quarter. Twisting stone passages and stairs descend from the tavern's taproom to a hidden sanctum where human warlocks gather. Gakin the Darkbinder oversees them there. In its shadowed rooms, instructors can teach novices to summon and bind minor demons without drawing the city marshals' immediate anger. Stormwind's coven welcomes capable hands, though refugee novices bring new strain. Human mentors already risk discovery by the city's paladins and authorities. As more practitioners arrive from Khaz Modan, Gakin and his colleagues find their sanctuary growing crowded. The steady flow from the dwarven mountain could expose their hidden gathering. Yet neither the gnomes nor the human warlocks have an easier choice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1715-e112f0eba1a910b8ea74/1-0000.mp3", duration = 94.2497959, start = 0},
  },
}
P.transport["quest:176"] = {
  hash = "423cb4",
  fullHash = "423cb4",
  text = "Wanted: \"Hogger\". In southwestern Elwynn, Hogger has turned back every local attempt to bring him down. The Alliance bounty posted outside Goldshire seeks the head of this massive, savage gnoll chieftain. Banditry and kobold infestations trouble Elwynn Forest, while gnolls in the south grow bolder and more organized under Hogger's brutal leadership. Taller than typical Riverpaw gnolls, he has made camp near the Forest's Edge. From there, he ambushes travelers and overpowers the local militia patrols sent to subdue him. The Stormwind Army is stretched thin and cannot spare regular forces to police the capital's outskirts. So Marshal Dughan has taken the unusual step of posting an open bounty on Hogger. Hunting him means venturing into deeply hostile gnoll territory. His ferocity has earned him a fearsome reputation among novice adventurers in Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_176-10c19684985e2b597cdc/1-0000.mp3", duration = 53.1591837, start = 0},
  },
}
P.transport["quest:179"] = {
  hash = "25cb1a",
  fullHash = "25cb1a",
  text = "Dwarven Outfitters. In Coldridge Valley, Sten Stoutarm offers new recruits a bargain. Hunt wolves for their tough meat, and he provides sturdy gloves against Dun Morogh's cold. Cold reaches every path through Coldridge Valley. Outside Anvilmar, Sten Stoutarm asks new recruits to hunt wolves in the snowy drifts and bring their tough meat to the outpost. In return, he gives them gloves to guard their hands from the cold. Wolves threaten the dwarven scouts and young gnomes training in the valley. Yet they also feed the garrison at Anvilmar. Hunting them makes the paths between local encampments somewhat safer. Stoutarm's bargain tests recruits against local wildlife and adds food for the bitter nights ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_179-5e1e19dd2746f9cc9c97/1-0000.mp3", duration = 44.9044898, start = 0},
  },
}
P.transport["quest:18"] = {
  hash = "31e857",
  fullHash = "31e857",
  text = "Brotherhood of Thieves. Across Northshire's eastern river, the Defias Brotherhood has begun to trouble the valley. Deputy Willem sends recruits to face the brigands, whose red burlap bandanas give Stormwind its first clear sign of their organized presence. Northshire Valley has long been a safe haven in Elwynn Forest. Stormwind guards it, and recruits and Clerics of the Holy Light train there. Lately, though, the valley's watch has grown thin. Vagrants and thieves cross the eastern river and hide near the woods. They make small camps close to the abbey.\n\nDeputy Willem keeps order, but the guards cannot watch every corner of the valley. He needs volunteers to help hold the line. The outlaws move together and wear matching red burlap bandanas. They call themselves the Defias Brotherhood, and the cloth marks their allegiance. Deputy Willem sends recruits to drive back the brigands and recover their masks. He hopes to slow their advance and learn how far the Defias have reached into the kingdom's heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_18-7fa1ba6257d5f9051fd2/1-0000.mp3", duration = 62.3281633, start = 0},
  },
}
P.transport["quest:1818"] = {
  hash = "6ece0d",
  fullHash = "6ece0d",
  text = "Speak with Dillinger. At Brill's Gallows' End Tavern, Austil de Mon sends fighters on a hazardous mission for Lady Sylvanas. The order sends able-bodied recruits to Deathguard Dillinger at the village's west end. At the Gallows' End Tavern in Brill, warrior trainer Austil de Mon seeks fighters willing to serve the Dark Lady. When the Deathguards need capable hands, he sends untested recruits into the field. Deathguard Dillinger oversees security on Brill's western edge and has requested someone with martial skill for an urgent task. The Forsaken must constantly prove their martial dominance on Tirisfal Glades' front line. Near Brill's graveyard, Dillinger manages local incursions. Reporting to him tests your combat skill and loyalty to the newly forged Forsaken nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1818-da8531707da0b562826b/1-0000.mp3", duration = 49.0318367, start = 0},
  },
}
P.transport["quest:1819"] = {
  hash = "911f86",
  fullHash = "911f86",
  text = "Ulag the Cleaver. Beneath a mausoleum north of Brill, Ulag the Cleaver awaits a trial for young Forsaken. Deathguard Dillinger sends you to free the captive and meet him in combat. After the Scourge swept across Lordaeron, the Forsaken captured an unusual undead warrior who named himself Ulag the Cleaver. His mind stayed clear, but the Lich King still held his spirit in psychic thrall. Beneath a mausoleum north of Brill, the Forsaken bound him with a magical seal. They hoped to learn how the Scourge chained a mind and to break its hold over Ulag. The Forsaken could not free Ulag from the Lich King's command. Now Deathguard Dillinger sets the captive as a combat trial for rising Forsaken warriors. Disturb the skull stone outside the crypt, and the wards break, freeing Ulag from his prison. A warrior must face him with an axe. Death will release him at last.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1819-128ca50a93a69fb421de/1-0000.mp3", duration = 53.5510204, start = 0},
  },
}
P.transport["quest:182"] = {
  hash = "b28127",
  fullHash = "b28127",
  text = "The Troll Cave. In southern Coldridge Valley, Grelin Whitebeard sends you against Frostmane whelps settling in a cave. Their growing camp threatens nearby dwarven homesteads. Grelin watches the frozen valley from a bluff as Ironforge's soldiers fight troggs across the snowfields. He and his brother Senir came on the mountain authorities' orders to learn whether the native ice trolls threatened the heartland. Now Grelin keeps watch alone, tracking their movements along the southern approaches. Grelin found the local Frostmane clan settling in a deep cave along Coldridge Valley's southern ridge. He judges a full mobilization a waste of dwarven manpower, so he hires capable local volunteers to cull the aggressive whelps. Thinning the young fighters could disrupt the camp before the Frostmane launch coordinated raids against nearby dwarven homesteads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_182-d62d3648a2c2e145d786/1-0000.mp3", duration = 51.3828571, start = 0},
  },
}
P.transport["quest:1820"] = {
  hash = "08323e",
  fullHash = "08323e",
  text = "Speak with Coleman. In Brill, Deathguard Dillinger sends proven fighters to Coleman Farthing for help. Their meeting in the tavern opens the way to a private matter tied to the old Agamand lands. You have helped contain grave threats near Brill, including Ulag the Cleaver. So Deathguard Dillinger trusts your strength. He watches the roads into town and chooses who can take on work beyond the usual patrols. Seeing you are ready, he points you toward people who need specialized help. Not every fight in Tirisfal Glades begins with orders from the Undercity. The surviving undead of Lordaeron still bear grudges over the lands, families, and fortunes they left behind. Coleman Farthing waits in the Gallow's End Tavern for a fighter willing to strike at threats near former settlements such as the Agamand Mills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1820-3f40e47d2fdfc6fda19a/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["quest:1821"] = {
  hash = "0420a1",
  fullHash = "0420a1",
  text = "Agamand Heirlooms. At Agamand Mills, Coleman Farthing sends you after heirlooms in the family crypt. He blames the Agamands for his death and seeks their ancestral weapons. Before the Third War devastated Lordaeron, Coleman Farthing served the wealthy Agamand family at their mills in Tirisfal Glades. Farthing blames his former lords for his death. Now raised into undeath among the Forsaken, he takes spiteful satisfaction in the Agamands' downfall. The once-proud family has become mindless minions enslaved to the Lich King. Farthing sends you to the Agamand Family Crypt beneath the northern bluffs of the mills. Restless dead and lingering Scourge wander its stone halls. He wants you to take four relics: the Agamand family sword, axe, dagger, and mace. Their loss would strip the bloodline of its remaining honor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1821-f228bd7c414b122eb61f/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["quest:183"] = {
  hash = "d3c6d3",
  fullHash = "d3c6d3",
  text = "The Boar Hunter. In Coldridge Valley, Talin Keeneye asks young recruits to thin the crag boars threatening the trails. Then seasoned hunters can track in peace. Coldridge Valley gives young mountaineers and Ironforge scholars a quiet, protected place to train. Through the harsh winter, small crag boars have multiplied across the valley. Their attacks now threaten everyone on the snowy trails. Hunting gives dwarves meat, hide, and practice in the field. When game grows numerous and attacks on sight, culling restores balance. Thin the crag boars across the valley slopes, and young adventurers prove their readiness for combat. Local hunters gain room to track without being overwhelmed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_183-7d3e483fdf6792f0cee7/1-0000.mp3", duration = 42.9191837, start = 0},
  },
}
P.transport["quest:184"] = {
  hash = "2fdf2c",
  fullHash = "2fdf2c",
  text = "Furlbrow's Deed. Farmer Furlbrow and Verna stand driven from their farm, while Defias bandits carry their land grant through Elwynn Forest. Return it to Farmer Furlbrow near the Westfall border, and the couple keeps its claim to the stolen homestead. A deed signed by Theodore and Verna Furlbrow turns up among Defias bandits in Elwynn. On its back, a crude note says the bandits drove the elderly farmer from his property. They carried the deed across the river into Elwynn to copy it and forge claims to other seized land. The note places the stranded Furlbrows just over the border, beside the road, after their wagon broke. The Defias have driven dozens of Westfall families from their ancestral land. They use force and false claims to seize more farms for the Brotherhood, while Theodore and Verna leave their own farm for safety. Their lawful deed preserves their claim if order ever returns to the province.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_184-63cb80723cc3e68dfc23/1-0000.mp3", duration = 52.9240816, start = 0},
  },
}
P.transport["quest:1858"] = {
  hash = "c0bc7a",
  fullHash = "c0bc7a",
  text = "The Shattered Hand. In Orgrimmar, Therzok tests rogues who seek a place in the Shattered Hand. He wants Tazan's recovered satchel opened with a key taken from an unwitting accomplice. You have Tazan's locked satchel, but it is no use without its key. Therzok expects a rogue to master the lock through skill, not brute force. So he sends you to Gamon, a tauren drunkard who frequents Orgrimmar's tavern. Gamon is easily distracted, and he once helped Tazan. That makes him a fitting mark for quiet theft. Take the key from Gamon without alerting the tavern. Then open the satchel and bring Tazan's logbook to Therzok in the Cleft of Shadow. A clean job meets the Shattered Hand's standards. Therzok gives you formal recognition as one of its operatives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1858-63de4d0e8c89cbf3430c/1-0000.mp3", duration = 49.5542857, start = 0},
  },
}
P.transport["quest:1859"] = {
  hash = "f23e5d",
  fullHash = "f23e5d",
  text = "Therzok. In Orgrimmar, Therzok awaits a promising rogue sent from Durotar. Kaplak has seen your skill in violence and stealth, and sends you to the Cleft of Shadow to meet a Shattered Hand operative. The new Horde honors Thrall, yet not all its servants fight openly beneath his banner. Word reaches Orgrimmar of a fighter skilled in violence and stealth, one willing to bend the rules of open warfare. The underground guild takes notice. Kaplak sends you beneath Orgrimmar's red stone cliffs to the Cleft of Shadow. Therzok waits there, hidden from the city's grunts. Lone cutpurses and ambushers are brought into the Shattered Hand, the Horde's covert network of daggers in the dark.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1859-cd8e051b18f5cfdf6a51/1-0000.mp3", duration = 42.4489796, start = 0},
  },
}
P.transport["quest:1860"] = {
  hash = "3c7b3d",
  fullHash = "3c7b3d",
  text = "Speak with Jennea. In Stormwind, novice mages from Goldshire come to Jennea Cannon after advancing beyond basic training in Elwynn Forest. Zaldimar Wefhellt sends them to her. In the Mage Quarter, the Wizard's Sanctum gathers the kingdom's senior mages for study and instruction in the arcane arts. They coordinate magical matters across the realm, and your training now has a place within that wider work. Jennea Cannon oversees local assignments, including reports on the security of Elwynn Forest and Stormwind, as well as your studies. Cautious about sharing grand secrets with a newly arrived apprentice, she receives your report as the beginning of your service to the wizarding order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1860-eec018e275b6319c6706/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["quest:1861"] = {
  hash = "5e027b",
  fullHash = "5e027b",
  text = "Mirror Lake. In Stormwind's Mage Quarter, novice Alliance mages are sent to test Mirror Lake for magical contamination. Jennea Cannon sends them southwest of the city gates to sample the waterfall spray. Azeroth's arcane currents were shaken by conflicts that began with the opening of the Dark Portal and continued through the Third War and the battle at Mount Hyjal. Those shocks tore ancient currents from their stable channels.\n\nIn Stormwind's Wizard's Sanctum, magi like Jennea Cannon watch the changes closely. They fear displaced arcane power could reach the wilderness and corrupt local ecosystems. Beneath the cliffs southwest of Stormwind's gates, Mirror Lake is a natural reservoir fed by mountain falls. The surrounding countryside depends on its waters.\n\nJennea sends novice mages with a glass flask to the waterfall's base, where they collect fresh spray. The Sanctum can then use scrying and reagent tests to learn whether wild magic is seeping into the public water supply.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1861-37ef7f81efdb4121d85c/1-0000.mp3", duration = 62.3542857, start = 0},
  },
}
P.transport["quest:1879"] = {
  hash = "5ddb68",
  fullHash = "5ddb68",
  text = "Speak with Bink. Magis Sparkmantle sends you to Bink in Ironforge, where her studies need an arcane specialist. Bink seeks someone who can wield magic and aid her work. Near Kharanos, Magis Sparkmantle sends apprentices who have outgrown their early exercises to answer Bink's call. In Ironforge's Mystic Ward, Bink studies in the Hall of Mysteries. Scholars, priests, and arcanists gather there. She watches each arriving apprentice closely, for raw potential without discipline can make a spellcaster dangerous in arcane work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1879-6a9f7e4580ac128813db/1-0000.mp3", duration = 34.6644898, start = 0},
  },
}
P.transport["quest:1881"] = {
  hash = "886f62",
  fullHash = "886f62",
  text = "Speak with Anastasia. In the Undercity, Cain Firesong sends a promising Forsaken mage to Anastasia Hartwell. Her summons calls you to the Magic Quarter for practical work among the Forsaken magi, with field investigations in Tirisfal Glades ahead. Cain Firesong trains young Forsaken mages in Brill. When he sees promise in a student, he sends them to the Undercity. There, the Forsaken magi study the arcane arts and plan defenses across Lordaeron. Cain decides which students are ready to serve more experienced practitioners. Those with real talent go to Anastasia Hartwell, who needs capable hands in the field. Anastasia Hartwell is one of the Undercity’s prominent mage instructors. She sends promising students into practical work for the Forsaken’s interests and territory, rather than letting them study incantations in safety. Answering her call begins your service among the Forsaken mages and their practical magical work in the years after the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1881-cf62335886ee26ba1043/1-0000.mp3", duration = 59.7159184, start = 0},
  },
}
P.transport["quest:1882"] = {
  hash = "f4fbe4",
  fullHash = "f4fbe4",
  text = "The Balnir Farmstead. In eastern Tirisfal, snapdragons at the Balnir Farmstead may reveal how far the Scourge's corruption has spread. Anastasia Hartwell sends young Forsaken mages to gather the flowers for study in the Undercity. Forsaken mages watch the borderlands for magical corruption. Anastasia Hartwell sends novice spellcasters to the Balnir Farmstead in eastern Tirisfal Glades to gather snapdragons from its gardens. The flowers absorb magical energies from the soil and air. Arcane scholars in the Undercity examine them to learn whether corruption from the Lich King's domain has reached Tirisfal. The Balnir Farmstead lies near the edge of the glades, close to the blighted wilderness of the Western Plaguelands. The Forsaken know the Lich King's plague rots the land, and Scourge corruption threatens their borders and security. Though the Forsaken wield dark arts of their own, Anastasia plans to pass the snapdragons to the apothecaries for study. Together, mages and alchemists can examine the danger and help defend Lordaeron's reclaimed heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1882-ccc67cd481f55f9ad694/1-0000.mp3", duration = 64.3657143, start = 0},
  },
}
P.transport["quest:1885"] = {
  hash = "1c3981",
  fullHash = "1c3981",
  text = "Mennet Carkad. In the Undercity, Marion Call sends you to report to Mennet Carkad. Deep in the Rogues' Quarter, he tests promising operatives for the Deathstalkers. Marion Call brings you a summons from Mennet Carkad. In the Undercity, higher leaders notice covert operatives, and Marion carries word when a scout or assassin is called to report. The Forsaken's intelligence arm is feared for its deadly work. Ignoring its orders is no real choice. Mennet Carkad waits in the Rogues' Quarter, where he watches recruits and judges their readiness. Those who answer his call face tests for entry into the Deathstalkers, the Forsaken's feared arm of espionage and assassination. To serve the Dark Lady from the shadows, obedience comes first.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1885-591e8391d7455b0df3fe/1-0000.mp3", duration = 48.6922449, start = 0},
  },
}
P.transport["quest:1886"] = {
  hash = "30e62f",
  fullHash = "30e62f",
  text = "The Deathstalkers. Mennet Carkad tests hopeful Deathstalkers in the Undercity by sending them after a traveling messenger. Only the ruthless will find a place in Lord Varimathras's covert order. In the Rogues' Quarter, Mennet Carkad sets a trial for anyone seeking a place among the Deathstalkers. They serve Varimathras as the Forsaken's secret police and elite assassins. A hopeful agent must show cunning and discretion, then prove the will to eliminate a target. Carkad means to turn away the weak and anyone troubled by too many scruples.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1886-1785f677ac401e24a821/1-0000.mp3", duration = 32.8620408, start = 0},
  },
}
P.transport["quest:1898"] = {
  hash = "001454",
  fullHash = "001454",
  text = "The Deathstalkers. In the Undercity, the Deathstalkers hunt suspected treachery within Forsaken ranks. At Lord Varimathras’s urging, you pose as an expected messenger and question a merchant who may aid an outside faction. At Lord Varimathras’s urging, Deathstalker Mennet Carkad sets an infiltration in motion. The Deathstalkers watch Forsaken citizens as closely as they guard against outside threats. With Astor Hadren’s letter of introduction, forged or acquired, you approach the local merchant Andron Gant. You try to pass as the courier he expects.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1898-a952c989213eb7761de0/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["quest:1899"] = {
  hash = "77805a",
  fullHash = "77805a",
  text = "The Deathstalkers. In the Undercity, the Deathstalkers turn Andron Gant's trust against him. Believing you are the courier he expected, Gant gives you a ledger for his secret contacts. You take it to Mennet Carkad in the Rogues' Quarter, opening the way to deeper covert work for the Forsaken state. Andron Gant keeps names and information in a personal ledger in the Undercity. Believing you are the courier he expected, he gives you the ledger to deliver to his secret contacts. Gant asks for the same courier to carry future messages. He does not know the ledger is bound for the Deathstalkers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1899-3f2d3bd5682ffc3d7bca/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["quest:1918"] = {
  hash = "fbf856",
  fullHash = "fbf856",
  text = "The Befouled Element. At Mystral Lake, its water spirits leave glowing globes of tainted water among the slain. You carry one to Mastok Wrilehiss at Splintertree Post to learn what has poisoned the lake and its spirits. In south-central Ashenvale, Mystral Lake's water elementals have grown violent and visibly corrupted. When slain, they leave strange, glowing spheres of putrid fluid instead of pure elemental essence. The globes hold the corruption that has settled over the lake. Something beyond natural territorial aggression is at work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1918-a9980428469acb7272da/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["quest:1941"] = {
  hash = "0543e8",
  fullHash = "0543e8",
  text = "Manaweave Robe. In Stormwind, Wynne Larson presents her finished Manaweave Robe with pride as a showcase for her family’s shop. She wove it from fine materials for a commission now complete. In Stormwind’s Mage Quarter, Larson Clothiers makes garments for spellcasters facing volatile energies. Fine magical robes need rare materials, careful needlework, and thread that holds through mystic resonance. Wynne Larson takes pride in every piece from her shop. Each robe worn into the field carries the Larson name. The manaweave robe offers comfort, freedom of movement, and practical resilience for travel through contested lands. Once you deliver the needed components, Wynne Larson weaves the final stitch herself and presents the finished garment. It is a fine example of Larson tailoring, meant to draw admiration and spread the shop’s name across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1941-025ad3b8c53a32fe2dde/1-0000.mp3", duration = 53.76, start = 0},
  },
}
P.transport["quest:1959"] = {
  hash = "57b5a5",
  fullHash = "57b5a5",
  text = "Report to Anastasia. Across Kalimdor and the Eastern Kingdoms, Horde mages are called to the Undercity. Anastasia Hartwell has sensed an unknown magical disturbance there and needs capable spellcasters to investigate. Horde mages across Kalimdor and the Eastern Kingdoms hear the same call. It reaches those studying atop Thunder Bluff, in Durotar's dusty heat, and among Lordaeron's ruins. The Undercity's mages have sensed an unexplained disturbance within their domain. They need help learning what it means. Anastasia Hartwell oversees arcane matters in the Undercity's Magic Quarter. Mages there have detected strange energies within the city, but no one knows if the magic is harmless or hostile. Anastasia needs a capable mage to investigate quietly. The inquiry begins in the Apothecarium.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1959-07a1023d92548a98d658/1-0000.mp3", duration = 51.5134694, start = 0},
  },
}
P.transport["quest:1960"] = {
  hash = "62e7bb",
  fullHash = "62e7bb",
  text = "Investigate the Alchemist Shop. In Algernon's shop, invisible creatures wander among the alchemy. Anastasia Hartwell sends Horde mages to reveal and contain them before they cause harm. Anastasia Hartwell sends arcane initiates to investigate a disturbance in the Apothecarium. Invisible magical creatures wander through Algernon's alchemy shop among its cauldrons and reagents. The Undercity's mage instructor suspects a breach in the flow of magic. The creatures must be contained before they cause serious damage. Anastasia gives her students a Cantation of Manifestation to reveal the invisible creatures and sturdy containment coffers to hold them. Ordinary tracking cannot find beings made entirely of raw arcane force. Once visible, the rift spawns must be weakened and sealed in the coffers before they can unravel further or harm the alchemists at work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1960-488d1df43150d107791d/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["quest:1961"] = {
  hash = "6dbdbc",
  fullHash = "6dbdbc",
  text = "Gathering Materials. In the Undercity, Gathering Materials sends new Horde mages to Silverpine Forest for Dalaran mana gems. They need linen as well to make their first true mage's robes. Undercity initiates gather a bolt of simple linen and potent Dalaran mana gems for their first true robes. Those robes mark their station and personal worth. Anastasia Hartwell directs the novices to gather the raw materials for an enchanted weave. The mana gems cannot be bought or conjured. Dalaran mages are stationed across Silverpine Forest, especially near Ambermill, and the gems must be taken from them. Anastasia Hartwell says Dalaran's arcane philosophies mirror those of the Forsaken. Yet sentiment has no place in the Undercity. To the Forsaken, wizards too weak to defend their relics forfeit their treasures and their lives. Josef Gregorian is a tailor in the Undercity's Magic Quarter, where the gathered cloth and gems are brought. He lacks the magical talent to judge the pristine quality of Dalaran's enchanted stones. But he has the rare artisan skill to weave their raw power into the robes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1961-049924aef7f946a173b5/1-0000.mp3", duration = 69.642449, start = 0},
  },
}
P.transport["quest:1962"] = {
  hash = "28dee1",
  fullHash = "28dee1",
  text = "Spellfire Robes. In the Undercity, Spellfire Robes mark a young Horde mage's passage toward mastery. Josef Gregorian finishes them after the apprentice brings rare components from across the realm. In Lordaeron, you need more than ordinary cloth to channel and shield your growing magic. Josef Gregorian is a tailor in the Undercity's Magic Quarter. He makes magical garments from specialized materials gathered by promising Horde spellcasters. The final stitching marks your passage beyond basic incantations toward arcane and fire magic. Josef Gregorian needs alchemical and arcane components to make robes that focus powerful magic. You gather the supplies through dangerous trials and bring them to his sanctum in the Undercity. There, Gregorian weaves them together. The robes mark your growing status and offer protection as an aspiring mage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1962-d4751a8fbbea161bccf8/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["quest:1963"] = {
  hash = "66cee8",
  fullHash = "66cee8",
  text = "The Shattered Hand. In Orgrimmar, Therzok tests rogues who seek entry to the secretive Shattered Hand. Their trial sends them after Tazan, a troll smuggler, and his locked satchel. The Shattered Hand works from the Cleft of Shadow beneath Orgrimmar. This order of assassins and thieves keeps to old orcish traditions. Warchief Thrall rules the young Horde with honor, diplomacy, and caution. Yet the Shattered Hand's leaders believe restraint weakens their people, so they seek to restore martial supremacy through covert violence. They use knives and poison when a battlefield charge may fail.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1963-fa2d224c4ed9c48af07a/1-0000.mp3", duration = 36.8326531, start = 0},
  },
}
P.transport["quest:1978"] = {
  hash = "58963e",
  fullHash = "58963e",
  text = "The Deathstalkers. In Undercity, the Deathstalkers welcome a new operative into their ranks. You carry Andron's Ledger to Varimathras as proof of the Syndicate's covert work. Mennet Carkad welcomes you into the Deathstalkers after you uncover Andron Gant's records. The order serves Lady Sylvanas across Lordaeron as her eyes, ears, and daggers. Its agents use intelligence, ruthless efficiency, and stealth to remove threats before they rise. Recognition by the order marks your first step in service to the Forsaken. You deliver the sensitive ledger to Varimathras in Undercity's Royal Quarter. The nathrezim commander oversees Forsaken tactical intelligence under Sylvanas Windrunner. Pleased by the Deathstalkers' initiative, Varimathras welcomes your ability and says his intelligence division can use someone who delivers results.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1978-08ae422df19dfb267aab/1-0000.mp3", duration = 51.8008163, start = 0},
  },
}
P.transport["quest:199"] = {
  hash = "15b056",
  fullHash = "15b056",
  text = "A Dark Threat Looms. At the Stonewrought Dam, sabotage threatens the barrier that holds back Loch Modan's waters. You find a barrel near the shore and bring its strange smelling powder to Chief Engineer Hinderweir the Seventh. Whispers of sabotage have reached the shore around the Stonewrought Dam. Near the water's edge, a barrel lies where it does not belong. Inside is strange, pungent powder, far from the dam's maintenance supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_199-af65d0161823e1eae9b7/1-0000.mp3", duration = 27.7942857, start = 0},
  },
}
P.transport["quest:1998"] = {
  hash = "16b7a5",
  fullHash = "16b7a5",
  text = "Fenwick Thatros. In the Undercity, Mennet Carkad sends promising rogues to kill Fenwick Thatros on Lord Varimathras's orders. Thatros is suspected of gathering independent undead along Silverpine Forest's shores. His death proves an operative's mettle to the Deathstalkers and earns access to advanced trade training. In the Undercity's Rogues' Quarter, Mennet Carkad handles Deathstalker contracts and trains rogues. The Deathstalkers are the Forsaken's secretive intelligence wing. Lord Varimathras has named Fenwick Thatros a priority target, a charge too serious for novice recruits. Thatros has established a foothold among rogue undead in Silverpine Forest. Left alone, their independent leaders could threaten Forsaken control across Lordaeron's old holdings. Deathstalker scouts place Fenwick Thatros near a decrepit dock on Lake Lordamere in Silverpine Forest. To reach him, you must cross wilderness claimed by feral beasts, Rot Hide gnolls, and Scourge remnants. Varimathras demands proof of the kill: Thatros's severed head. Bring it back, and you may earn entry into deeper covert operations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1998-05b28ed75bc0710bbb44/1-0000.mp3", duration = 74.7885714, start = 0},
  },
}
P.transport["quest:2038"] = {
  hash = "bf87d5",
  fullHash = "bf87d5",
  text = "Bingles' Missing Supplies. On Loch Modan’s southeastern shore, Bingles Blastenheimer is stranded after troggs steal his gear. You can recover his tools and Blastencapper explosives so he can repair his gyrocopter and return to the fight for Gnomeregan. Bingles Blastenheimer crashes his gyrocopter into Loch Modan’s cold waters. He drags himself ashore, dazed, and troggs from the lake’s central islands swarm him. They steal his most valuable belongings. Troggs scatter Bingles’ gear among their island camps. The stolen things include a wrench, screwdriver, and hammer, along with his volatile, high-yield invention, the Blastenheimer Blastencapper. Left among troggs, the explosives put travelers in immediate danger. Bingles fights to free Gnomeregan, his homeland, from subterranean troggs and irradiated leper gnomes. He imagines a decisive aerial assault, but without his tools and Blastencappers he cannot rebuild his flying machine. His campaign remains grounded in the reeds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2038-82fe3aa53d84292016ce/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["quest:2039"] = {
  hash = "67ac60",
  fullHash = "67ac60",
  text = "Find Bingles. In Ironforge, Gnoarn starts a search for Find Bingles after more than a week without word. Bingles Blastenheimer vanished during a flight toward fallen Gnomeregan, and searchers are sent to Loch Modan's shores. There, Bingles is alive and needs mechanical salvage. Gnome aviator Bingles Blastenheimer was sent from Tinker Town in Ironforge to scout the irradiated ruins of Gnomeregan from the air. More than a week has passed without word. Gnoarn fears Bingles may have blown himself out of the sky, a danger of gnome engineering. His last report placed him somewhere above Loch Modan's waters. Searchers find Bingles alive along the Loch Modan shoreline, far from a tragic pile of wreckage. He is unfazed by his long absence and takes slight offense that anyone doubted his piloting. Rather than return promptly to report to Gnoarn, he asks his rescuer to recover tools and Blastencapper explosives stolen by troggs. He wants them so he can resume his duties for the gnomish movement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2039-ba5fbf1544c06f41bc86/1-0000.mp3", duration = 64.4440816, start = 0},
  },
}
P.transport["quest:2041"] = {
  hash = "f424ca",
  fullHash = "f424ca",
  text = "Speak with Shoni. In Ironforge, Alliance travelers are sent to Stormwind to find Shoni the Shilent, whose unit prepares for Gnomeregan. After Gnomeregan fell to radiation, surviving gnomes made an exile quarter in Ironforge. Its engineers, tinkers, and strategists keep seeking a way back into their lost home. Tinkertown directs the effort, but the preparations reach beyond Khaz Modan. Now adventurers are sent south to Stormwind, where military gear for fighting underground is being prepared. In Stormwind's Dwarven District, Shoni the Shilent commands an elite crew trained for underground assault. Her sappers need gyrodrillmatic excavationators to burrow toward the sectors held by troggs. The Deeprun Tram runs beneath the mountains between Ironforge and Stormwind, making the journey to Shoni straightforward.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2041-5000fa27342e7c70895f/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["quest:21"] = {
  hash = "57a1eb",
  fullHash = "57a1eb",
  text = "Skirmish at Echo Ridge. At Echo Ridge, Marshal McBride sends you into a mine overrun by kobolds. Left alone, the garrison fears, they will tighten their hold. Kobolds dig deep in Echo Ridge Mine, hoarding what they steal and growing in number. Thin their ranks now, before they spread through Northshire Valley, its farms, and its spiritual retreat. McBride has few soldiers to spare. The garrison guards the southern borders, while unrest is rumored across Elwynn. Prove reliable at Echo Ridge, and you earn the army’s respect and readiness for harder work elsewhere in the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_21-b21a53011fb396c73b9b/1-0000.mp3", duration = 37.0155102, start = 0},
  },
}
P.transport["quest:2118"] = {
  hash = "5b6b5a",
  fullHash = "5b6b5a",
  text = "Plagued Lands. Darkshore's wildlife is falling to a creeping sickness, and Tharnariun Treetender seeks a way to save it. He asks you to calm a rabid thistle bear with an enchanted relic and bring it back alive. A creeping sickness twists Darkshore’s beasts into maddened, violent creatures. Thistle bears suffer most, and their frenzy threatens travelers and the coast’s fragile balance. Night elf sentinels answer with steel, while druids seek to understand the sickness and heal its cause. Tharnariun Treetender will not kill the corrupted beasts before trying to save them. He made a trap called Tharnariun’s Hope. Set on the forest floor, its soothing light briefly calms a raging thistle bear. Pacified, the bear follows you back to Tharnariun’s outpost for study.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2118-8a3f9307b3fc6e78158a/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:2138"] = {
  hash = "b40372",
  fullHash = "b40372",
  text = "Cleansing of the Infected. In Darkshore, Tharnariun Treetender asks you to stop the infected thistle bears. His attempt to cleanse one failed, and he fears the rabid beasts will harm other creatures and spread the sickness. Tharnariun Treetender has searched for a remedy to the sickness in Darkshore's wildlife. He tried to cleanse a captured bear, but the thistle bears remain diseased and violent. So he asks you to put them down before they maul other creatures or carry the sickness farther into the ancient woodlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2138-dcb0c0e64000145016ce/1-0000.mp3", duration = 28.917551, start = 0},
  },
}
P.transport["quest:2139"] = {
  hash = "ed69b4",
  fullHash = "ed69b4",
  text = "Tharnariun's Hope. In Auberdine, Tharnariun Treetender's work against the wildlife sickness reaches a grim turn. Travelers have put down infected beasts across Darkshore, and now he sends an Alliance champion after the rabid Den Mother northeast of town. Since the Third War, an unnatural sickness has made Darkshore's wild creatures rabid. Tharnariun Treetender is stationed in Auberdine, where he has asked travelers to put down infected beasts and ease the forest's suffering. Yet killing rabid thistle bears treats only a symptom. Tharnariun decides the source among the local bears must be removed: their matriarch, the Den Mother. Tharnariun gives profound thanks after the Den Mother's death, though melancholy shadows his words. For the kaldorei, raising weapons against woodland creatures is agony. Dark forces press against their new home, and many despair or seek shelter. Auberdine's defenders accept the heavy burden of protecting their wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2139-ec868fee5dc7d6119f06/1-0000.mp3", duration = 60.16, start = 0},
  },
}
P.transport["quest:214"] = {
  hash = "cfbc4d",
  fullHash = "cfbc4d",
  text = "Red Silk Bandanas. In the Deadmines, Scout Riell sends the People's Militia after Red Silk Bandanas. Their fine weave marks the Defias leaders directing the uprising in Westfall. Scout Riell and the People's Militia have learned that cloth marks rank in the Defias Brotherhood. Across Westfall, common cutpurses and highwaymen tie coarse red cloth over their faces. Senior conspirators and inner-circle operatives wear fine red silk. Recovering their bandanas strikes at the experienced officers coordinating Edwin VanCleef's uprising. The senior outlaws gather deep in the Deadmines beneath Moonbrook. Sentinels and scouts outside Sentinel Hill depend on freelance champions to enter the contested tunnels. Each silk bandana recovered means one fewer lieutenant organizing ambushes, guarding weapon caches, or enforcing VanCleef's rule across Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_214-3709b08406f4b7efbf06/1-0000.mp3", duration = 54.4130612, start = 0},
  },
}
P.transport["quest:2159"] = {
  hash = "69d0a5",
  fullHash = "69d0a5",
  text = "Dolanaar Delivery. In Shadowglen, travelers carry herbs south to Dolanaar. Porthannius is busy with the druids, and the road beyond the sheltered glade opens before young adventurers. Porthannius asks travelers bound south from Shadowglen to carry freshly gathered herbs along the forest path. Pressing business with the druids tending the glade keeps him from making the journey himself. The bundle goes south as young adventurers leave the training grounds and set out into the wider reaches of Teldrassil. The southern road from Shadowglen reaches Dolanaar, a foremost night elf settlement on Teldrassil's great boughs. Innkeeper Keldamyr looks after rest, hospitality, and supplies for wanderers, sentinels, and druids. When he receives Porthannius's herbs, he urges young adventurers to rest their minds and spirits before facing the corruption spreading across the world tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2159-9d35a6e8814ed0233d43/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:2160"] = {
  hash = "436b4d",
  fullHash = "436b4d",
  text = "Supplies to Tannok. Hands Springsprocket has inn supplies for Tannok Frosthammer, but troggs have made the pass unsafe. He asks you to carry the crate from Coldridge Valley to the Thunderbrew Distillery in Kharanos. Troggs have overrun Coldridge Pass, making the route out of Coldridge Valley dangerous. Mountaineers are stretched thin guarding settlements and defenses, so supply escorts can be delayed for days. The inn's crate has no safe way through. Hands Springsprocket is a gnome tinkerer waiting at the pass, but he cannot carry the crate safely himself. You can take the supplies to Tannok Frosthammer, the assistant at the Thunderbrew inn in Kharanos. Tannok Frosthammer receives the supplies in Kharanos. He says word from Anvilmar has been scarce since troggs disrupted travel. Without the delivery, communication and trade between the two isolated dwarf communities remain fragile.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2160-75186832797bb6b55fe9/1-0000.mp3", duration = 54.6742857, start = 0},
  },
}
P.transport["quest:2161"] = {
  hash = "4570b2",
  fullHash = "4570b2",
  text = "A Peon's Burden. Ukor waits outside the Valley of Trials with provisions he cannot carry home. The recruits in the red canyon refused his food, so he asks travelers to take it back to Razor Hill. Ukor left Razor Hill carrying provisions for the fresh recruits training in the red canyon. He thought they needed the food, but the taskmasters sent him away. They keep rations meager, believing hardship teaches young Horde warriors discipline and endurance. Innkeeper Grosk later explains that hunger is part of their training. Ukor reached the pass, but fears crossing Durotar on the way back. Scorpids, venomous spiders, and prowling boars haunt the rocky trail. He has no weapons or armor, and lacks the fighting spirit expected of an orcish grunt.\n\nSo Ukor waits along the path and asks travelers leaving the proving grounds to carry his heavy provisions back to the inn in Razor Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2161-44b500bf0cc10c96d938/1-0000.mp3", duration = 55.0138776, start = 0},
  },
}
P.transport["quest:217"] = {
  hash = "69c219",
  fullHash = "69c219",
  text = "In Defense of the King's Lands. Captain Rugelfuss sends you into Stonesplinter Valley to stop the attacks on the King’s Lands. Scouts have traced them to Grawmug, chieftain of the Stonesplinter troggs. His death may break the pack’s resolve and help reclaim southern Loch Modan. Captain Rugelfuss’s scouts have found that the Stonesplinter troggs follow Chieftain Grawmug. Their attacks threaten the King’s Lands in southern Loch Modan. You are sent into their lair to kill Grawmug and his personal bruisers. Breaking the pack’s cohesion may stop its advance. Grawmug holds a cavern in the southeastern cliffs of Stonesplinter Valley. His trusted brutes, Gnasher and Brawler, stand beside him, making the three a danger to a lone soldier. Defeating them could throw the remaining troggs into disarray. That would give the beleaguered Mountaineers time to fortify the roads and drive the beasts back underground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_217-126bbf572c6a378952bb/1-0000.mp3", duration = 52.4538776, start = 0},
  },
}
P.transport["quest:2178"] = {
  hash = "7b78ff",
  fullHash = "7b78ff",
  text = "Easy Strider Living. In Auberdine, Alanndarian Nightsong offers hunters her own recipe for strider stew if they bring her foreststrider meat. Auberdine's coastal folk make use of the wildlife around them. Alanndarian Nightsong has her own recipe for hearty strider stew, made from the tall foreststriders that range through Darkshore's woods. She asks you to hunt the birds and bring back their meat before she shares her cooking. Foreststriders range through the woodlands and beaches north and south of Auberdine. Their sharp beaks and quick tempers make them dangerous when provoked, but their meat makes a rich stew. Bring fresh meat to Alanndarian, and she will share her recipe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2178-1ccbc30ab20ed76c1393/1-0000.mp3", duration = 40.0718367, start = 0},
  },
}
P.transport["quest:218"] = {
  hash = "6af238",
  fullHash = "6af238",
  text = "The Stolen Journal. Grelin Whitebeard needs his stolen journal to finish judging the troll threat in Coldridge Valley. Grik'nir the Cold, leader of the Frostmane, carried it into the troll cave, leaving Grelin without most of his reconnaissance. The Frostmane trolls have pressed into Coldridge Valley, and Grelin Whitebeard's notes track them. They record the trolls' habits and their sudden aggression. During the unrest, an imposing troll stole Grelin's personal journal and fled into the depths of the den. The journal holds most of his reconnaissance, so Grelin cannot finish his assessment until it is recovered. Grik'nir the Cold holds court in the heart of the valley's troll cave. Distinctive paint marks his body and face. Defeating this powerful Frostmane troll breaks the cave trolls' immediate leadership and secures Grelin's journal. With it returned, Grelin can finish his findings, judge the local troll situation manageable, and send his report to his brother Senir.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_218-3a920d6df6dbc539e511/1-0000.mp3", duration = 56.32, start = 0},
  },
}
P.transport["quest:22"] = {
  hash = "bd1874",
  fullHash = "bd1874",
  text = "Goretusk Liver Pie. At the Saldean Farm in Westfall, Salma Saldean is making pie through hard times. Bandits have ravaged the kingdom’s breadbasket, and homesteaders hunt aggressive boars to feed their families. Westfall once fed Stormwind as its fertile breadbasket. Now neglected roads, roving outlaws, and overgrown fields make life hard for the few settlers who remain. At the Saldean Farm, Salma Saldean works to keep a sense of home despite the dangers. A traditional meat pie offers one of the few comforts to homesteaders trying to preserve their way of life. Goretusks roam Westfall’s plains in great numbers. Their tough hides and vicious tusks make them dangerous to farmhands alone, yet their meat feeds families cut off from regular trade. Salma’s recipe calls for crushed rosemary, minced garlic, chopped dill, and simmering gravy. Prepared with care, the beasts’ pungent organs become a rich, savory meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_22-b6412804eba50f6f94ec/1-0000.mp3", duration = 57.835102, start = 0},
  },
}
P.transport["quest:2205"] = {
  hash = "8472ca",
  fullHash = "8472ca",
  text = "Seek out SI: 7. From Goldshire, Keryn Sylvius sends new rogues with a sealed package to Stormwind City. The delivery brings them before Master Mathias Shaw, who leads the crown's covert intelligence network. Rogue trainer Keryn Sylvius doubts that fresh initiates look like covert agents. She gives them a sealed delivery for the capital, testing their reliability as couriers. In doing so, she quietly judges whether they might serve the realm as scouts. SI: 7, or Stormwind Intelligence, Section 7, works from southeastern Old Town in Stormwind City. In this worn district, Master Mathias Shaw oversees the kingdom's covert operations. He receives the package with dry skepticism, then judges whether you have the grit for real espionage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2205-37bcc2b88f93727f9c5e/1-0000.mp3", duration = 49.0840816, start = 0},
  },
}
P.transport["quest:2206"] = {
  hash = "294a14",
  fullHash = "294a14",
  text = "Snatch and Grab. At Jerod's Landing, Master Mathias Shaw sends agents to learn how the Defias move their supplies. The Brotherhood uses the river dock to ship goods in secret. Master Mathias Shaw tests those who seek a place among Stormwind's covert agents. He asks for finesse and stealth, not brute force. SI:7 agents quietly take down key figures and recover important papers. They do this without drawing the realm into open scandal. Each new operative must prove they can work unseen. Jerod's Landing sits on the river in southern Elwynn, south of Goldshire and just east of the Maclure Vineyards. The Defias Brotherhood seized the once-quiet dock and turned it into an illicit route. Arms, supplies, and contraband cross the water from Redridge toward Westfall. Royal road patrols cannot reach them there. Master Mathias Shaw warns agents that capture, compromise, or death leaves them without the Crown's support. Stormwind and its spymasters will deny they ever existed. The Defias Dockmaster's schedule gives SI:7 proof of the Brotherhood's supply lines. Recovering it keeps Stormwind's official involvement hidden.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2206-7332e131f2333bd5252d/1-0000.mp3", duration = 72.6204082, start = 0},
  },
}
P.transport["quest:224"] = {
  hash = "e12d8c",
  fullHash = "e12d8c",
  text = "In Defense of the King's Lands. At the southern watchtower, Mountaineer Cobbleflint calls for help as Stonesplinter troggs press toward the Valley of Kings. Ironforge’s forces serve on distant fronts. Cobbleflint and the guards are too few to stop the growing trogg invasion beneath the great dwarven monuments. King Magni Bronzebeard has sent much of his regular army abroad to support the Alliance. Local patrols and hired blades must keep the province from being overrun. Stonesplinter Valley cuts through Loch Modan’s southern peaks, where troggs have burrowed up from the depths. Their scouts reconnoiter the roads while warriors build camps along the valley floor. If left unchecked, their parties threaten the roads to the southern passes. The Mountaineers must fight them without pause.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_224-f0b3f4368db86c87948c/1-0000.mp3", duration = 47.5689796, start = 0},
  },
}
P.transport["quest:2242"] = {
  hash = "f2f1fa",
  fullHash = "f2f1fa",
  text = "Destiny Calls. Near the Oracle Glade, Syurna asks you to learn what Sethir the Ancient knows of Teldrassil's corruption. The satyr has turned away force and diplomacy alike. Teldrassil's growing sickness troubles the night elf leaders in Darnassus. Syurna, the rogue trainer, needs someone quiet, since armed patrols have died trying to reach Sethir the Ancient. The satyr roosts on a remote bough near the Oracle Glade. He has turned away force and diplomacy alike. To learn what he knows, you must enter his lair and take his personal possessions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2242-23dbcd3e712f37804beb/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["quest:2259"] = {
  hash = "5959cd",
  fullHash = "5959cd",
  text = "Erion Shadewhisper. From the forests of Teldrassil, promising rogues are sent to Darnassus. At the Cenarion Enclave, Erion Shadewhisper points them toward work beyond the forests. Jannok Breezesong sends you from Teldrassil to find Erion Shadewhisper in Darnassus. There is no need to fear a summons to Syurna, the exacting trainer. Erion waits in the Cenarion Enclave, where he handles work that calls for a quieter touch. For rogues in night elf lands, Teldrassil's forests can no longer contain their duties. Erion Shadewhisper sends capable hands into a wider, more dangerous world. Their work lies across the sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2259-6d5fb6034bc898711711/1-0000.mp3", duration = 42.6579592, start = 0},
  },
}
P.transport["quest:2260"] = {
  hash = "bf2164",
  fullHash = "bf2164",
  text = "Erion's Behest. In Darnassus, Erion Shadewhisper sends promising night elf rogues across the Great Sea. He sees their growing skill in stealth and directs them to Stormwind City to report to Stormwind Intelligence. Night elf rogues train in Teldrassil's shadow under mentors such as Erion Shadewhisper. When one shows exceptional talent, word travels beyond the World Tree. Through Erion, Stormwind Intelligence, also called SI:7, invites you across the Great Sea to the human capital. From northern Kalimdor, you travel by way of the docks at Darkshore or the Wetlands to Stormwind City. In the capital, you make your way to SI:7 headquarters in Old Town and report to Renzik \"The Shiv.\" He assesses newcomers and opens the way to advanced espionage, poison mastery, and covert operations for the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2260-28d6129d756e098a5aee/1-0000.mp3", duration = 50.9910204, start = 0},
  },
}
P.transport["quest:2281"] = {
  hash = "0b536d",
  fullHash = "0b536d",
  text = "Redridge Rendezvous. In Lakeshire, promising Alliance rogues train for dangerous work under seasoned operatives. SI:7 sends them east from Stormwind’s intelligence headquarters to prepare for the field. Renzik 'The Shiv', SI:7’s second-in-command in Stormwind, knows that untrained rogues rarely survive dangerous operations. Sending raw recruits into hostile territory brings casualties instead of intelligence. So SI:7 sends promising agents east to the Redridge Mountains. There, Lucius trains them among Lakeshire’s docks. Lakeshire gives Lucius good ground for clandestine training. Gnolls and Blackrock orcs threaten the frontier town. Its piers let him test a rogue’s stealth, reflexes, and lockpicking without drawing the notice of townspeople or guards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2281-e9e54faff98b78aae65e/1-0000.mp3", duration = 50.5991837, start = 0},
  },
}
P.transport["quest:2300"] = {
  hash = "bc74c9",
  fullHash = "bc74c9",
  text = "SI:7. From Goldshire, promising young rogues are sent to report to Renzik \"The Shiv\" in Stormwind. There, you enter Master Mathias Shaw's service, where covert work awaits. At the Lion's Pride Inn, Keryn Sylvius watches Goldshire's local recruits. You prove cunning and capable against the growing Defias threat, and Sylvius passes along a message from headquarters. Report to Renzik \"The Shiv\" without delay. You leave Elwynn's fields for Stormwind's covert ranks. Behind an unassuming barracks in Old Town, Stormwind's hidden agency keeps its headquarters. Master Mathias Shaw commands its work across the kingdom and beyond. The agency handles covert operations, reconnaissance, and assassination.\n\nRenzik \"The Shiv\" is Shaw's sharp-tongued second-in-command. He assesses promising agents, then sends them into dangerous work beyond the reach of the kingdom's formal military.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2300-bac285436f97a0302256/1-0000.mp3", duration = 58.6971429, start = 0},
  },
}
P.transport["quest:233"] = {
  hash = "86e0ca",
  fullHash = "86e0ca",
  text = "Coldridge Valley Mail Delivery. At Anvilmar, Sten Stoutarm sends you west with mail for scouts beyond the frozen lake. Snow and nearby troggs can cut off the valley's defenders, leaving important news undelivered. Mail from across Dun Morogh reaches Anvilmar by mountain pass, where winter couriers leave it to gather. Sten Stoutarm tends supplies and security, so recruits carry the bundles down the western road. Without your help, important messages remain in the hall. Talin Keeneye watches the frozen lake west of Anvilmar for trogg movements and dangerous wildlife. Even at a cold outpost, news from Ironforge and the surrounding camps matters. Harsh mountain conditions make sorting mail difficult, so letters for different scouts can end up together in one bundle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_233-f166e786a3c7ed23e1e6/1-0000.mp3", duration = 46.6285714, start = 0},
  },
}
P.transport["quest:234"] = {
  hash = "3c5907",
  fullHash = "3c5907",
  text = "Coldridge Valley Mail Delivery. In Coldridge Valley, a dispatch travels from Talin Keeneye's post to Grelin Whitebeard's camp. You carry it down the southeastern road, keeping the mountaineers in touch with Ironforge. Anvilmar is Coldridge Valley's center of rule. From there, field scouts and sentries carry dispatches along the trails between the high passes and Ironforge. Grelin Whitebeard keeps a small camp southeast of Talin Keeneye's post. Veteran mountaineers at these remote watchpoints face freezing drifts and steady trogg harassment. Regular letters keep them abreast of affairs across Dun Morogh and the kingdom beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_234-e4c0ce72d0190110391d/1-0000.mp3", duration = 38.1910204, start = 0},
  },
}
P.transport["quest:237"] = {
  hash = "e8f2f2",
  fullHash = "e8f2f2",
  text = "In Defense of the King's Lands. In southern Loch Modan, Mountaineer Gravelgaw calls for help against the Stonesplinter troggs. With dwarven forces committed to the Alliance front, local outposts rely on volunteers to hold the line. The Mountaineers guarding the southern pass into Dun Morogh are stretched thin. King Magni Bronzebeard has sent much of Ironforge's strength to the wider Alliance front, leaving the Valley of Kings towers short of regular infantry. So Mountaineer Gravelgaw calls on volunteers to strike Stonesplinter Valley and keep the troggs at bay. Reinforcements may never come. The Stonesplinter troggs are neither mindless nor aimless. Their war bands fight with brute force and crude elemental magic. Gravelgaw wants their veteran Skullthumpers and their Seers, who lead with mystic power, driven from the fight. Without those leaders, the tribe's southern camps lose their order and cannot mass against the Ironforge road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_237-4db48a9bff34a9f3e67b/1-0000.mp3", duration = 57.9657143, start = 0},
  },
}
P.transport["quest:2378"] = {
  hash = "46211c",
  fullHash = "46211c",
  text = "Find the Shattered Hand. A Forsaken rogue from Tirisfal Glades is bound for Orgrimmar, where the Shattered Hand awaits. The Deathstalkers send the promising initiate across the sea to Durotar to learn the clan’s specialized arts. Mennet Carkad has seen a rogue prove their worth in Tirisfal Glades. The Forsaken train their own covert order, the Deathstalkers. Their alliance with the Horde opens a path to darker arts. So Mennet directs promising rogues to the Shattered Hand in Orgrimmar, joining Lordaeron’s undead operatives with Kalimdor’s orcish assassins. The journey ends beneath Orgrimmar in the Cleft of Shadow. Warlocks, rogues, and demon-binders work out of sight there. Shenthul, a Shattered Hand trainer, awaits the newly arrived undead agent. The gruff troll greets the envoy with harsh skepticism. Reputation alone will not satisfy him; he wants to see whether the envoy has real cunning or has wasted the voyage across the Great Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2378-d20e50f48a091f409e40/1-0000.mp3", duration = 61.0481633, start = 0},
  },
}
P.transport["quest:2379"] = {
  hash = "9c6a05",
  fullHash = "9c6a05",
  text = "Zando'zan. In Orgrimmar's Cleft of Shadow, Shenthul sends a promising rogue to meet Zando'zan. There, training begins for the Shattered Hand's covert ranks. Orgrimmar's rulers know strength alone cannot win every war. Beneath the city, the Cleft of Shadow is home to the Shattered Hand, a covert guild serving the Horde through espionage, sabotage, and theft. When rogue trainer Shenthul sees promise in an initiate, he sends them to Zando'zan for training as an operative. Zando'zan tests each inexperienced rogue who enters the cavern before granting respect. Meeting him begins formal training in stealth, subterfuge, and thievery. His lessons bridge the gap between rough street cutpurses and organized intelligence operatives. From there, rogues prepare for fieldwork beyond the safety of the capital's red canyon walls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2379-57de62af044f242ef44d/1-0000.mp3", duration = 52.8718367, start = 0},
  },
}
P.transport["quest:2380"] = {
  hash = "0936ed",
  fullHash = "0936ed",
  text = "To Orgrimmar!. Kaplak sends a young rogue from Razor Hill north to Orgrimmar. You are to find Shenthul in the Cleft of Shadow and enter the Shattered Hand's network. Kaplak sends you north from Razor Hill to Orgrimmar. Your growing skill has drawn the notice of handlers with greater standing, though your craft is still rough. You leave Durotar's red crags behind and make for the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2380-689a3f8a9197c247a493/1-0000.mp3", duration = 22.804898, start = 0},
  },
}
P.transport["quest:2381"] = {
  hash = "985889",
  fullHash = "985889",
  text = "Plundering the Plunderers. Near Ratchet, Wrenix the Wretched sends new Shattered Hand rogues against the Southsea Freebooters. Aboard the Tide Razor, they face pirates, locked strongboxes, and a dangerous guardian before claiming the Southsea Treasure. Wrenix the Wretched tests aspiring Shattered Hand operatives in Ratchet. He sends rogues south along the Barrens coast to a cove where the Tide Razor lies at anchor. Southsea Freebooters crew the ship. Rogues must board unseen and enter the pirates’ den, where cutpurses train. Then they pick the strongboxes in the hold and bring back the plunder.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2381-c36011e2e264ef165791/1-0000.mp3", duration = 36.2318367, start = 0},
  },
}
P.transport["quest:2382"] = {
  hash = "e85b07",
  fullHash = "e85b07",
  text = "Wrenix of Ratchet. In Orgrimmar, Wrenix of Ratchet draws Horde rogues toward a goblin port far to the south. Zando'zan sends you to aid Wrenix the Wretched, a disreputable goblin in Ratchet. In the Cleft of Shadow, Orgrimmar's rogue guild works from winding crevices, mostly unseen. Zando'zan is a troll who greets operatives with wild ramblings and dark portents. He speaks of Warchief Thrall struck down by poison and blade. Then he gives no reason for the vision and sends agents south to Ratchet, a port town in the Barrens. Ratchet lies on the Barrens coast, east of the Crossroads. Scoundrels, mercenaries, and tinkerers gather in this neutral port, where Wrenix the Wretched makes his home. Wrenix has little patience for Zando'zan's strange ways. He says the troll's earlier recruits met grim ends in the bay, among its hungry predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2382-88c8abf511a0668442d4/1-0000.mp3", duration = 55.0661224, start = 0},
  },
}
P.transport["quest:239"] = {
  hash = "e93faa",
  fullHash = "e93faa",
  text = "Westbrook Garrison Needs Help!. At Westbrook Garrison, Deputy Rainer and his guards face growing pressure with few soldiers to spare. Marshal Dughan sends available adventurers west to the outpost on Elwynn Forest's border with Westfall. Stormwind's army is stretched thin across the kingdom, leaving the garrison to contend with Riverpaw gnolls and wandering thieves without regular reinforcements. Westbrook Garrison guards Elwynn Forest's western edge, where settled woodland meets Westfall's troubled plains. Gnoll warbands and bandits grow bolder along the waterways and western roads, so the small garrison has asked for more men. Marshal Dughan and Goldshire's administration have no Stormwind soldiers to spare. Local commanders must hire traveling mercenaries and wandering adventurers. Deputy Rainer and his men face Riverpaw gnolls who harass travelers and nearby homesteads. The pack ranges through the borderlands between Elwynn and Westfall. Stormwind is distracted by political and military troubles, and the gnolls press deeper into inhabited lands. Westbrook Garrison guards against their unchecked advance into the heart of the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_239-ff29f09456d8d8fe19bd/1-0000.mp3", duration = 69.0938776, start = 0},
  },
}
P.transport["quest:2399"] = {
  hash = "1ebc37",
  fullHash = "1ebc37",
  text = "The Sprouted Fronds. At Denalan's garden by Lake Al'Ameth, the planted frond has taken root and sprouted. Its new growth now shows among the garden beds. You find Denalan's garden near Lake Al'Ameth. There the botanist studies Teldrassil's peculiar plants. After a shimmering frond is planted, new fronds rise from the soil in his planter, ready for gathering and study. Young Teldrassil is vast, and its plants grow quickly. Night elf herbalists find that growth fascinating and troubling. The shimmering fronds and their offshoots show how quickly life takes hold on the World Tree's boughs. Yet its vitality can be hard to predict.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2399-7064c1b5664fee6b6d22/1-0000.mp3", duration = 40.3591837, start = 0},
  },
}
P.transport["quest:2438"] = {
  hash = "9c2d5d",
  fullHash = "9c2d5d",
  text = "The Emerald Dreamcatcher. In Dolanaar, Tallonkai Swiftroot asks you to retrieve the Emerald Dreamcatcher from his abandoned home in Starbreeze Village. Gaerolas Talvethren gave him the heirloom, but corrupted Gnarlpine furbolgs drove him from the village before he could take it. Its gentle magic still waits there. Gaerolas Talvethren gave Tallonkai a rare druidic talisman. The warden watches over the sleeping druids in Ban'ethil Barrow Den. The amulet channels the serene currents of the Emerald Dream, bringing peace and fortune to its bearer. Such gifts go only to a trusted few whose lives are bound to the forest's care. Starbreeze Village was peaceful until the Gnarlpine furbolgs fell to violent madness. They drove the villagers from their ancestral homes. In the fearful flight, Tallonkai left his most treasured possession hidden in his dresser in the village's southeastern quarter. Alone, he could not reclaim it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2438-05484dc986c0a3374cd1/1-0000.mp3", duration = 57.6522449, start = 0},
  },
}
P.transport["quest:244"] = {
  hash = "d60841",
  fullHash = "d60841",
  text = "Encroaching Gnolls. Gnolls press toward Redridge’s western road, and Lakeshire fears being cut off. Guard Parker spots camps near the border and sends word to Deputy Feldon. The warning confirms the town’s fear that the beastmen may isolate Redridge. Guard Parker watches the western border trail, where the road leads from Elwynn Forest into Redridge Mountains. Stormwind’s forces have thinned, leaving few defenders along the route. Parker keeps the gravel road open for supply wagons, but his scouts report gnoll warbands advancing from the crags to the north and east. Their camps lie alarmingly close to the road. Near the Lakeshire bridge, Deputy Feldon receives the warning and sees the danger facing the town. Redridge gnolls raid near Lakeshire, while their camps near the Elwynn border could let them encircle the town and push into the kingdom’s heartland. Stormwind has ignored pleas for reinforcements, leaving Lakeshire’s watch unready for threats from both sides.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_244-891fd8a890828e944e4e/1-0000.mp3", duration = 60.5518367, start = 0},
  },
}
P.transport["quest:2459"] = {
  hash = "aeb621",
  fullHash = "aeb621",
  text = "Ferocitas the Dream Eater. In Dolanaar, Tallonkai Swiftroot sends you north to recover an emerald stolen by Gnarlpine furbolgs. Their leader, Ferocitas the Dream Eater, wears it around his neck. Tallonkai Swiftroot was relieved when his dreamcatcher returned from the corrupted wilds. Then he saw its ruined state. The sacred artifact had been vandalized, and its emerald centerpiece pried from the woven frame.\n\nNight elves spoke of Gnarlpine mystics north of Starbreeze Village, fallen under the sway of their leader, Ferocitas the Dream Eater. He wore a brilliant green stone around his neck. The gem was useless and perverse in Ferocitas's clutches, so Tallonkai sent defenders to reclaim it. The Gnarlpine furbolgs in northern Teldrassil were once peaceful neighbors. Corruption from the World Tree drove them into frenzy and madness. Their mystics once practiced harmonious nature rites, but now draw on distorted magical energies. You can reach Ferocitas by cutting through the mystics guarding his woodland enclave. Return the jewel to Tallonkai, so he can make his dreamcatcher whole and restore balance to the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2459-ab87acda9f88881c10c4/1-0000.mp3", duration = 71.5493878, start = 0},
  },
}
P.transport["quest:246"] = {
  hash = "4db296",
  fullHash = "4db296",
  text = "Assessing the Threat. Near Lakeshire, Deputy Feldon needs to learn how great the gnoll threat has grown. With the garrison stretched thin and Stormwind withholding reinforcements, he pays travelers to thin the packs and gauge their strength. Blackrock orc warbands threaten Lakeshire from the heights, while aggressive gnolls roam the valleys. The town has too few defenders for ordinary scouting patrols. When reports showed gnolls pressing toward the border, Deputy Feldon called on travelers. He pays them to test the enemy in the wild, sparing guards the town cannot afford to send. You scout along Redridge's southern road and strike the camps of Redridge Mongrels and Poachers. Each fight thins the gnolls' forward scouts and disrupts their supply lines. The clashes reveal whether the packs are scattered scavengers or an organized force threatening Lakeshire. Feldon can use what you learn to plan the town's strained defense.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_246-606afacd8cc2fb97246d/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:2498"] = {
  hash = "419295",
  fullHash = "419295",
  text = "Return to Denalan. At Lake Al'Ameth, you carry Rellian Greenspyre's alarming news to Denalan, the botanist studying corruption in Teldrassil. After examining the mossy tumors on timberlings, you head south to help Denalan with his discovery. Rellian Greenspyre studies the mossy tumors afflicting Teldrassil's timberlings when urgent word comes from his colleague Denalan. At his camp beside Lake Al'Ameth, Denalan has finally isolated the cause of these unnatural growths on the forest's nature spirits. Rellian sees the gravity of this discovery and sends you south at once to lend a hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2498-deb0e0c93868b8699d39/1-0000.mp3", duration = 35.84, start = 0},
  },
}
P.transport["quest:2499"] = {
  hash = "5d3d73",
  fullHash = "5d3d73",
  text = "Oakenscowl. At Lake Al'Ameth, blight spreads from Oakenscowl, once a guardian of Teldrassil. Denalan asks you to end the threat. The maddened timberling dwells in a cave on the lake's southern bank. Timberlings tend Teldrassil's boughs, and Oakenscowl once led them. Now corruption reaches the world tree's humble wildlife and ancient protectors alike. A massive growth swells across Oakenscowl's bark and drives the timberling mad. Its old duty was to guard the forest. Now blight takes hold. Oakenscowl hides in a cavern on Lake Al'Ameth's southern shore. From there, it poisons nearby water and woodland beasts. Denalan cannot face the creature alone, so he seeks its destruction. He hopes to cut off the corruption and study the strange growth afflicting the lake's spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2499-92acd40a926cb234521d/1-0000.mp3", duration = 52.2187755, start = 0},
  },
}
P.transport["quest:250"] = {
  hash = "c969f5",
  fullHash = "c969f5",
  text = "A Dark Threat Looms. Chief Engineer Hinderweir the Seventh fears Dark Iron sappers near the eastern ramp threaten the Stonewrought Dam. With much of its garrison sent to the Alliance Front, you investigate the danger. The Stonewrought Dam holds back Loch Modan's waters. Ironforge engineers raised it as a great work, yet much of its security detail has gone to the Alliance Front. Chief Engineer Hinderweir the Seventh and his small crew now have little protection if an attack comes. Dark Iron dwarves struck the Thandol Span and pillaged Dun Modr in the Wetlands. Now known sappers lurk near the dam's eastern ramp. Hinderweir fears the clan has turned to Loch Modan's lifeline, and means to demolish it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_250-a862629303f33b452d90/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:2518"] = {
  hash = "1b926c",
  fullHash = "1b926c",
  text = "Tears of the Moon. At the Temple of the Moon, Priestess A'moora grieves for Lady Sathrah. Once blessed by Elune, the spider now brings danger, and the Sisterhood seeks to ease her suffering and recover her sacred spinnerets. At the Temple of the Moon in Darnassus, Priestess A'moora grieves for Lady Sathrah. Elune once blessed the spider. Beneath the night sky, Sathrah wove silver webs across Teldrassil's boughs, and evening mist gathered on them. The Sisterhood of Elune collected the shimmering dew for its healing power in sacred rites.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2518-b786c91df2bf9bf48915/1-0000.mp3", duration = 34.2726531, start = 0},
  },
}
P.transport["quest:2519"] = {
  hash = "18bb3f",
  fullHash = "18bb3f",
  text = "The Temple of the Moon. In Darnassus, Sister Aquinne calls for aid to a suffering ancient creature in Teldrassil. The Sisterhood of Elune cannot tend to it alone, and the call begins a solemn ritual of mercy. In Darnassus's Temple Gardens, Sister Aquinne asks you to help a venerable forest creature in pain. She serves Elune and speaks for her order. The Sisters cannot tend to the creature alone. Sister Aquinne sends you southeast to the Temple of the Moon. There, Priestess A'moora coordinates rituals and practical duties for Teldrassil's troubled wildlife. She prepares allies for a sorrowful act of mercy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2519-3780fa555c4e79549b7c/1-0000.mp3", duration = 40.3853061, start = 0},
  },
}
P.transport["quest:2520"] = {
  hash = "0ce3c8",
  fullHash = "0ce3c8",
  text = "Sathrah's Sacrifice. At the Temple of the Moon, Sathrah's Sacrifice offers Lady Sathrah a final rite. You bring her spinnerets to Elune's sacred waters, where the Priesthood seeks to cleanse her soul of corruption. Priestess A'moora asks you to perform a final rite for Lady Sathrah after she is slain. The dark madness spreading across Teldrassil twisted the great spider's peaceful nature into mindless aggression. The Priesthood of Elune seeks to redeem her fallen essence, not treat her death as a simple culling. You place her silvery spinnerets in the fountain at the heart of the Temple of the Moon. Its consecrated waters wash away the corruption and grant her release.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2520-5e672cd77e5548afbfcc/1-0000.mp3", duration = 39.3404082, start = 0},
  },
}
P.transport["quest:2541"] = {
  hash = "0bc647",
  fullHash = "0bc647",
  text = "The Sleeping Druid. In Ban'ethil Barrow Den, Oben Rageclaw lies asleep while his spirit is caught in the Emerald Dream. Gnarlpine shamans have drawn it from his body and set his flesh moving through the den. Night elf druids sleep in barrow dens across Kalimdor while their spirits wander the Emerald Dream. Their bodies rest in stone alcoves through centuries of slumber. Teldrassil's corruption has driven the Gnarlpine furbolgs to desperate savagery. In Ban'ethil Barrow Den, Gnarlpine shamans have breached Oben Rageclaw's sacred rest and drawn his living spirit from his sleeping body.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2541-5a47c738d68d4fc24474/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["quest:255"] = {
  hash = "e8f3fe",
  fullHash = "e8f3fe",
  text = "Mercenaries. In Thelsamar, Magistrate Bluntnose hires passing fighters as Mo'grosh ogres press into northeastern Loch Modan. Ironforge has promised soldiers for the valley's defense, but they are months away. Settlements, excavations, and the Stonewrought Dam remain exposed. Ironforge took two months to promise a handful of soldiers for Loch Modan's local defense. Another two months will pass before they arrive. Thelsamar's guards are stretched thin as hostile forces gather beyond the valley. Magistrate Bluntnose cannot wait for reinforcements. Mo'grosh ogres have fortified a camp in the hills northeast of the loch. Their growing presence threatens Thelsamar, the Ironband Excavation Site, and the Stonewrought Dam. If the dam is attacked or damaged, destruction downstream would be catastrophic.\n\nWithout official mountaineer detachments, Bluntnose hires independent fighters to thin the ogre ranks. He hopes to buy the valley time against both ogres and troggs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_255-aeda41b423ffcbefaaa1/1-0000.mp3", duration = 63.1902041, start = 0},
  },
}
P.transport["quest:2561"] = {
  hash = "58229e",
  fullHash = "58229e",
  text = "Druid of the Claw. Beneath Teldrassil, Oben Rageclaw’s spirit waits for release. The corrupted Gnarlpine furbolgs bound his body with dark enchantment, and you can free him by destroying its soulless shell. Oben Rageclaw slept in the barrows beneath Teldrassil. Then the corrupted Gnarlpine furbolgs laid a voodoo enchantment over his body. The magic tore his spirit from his mortal flesh and trapped it in the Emerald Dream. Now Oben’s spirit lingers nearby, unable to rest or reclaim his body.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2561-6095fa600bfbdd19c83b/1-0000.mp3", duration = 32.0783673, start = 0},
  },
}
P.transport["quest:257"] = {
  hash = "9bf5b2",
  fullHash = "9bf5b2",
  text = "A Hunter's Boast. At Farstrider Lodge, Daryl the Youngling sets you a timed hunt in Loch Modan: bring down six mountain buzzards within fifteen minutes. Daryl calls himself Daryl the Bold and dismisses travelers as greenhorns who cannot match his hunting skill. Then he points you toward the mountain buzzards scavenging around the lodge's nearby crags and hillsides. The hunt tests your speed, patience, and aim against the buzzards' quick flight. Bring down all six before time runs out, and Daryl grudgingly gives up one of his ranged weapons. He offers you further hunting dares, too.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_257-f41309a6e51a5adcf070/1-0000.mp3", duration = 38.164898, start = 0},
  },
}
P.transport["quest:258"] = {
  hash = "3a1793",
  fullHash = "3a1793",
  text = "A Hunter's Challenge. At Farstrider Lodge, Daryl the Youngling dares you to kill five elder mountain boars within twelve minutes. He expects Loch Modan's rough highlands and dangerous wildlife to make you fail. Daryl the Youngling lives among Farstrider Lodge's seasoned huntsmen, but he lacks their quiet patience. He covers his youth with bluster and long hunting tales, including rambling accounts of how he earned his “famous” scar. He refuses to admit that anyone else is skilled. He also keeps getting his fellow hunters' names wrong and sets strict trials for newcomers, hoping to humble them and restore his standing among the lodge's residents. Elder mountain boars roam Loch Modan's crags and hillsides. They are massive and thick-skinned, and grow dangerous when provoked. Daryl gives you twelve minutes to find and kill five. If you finish in time, the loudmouthed youngster retreats awkwardly and pretends he knows nothing of the extravagant wager he made so casually.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_258-d6a181cd6f8c951ea8ff/1-0000.mp3", duration = 58.9061224, start = 0},
  },
}
P.transport["quest:26"] = {
  hash = "848f53",
  fullHash = "848f53",
  text = "A Lesson to Learn. In Darnassus, Mathrengyl Bearwalker sends young druids to Moonglade to learn the ways of water. There, an elder of the Cenarion Circle guides their first steps toward aquatic form. Mathrengyl Bearwalker guides young night elf druids as they practice among Darnassus’s boughs. When an initiate shows a firm bond with nature and is ready for greater responsibility, Mathrengyl sends them to master the waters. Cenarius’s gifts demand focus. To cross the depths without drowning, young druids need the guidance of the Cenarion Circle’s elders. You leave Darnassus for Moonglade, an ancient sanctuary beneath Mount Hyjal. In Nighthaven, Dendrite Starblaze waits as an elder mentor of the Cenarion Circle. Starblaze judges whether young shapeshifters are ready for the trials that lead to aquatic form. Mastering water takes physical resilience and mental resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_26-e171bcab06807066edc7/1-0000.mp3", duration = 54.7526531, start = 0},
  },
}
P.transport["quest:263"] = {
  hash = "fbec5c",
  fullHash = "fbec5c",
  text = "In Defense of the King's Lands. At the Southern Guard Tower, Mountaineer Wallbang calls travelers to defend Loch Modan from the Stonesplinter troggs. With Ironforge's reserves sent to distant fronts, the southern pass is thinly held. Wallbang sends seasoned recruits into Stonesplinter Valley against the clan's shamans and bonesnappers. Loch Modan's defenses are stretched thin. Ironforge's regular reserves have been summoned to distant fronts across Azeroth, leaving the Southern Guard Tower short-handed. Mountaineer Wallbang and his few comrades face constant pressure from the Stonesplinter clan. They depend on Alliance travelers passing through to help hold the southern pass. The fight reaches beyond stray scouts to the Stonesplinter clan's strength. Its bonesnappers bring brutal force, while its shamans use earthen magic to rally their kin. Slaying twenty of these foes weakens the clan's incursions into the lowlands. It also serves King Magni Bronzebeard's defense of the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_263-976c895e4b146372c04f/1-0000.mp3", duration = 60.4734694, start = 0},
  },
}
P.transport["quest:264"] = {
  hash = "ff7073",
  fullHash = "ff7073",
  text = "Until Death Do Us Part. In Silverpine Forest, Clarice Foster sends her keepsake to Yuriv’s grave. From the Pools of Vision beneath Thunder Bluff, the Forsaken asks you to lay it on the tomb of the husband who abandoned her and their children. Clarice Foster remembers her mortal marriage with bitterness. As Lordaeron crumbled, Yuriv left her and their children to join a crusade against the rising undead. He declared service to the Holy Light paramount. His devotion saved neither his family nor himself. Clarice was raised into undeath, while Yuriv lies beneath a defaced stone. She wants the last tangible reminder of his broken promises cast away. Yuriv’s tomb lies in the graveyard around the Sepulcher, marked by gashes, rubbish, and weeds. Set Clarice’s pendant on the relief of his sculpted hands. No grand magic or spiritual closure follows. The gem grows dull, and a cold, silent gust passes over the tombs. The old resentments of Lordaeron’s fallen people remain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_264-aca471e285bef2132ddb/1-0000.mp3", duration = 64.1044898, start = 0},
  },
}
P.transport["quest:267"] = {
  hash = "6112eb",
  fullHash = "6112eb",
  text = "The Trogg Threat. At Loch Modan’s Southern Gate, Captain Rugelfuss faces a growing trogg threat with too few defenders. The Ironforge Reserve has been called away to Alliance battlefronts, leaving him to hold the pass while troggs threaten the nearby hills. Dwarven mountaineers and the Ironforge Reserve have gone to reinforce Alliance battlefronts. Captain Rugelfuss now has only a small garrison. Strict orders keep him at the gate, unable to lead an attack into the highlands. Settlers and travelers there remain exposed to ambushes. Troggs in the nearby crags threaten Khaz Modan. Left unchecked, their numbers grow quickly, and they could overrun dwarven outposts. Rugelfuss calls for help to buy time and thin their ranks. Strike at the troggs in their hillside warrens, then bring back their stone teeth as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_267-52c9f4f4a1b8a99b90ca/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["quest:27"] = {
  hash = "1dd269",
  fullHash = "1dd269",
  text = "A Lesson to Learn. In Thunder Bluff, Turak Runetotem sends young tauren druids north to study the waters. Their road leads to Nighthaven in Moonglade, where the Cenarion Circle guides their training. You have learned the bear form and its strength. Now Turak Runetotem turns his students toward adaptability. Azeroth's waterways hold hazards that are hard for travelers bound to land. So he sends those devoted to nature north to learn the aquatic form. Turak Runetotem sends you beyond Mulgore to learn how to shape yourself for the waters. You travel to Moonglade, the sanctuary beneath Mount Hyjal, and reach Nighthaven. There, night elf mentors of the Cenarion Circle welcome tauren students. They set factional strife aside to preserve the shared teachings of Cenarius. Dendrite Starblaze waits for you in Nighthaven, where your training begins. The night elf elder says mastery over the waters must be earned. Two trials await. One tests your endurance and composure beneath the water. The other calls for deep spiritual understanding of the aquatic aspect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_27-a94a9a347a934e12d0c3/1-0000.mp3", duration = 67.6571429, start = 0},
  },
}
P.transport["quest:273"] = {
  hash = "abe9c1",
  fullHash = "abe9c1",
  text = "Resupplying the Excavation. Jern Hornhelm sends you from Thelsamar after a slow wagon carrying blastpowder to Ironband's Excavation Site. Its three dwarven haulers travel south along the Loch's shore. In southern Loch Modan, Ironband's Excavation Site needs blastpowder to break through hard rock. The powder comes first to Thelsamar, where Jern Hornhelm arranges for Huldar, Miran, and Saean to haul three volatile barrels south. The heavy load slows their pack team along the lakeside road, giving you time to catch them and help on the way.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_273-80f93629bdba7fc1d844/1-0000.mp3", duration = 31.8171429, start = 0},
  },
}
P.transport["quest:274"] = {
  hash = "5e6fec",
  fullHash = "5e6fec",
  text = "A Dark Threat Looms. At Stonewrought Dam, strange powder puts Loch Modan and Ironforge at risk. Ashlan Stonesmirk in Dun Modr identifies it as unstable Seaforium, which can explode when it touches water. Ashlan Stonesmirk recognizes the silver crystals and sharp odor in samples from Stonewrought Dam. The powder is Seaforium. It stays inert while dry, but moisture makes it react violently. An unchecked blast could blow Ironforge out of the mountain, Ashlan warns.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_274-65208f2d1280628e6191/1-0000.mp3", duration = 30.7461224, start = 0},
  },
}
P.transport["quest:2751"] = {
  hash = "b58a1a",
  fullHash = "b58a1a",
  text = "Barbaric Battlements. In Orgrimmar, Orokk Omosh seeks an apprentice to carry on his family's forge craft. With no heirs, he asks a budding smith to prove a sure hand with bronze before sharing his knowledge. Orokk Omosh works the anvils of Orgrimmar beneath the weight of his family's past. For twenty generations, the Omosh line has shaped ore into weapons and armor for the Horde. Orokk has no kin and cannot sire children, so he sees himself as a failure to that line. With the family craft at risk, he sets bloodline pride aside and seeks an apprentice to carry its smithing traditions forward. Orokk will not share his secrets with an untested smith. He asks for two patterned bronze bracers, two bronze greatswords, and two sharp beast claws as proof of skill at the anvil. To him, blacksmithing is no idle luxury. Its highest honor is armor and steel stained with enemy blood. Meet his demands, and he may believe an apprentice can keep the Omosh legacy alive and earn a chance to learn more of the craft.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2751-cc24085fc28969094d60/1-0000.mp3", duration = 63.6865306, start = 0},
  },
}
P.transport["quest:2753"] = {
  hash = "f1ead0",
  fullHash = "f1ead0",
  text = "Trampled Under Foot. In Orgrimmar's Valley of Honor, Orokk Omosh tests smiths with hard work. Green iron armor puts their endurance to the proof and teaches them to make heavy iron boots, while the Omosh bloodline's techniques hang in the balance. Orokk Omosh trains armorsmiths in Orgrimmar with trials of hard physical labor. To him, metalworking is more than heating ore and shaping it. It honors his ancestral clan and tests a smith's endurance. This is the third trial in his chain, and making tempered green iron armor again and again builds muscle and discipline. Smiths who bring Orokk the requested green iron gear win rare praise from the gruff armorsmith. He compares an artisan who endures the work to his grandfather, Chief Gorokk of Omosh. For the armor, Orokk teaches the ancestral design for sturdy iron boots. Horde warriors wear them to crush their enemies beneath their heels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2753-4e7e2386d3733d4f07d4/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["quest:2755"] = {
  hash = "b035ce",
  fullHash = "b035ce",
  text = "Joys of Omosh. After your great help, Orokk Omosh shares a family tradition in Orgrimmar. The veteran blacksmith wipes his tears away as soot, then dances for joy to pass on an unusual piece of family heritage. At Orgrimmar's forge, Orokk Omosh is known for heavy hammer blows, not tears. Your great help has touched the burly blacksmith deeply. Yet he stubbornly blames a fleck of soot in his eye rather than admit he is weeping. Before you part, Orokk Omosh says he must share one last family secret. He performs the vigorous, exhausting Omosh dance of joy for his apprentice. Then he teaches the apprentice to strike with an iron fist.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2755-8de4dbe0bf41f3a02335/1-0000.mp3", duration = 41.0906122, start = 0},
  },
}
P.transport["quest:278"] = {
  hash = "0910f0",
  fullHash = "0910f0",
  text = "A Dark Threat Looms. Dark Iron explosives threaten the Stonewrought Dam, and Chief Engineer Hinderweir the Seventh needs your help. He asks you to gather rare reagents from Loch Modan so he can make a mixture to neutralize them. Chief Engineer Hinderweir the Seventh needs three ingredients for his mixture. Forest Lurker venom, a tear from a crocolisk in the Loch, and a Mo'grosh crystal each bring a different reaction. Together, they can render the dwarven charges inert. The ingredients lie in dangerous parts of Loch Modan. Forest Lurker spiders and crocolisks threaten travelers, while Mo'grosh ogres guard their mined crystals in a stronghold to the northeast. Reaching the crystals means facing the ogres in their encampments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_278-aea9dac2e5ff3d38f2ea/1-0000.mp3", duration = 45.4791837, start = 0},
  },
}
P.transport["quest:280"] = {
  hash = "6bad8e",
  fullHash = "6bad8e",
  text = "A Dark Threat Looms. Dark Iron saboteurs threaten the Stonewrought Dam in Loch Modan. Chief Engineer Hinderweir the Seventh needs the charge disarmed before the loch floods the lowlands. Chief Engineer Hinderweir the Seventh saw Dark Iron Insurgents swim toward the Stonewrought Dam with a keg of explosive Seaforium. No Mountaineers were nearby to stop them. The infiltrators fastened the keg against the dam’s underwater foundation. If the dam breaks, the loch will flood the lowlands and cripple dwarven trade and travel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_280-c37f9bf82980b085599d/1-0000.mp3", duration = 32.2089796, start = 0},
  },
}
P.transport["quest:282"] = {
  hash = "671fda",
  fullHash = "671fda",
  text = "Senir's Observations. Grelin Whitebeard sends you east to Kharanos with his report for his brother Senir. Troggs have overrun the tunnel from Coldridge Valley, where Mountaineer Thalos guards the way. Grelin Whitebeard's report tells of Frostmane troll activity around Coldridge Valley. The trolls stole his journal, and you recovered it. Grelin judged the findings too important for an inexperienced apprentice to carry. So he entrusts the report to you, to deliver directly to his brother Senir in Kharanos. Troggs have overrun the eastern tunnel from Coldridge Valley into the rest of Dun Morogh. Mountaineer Thalos guards the entrance to keep civilians from danger. He lets travelers through only when they carry urgent official business.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_282-4ae2f60ef9d91e4d284a/1-0000.mp3", duration = 42.8408163, start = 0},
  },
}
P.transport["quest:287"] = {
  hash = "1a14b0",
  fullHash = "1a14b0",
  text = "Frostmane Hold. Above Iceflow Lake, Frostmane trolls guard a cavern stronghold in the western peaks. Senir Whitebeard, a mountaineer and scout in Kharanos, sends you to scout its depths and bring back intelligence for his reports. Senir tracked the aggressive tribes to their main cavern southwest of Brewnall Village. Armed trolls crowd the entrance. Behind on his official reports, Senir will not enter alone, so he hires you to scout the icy cavern in his place. Above Iceflow Lake, the stronghold is carved into the western peaks and packed with hostile ice trolls. You fight through underground tunnels, kill the Frostmane Headhunters stationed along the ledges, and map the interior. Your findings give Senir the intelligence he needs to complete his report for Ironforge's military commanders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_287-84f5b350ce2eb9439f3e/1-0000.mp3", duration = 49.2408163, start = 0},
  },
}
P.transport["quest:291"] = {
  hash = "9b5a0d",
  fullHash = "9b5a0d",
  text = "The Reports. From Kharanos, Senir Whitebeard sends word to Senator Barin Redstone in Ironforge about the Frostmane threat to Dun Morogh. He asks you to leave his scout unnamed. The report carries news from deep inside Frostmane Hold, where the trolls threaten Dun Morogh. Senir wants you to take it straight to Barin Redstone and keep the scout from the snowy crags unnamed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_291-6094f814986fe74060bd/1-0000.mp3", duration = 24.0587755, start = 0},
  },
}
P.transport["quest:2948"] = {
  hash = "9c346e",
  fullHash = "9c346e",
  text = "Gnome Improvement. In Ironforge, Talvash del Kissel offers to improve a ring he made in Gnomeregan. He needs silver and moss agate for a delicate lattice over its old band. Talvash del Kissel fled Gnomeregan after the trogg invasion and radiation brought the city down. Now the gnome refugee lives in Ironforge's Mystic Ward. The jeweler and tinkerer is short on coin and out of stock, but determined to prove his skills remain sharp in exile. Talvash is glad to see his simple ring design again, cleaned by the Sparklematic 5200. Yet he considers the old band dated. He offers to improve it with silver and moss agate lattice work, showing his skill with metal and gemstones.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2948-366180a14ba3a8e644f5/1-0000.mp3", duration = 45.0089796, start = 0},
  },
}
P.transport["quest:2950"] = {
  hash = "834652",
  fullHash = "834652",
  text = "Nogg's Ring Redo. In Orgrimmar, Nogg seeks to improve a ring brought from Gnomeregan. He wants rare materials and word of the Dark Iron dwarves, hoping to prove goblin craft finer than gnomish design. You carry a cleaned gold ring from Gnomeregan to Nogg's workshop in the Valley of Honor. The goblin engineer studies its plain gnomish work and offers a bargain. Bring him raw materials and a small fee, and he will frame the band with silver and moss agate. The lattice is meant to strengthen the magic within.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2950-11f17a38bac13fbab012/1-0000.mp3", duration = 30.2759184, start = 0},
  },
}
P.transport["quest:298"] = {
  hash = "60ef9d",
  fullHash = "60ef9d",
  text = "Excavation Progress Report. At Ironband's Excavation Site, Prospector Ironband needs you to carry his dispatches and powder orders to Jern Hornhelm in Thelsamar. Ironband's dispatches tell of his dig and renew its supply requests. The work needs picks, workers, and blasting powder to break through bedrock. Ironband relies on runners to keep Jern Hornhelm informed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_298-338b382dfa0227dcdb71/1-0000.mp3", duration = 22.3085714, start = 0},
  },
}
P.transport["quest:2997"] = {
  hash = "4ef0d9",
  fullHash = "4ef0d9",
  text = "Tome of Divinity. Azar Stronghammer sends promising dwarven paladins from Dun Morogh to Ironforge for deeper instruction. There, Tiza Battleforge awaits in the Hall of Mysteries, where the trials begin in service to the Holy Light. Dwarven initiates guard Dun Morogh's snowbound villages and roads. When Azar sees that a defender is ready for deeper spiritual instruction, he sends that candidate from field duties to Ironforge. There, the city's holy elders can guide them. The summons takes you through the Mystic Ward to the Hall of Mysteries. Sacred relics and solemn study fill its halls. Tiza Battleforge tests your readiness for self-sacrifice, mercy, and the moral duties of your calling.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2997-8c032e2dff0a1cba0308/1-0000.mp3", duration = 44.0685714, start = 0},
  },
}
P.transport["quest:2998"] = {
  hash = "e48646",
  fullHash = "e48646",
  text = "Tome of Divinity. A summons now calls promising paladins from Elwynn to Stormwind. Brother Wilhelm sends for them, and the Tome of Divinity begins the sacred trials that teach mastery of resurrection through the Holy Light. In Elwynn Forest, novice paladins spend their early days helping locals and testing their strength against wolves, Defias bandits, and kobolds. When an initiate shows discipline in battle and devotion to the Holy Light, mentors such as Brother Wilhelm send a personal summons. The paladin leaders mark promising students and direct them to leave the local chapels behind. Their report is due at the kingdom's spiritual heart. In Cathedral Square, Stormwind's Cathedral of Light is the kingdom's foremost sanctuary for its priesthood and the Knights of the Silver Hand. Duthorian Rall lives there and oversees those sworn to the Order. Beneath its vaulted ceilings, high-ranking paladins set the formal trials of the Tome of Divinity before each initiate. The trials test compassion, fortitude, and willingness to sacrifice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2998-ee9f1c7b73ef4dea27f6/1-0000.mp3", duration = 61.9102041, start = 0},
  },
}
P.transport["quest:2999"] = {
  hash = "69a806",
  fullHash = "69a806",
  text = "Tome of Divinity. In Ironforge, young dwarven paladins are sent to Tiza Battleforge to learn the Holy Light's deeper duties. Their rite of passage reaches beyond martial training and toward sacred vows. You have defended Anvilmar and Kharanos from troggs and frost trolls, proving your discipline in battle. Now Brandur Ironhammer, your trainer, sends you upstairs in the Hall of Mysteries. Senior paladins there prepare initiates for the order's spiritual duties. Tiza Battleforge teaches that the Light asks more than swordplay and hammer blows. It asks for compassion, justice, and self-sacrifice. Seeking her begins your formal study of the Tome of Divinity, a sacred path toward the power to resurrect the fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2999-898aaf91c80782f3ee0a/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["quest:3000"] = {
  hash = "6400cc",
  fullHash = "6400cc",
  text = "Tome of Divinity. In Ironforge, dwarf paladins return for deeper training in the Holy Light. Lord Grayson Shadowbreaker sends them home, and Tiza Battleforge guides them toward the sacred trials of the Tome of Divinity. Dwarf paladins keep their spiritual and martial roots in Khaz Modan, even when they serve Stormwind or travel through human lands. When Lord Grayson Shadowbreaker judges that a dwarf has gained enough field training, he sends them home. There they learn the duties expected of a full Knight of the Silver Hand. In Ironforge, you are directed to the Mystic Ward and the Hall of Mysteries. Tiza Battleforge waits upstairs, where she mentors young dwarven paladins. She prepares them to bear the burden of the Holy Light through sacred trials recorded in the Tome of Divinity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3000-f67ef71ed2e7fac625d9/1-0000.mp3", duration = 49.6326531, start = 0},
  },
}
P.transport["quest:301"] = {
  hash = "09fd13",
  fullHash = "09fd13",
  text = "Report to Ironforge. Jern Hornhelm sends Ironband’s report to Prospector Stormpike in Ironforge. The dig in southern Loch Modan has run short of blasting supplies, and the Explorers’ League must attend to it. The Explorers’ League funds and oversees archaeological expeditions across Khaz Modan, and supplies them. Ironband’s dig in southern Loch Modan has run short of blasting supplies. Its overseers cannot simply requisition more nearby.\n\nAt the Thelsamar inn, Jern Hornhelm entrusts you with Ironband’s written report. You carry it over the mountain passes to Prospector Stormpike at the League’s headquarters in Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_301-3168a6ba950a2ba37724/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["quest:302"] = {
  hash = "ccb4b8",
  fullHash = "ccb4b8",
  text = "Powder to Ironband. In Ironforge, the Explorer's League sends blasting powder south to Prospector Ironband's dig in Loch Modan. Prospector Stormpike approves the request, and the shipment goes to Thelsamar before continuing to Ironband's Excavation. The Explorer's League sends blasting powder from Ironforge to Prospector Ironband's expedition in southern Loch Modan. When the dig runs short, word reaches the League's leaders. Prospector Stormpike approves the request and sends the runner to Jern Hornhelm in Thelsamar, the valley's main supply hub.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_302-3b781d2a814648b4ad6a/1-0000.mp3", duration = 34.1420408, start = 0},
  },
}
P.transport["quest:3065"] = {
  hash = "2a8466",
  fullHash = "2a8466",
  text = "Simple Tablet. In the Valley of Trials, a marked parchment sends you to Frang after you prove yourself against local beasts. The warrior trainer waits outside the Den. After you prove yourself against the Mottled Boars, Gornek gives you a parchment marked for you alone. Durotar is harsh, so the Horde gives its fighters guidance quickly. The parchment sends you to Frang, the veteran warrior trainer outside the Den. Frang shelters in the shade outside the Den and watches recruits come from the red scrubland. He judges each arrival with a seasoned eye, then teaches the fundamentals with a heavy axe or a spear. He prepares each recruit to defend the young Horde's fragile settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3065-915947f8983cba1ca12a/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["quest:307"] = {
  hash = "336ff3",
  fullHash = "336ff3",
  text = "Filthy Paws. In Silver Stream Mine, Filthy Paws supplies wait in danger. The Miners' League stored its equipment there after the ore ran dry, but kobolds now fill the tunnels. Mountaineer Stormpike wants the tools recovered before his warriors attack. Silver Stream Mine lies in northern Loch Modan, east of Algaz Station. Its silver ran out long ago, so the dwarven Miners' League turned the empty shafts into a depot for spare excavation gear, picks, and staging materials. Across Khaz Modan, sturdy tunnels make good storehouses, provided they stay guarded and locked against the wilderness. As dwarven watchfulness across Loch Modan has thinned, kobolds have slipped into the mine. Dark shafts and gleaming iron tools drew the scavengers, and soon the depot became their warren. Mountaineer Stormpike is ready to lead warriors inside and drive them out, but their heavy boots and sweeping blows could smash the crates. You can slip or fight your way in to recover the League's supplies before the assault begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_307-256613be0b8a82d3865c/1-0000.mp3", duration = 62.7722449, start = 0},
  },
}
P.transport["quest:308"] = {
  hash = "f39d78",
  fullHash = "f39d78",
  text = "Distracting Jarven. At Thunderbrew Distillery in Kharanos, Jarven Thunderbrew watches the cellar stores. His family forbids him to drink from the barrels while on duty, so he asks you to bring him Thunder Ale from upstairs. He hopes a mug will sharpen his wits. Jarven watches the deep stores, with Dun Morogh’s finest stout all around him. His family forbids him to drink from the stock while he is on guard. Yet temptation gets the better of him, and he asks you to fetch a pint of potent Thunder Ale from the taps upstairs. Jarven says a good drink will sharpen his senses and strengthen his watch. Whether a guard ought to drink on duty is another matter. Still, few hardy dwarves can fault a Thunderbrew for wanting a taste of the ale his own kin make.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_308-98245ae023981485e831/1-0000.mp3", duration = 45.9755102, start = 0},
  },
}
P.transport["quest:3082"] = {
  hash = "c1b727",
  fullHash = "c1b727",
  text = "Etched Tablet. In the Valley of Trials, Gornek sends a carved tablet to young hunters. Jen'shan's mark calls them to train in the wild. After young hunters prove themselves against the boars near the Den, Gornek brings them a carved tablet. Jen'shan's mark is cut into the stone. She is a skilled troll huntswoman stationed nearby, and her message shows that seasoned hunters have noticed the recruit's grit. Now the lesson turns from surviving local dangers to disciplined training in the wild. Jen'shan teaches that orcs and trolls have a long history within the Horde. Orcs brought renowned traditions of warriors and shamans. The Darkspear trolls carried ancient skills in stalking, tracking, and survival, which helped orcs endure life on Azeroth. As Jen'shan trains new hunters, the two peoples share what they know, bound by respect for the hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3082-f1cd672cf706fcbb041e/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["quest:3083"] = {
  hash = "0f0434",
  fullHash = "0f0434",
  text = "Encrypted Tablet. In the Valley of Trials, Gornek sends new rogues to Rwag with a coded message. The summons leads them into the Den, where rogue training is bound to the Shattered Hand. Gornek gives the Encrypted Tablet to initiates who prove their mettle against the local wildlife. Its message is written in cipher, a test and safeguard for those trained in stealth, poison, and subterfuge. The summons sends each recruit into the Den to meet Rwag, trainer of the Horde’s rogues, thieves, and cutpurses. Inside the Den, Rwag trains new rogues as an agent aligned with the Shattered Hand. He says the guild will not dictate every breath, yet the Hand holds him to account if an apprentice fails to perform. The fledgling Horde is surrounded by foes, so it depends on silent scouts and agile cutpurses to gather intelligence and strike from the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3083-eb4811db9b19ac453788/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["quest:3084"] = {
  hash = "ae80e8",
  fullHash = "ae80e8",
  text = "Rune-Inscribed Tablet. In the Valley of Trials, Shikrik calls promising initiates to formal shaman training. The tablet's runes carry the summons to study the spirits and the elements: earth, fire, water, and air. After showing early discipline in the Valley of Trials' dusty grounds, fledgling shamans receive a carved stone tablet from Gornek. Its runes carry an invitation from Shikrik, the local shaman trainer. The summons says each initiate is ready to look beyond physical combat and heed the deeper currents of the natural world. Shamanism holds a sacred place in the revitalized Horde. Shikrik teaches that shamans draw power from the four elements and strength from ancestral spirits. They follow Warchief Thrall's example as spiritual guides and sources of wisdom for their communities. Across Durotar, they protect the settlements taking root.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3084-bf45e00c75fef190ad2b/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["quest:3085"] = {
  hash = "49b3c9",
  fullHash = "49b3c9",
  text = "Hallowed Tablet. In the Valley of Trials, the Hallowed Tablet carries Ken'jai's call to young priests after their first test. It points them toward the Darkspear way of communing with spirits. After you prove yourself against the boars under Gornek's watch, he gives you an inscribed stone: the Hallowed Tablet. Ken'jai's mark is on its message. The Darkspear mystic waits outside the Den, where he watches over newcomers drawn to faith and spiritual magic. Darkspear priests among the Horde seek communion with spirits and loa. Across the sea, human and dwarven priests follow the Holy Light. Ken'jai welcomes you to Durotar and teaches that spiritual discipline makes your power grow. He will guide you in greater rites as your bond with the spirits matures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3085-8f2571341fa85584fd74/1-0000.mp3", duration = 47.6473469, start = 0},
  },
}
P.transport["quest:3086"] = {
  hash = "5c754b",
  fullHash = "5c754b",
  text = "Glyphic Tablet. In the Valley of Trials, a Glyphic Tablet calls young Horde mages to Mai'ah. Gornek gives it to them after they prove their strength, and the troll trainer waits outside the Den. You have proved your strength against the Valley of Trials' wildlife. Gornek gives you an inscribed tablet sent by Mai'ah, the valley's mage trainer. When you are ready to begin your arcane studies, she asks you to meet her by the Den's entrance. Mai'ah speaks plainly about a mage's power and its danger. Magic's unseen pull toward corruption, she warns, is a greater threat than rival warriors or enemy races. Humility and patience matter. Without them, unchecked sorcery can make a mage believe they have mastered more than they have.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3086-7016c81936e5b625d802/1-0000.mp3", duration = 44.4604082, start = 0},
  },
}
P.transport["quest:3087"] = {
  hash = "c34e5c",
  fullHash = "c34e5c",
  text = "Etched Parchment. In the Valley of Trials, Gornek delivers Jen'shan's summons to a young hunter. It comes after the initiate's first blooding and opens the way to wilderness training in Durotar. After proving themselves against mottled boars, hunters in the Valley of Trials receive a parchment from Gornek. Jen'shan, a skilled Darkspear hunter, sent it after watching new arrivals from the edges of the encampment. Her note welcomes the initiate to formal training and recognizes the instincts needed to master Durotar's untamed beasts and harsh land. Reporting to Jen'shan marks the move from recruit to dedicated stalker. She warns that hunting is no easier than the arcane arts or ancestral shamanism. Mastering Durotar's predators, keeping ranged weapons in good order, and surviving on unforgiving land all demand discipline.\n\nJen'shan sends her apprentices to aid the valley's other inhabitants and test their abilities. Then they return to learn more advanced ways to survive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3087-ce44bb94a3ced1f82219/1-0000.mp3", duration = 61.1526531, start = 0},
  },
}
P.transport["quest:3088"] = {
  hash = "db7501",
  fullHash = "db7501",
  text = "Encrypted Parchment. In the Valley of Trials, Encrypted Parchment calls proven novice orc rogues toward the Den. Its cipher leads them to Rwag, an agent of the Shattered Hand. Gornek gives the coded parchment to novice orcs who have proved themselves against the local wildlife. Other trainers recruit pupils openly in the clearing, but rogue instructor Rwag sends his summons by cipher. The message leads you past the sunlit camp and deep into the cavern called the Den. You find Rwag watching among the rocks inside the Den. Warlocks lurk deeper in the cave, and Rwag tells you he watches recruits for the Shattered Hand. Orcish society prizes open honor and glory in battle. The Shattered Hand works in secret as the Horde's network of spies, cutthroats, and gatherers of intelligence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3088-9d4cecd5d8f3f321ebbb/1-0000.mp3", duration = 50.6253061, start = 0},
  },
}
P.transport["quest:3089"] = {
  hash = "9edef5",
  fullHash = "9edef5",
  text = "Rune-Inscribed Parchment. At the Valley of Trials, Gornek gives new shamans Rune-Inscribed Parchment, a summons from Shikrik. It begins their training in communion with spirits and the elements. New orc shamans prove they can survive against local wildlife. Then Gornek, who oversees the Valley of Trials, gives them a rune-inscribed summons. Shikrik, the valley's shaman trainer, wrote its mystical message and asks to meet each newly arrived initiate. Meeting Shikrik begins a shaman's sacred duty to the Horde. She teaches that shamans serve as conduits for ancestral spirits and wield the wrath of the elements. Under her guidance, new shamans learn to channel spiritual energies, mend wounds, and call on Kalimdor's natural forces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3089-7204d84794a84a16b16a/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["quest:309"] = {
  hash = "a9017d",
  fullHash = "a9017d",
  text = "Protecting the Shipment. In southern Loch Modan, Miran carries blasting powder toward Ironband's Excavation Site. Prospector Ironband needs it for his dig, but failed supply lines and threats to the courier wagons have left Miran stranded. Prospector Ironband needs blasting powder to cut through stone at his dig. Miran is stranded on the road under threat, carrying a heavy load. You guide him along the uneven roads to the excavation site so the powder can reach the dig.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_309-26c9e7d8688140be4f8b/1-0000.mp3", duration = 28.2644898, start = 0},
  },
}
P.transport["quest:3092"] = {
  hash = "4dde67",
  fullHash = "4dde67",
  text = "Etched Note. At Camp Narache, Etched Note calls a young tauren hunter to train with Lanka Farshot. The message begins their study of the wild. Grull Hawkwind gives the etched message to a young tauren skilled in marksmanship and tracking. The novice has trained among the bluffs of Red Cloud Mesa. Lanka Farshot has noticed the youth's bloodline and raw ability, and calls them to study under his watch. Among the Shu'halo, hunters scout and fight, but they serve the tribes in other ways too. They provide food with their quarry, guard nomadic camps, and keep close to Kalimdor's beasts. Lanka begins with weapons and Mulgore's creatures. In time, the novice may learn the ancient art of taming wild companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3092-d6fe5dac1aab120b5d87/1-0000.mp3", duration = 46.8636735, start = 0},
  },
}
P.transport["quest:3094"] = {
  hash = "514b99",
  fullHash = "514b99",
  text = "Verdant Note. At Camp Narache, the Verdant Note calls young tauren to seek Gart Mistrunner. Grull Hawkwind carries the summons on Gart’s behalf. On the Red Cloud Mesa, Grull Hawkwind gives young tauren a message from a messenger sent by Gart Mistrunner. The summons calls those with natural gifts to accept their responsibilities. It invites them into the ancient practice of tauren druidism and asks them to leave simple village errands behind for the balance of the plains. Gart Mistrunner warns that ancestral and natural spirits have grown restless across Mulgore. Tauren druids act as living avatars of nature and keep harmony with the Earthmother’s will despite rivalries far away. Night elves also practice druidic arts, but Gart says their pride blinds them to the tauren’s deep bond with the natural realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3094-57cbd9d30c918a791b89/1-0000.mp3", duration = 49.4759184, start = 0},
  },
}
P.transport["quest:3096"] = {
  hash = "717d01",
  fullHash = "717d01",
  text = "Encrypted Scroll. At Deathknell, a sealed message reaches a newly awakened Forsaken rogue. Shadow Priest Sarvis sends the recruit to David Trias after they prove ready. Newly raised Forsaken fight mindless zombies in the cemetery while Deathknell's leaders watch for those drawn to stealth and subterfuge. Once you prove ready, Shadow Priest Sarvis gives you a sealed parchment. David Trias's discreet seal marks an early link to the covert network beneath Forsaken leadership. David Trias watches Deathknell's crossroads and inn for prospects in future covert operations. The Forsaken need disciplined agents for their fledgling kingdom, not common thieves or reckless cutpurses. Trias says capable rogues may draw the notice of the Shadowstalkers, a Forsaken cadre that prizes cunning, precision, and absolute loyalty to the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3096-d21019ea9da451a5e287/1-0000.mp3", duration = 52.7934694, start = 0},
  },
}
P.transport["quest:3097"] = {
  hash = "30a104",
  fullHash = "30a104",
  text = "Hallowed Scroll. In Deathknell, Shadow Priest Sarvis calls newly risen Forsaken priests to the chapel. He sends each novice to Dark Cleric Duesten to learn how the Forsaken wield faith after death. Newly awakened undead stagger from Deathknell’s graves, their minds shaken by plague, death, and freedom from the Lich King's grip. Those who followed the Holy Light in life find death hard to understand. As fledgling undead fight the mindless Scourge at the settlement’s edge, Shadow Priest Sarvis receives a message from Dark Cleric Duesten. It calls newly risen priests away from their wandering and into the desecrated town chapel. At the chapel, Dark Cleric Duesten teaches a harsh faith. He says the Holy Light abandoned the Forsaken in death, ancestral spirits are hollow tales, and demons do not care about their plight. Forsaken clergy teach that willpower and self-reliance are their only sources of salvation. Under Duesten’s guidance, newly risen priests learn divine discipline and shadow through faith in their own survival, not devotion to distant gods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3097-443c99f17888161fd1f9/1-0000.mp3", duration = 65.8285714, start = 0},
  },
}
P.transport["quest:3098"] = {
  hash = "d7b5f6",
  fullHash = "d7b5f6",
  text = "Glyphic Scroll. In Deathknell, Isabella calls newly awakened Forsaken mages to the ruined church. Her sealed scroll bids them to hone their volatile arcane powers. Isabella calls newly awakened Forsaken mages to the ruined church in Deathknell. Nearby, you show an affinity for arcane magic while fighting the mindless Scourge. Then a scroll bearing her arcane sigil bids you to report to her. Isabella trains local mages and knows untrained magic can endanger the Forsaken as much as their enemies. In Deathknell’s ruined chapel, Isabella teaches new Forsaken mages that undeath has not ended the dangers of arcane magic. Their bodies have lost life’s frailties, yet magic remains volatile and corrupting. Mastering the arcane takes more than study. It can help the Forsaken survive, seek vengeance, reclaim their destiny, and destroy those who threaten their fragile return to Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3098-838e8795dde1060fb0dc/1-0000.mp3", duration = 57.5738776, start = 0},
  },
}
P.transport["quest:31"] = {
  hash = "e7e035",
  fullHash = "e7e035",
  text = "Aquatic Form. In Thunder Bluff, a young Horde druid returns to be recognized among the keepers of nature. The druid has proved worthy in Moonglade and taken on the sea lion aspect; now formal recognition brings Aquatic Form. Dendrite Starblaze sends you back to Mulgore after your trials in Moonglade. The Pendant of the Sea Lion bears proof of your balance and dedication across Kalimdor's waters. By carrying it home, you show that you have honored the ancient traditions needed to take an aquatic aspect. At Thunder Bluff's heights, you bring the pendant to Turak Runetotem, your mentor. He is pleased that you have honored your ancestors and kept nature in balance. Then Turak teaches you the secret of aquatic form. You can swim beneath rivers and oceans, breathe freely, and find your way through the depths as a sea creature.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_31-9f1147c34a6fb782a0c7/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["quest:310"] = {
  hash = "4f8643",
  fullHash = "4f8643",
  text = "Bitter Rivals. Marleth Barleybrew asks you to replace a cask of Thunder Ale at the Thunderbrew Distillery in Kharanos with her family's brew. The Barleybrews have long begrudged the Thunderbrews the fame of their distillery. Marleth respects its ale, but she cannot abide Dun Morogh knowing only Thunderbrew. She means to change local tastes with her family's fiery Barleybrew Scalder. Beneath the Thunderbrew Distillery in Kharanos, aging casks fill a basement storeroom. A guard watches near the Thunderbrews' prized reserve. Draw him away, then secretly switch the barrels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_310-ded67e4474685f0673b6/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["quest:3103"] = {
  hash = "e2ed0e",
  fullHash = "e2ed0e",
  text = "Hallowed Letter. In Northshire, Marshal McBride gives promising young priests a letter from Priestess Anetta. It calls them to begin formal training in the Holy Light at Northshire Abbey, while trouble still shadows the realm. After proving themselves against the kobold camps around Northshire, novice priests receive a letter sealed by Priestess Anetta. Marshal McBride delivers it as an invitation to study the Holy Light in the abbey's quiet halls. When you bring the letter, Priestess Anetta tells you the realm remains troubled. The Burning Legion's lingering threats still shadow Azeroth, and the continents bear fresh wounds and unrest. To Anetta, becoming a priest means more than study. It is a duty to bring healing and comfort to a suffering world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3103-10ecda72725b6a08eb21/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["quest:3104"] = {
  hash = "9c1bed",
  fullHash = "9c1bed",
  text = "Glyphic Letter. A summons reaches novice human mages in Northshire Valley from Marshal McBride. Khelden Bremen calls promising spellcasters to Northshire Abbey to begin their arcane tutelage. Marshal McBride gives the rune-marked letter to an aspiring apprentice who has proved capable by helping him against local vermin. Khelden Bremen, the mage trainer at Northshire, wrote it. He watches new recruits arrive at the abbey, looking for magical discipline and talent. Northshire Abbey has long sheltered the Holy Light. Yet Stormwind's dangers call for practitioners of every discipline. The letter brings you upstairs to Khelden Bremen, who offers no easy praise. He warns that mastering arcane power means defying nature's limits. Such power earns profound respect and deep fear from ordinary folk.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3104-a38ca782de38e54798f5/1-0000.mp3", duration = 50.4685714, start = 0},
  },
}
P.transport["quest:3105"] = {
  hash = "123f54",
  fullHash = "123f54",
  text = "Tainted Letter. In Northshire, Tainted Letter draws novice human warlocks away from the Abbey guards to learn the fel arts. Drusilla La Salle gives it to Marshal McBride, who carries it to her recruits. After proving themselves against the kobolds, novice warlocks receive a letter from Marshal McBride. Priests and paladins study openly in Northshire Abbey, but warlocks must keep to quieter paths. Drusilla La Salle's insignia marks the letter. It directs each fledgling spellcaster to her secluded post outside the abbey's main walls before taking on other duties. Drusilla warns that Stormwind's guards watch warlocks closely. She calls them 'pathetic mundanes.' Drawing power from the Twisting Nether and communing with demons both risk corruption. So she urges patience, prudence, and firm self-control when handling those dark energies. Caution, she says, must not extinguish a warlock's ambition.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3105-82706fcf0b00011a8807/1-0000.mp3", duration = 55.8497959, start = 0},
  },
}
P.transport["quest:3106"] = {
  hash = "1b6f0d",
  fullHash = "1b6f0d",
  text = "Simple Rune. At Anvilmar, Sten Stoutarm brings new dwarven warriors a summons from Thran Khorman. The rune calls them from Coldridge Valley's snowy paths to begin training. Veteran scouts watch recruits clear pests around Coldridge Valley, seeking promising fighters. Sten brings an inscribed stone from Thran Khorman. Its simple rune calls them from the snowy paths into Anvilmar's warm forge-hall, where they can pledge themselves to the warrior's trade. Thran speaks plainly about Dun Morogh's troubles. Gnomes displaced by the explosions that destroyed Gnomeregan seek refuge, while some dwarves take up foreign arcane arts or follow the human faith in the Holy Light. Troggs claw at the mountain borders after being disturbed deep underground. Thran believes firm martial discipline is needed to withstand these threats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3106-6d418636bf08945fc919/1-0000.mp3", duration = 50.3379592, start = 0},
  },
}
P.transport["quest:3107"] = {
  hash = "6ef016",
  fullHash = "6ef016",
  text = "Consecrated Rune. At Anvilmar, Bromos Grummner calls fledgling dwarven paladins to join the Knights of the Silver Hand. Sten Stoutarm summons them there. Your rune marks the start of a formal induction, where raw potential must meet discipline. Around Coldridge Valley, local leaders watch for those gifted in divine martial prowess. Bromos Grummner awaits inside Anvilmar to guide new initiates. The Knights of the Silver Hand began among the humans of Lordaeron, yet Ironforge dwarves embraced the Holy Light with fierce devotion. Bromos welcomes you into the brotherhood and reminds you that dwarven paladins share the solemn duty of protecting Azeroth. The order is grounded in sacrifice, tradition, and martial virtue, and asks recruits to take up hammer and faith in equal measure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3107-c850ae619f02b03d883d/1-0000.mp3", duration = 51.0693878, start = 0},
  },
}
P.transport["quest:3108"] = {
  hash = "b3a24f",
  fullHash = "b3a24f",
  text = "Etched Rune. In Coldridge Valley, novice dwarf hunters receive a carved summons from Sten Stoutarm. It sends them to Thorgas Grimson inside Anvilmar to learn the hunt. As you help Sten Stoutarm face threats around Coldridge Valley, he gives you the Etched Rune. Dwarven mentors favor carved runes for formal messages, not spoken orders or plain parchment. The stone asks you to take stock of your early work, then report indoors at Anvilmar for deeper instruction in the hunt. At Anvilmar, the Etched Rune marks a hunter's entry into formal discipline. Thorgas Grimson teaches that mountaineering and survival in Khaz Modan demand respect for the harsh land. You learn to read tracks in bitter snowdrifts, care for your weapons and ammunition, and understand the wild beasts roaming the crags. The rune marks your first step from a lone wanderer with a gun to an apprentice among Anvilmar's veteran pathfinders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3108-1dff11d05c6f7f511c35/1-0000.mp3", duration = 54.9877551, start = 0},
  },
}
P.transport["quest:3109"] = {
  hash = "90ce0c",
  fullHash = "90ce0c",
  text = "Encrypted Rune. In Coldridge Valley, Sten Stoutarm gives young rogues a coded rune and calls them into Anvilmar to meet Solm Hargrin. Sten says someone slipped him the etched stone to deliver. He suspects Solm Hargrin sent it. The rune tests whether a novice can keep a confidence, calling them inside without Solm announcing his need for scouts and scoundrels across the courtyard. Inside Anvilmar, Solm Hargrin welcomes the new rogues to their craft. He offers to teach the maneuvers, strikes, and subtle arts that keep them alive and earn them coin. He also reminds dwarf rogues to look after their displaced gnomish allies, still recovering from Gnomeregan's catastrophic fall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3109-bd92dd8b445f1be1c20b/1-0000.mp3", duration = 42.0310204, start = 0},
  },
}
P.transport["quest:311"] = {
  hash = "8f13bc",
  fullHash = "8f13bc",
  text = "Return to Marleth. Marleth waits in Brewnall Village for the Thunder Ale you bring from Kharanos. The barrel will prove her Scalder reached the Thunderbrew cellar. The barrel comes from the Thunderbrew cellar, taken under the distillers’ noses. It proves the switch worked and gives Marleth a trophy from her rival. You carry the heavy keg over snowy ridges to Brewnall Village. Marleth delights in outsmarting Kharanos’s guards and cellar masters. Her caper shows how fiercely dwarven families prize their signature recipes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_311-d89c76cd4771250f1200/1-0000.mp3", duration = 31.242449, start = 0},
  },
}
P.transport["quest:3110"] = {
  hash = "abcc99",
  fullHash = "abcc99",
  text = "Hallowed Rune. In Coldridge Valley, a young dwarf priest is called to Anvilmar by Sten Stoutarm. He carries Branstock Khalder’s inscribed prayers and guidance to the novice, who is summoned inside to deepen their bond with the Holy Light. A young priest earns Sten Stoutarm’s notice while helping clear threats outside Anvilmar. Branstock Khalder, the settlement’s spiritual guide, gives Sten a rune inscribed with prayers and guidance for the novice. Then the young priest is called inside Anvilmar’s sturdy halls to begin sacred studies. Dwarven life prizes martial strength and heavy plate, yet the Holy Light remains central to Ironforge society. In Coldridge Valley, holy casters stand with warriors and hunters to protect the enclave from trogg incursions and dangerous wildlife moving through the snow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3110-39942e0efb469543a965/1-0000.mp3", duration = 51.722449, start = 0},
  },
}
P.transport["quest:3112"] = {
  hash = "8b4cd0",
  fullHash = "8b4cd0",
  text = "Simple Memorandum. In Coldridge Valley, gnome warriors receive a call to Anvilmar. Sten Stoutarm carries Thran Khorman’s summons to trained fighters, who are invited to learn the arts of war and prepare to reclaim Gnomeregan. You help Sten Stoutarm drive off troggs and boars in Coldridge Valley. Thran Khorman, a veteran trainer in Anvilmar, sees promise in the refugee recruit. He calls the recruit to the central hall for martial instruction. Dwarven trainers may tease gnome warriors about their size, but Thran Khorman takes their loss seriously. He asks them to imagine how dwarves would feel if Ironforge fell to the Dark Irons. Thran has pledged to help the exiled gnomes. He teaches them the arts of war until they are ready to reclaim their home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3112-436042464ae6afcc3006/1-0000.mp3", duration = 46.315102, start = 0},
  },
}
P.transport["quest:3113"] = {
  hash = "3bbe57",
  fullHash = "3bbe57",
  text = "Encrypted Memorandum. In Coldridge Valley, Sten Stoutarm gives new gnome rogues a folded note for Solm Hargrin inside Anvilmar. As you help the mountaineers face trogg threats, Sten gives you a parchment entrusted to him. It looks like an official memorandum. The note invites you to meet Solm Hargrin, the rogue trainer stationed inside Anvilmar. Gnome survivors share close quarters with their dwarven hosts after Gnomeregan's sudden fall drove them from their underground home. Solm Hargrin knows rogues draw suspicion when items go missing. So he urges them to stand together quietly and help each other survive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3113-3e9b712462e70b41b772/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["quest:3114"] = {
  hash = "f8450e",
  fullHash = "f8450e",
  text = "Glyphic Memorandum. In Anvilmar, Mountaineer Sten Stoutarm gives you a memorandum from mage trainer Marryk Nurribit, who invites you to meet him. The summons is for you, a novice mage Sten assists in Coldridge Valley. Read it, then go inside Anvilmar to meet the gnome who wrote it. Your spellcraft studies begin there. Inside Anvilmar, gnome mage trainer Marryk Nurribit offers plain advice before your lessons. Keep out of serious trouble and save coin for training and tavern drinks. Stay clear of fallen Gnomeregan and its radioactive danger. Marryk is ready to teach you the arcane arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3114-77cbbaea25d8ccdbd5fb/1-0000.mp3", duration = 38.1387755, start = 0},
  },
}
P.transport["quest:3115"] = {
  hash = "aaf56b",
  fullHash = "aaf56b",
  text = "Tainted Memorandum. In Coldridge Valley, Sten Stoutarm quietly sends you to Alamar Grimm in Anvilmar. Grimm urges you to trust dark power over your dwarven hosts. Warlocks face deep suspicion in Coldridge Valley. As you help Sten Stoutarm with local threats, he reluctantly slips you a note. His warning makes plain how little your kind is trusted here, even under the uneasy truce that allows warlocks to practice in Alliance lands. In Anvilmar, Alamar Grimm speaks of the gnomes’ plight. He believes ordinary magic and tinkering failed Gnomeregan, bringing their people near extinction and leaving them as second-class refugees dependent on dwarven goodwill. He urges you to trust neither the Holy Light nor dwarven politics. Instead, summon fiends and master them, for their obedience is unconditional.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3115-7f27e21a6decc3176872/1-0000.mp3", duration = 52.7673469, start = 0},
  },
}
P.transport["quest:3116"] = {
  hash = "b9d2d2",
  fullHash = "b9d2d2",
  text = "Simple Sigil. In Shadowglen, Alyissia calls young night elf warriors to defend their people. Conservator Ilthalaine bears her summons as the Kaldorei face change across Teldrassil and beyond. You have proved your skill at surviving Shadowglen's restless wildlife. Now Conservator Ilthalaine gives you an inscribed sigil from Alyissia, the warrior trainer at Aldrassil. It marks the beginning of your combat training. Alyissia asks you to dedicate your strength to defending your people. Alyissia begins your training while the night elves face swift change and danger. In only a few years, they have raised the World Tree Teldrassil, watched a taint spread through forest beasts near and far, and reconnected with ancient lands once thought lost, including Feralas. The Kaldorei need capable defenders against these perils. Alyissia prepares young Kaldorei for more than combat. She asks you not to judge visitors to Teldrassil by their race. Some may not act from pure generosity, yet allies are vital to the Kaldorei's defense. As you take up the work of protecting your people, she asks you to offer visitors reasonable trust.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3116-6e29bdcdeb048602d58b/1-0000.mp3", duration = 72.2546939, start = 0},
  },
}
P.transport["quest:3117"] = {
  hash = "d0ac5e",
  fullHash = "d0ac5e",
  text = "Etched Sigil. In Shadowglen, the Etched Sigil sends young night elf hunters to Aldrassil. Through Conservator Ilthalaine, Ayanna Everstride calls them to meet their trainer and begin learning archery and beastcraft. After young kaldorei hunters help defend Shadowglen, Conservator Ilthalaine gives them an inscribed token. A messenger brought it from their mentor, Ayanna Everstride. The sigil directs each novice into Aldrassil’s high boughs, where the trainers watch over the canopy. Meeting Ayanna begins a hunter’s training on Teldrassil. She teaches novices marksmanship and how to understand Kalimdor’s wild creatures. A hunter must respect their beast companions and face the world’s unseen dangers with awareness and humility.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3117-e31769e65fa54f9445ca/1-0000.mp3", duration = 44.6693878, start = 0},
  },
}
P.transport["quest:3118"] = {
  hash = "b18cbe",
  fullHash = "b18cbe",
  text = "Encrypted Sigil. In Shadowglen, a coded summons brings new night elf rogues to their trainer. Conservator Ilthalaine carries the message for Frahun Shadewhisper, who warns that peace across Kalimdor remains fragile. While young night elves study nature's balance under Conservator Ilthalaine, those drawn to stealth receive a quieter summons. A runner brings the Encrypted Sigil from Frahun Shadewhisper, Shadowglen's rogue mentor. Its ciphers are meant for initiates of the trade. They are to decipher the message and find Frahun near the roots of Aldrassil to begin instruction. Frahun's message warns that peace across Kalimdor remains uncertain. The Third War has ended, but the truce between the Alliance and the emerging Horde is fragile. So rogue scouts and informers in Shadowglen are urged to sharpen their eyes and ears early. They watch for threats and covert provocations that could renew war across the borders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3118-3fb527dcc42a9924d837/1-0000.mp3", duration = 55.5363265, start = 0},
  },
}
P.transport["quest:3119"] = {
  hash = "d499da",
  fullHash = "d499da",
  text = "Hallowed Sigil. In Shadowglen, the Hallowed Sigil carries Shanda's call to young night elf priests beginning their training in Aldrassil. Conservator Ilthalaine delivers her message as novices learn to wield Elune's grace. Night elf priests serve Elune as handmaidens and servants of the moon goddess. When a young kaldorei in Shadowglen shows devotion and an affinity for the divine light, Conservator Ilthalaine gives them a hallowed sigil. Shanda, the priest trainer, sent the token by messenger as an invitation to come to Aldrassil and begin spiritual training. Shanda tells the young acolyte that unusual change has reached Teldrassil's sheltered sanctuary. Travelers fill the World Tree's boughs, including members of the wider Alliance who have leave to meet with the kaldorei. The wider world calls, but Shanda urges novices to first attend to Shadowglen's troubles before turning to conflicts beyond it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3119-0644e89cdcf43d90eebd/1-0000.mp3", duration = 56.5028571, start = 0},
  },
}
P.transport["quest:312"] = {
  hash = "82361d",
  fullHash = "82361d",
  text = "Tundra MacGrann's Stolen Stash. Tundra MacGrann needs his winter stores back from Old Icebeard. The yeti carried off the thorium-reinforced meat locker, and MacGrann's injured leg keeps him from reaching the cave. For the cold season, MacGrann had salted away a month's worth of dried meat. He sealed it in a thorium-reinforced locker to keep hungry bears out. Old Icebeard carried off the whole chest instead of trying to open it. While MacGrann was away hunting deer, Old Icebeard dragged the chest to a cave in the jagged hills. MacGrann believes the yeti cannot break through solid thorium, but his injured leg keeps him from retrieving the stores. You can face the beast or slip inside while it prowls the snowdrifts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_312-3e7c5dd9eb4e64770840/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["quest:3120"] = {
  hash = "101d7c",
  fullHash = "101d7c",
  text = "Verdant Sigil. In Shadowglen, newly awakened night elf druids receive a summons to begin their training. Conservator Ilthalaine gives them the Verdant Sigil for Mardant Strongoak inside Aldrassil, where their study of nature and the Emerald Dream begins. When a young night elf shows promise in keeping Shadowglen's balance, the order calls for a formal introduction. A runner brings the Verdant Sigil to Conservator Ilthalaine. She entrusts it to the initiate, showing that the circle in Aldrassil has taken notice and inviting the young druid to begin formal training. Present the sigil to Mardant Strongoak inside Aldrassil, and the initiate is welcomed into the fold. Deeper communion with the Emerald Dream and mastery of animal forms lie ahead. For now, Mardant becomes their first guide, teaching them to read nature's spirits and channel the raw power of the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3120-46204eb0b67b04bcbbf0/1-0000.mp3", duration = 53.1591837, start = 0},
  },
}
P.transport["quest:313"] = {
  hash = "f5236c",
  fullHash = "f5236c",
  text = "The Grizzled Den. At Steelgrill's Depot near Kharanos, Pilot Stonegear sends you west to hunt wendigos in the Grizzled Den. Their thick pelts will warm his siege engine, Trollplow. Stonegear tests newcomers before he trusts them with the work. A massive siege tank is hard to operate in freezing mountain air. It takes nerves of iron and a steady constitution. Face the native beasts in the frozen hills to prove you have both. Dun Morogh's bitter cold bites through Trollplow's cramped, iron-plated cabin. Stonegear wants thick wendigo manes for a warm, durable rug on the engine's deck. The hunt also helps keep the local beasts in check.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_313-aa3af2dd60f4a3d185a7/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["quest:314"] = {
  hash = "1858ad",
  fullHash = "1858ad",
  text = "Protecting the Herd. At Amberstill Ranch, Rudra Amberstill fears Vagash will take more prized mountain rams. He asks passing fighters to protect the herd and bring proof of the predator’s death. Vagash has taken two prized mountain rams from Amberstill Ranch. The ranch supplies the Bronzebeard dwarves with riding and working beasts, and the herd supports Dun Morogh’s rustic economy. Vagash hunts local livestock in the crags above the ranch. Ironforge’s forces are spread thin across the realm, supporting the Alliance on distant frontiers. With no military patrol on the ridgelines, Rudra Amberstill asks independent fighters to hunt Vagash. He wants one of the beast’s deadly fangs as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_314-8f706e207f2cc9c26ea6/1-0000.mp3", duration = 44.0685714, start = 0},
  },
}
P.transport["quest:315"] = {
  hash = "794b95",
  fullHash = "794b95",
  text = "The Perfect Stout. In Brewnall Village, Rejold Barleybrew still pursues The Perfect Stout. He draws on family brewing tradition and exotic local ingredients, and now seeks shimmerweed, a pungent plant cultivated only by the hostile Frostmane trolls atop Shimmer Ridge. He sends daring travelers into their encampment to take the herb from tribal baskets. Brewing is a way of life in Brewnall Village, especially for the Barleybrew family. Rejold Barleybrew believes greatness runs in his blood, but the perfect stout calls for new ideas. He looks beyond hops, malt and mountain spring water to Dun Morogh's untamed plants, hoping they will give his ale an unmistakable bite. East of Brewnall Village, the Frostmane trolls cultivate shimmerweed on Shimmer Ridge. They gather it for tribal and mystic rituals, while dwarves know it for its sharp, distinct flavor. The herb is kept in baskets in the troll village, where Rejold's latest and boldest brewing experiment awaits it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_315-cfc765b7787279cef672/1-0000.mp3", duration = 59.5330612, start = 0},
  },
}
P.transport["quest:317"] = {
  hash = "631fca",
  fullHash = "631fca",
  text = "Stocking Jetsteam. At Steelgrill's Depot, Pilot Bellowfiz prepares Jetsteam for a long deployment with the Ironforge Siege Brigade. Its crew needs boar meat and bear pelts for the journey. Master engineer Beldin Steelgrill tunes the siege tank at Steelgrill's Depot, just outside Kharanos. Jetsteam is being readied for an operation on behalf of the Siege Brigade. The crew needs a month's provisions to endure Dun Morogh's sub-zero temperatures. Beldin Steelgrill works beneath Jetsteam's hood, so Bellowfiz cannot leave the vehicle to gather food and insulation. The snowy plains south of the Grizzled Den hold boars for meat and bears whose pelts can line the tank's bedding and keep it warm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_317-cfd593476f48ea675429/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["quest:318"] = {
  hash = "6aa425",
  fullHash = "6aa425",
  text = "Evershine. At Steelgrill's Depot near Kharanos, Pilot Bellowfiz needs Evershine from Rejold Barleybrew in Brewnall Village. The strong brew warms him and can fuel his siege engine, Jetsteam. Rejold Barleybrew's brewing experiments go beyond ordinary dwarven ales. Evershine can knock all but the hardiest dwarves flat, yet its heat is prized in Dun Morogh's bitter cold. At Steelgrill's Depot outside Kharanos, Pilot Bellowfiz takes a warming sip of Evershine against the freezing winds. The volatile brew can also feed Jetsteam's furnace. When Bellowfiz is in a tight spot, it gives his siege engine an explosive burst of emergency power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_318-4b690e6cc5f7885b602a/1-0000.mp3", duration = 42.1616327, start = 0},
  },
}
P.transport["quest:319"] = {
  hash = "65abb9",
  fullHash = "65abb9",
  text = "A Favor for Evershine. At Steelgrill's Depot, Pilot Bellowfiz needs Evershine for his siege engine, Jetsteam. Rejold Barleybrew will give up a cask only after you drive the predators away from Brewnall Village. Rejold offers his brew if you thin the wild beasts of western Dun Morogh. Ice Claw Bears, Elder Crag Boars, and Snow Leopards roam near Brewnall Village. Their presence endangers the locals and keeps Rejold from freely giving up the cask. Rejold says no self-respecting dwarf cowers before wild animals. Yet watching for predators around the village takes the craftsmen valuable hours. Once the beasts are driven off, villagers can focus on distilling and smithing without keeping watch on the tree line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_319-61ce228eac8991270810/1-0000.mp3", duration = 44.8783673, start = 0},
  },
}
P.transport["quest:3221"] = {
  hash = "1cced5",
  fullHash = "1cced5",
  text = "Speak with Renferrel. At the Sepulcher, Apothecary Renferrel awaits your findings about the tainted wolf hearts. High Executor Hadrec has sent you to speak with the Royal Apothecary Society researcher. After you help the Deathstalkers across Silverpine Forest, High Executor Hadrec gives you an urgent message from Apothecary Renferrel. Renferrel has studied discolored wolf hearts gathered from local wildlife and needs you at once. Apothecary Renferrel works for the Royal Apothecary Society in a laboratory inside the Sepulcher crypt. He studies how dark magic and disease are changing Silverpine's beasts. His alchemical research draws on military reports from the front.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3221-ef577a21d4ad521c5b29/1-0000.mp3", duration = 41.0122449, start = 0},
  },
}
P.transport["quest:3261"] = {
  hash = "b18c62",
  fullHash = "b18c62",
  text = "Jorn Skyseer. In the southern Barrens, Jorn Skyseer guides Horde hunters seeking deeper knowledge of the wilds. After your hunts for Sergra Darkthorn, she sends you south to Camp Taurajo, where an elder tracker teaches you more. You have hunted sunscale and scytheclaw raptors across the northern savannah, earning Sergra Darkthorn's respect at the Crossroads. She knows a hunter needs more than skill with weapons; the land's great beasts demand understanding. Her teaching here is done, so she sends you south. The Gold Road leads south across rougher plains to Camp Taurajo, a tauren settlement near the southern wilds. Jorn Skyseer waits there, an elder tracker with lessons for hunters who seek elusive and legendary quarry across the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3261-9b7cc845aac9fd348936/1-0000.mp3", duration = 45.1134694, start = 0},
  },
}
P.transport["quest:3281"] = {
  hash = "6bda10",
  fullHash = "6bda10",
  text = "Stolen Silver. At the Crossroads, Gazrog sends you after silver stolen from the guards’ payroll by raptors. Their cunning has led you south of Ratchet, into the Raptor Grounds. The garrison needs its wages back. Gazrog needs the Crossroads guards paid, and raptors have taken their wages. He sends you to recover the stolen coin, not simply punish the beasts. At first, he wanted vengeance for the ambush on the payroll shipment. But killing the pack would not bring the money back. The Horde needs to learn how the raptors carried off heavy crates of coin and where they took them. Scouts found a raptor nest between two craggy peaks, south of Ratchet and northwest of Northwatch Hold. The creatures dragged the intact lockbox into their territory and guard it beside their eggs and fresh kills. Gazrog's tales of raptor cunning and hoarding now seem true. Ordinary beasts rarely stash metallic valuables.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3281-a8614d544edb24ec7b3e/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["quest:33"] = {
  hash = "b06342",
  fullHash = "b06342",
  text = "Wolves Across the Border. In Northshire Valley, Eagan Peltskinner asks you to hunt wolves and bring him their meat. He waits outside Northshire Abbey, where daily needs remain even as guards focus on Defias bandits. Eagan Peltskinner waits by Northshire Abbey’s walls, angry at the local timber wolves. Marshal McBride and the Stormwind guards have little strength to defend the abbey from Defias bandits. Tradesfolk still have daily needs, so Eagan asks you to thin the wolves’ numbers and bring back their tough meat for his cooking. Wolves roam closer to Northshire Abbey as patrols weaken. The Kingdom of Stormwind has too few troops and lacks leadership. Young wolves and timber wolves prowl the abbey’s paths and orchards. Hunting them supplies Eagan’s pantry and makes nearby trails safer for novitiates, laborers, and newly arrived defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_33-65063ea756751bc09899/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:3301"] = {
  hash = "f94839",
  fullHash = "f94839",
  text = "Mura Runetotem. At the Sepulcher in Silverpine Forest, Mura Runetotem hopes a shell from the Barrens can help the Forsaken. Around the Barrens oases, Tonga Runetotem studies wildlife changed by magic. The altered snapjaws catch his eye. Their shells pulse with resilient energy despite their corruption. So he asks you to carry one across the Great Sea to his clanmate, Mura Runetotem, stationed in the Eastern Kingdoms. At the Sepulcher, a Forsaken outpost in Silverpine Forest, Mura Runetotem aids her allies. She made the arduous journey to help them cleanse and renew their ailing, blighted woodland. The shell holds an inner glow and an enduring spark of life. Mura hopes it may reveal how to restore vitality to the northern continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3301-22e622ba8ac4742ce3e2/1-0000.mp3", duration = 47.5689796, start = 0},
  },
}
P.transport["quest:332"] = {
  hash = "b62881",
  fullHash = "b62881",
  text = "Wine Shop Advert. Renato Gallina draws passersby to his family's wine shop in Stormwind. He offers a voucher for a free bottle of vintage wine at their canal-side storefront, a small sign of trade in the rebuilt capital. In Stormwind's Trade District, commerce fills the cobbled streets. Renato Gallina walks among them, promoting Gallina Winery, the small shop he runs with his sister, Suzetta. He hands flyers to thirsty travelers and locals. Each offers a free tasting. The Gallina family offers a bottle of their famous pinot noir. Follow the ticket to the winery entrance near the canals, where Suzetta Gallina hands over the bottle. The family hopes a taste of their signature wine will bring newcomers back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_332-d36cc14524a2152f6ec0/1-0000.mp3", duration = 45.322449, start = 0},
  },
}
P.transport["quest:333"] = {
  hash = "59801e",
  fullHash = "59801e",
  text = "Harlan Needs a Resupply. In Stormwind, merchant Harlan Bagley cannot keep sturdy clothes and armor in stock. Demand surges, so he sends an urgent cloth order to Rema Schneider at the Canal Tailor and Fit Shop, unaware of the conflicts brewing beyond the city walls. Across Stormwind City, Harlan Bagley's shelves empty fast. Citizens and wandering adventurers buy reinforced tunics, traveling clothes, and battle-ready armor. Harlan wonders if they are preparing for a harsh season or winter. The rush leaves his shop short of finished cloth. Harlan sends a runner across the city's waterways to Rema Schneider, a seamstress at the Canal Tailor and Fit Shop. She is glad of his trade, yet the sudden demand for protective clothing troubles her. Rumors of tension spread through the kingdom. Rema wonders whether the House of Nobles is hiding talk of open war from ordinary people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_333-d6e8d64458e494bf5f9e/1-0000.mp3", duration = 53.6032653, start = 0},
  },
}
P.transport["quest:334"] = {
  hash = "4bd583",
  fullHash = "4bd583",
  text = "Package for Thurman. Rema Schneider needs help getting her son’s shears and needles to Larson Clothiers in Stormwind’s Mage Quarter. Thurman is apprenticing there and may fall behind without them. Thurman hurried out of home without his tools. Rema fears he will fall behind at his apprenticeship, so she asks you to carry the shears and needles across Stormwind’s canals to his workshop.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_334-b74404d1c757d7c87661/1-0000.mp3", duration = 22.7526531, start = 0},
  },
}
P.transport["quest:3361"] = {
  hash = "cdc310",
  fullHash = "cdc310",
  text = "A Refugee's Quandary. Gnomeregan's displaced gnomes flee into Dun Morogh after troggs and radiation drive them from their home. Near Anvilmar, engineer Felix Whindlebolt has lost his tools and belongings to Frostmane scavengers. Troggs overran Gnomeregan, the high-tech city beneath the earth. High Tinker Gelbin Mekkatorque and his advisors released radioactive gas to kill the invaders. The gas brought disaster instead. Thousands of innocents died, survivors became mindless leper gnomes, and the rest fled across Dun Morogh. Gnome engineers and tinkerers carried away the tools and blueprints they could save. Frostmane trolls prowl the icy mountain passes between Gnomeregan and Coldridge Valley. As Felix Whindlebolt hurried toward shelter at Anvilmar, Frostmane raiders took his tool chest, lockbox, and bucket of bolts. They carried his belongings to camps southwest of town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3361-4cd0aba55682acdfc9dc/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:3364"] = {
  hash = "54fcd1",
  fullHash = "54fcd1",
  text = "Scalding Mornbrew Delivery. Nori Pridedrift sends you across Coldridge Valley with hot mornbrew for Durnan Furcutter in Anvilmar. The mountain cold can steal its heat before it arrives. After you deliver to Grelin Whitebeard, Nori has another cup to send. He cannot carry it himself before the mornbrew freezes into slush. So he asks you to brave the snow and keep his customer from waiting. Durnan Furcutter waits inside Anvilmar's warm mountain hall and is particular about his refreshments. He will not take chilled mornbrew. A hot cup gives the weary dwarf a needed break from his duties. Nori expects his favorite mug back in one piece.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3364-70b7890893eea96582e2/1-0000.mp3", duration = 39.0008163, start = 0},
  },
}
P.transport["quest:3365"] = {
  hash = "d87669",
  fullHash = "d87669",
  text = "Bring Back the Mug. Durnan Furcutter sends you back across Coldridge Valley with Nori Pridedrift's empty mug. Its return closes the Mornbrew delivery. After warming himself with the Mornbrew, Durnan leaves the tankard in your care. Cold bites hard in Dun Morogh, where hospitality depends on mutual respect. Good dishware should make it back too. Nori Pridedrift values sturdy drinkware. Mugs do not grow on trees, especially among the subzero crags of the dwarven homeland. Bring his mug back in one piece, and you show the local community that you can be trusted.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3365-edaeb88208a8e0c3e1c5/1-0000.mp3", duration = 34.9257143, start = 0},
  },
}
P.transport["quest:3376"] = {
  hash = "c815dc",
  fullHash = "c815dc",
  text = "Break Sharptusk!. At Red Cloud Mesa, Brave Windfeather sends you east to end the raids on Mulgore. Sharptusk Thornmantle leads the Bristleback quilboar in Brambleblade Ravine, and his death may weaken their attacks. Young tauren learn to hunt and follow the ways of the Earth Mother at Red Cloud Mesa. East of the mesa, Bristleback quilboar hold Brambleblade Ravine. They see the tauren as invaders on sacred ground, and their skirmishes threaten the tribes trying to make a home in Mulgore. Chief Sharptusk Thornmantle commands the Bristleback attacks on Red Cloud Mesa. From a fortified, makeshift village deep in Brambleblade Ravine, he directs warriors and geomancers against the Shu'halo. Brave Windfeather knows the raids will continue while Sharptusk lives. She sends you into the ravine to kill him and bring back his severed head as proof. Brave Windfeather teaches that hunting an enemy who hunts back tests more than skill. For young tauren and their allies, the hunt for Sharptusk calls for courage, awareness, and discipline. His death brings justice for fallen kin and marks a hunter's readiness to travel across Mulgore's wider plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3376-c335bcdf516a826ecde6/1-0000.mp3", duration = 68.9893878, start = 0},
  },
}
P.transport["quest:35"] = {
  hash = "cb068a",
  fullHash = "cb068a",
  text = "Further Concerns. East of Goldshire, Marshal Dughan sends you to check reports of danger. You cross Elwynn Forest to speak with Guard Thomas at the river crossing toward Redridge. Marshal Dughan commands Goldshire's garrison and takes reports of hostile creatures along Elwynn's riverbanks seriously. Bandits and vermin already trouble the forest's center, so he cannot spare guards from town. He sends you east to consult Guard Thomas, the sentry at the bridge toward Redridge. Guard Thomas has held the bridge outpost for more than a week and has seen the danger for himself. Hostile, semi-intelligent murlocs have made camps along eastern Elwynn's waterways. Stormwind's army is absent, and local garrisons guard town walls and supply lines. Rural bridge posts like Thomas's are left isolated as the danger grows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_35-d96bb391c9f26704a7c3/1-0000.mp3", duration = 48.3787755, start = 0},
  },
}
P.transport["quest:3519"] = {
  hash = "81fea8",
  fullHash = "81fea8",
  text = "A Friend in Need. In Shadowglen, Iverron lies bitten and in danger. The young night elf calls for Dirania Silvershine, whose help may save him from Githyiss the Vile's venom. Iverron lies weakened from a bite by Githyiss the Vile. He ignored warnings and ventured too near the webwood caverns, where the vicious spider struck. Now dizziness and failing strength keep him from reaching safety alone. Iverron sends passersby to Aldrassil's central tree to find Dirania Silvershine. She watches over him and knows the dangers of Shadowglen. His life may depend on her preparing an antidote before the venom proves fatal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3519-ed1a4dacd90771c1fcbd/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:3521"] = {
  hash = "99aa54",
  fullHash = "99aa54",
  text = "Iverron's Antidote. In Shadowglen, Iverron's Antidote must be brewed before a scout's poison takes hold. Dirania Silvershine needs wild mushrooms, lilies, and spider ichor to make the remedy. Young Iverron was scouting the boughs of Shadowglen when Webwood spiders struck him with their poisonous fangs. Now collapsed and dying, he depends on Dirania Silvershine's herbal knowledge at Aldrassil. His venom spreads fast, so she must prepare a remedy before it takes hold. Dirania balances Teldrassil's restorative plants against the spiders' venom. Hyacinth mushrooms, which thieving grell favor in the south, make an earthy base. Moonpetal lilies from tranquil forest pools bring purifying qualities. She also needs Webwood ichor from spiders near Shadowthread Cave, to tailor the cure to their poison.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3521-433f3c189dd3a1e8b1e5/1-0000.mp3", duration = 51.6963265, start = 0},
  },
}
P.transport["quest:3522"] = {
  hash = "cec333",
  fullHash = "cec333",
  text = "Iverron's Antidote. In Shadowglen, Iverron waits for a cure before the poison takes hold. Webwood spiders have poisoned the night elf scout, and Dirania Silvershine's brew must reach him within five minutes. Dirania Silvershine makes the cure from fresh venom sacs, lily roots, and hyacinth fungi. Once distilled, the unstable brew holds its strength for only five minutes. Carry the vial straight from the glade toward the northern heights, without delay. Webwood spiders near Shadowglen's barrows and caves poisoned Iverron. He admits he often stumbles into danger and relies on Dirania's herbal skill to save him. Even after he drinks the antidote, he remains frail. Hostile spiders still guard his way home, and he fears them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3522-6249b560ad336a7d00ce/1-0000.mp3", duration = 45.8971429, start = 0},
  },
}
P.transport["quest:3524"] = {
  hash = "12d0d1",
  fullHash = "12d0d1",
  text = "Washed Ashore. Along Darkshore, sea creatures are washing ashore in growing numbers. Gwennyth Bly'Leggonde studies the deaths from Auberdine for the Temple of the Moon in Darnassus, where priestesses fear the strandings may be an ill omen. Great sea creatures have sometimes beached themselves on Darkshore. It is a tragic sight, but it has been occasional. Now they wash ashore in growing numbers along the coast. The Priestesses of Elune in the Temple of the Moon fear these deaths may bring ill omens to northern Kalimdor. The Temple of the Moon sends scholar Gwennyth Bly'Leggonde to the port town of Auberdine to learn why the great beasts come ashore. Based there, she gathers biological samples to send by hippogryph to Darnassus for close examination. Greymist murlocs swarm the carcasses in the surf, scavenging the remains. Without armed protection, researchers cannot reach the bones.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3524-bdb8ac3d472e0bca08b4/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["quest:353"] = {
  hash = "330e56",
  fullHash = "330e56",
  text = "Stormpike's Delivery. Grimand Elmore sends travelers north with an axe for Mountaineer Gringer Stormpike. From Stormwind's Dwarven District, the road reaches an Ironforge outpost in Loch Modan. Grimand Elmore has been asked to make an axe for Mountaineer Gringer Stormpike. In Ironforge, the Stormpike clan is respected for its discerning taste and martial pride. Elmore entrusts travelers with carrying the weapon north, across the distance from Stormwind to the dwarven borderlands. At Loch Modan's northern guard tower, Mountaineer Stormpike watches over lands troubled by wandering troggs and burrowing kobolds. Rumors of unrest and banditry reach the southern human kingdoms, while the dwarven frontier has dangers of its own. Stormpike needs a new blade to help keep the mountain passes secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_353-88914469200b0a1b08ea/1-0000.mp3", duration = 50.4685714, start = 0},
  },
}
P.transport["quest:354"] = {
  hash = "751467",
  fullHash = "751467",
  text = "Deaths in the Family. In Brill, Coleman Farthing seeks vengeance on the Agamand family. He once worked at their mills and stayed to defend their estate during the Third War. His fellow workers and their stubborn masters died there, then rose as mindless thralls of the Lich King. Before the Third War, the Agamands were Tirisfal Glades' wealthiest and most influential farming family. Their mills and fertile pastures yielded grain through the labor of dozens of tenant farmers and millers. When the Plague of Undeath crossed Lordaeron, the family refused to flee or leave its ancestral lands. They believed their stone walls and loyal workers could hold back the horrors advancing from the east. Coleman Farthing and the other workers trusted their lords' assurances and stayed to defend the estate. The Scourge overwhelmed them. The Agamands and their workers were slaughtered, then raised into undeath where they fell. Farthing eventually broke free through Sylvanas Windrunner's liberation. The Agamand patriarchs and heirs remained under the Lich King's mental grip, wandering the ruined mills as mindless Scourge sentries. Coleman Farthing now lives in Brill, still bitter toward the masters whose pride cost him his mortal life. Seeking vengeance and closure, he sends Forsaken champions to Agamand Mills to destroy Gregor, Nissa, and Thurman Agamand. He hopes his former masters kept enough awareness behind their rotting faces to feel terror as their unlife came to an end.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_354-423ebc7f72a9268f280d/1-0000.mp3", duration = 90.4359184, start = 0},
  },
}
P.transport["quest:355"] = {
  hash = "55d2cf",
  fullHash = "55d2cf",
  text = "Speak with Sevren. In Brill, Magistrate Sevren calls you north after Coleman Farthing's reckoning at Agamand Mills. The undead there threaten Brill's northern border. Coleman Farthing sought revenge on his former neighbors, the Agamands, and sent travelers north to kill the undead around their flour mills. When you brought back their remains, Coleman saw that his grudge had uncovered a greater danger. The Agamand estate still crawls with aggressive Scourge minions, close to Brill. Magistrate Sevren oversees Brill's civic and military security for the Dark Lady. Reports say you survived deep incursions into the haunted farmlands. Now Sevren directs you toward the source of the infestation: the ancient Agamand family crypt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_355-e1244468e36eafcfc07b/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["quest:356"] = {
  hash = "e4817f",
  fullHash = "e4817f",
  text = "Rear Guard Patrol. At the Bulwark, Deathguard Linnea sends you to guard Tirisfal's eastern flank. Scourge horrors and lingering spirits threaten Balnir Farmstead, the road, and the supply lines that keep the front supplied. The Bulwark guards Tirisfal Glades from the pestilence and armies of the Western Plaguelands. Deathguard Linnea watches over the defenders behind the frontier. They cannot spare troops to guard against attacks from the rear. So any undead that slip past the choke point must be destroyed before they cut the supply lines feeding the front. Balnir Farmstead once worked as a farm in eastern Tirisfal, but fell to ruin during the Third War. Blight covers its fields, and Bleeding Horrors and restless Wandering Spirits shelter in its crumbling stables. Clearing the farmstead denies the Lich King a place to gather forces inside Tirisfal. It also keeps the road open for Horde reinforcements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_356-4ba3c49a9eb087970bae/1-0000.mp3", duration = 55.4318367, start = 0},
  },
}
P.transport["quest:357"] = {
  hash = "075f33",
  fullHash = "075f33",
  text = "The Lich's Identity. Bethor Iceshard seeks the name of the lone lich on Brightwater Lake. He sends an emissary to take the lich's spellbook and learn his power and allegiance. A lone lich lives in exile on a small island in Brightwater Lake, north of the Undercity. Unlike the Lich King's mindless pawns, he has free will, but paranoia rules him. He believes any undead who come near are Scourge thralls sent to drag him back into servitude. So he sends summoned minions against anyone who sets foot on his shore. Word of the rogue lich reaches Bethor Iceshard, the archmage who oversees the Undercity's mages. Bethor knows Lady Sylvanas Windrunner seeks every scrap of magical mastery and every capable will to strengthen the Forsaken against their many foes. To learn whether the recluse can be recruited, Bethor needs proof of his identity and necromantic skill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_357-3bbdd464691ce06e0498/1-0000.mp3", duration = 54.5436735, start = 0},
  },
}
P.transport["quest:358"] = {
  hash = "8b3d0c",
  fullHash = "8b3d0c",
  text = "Graverobbers. At the Mass Grave southwest of Garren's Haunt, Rot Hide gnolls dig among the dead. Magistrate Sevren sends you to stop them and bring back their embalming ichor for the Royal Apothecary Society. The Plague of Undeath swept through Tirisfal Glades, leaving more dead than the living could bury. Across the north, people dug immense mass graves for the countless victims. For a time, those buried there escaped resurrection.\n\nNow the Scourge sends Rot Hide gnolls to the trenches southwest of Garren's Haunt. They exhume the remains to swell the Lich King's armies. Embalming ichor preserves and animates the Rot Hides' rotting frames. Magistrate Sevren sends you to kill the graverobbers and recover the fluid. This keeps the Scourge from harvesting more bodies and gives Brill's apothecaries specimens to study.\n\nThey hope to turn the Lich King's own alchemy against him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_358-4242053955fd05d4ed8e/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["quest:36"] = {
  hash = "39dc80",
  fullHash = "39dc80",
  text = "Westfall Stew. Westfall homesteaders are driven from their farms by banditry. As the Furlbrows prepare to leave, Verna entrusts her cherished recipe to Salma Saldean. Defias thieves and wild mechanical harvest reapers have driven Verna and Farmer Furlbrow from their family acreage. They pack their wagon and prepare to seek refuge behind Stormwind's walls. Before they go, Verna gives her neighbor Salma Saldean the recipe for Westfall Stew. She hopes the farm's home-cooked tradition will live on. Salma Saldean and her husband, Farmer Saldean, still hold their homestead just down the road. Verna's recipe keeps a local farm tradition alive as another family leaves. Salma sets out to gather ingredients to feed those still struggling on the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_36-c0af8060bc82c2ce4ac9/1-0000.mp3", duration = 46.602449, start = 0},
  },
}
P.transport["quest:360"] = {
  hash = "a63bbe",
  fullHash = "a63bbe",
  text = "Return to the Magistrate. At Brill, Magistrate Sevren receives word that the Lich King's servants still press against the Forsaken frontier. Deathguard Linnea sends the warning from the east. East of Tirisfal Glades, the road runs to the blighted ruins of the Western Plaguelands, where the Scourge holds sway. The Forsaken built the Bulwark to bar the undead from their homeland. Deathguard Linnea watches from a waystation behind the line and gathers reports from the eastern gate. Then she sends messengers west along the King's Road to Brill, before enemy infiltrators can find gaps in the defenses. In Brill, Magistrate Sevren hears that Scourge scouts are finding paths around or through the frontline. Each creeping ghoul and mindless skeleton recalls the Forsaken's enslavement, ended when Lordaeron fell. Sevren vows that no matter how ceaseless the Lich King's assault, the free undead will not surrender their new autonomy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_360-38437d2619a4c90c534b/1-0000.mp3", duration = 57.077551, start = 0},
  },
}
P.transport["quest:361"] = {
  hash = "bc69e3",
  fullHash = "bc69e3",
  text = "A Letter Undelivered. Among Agamand Mills' skeletal ruins, A Letter Undelivered lies bloodstained and faded. It recalls two lovers parted as the Scourge swept across Lordaeron, and the life Forsaken left behind. Thurman Agamand, eldest son of patriarch Gregor Agamand, wrote a message that never reached Yvette Farthing. When the Plague of Undeath consumed Tirisfal Glades, Thurman refused to leave his ancestral home or his kin. As the Scourge struck, he took up his quill for Yvette. He had loved her before the kingdom turned to ash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_361-58b7ccf8d8319f5e4402/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["quest:362"] = {
  hash = "ce9c2f",
  fullHash = "ce9c2f",
  text = "The Haunted Mills. Coleman Farthing sends you north from Brill to Agamand Mills, seeking vengeance on the family who once owned his land. First, he wants Devlin's remains gathered. Their feud began when the Agamands failed to protect Tirisfal's common folk from the Plague. Before the Third War, the wealthy Agamand family ruled the mills and fed northern Tirisfal. When the Scourge swept across Lordaeron, the common folk turned to the nobles for safety, but found no shelter. Coleman Farthing survived as undead, yet hatred for the family he served still consumes him. He wants their bones gathered so he can desecrate them beneath his heel. Devlin Agamand was the younger brother of Thurman Agamand. People remembered Devlin as weak, spiteful, and sharp-tongued, unlike his gentle elder brother. When the Plague of Undeath reached the mill estate, Devlin quickly fell to its corruption. Now his mindless corpse chatters without cease along the northern road into the family mills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_362-6dcb4f4d3317cedd2be5/1-0000.mp3", duration = 60.917551, start = 0},
  },
}
P.transport["quest:363"] = {
  hash = "27b2d4",
  fullHash = "27b2d4",
  text = "Rude Awakening. Newly awakened Forsaken leave Deathknell's crypts and face an unfamiliar life. Freed from the Lich King's grip, you are sent down the hill, away from the incinerators, to learn what comes next from Shadow Priest Sarvis. In Deathknell's crypt, you wake to undeath among damp stone and cold air. Undertaker Mordo watches the newly buried, sorting those who regain free will from those bound for the burning pits. Many rise confused, surrounded by rot and stone. By chance, they have slipped the Scourge's grasp. Before you reach the chapel, you face a grim truth: once, you were a mindless tool of the Lich King. Lady Sylvanas Windrunner broke that psychic enslavement, freeing remnants of your former humanity to reclaim independent thought. You leave the tomb and head down into Deathknell, beginning life in a world where the living and the Scourge alike see you as an abomination to be destroyed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_363-1f01cc2813c335f9d0a8/1-0000.mp3", duration = 59.4808163, start = 0},
  },
}
P.transport["quest:364"] = {
  hash = "e4cb5f",
  fullHash = "e4cb5f",
  text = "The Mindless Ones. At Deathknell's northern edge, newly risen Forsaken face The Mindless Ones. Shadow Priest Sarvis sends them against Mindless Zombies and Wretched Zombies, Scourge thralls bound to the Lich King's command. Many who rise from Lordaeron's soil never recover their minds. The Forsaken broke free of Ner'zhul's rule as his power waned, but countless dead remain chained to his will. In northern Deathknell, Mindless Zombies and Wretched Zombies roam, driven to violence. For you, newly risen among the undead, laying them to rest is your first hard trial. You prove your freedom by ending the thrall of those who never escaped. Shadow Priest Sarvis grieves that these legions of dead cannot strengthen the Forsaken's desperate struggle. There is no cure for them. Their minds are broken, and they remain instruments of slaughter. Left to roam, they bring chaos to Deathknell's doorstep and give the Lich King easy fodder. Destroying them is necessary for the settlement and brings a grim end to some of Lordaeron's fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_364-b064ad80e3a4b1f36b81/1-0000.mp3", duration = 66.8995918, start = 0},
  },
}
P.transport["quest:365"] = {
  hash = "edaa9f",
  fullHash = "edaa9f",
  text = "Fields of Grief. Pumpkins from a human farm north of Deathknell are bound for the Royal Apothecary Society in Brill. Deathguard Simmer sends the newly risen Forsaken to gather them. Deathguard Simmer sends you from Deathknell's crypts into hostile land. He serves Sylvanas Windrunner's forces. There, survival means taking what the living have and putting it to use for the Undercity's darker aims. The farm lies west of the road and north of Deathknell. Human peasants work its blighted soil, and Simmer says they infest the realm like mold on a corpse. They hold their homesteads under the uneasy protection of nearby Scarlet Crusade towers. Taking their crops strikes at their supplies and gives the Royal Apothecary Society produce for research.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_365-3e0dc368857faed2941c/1-0000.mp3", duration = 46.7330612, start = 0},
  },
}
P.transport["quest:366"] = {
  hash = "a34878",
  fullHash = "a34878",
  text = "Return the Book. Bethor Iceshard sends an enchanted message to Gunther Arcanus on Brightwater Lake. The stolen spellbook may draw his old Kirin Tor companion toward the Forsaken. Bethor Iceshard sends a message to Gunther Arcanus through a stolen spellbook. Learning that the necromancer on Brightwater Lake is his old companion, Bethor enchants its pages. His magic leaves a mark on the tome. It shows Gunther that Bethor is active in Lordaeron and free of the Lich King's control. Before the Third War devastated Lordaeron, Bethor Iceshard, Gunther Arcanus, and Thule Ravenclaw studied together in the Kirin Tor of Dalaran and became friends. When the Lich King rose, Thule betrayed them and joined the Scourge willingly. Bethor and Gunther fell to the Plague. Bethor later broke free alongside Queen Sylvanas.\n\nBethor believed Gunther dead or enslaved. Now he learns his old friend has won his freedom too, and seeks to bring him into the Forsaken fold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_366-25cad471961a6bfa56a5/1-0000.mp3", duration = 60.6040816, start = 0},
  },
}
P.transport["quest:367"] = {
  hash = "7ef8fc",
  fullHash = "7ef8fc",
  text = "A New Plague. In Brill, Apothecary Johaan gathers blood from darkhounds for a new plague. The Royal Apothecary Society works at Lady Sylvanas Windrunner’s command. Apothecary Johaan serves the Royal Apothecary Society in Brill, under orders from the Dark Lady. Sylvanas Windrunner has charged her alchemists with making a disease unlike any Azeroth has known.\n\nThe Lich King's Plague of Undeath slaughtered humanity and bound their souls. This new plague is meant to annihilate Arthas Menethil and lay waste to his Scourge legions. Johaan seeks grim experiments for a weapon against the undead. He believes the blood of native beasts may hold useful chemical properties, and begins with darkhounds roaming Tirisfal Glades.\n\nYou gather vials of their tainted blood. Johaan can isolate its elements and test whether the beasts' resilience and predatory nature might help make a lethal contagion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_367-2928b120eb3f1b54f5b9/1-0000.mp3", duration = 59.5330612, start = 0},
  },
}
P.transport["quest:368"] = {
  hash = "8d534b",
  fullHash = "8d534b",
  text = "A New Plague. In Brill, Apothecary Johaan gathers Vile Fin scales for the Royal Apothecary Society's work on a plague. He hopes it will spread beyond isolated victims and reach larger populations. Apothecary Johaan's work in Brill calls for more than a poison that harms one target. He seeks a disease that can spread on its own and endure in the wild. So he studies the shoreline wildlife of Tirisfal Glades. The resilient Vile Fin murlocs offer promising material. Aggressive Vile Fin murloc tribes trouble Tirisfal Glades' northern and western shores. Their scales hold organic compounds adapted to damp, harsh conditions. Johaan hopes these slick, resilient scales will strengthen the Royal Apothecary Society's new plague and help it endure in the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_368-4f0e9d56490b03ecac38/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["quest:3681"] = {
  hash = "c573ae",
  fullHash = "c573ae",
  text = "Tome of Divinity. In Ironforge, Master Brandur Ironhammer sends promising human paladins south for deeper training. At Stormwind's Cathedral of Light, Master Duthorian Rall guides their study of the sacred Tomes of Divinity. Stormwind calls promising holy warriors south to the Cathedral of Light. Senior priests and paladin mentors await them there, keeping the Silver Hand's traditions alive in the Church of the Holy Light among human lands. Master Brandur Ironhammer knows when a student is ready for deeper study of the faith. You can reach Stormwind's Cathedral District by the Deeprun Tram or across the mountain passes. There, Duthorian Rall prepares initiates to study the sacred Tomes and learn the rites of redemption.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3681-45d43898f5fb839136db/1-0000.mp3", duration = 44.8783673, start = 0},
  },
}
P.transport["quest:369"] = {
  hash = "743e8b",
  fullHash = "743e8b",
  text = "A New Plague. In Brill, Apothecary Johaan searches old records for a plague that endured in spider venom. He hopes to give the Forsaken a potent new biological agent. Apothecary Johaan studies old texts in Brill for the Royal Apothecary Society. There he finds records of an ancient pestilence that killed thousands. The writings say its pathogen endured across generations in the venom of spiders native to Tirisfal Glades. Johaan needs that venom as a biological reagent. Apothecary Johaan sends agents to eastern Tirisfal Glades in search of a living sample. Venomweb Vale lies south of the Scarlet Monastery, and vicious night web spiders fill its hollow. To gather fresh venom glands for Johaan's experimental brew, harvesters must enter the spiders' dens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_369-b47cb84ea520b37028a4/1-0000.mp3", duration = 49.7110204, start = 0},
  },
}
P.transport["quest:37"] = {
  hash = "5ba2da",
  fullHash = "5ba2da",
  text = "Find the Lost Guards. Guard Thomas waits at Elwynn's eastern bridge, needing news of two missing Stormwind guards. At the crossing where the King's road nears Redridge, the riverbanks have grown more dangerous. Days ago, Thomas sent Rolf and Malakai north along the river to scout the murloc threat and clear their nests. Now he fears violence has stopped their patrol.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_37-411f929a0409eccf9793/1-0000.mp3", duration = 22.2040816, start = 0},
  },
}
P.transport["quest:370"] = {
  hash = "6d6158",
  fullHash = "6d6158",
  text = "At War With The Scarlet Crusade. In Tirisfal, the Forsaken strike at Scarlet Crusade forces threatening their borders. Executor Zygand sends champions against Captain Perrine and his garrison at a ruined tower southwest of Brill, guided by intelligence taken in Deathknell. Executor Arren recovered Scarlet Crusade documents in Deathknell. They revealed troop movements across Tirisfal Glades. So Executor Zygand uses that intelligence to strike the field commanders first, before the fanatics can attack newly fortified Brill. At a ruined watchtower southwest of Brill, Captain Perrine commands Scarlet Zealots and Missionaries. The Crusade watches Forsaken movements from there and reaches farther into Tirisfal. Perrine's death matters to the defense of the Dark Lady's young kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_370-1cf2e520f9ca5bfbaf54/1-0000.mp3", duration = 50.1289796, start = 0},
  },
}
P.transport["quest:371"] = {
  hash = "f7da53",
  fullHash = "f7da53",
  text = "At War With The Scarlet Crusade. Near Balnir Farmstead, Executor Zygand sends Forsaken fighters against the Scarlet Crusade. They target Captain Vachon and his friars in southeastern Tirisfal Glades, where Crusader raids threaten the Dark Lady's lands. Brill and the Undercity are guarded by the Forsaken, while the Scarlet Crusade holds fortified sites across the countryside. From a crumbling guard tower in southeastern Tirisfal Glades, Executor Arren reports active Crusader incursions. The tower stands close to the abandoned Balnir Farmstead. Executor Zygand strikes at the Crusade's field leaders, for coordinated squads are more dangerous than scattered zealots. You attack Captain Vachon and the Scarlet Friars who strengthen his men with holy magic. Without their leaders and support, the cell may lose its unity, and its raids into Forsaken lands may falter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_371-e9fb23e3df812393181f/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["quest:372"] = {
  hash = "4fee62",
  fullHash = "4fee62",
  text = "At War With The Scarlet Crusade. In Tirisfal, Executor Zygand sends Forsaken agents from Brill against the Scarlet Crusade. Captain Melrache and his sworn guards hold a ruined watchtower beyond Faol's Rest. The Forsaken are securing Lordaeron's ruins, but the Scarlet Crusade keeps testing Tirisfal's borders. From a tower in the north, past Faol's Rest, crusaders lead raids against Forsaken patrols and lands. Executor Zygand means to strike the officers directing those raids before another attack comes. Captain Melrache commands the northern camp with two sworn bodyguards always at his side. From the tower, the Scarlet Crusade watches the coastal roads and nearby woods. Kill Melrache, and the raiders near Brill lose their order. His fall removes a direct threat to Lady Sylvanas's young kingdom and drives the zealots toward stronger fortifications farther east.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_372-11c86bf0659579ad0b65/1-0000.mp3", duration = 55.1183673, start = 0},
  },
}
P.transport["quest:374"] = {
  hash = "990ed3",
  fullHash = "990ed3",
  text = "Proof of Demise. In Brill, Proof of Demise sends soldiers against the Scarlet Crusade across Tirisfal Glades. Varimathras, Sylvanas Windrunner's dreadlord lieutenant, orders the campaign to thin their ranks and test loyalty to the Forsaken cause. Recruits must take signet rings from fallen crusaders as proof. Across northern Tirisfal Glades, the Forsaken wage a coordinated war against the living. Varimathras surrendered and pledged his blade to Sylvanas Windrunner. He oversees many of the Forsaken's aggressive military maneuvers.\n\nHis orders pass to commanders such as Executor Zygand, then to frontline officers like Deathguard Burgess. Burgess makes the order plain: humans are vermin to be purged from Lordaeron, and nearby crusaders are the immediate target. In Brill, words alone do not satisfy the commanders. Soldiers must take Scarlet Insignia Rings from the fingers of slain zealots to prove obedience to the Dark Lady and her lieutenant. The rings bear the Scarlet Crusade's mark, identifying their bearers as sworn enemies of the Forsaken.\n\nBring back these trophies, and the dead crusaders are proved. The rings also show a soldier's allegiance to the Forsaken leadership.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_374-6ad733cccbcaf713e1c6/1-0000.mp3", duration = 77.6097959, start = 0},
  },
}
P.transport["quest:3741"] = {
  hash = "91d465",
  fullHash = "91d465",
  text = "Hilary's Necklace. At Lakeshire's docks, Hilary loses the necklace her father gave her. Shawn asks you to find it in Lake Everstill, where their parents forbid them to swim. Hilary and Shawn fish from Lakeshire's docks, seeking an ordinary day amid the threats around the Redridge Mountains. Then Hilary's treasured necklace slips into Lake Everstill. They search the piers and shore, but find nothing. Shawn asks you to help. Their parents forbid Hilary and Shawn to swim in Lake Everstill. Aggressive murlocs and hungry threshedons lurk below the surface. The necklace lies in glinting mud at the lake bottom, beyond the children's reach. So Shawn asks you to recover the gift.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3741-acc59c951610ddf239d8/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["quest:375"] = {
  hash = "e03d41",
  fullHash = "e03d41",
  text = "The Chill of Death. In Brill, The Chill of Death weighs on Gretchen Dedmar as she fights the cold of undeath. The Forsaken tailor fears losing her mind and her service to Lady Sylvanas, so she asks for materials to sew a warm blanket. Gretchen Dedmar feels the Plague of Undeath like an icy serpent moving through her body. The chill drains warmth from her limbs and threatens to leave her mindless, like the wandering corpses in Tirisfal Glades. Her shaking hands make even ordinary work difficult. Gretchen will not abandon her duty to the Forsaken kingdom. When Sylvanas Windrunner first rallied the liberated dead, Gretchen sewed burial shrouds and body bags for fallen soldiers. Sturdy duskbat pelts and coarse thread can help her make a blanket. Its warmth may steady her hands enough to keep serving the Forsaken cause.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_375-46e3321a21c488977041/1-0000.mp3", duration = 51.9053061, start = 0},
  },
}
P.transport["quest:376"] = {
  hash = "c2befb",
  fullHash = "c2befb",
  text = "The Damned. New Forsaken in Deathknell seek clothing and battlefield wraps from Novice Elreth. She trades salvaged armor for the materials to make them. Novice Elreth tends the newly risen Forsaken in Deathknell. She aids Shadow Priest Sarvis, cares for battered soldiers, and mends their garments. When supplies run short, she sends you into the surrounding glades to hunt duskbats and scavenger wolves. Their pelts, wings, and sinew help supply the camp, and Elreth offers salvaged armor in return. Elreth's armor belonged to Forsaken who did not survive their awakening. She hopes it serves you better than it served its former owner. In Tirisfal Glades, every piece of leather and rusted chain finds a use.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_376-46a4f96149b7b3a795ae/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["quest:38"] = {
  hash = "ae6ef4",
  fullHash = "ae6ef4",
  text = "Westfall Stew. On her farm in Westfall, Salma Saldean cooks Westfall Stew from what the frontier offers. Its ingredients reflect how homesteaders endure bandits, famine, and dangerous beasts. Westfall's settlers face bandits, famine, and rampaging beasts, far from Stormwind's lavish larders. Families like the Saldeans make do with what the land provides. Salma Saldean turns ingredients many city folk might call pests or scraps into a meal that sustains her farmhands. Salma's recipe brings together local okra, stringy meat from circling vultures, and snouts from wild goretusks roaming the plains. It also calls for fresh murloc eyes gathered from coastal raiders. Such fare may turn delicate stomachs in Elwynn, but Westfall cooks swear the blend makes a rich, fortifying meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_38-228b48c8447025d43338/1-0000.mp3", duration = 51.957551, start = 0},
  },
}
P.transport["quest:380"] = {
  hash = "2688bb",
  fullHash = "2688bb",
  text = "Night Web's Hollow. Northwest of Deathknell, spiders overrun a gold mine the Forsaken need. Executor Arren sends newly risen recruits into the cavern to thin their ranks. Raw materials are scarce, and the mine's wealth could sustain the Forsaken settlement and war effort. In Deathknell, Executor Arren oversees the newly risen Forsaken as they struggle to survive. The Scourge and Scarlet crusaders threaten them, but defense is only part of the work. A fledgling society needs raw materials too. Precious metals such as gold were scarce in northern Lordaeron even when the Alliance was strong. Arren knows the Forsaken need wealth to arm and equip themselves and establish their society. Northwest of Deathknell's cemetery, a gold vein runs through the natural cavern called Night Web's Hollow. Monstrous spiders have overrun its tunnels, laying thick webs and deadly venom in the depths. Arren has too few seasoned troops for a full purge, so fresh recruits thin the young and adult spiders. Once the danger is reduced, mining crews can burn away the webs and extract the ore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_380-28fd6d89bf39358f1248/1-0000.mp3", duration = 67.9444898, start = 0},
  },
}
P.transport["quest:381"] = {
  hash = "2bac3f",
  fullHash = "2bac3f",
  text = "The Scarlet Crusade. In Tirisfal, a Scarlet Crusade camp threatens Deathknell from the southeast. Executor Arren sends the newly awakened Forsaken to strike its zealots, among their most fanatical and persistent enemies. After the Night Web spiders are dealt with, Executor Arren turns his attention to a danger drawing near Deathknell. A Scarlet Crusade detachment has made a foothold just southeast of the settlement. Its zealots see no difference between mindless Scourge and free-willed Forsaken. Their presence on Deathknell's border threatens the newly risen dead. Executor Arren orders a strike before the camp can grow into an organized attack on Deathknell. You cut down Scarlet Converts and Scarlet Initiates, then return with their crimson armbands as proof. The holy fanatics see all dead flesh as an abomination, so the Forsaken must claim survival by force.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_381-29e40f1e07e74505c2e6/1-0000.mp3", duration = 54.7526531, start = 0},
  },
}
P.transport["quest:382"] = {
  hash = "0c65a3",
  fullHash = "0c65a3",
  text = "The Red Messenger. Executor Arren sends you after a courier bound for the camp outside Deathknell. Sent from the Scarlet Monastery, the courier carries the crusade's word to its camp. This offensive move secures intelligence before the zealots can strengthen their hold in the valley, as the Forsaken defend their fledgling sanctuary. Executor Arren learns of the Scarlet courier from his superiors in Brill. The Scarlet Crusade sent an emissary west from its stronghold at the Scarlet Monastery to Deathknell. Crusaders press across Lordaeron. A courier sent to the edge of the Forsaken's waking grounds signals an organized effort to destroy the newly risen before they can prepare a defense. Meven Korgal, the courier, has blended into the small Scarlet camp east of Deathknell without distinctive heraldry. Executor Arren orders a targeted strike to kill Korgal and seize his dispatch. Taking the missives cuts off the local zealots from further tactical coordination with their eastern headquarters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_382-54d71195bf34bc25d462/1-0000.mp3", duration = 59.5591837, start = 0},
  },
}
P.transport["quest:383"] = {
  hash = "e9fa2c",
  fullHash = "e9fa2c",
  text = "Vital Intelligence. In Tirisfal Glades, a newly risen Forsaken bears captured Scarlet Crusade documents from Deathknell to Brill. Executor Zygand awaits the courier there. Executor Arren sends you from Deathknell with captured Scarlet Crusade documents. You have dealt with local threats and intercepted a Scarlet Crusade courier, and now wider service awaits. Leave through Deathknell's sheltered canyon and follow the road east toward Brill, passing Cold Hearth Manor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_383-f5056f62c940a26fad43/1-0000.mp3", duration = 29.6489796, start = 0},
  },
}
P.transport["quest:384"] = {
  hash = "e929d1",
  fullHash = "e929d1",
  text = "Beer Basted Boar Ribs. At the Thunderbrew Distillery in Kharanos, patrons hunger for Ragnar Thunderbrew's famed ribs. His regular supplier has joined the King's Army, so Ragnar needs fresh crag boar ribs and Rhapsody Malt to keep them on the menu. Tavern keeper Ragnar Thunderbrew has eager customers, but his pantry is bare. The local hunter who supplied fresh meat enlisted in the King's Army to reinforce the Alliance front. Now Ragnar has no fresh ribs for the patrons who favor them. Crag boars roam the snowy foothills around Kharanos, and their meat is tough. Ragnar's recipe also calls for fresh Rhapsody Malt, drawn straight from the distillery's taps. The malt softens the game meat and makes a savory feast fit for a dwarf's praise.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_384-4e9100ff1518a8a48639/1-0000.mp3", duration = 47.2293878, start = 0},
  },
}
P.transport["quest:385"] = {
  hash = "0fa0a8",
  fullHash = "0fa0a8",
  text = "Crocolisk Hunting. At Farstrider Lodge, Marek Ironheart seeks trackers to hunt Loch Modan's crocolisks. Their hides and meat bring steady trade, though hunting along the lake's shores and rocky islets is dangerous. Crocolisks haunt the shallows and muddy banks, making crossings and fishing perilous. Across Khaz Modan, craftsmen and tailors seek their hides for rugged armor and leather goods. Rustic taverns pay well for the lean tail meat. Loch Modan's crocolisks gather mainly around the rocky islets. Their crushing jaws and sharp teeth make them dangerous quarry. Dwarven veterans like Marek Ironheart carry scars from wrestling them into submission. He warns that one misstep in the water can cost a limb. Skinning and butchering one takes patience, sturdy steel, and a willingness to enter its hunting ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_385-b4423ec7ed8d837b8b8b/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:3861"] = {
  hash = "5c1dee",
  fullHash = "5c1dee",
  text = "CLUCK!. In Westfall, a chicken may answer when you call and feed it. Follow its scratched message to the Saldean family, and a warm egg may be yours to hatch. Across Azeroth, ordinary chickens wander farmsteads, though most travelers pass them by. Mimic a chicken's gestures and cluck, and one may stop pecking to regard you. In that brief moment, it scratches letters in the dirt, pointing you toward the farmer who can provide the food it wants. The bird asks for Special Chicken Feed, which the Saldean family keeps for its flock in Westfall. Offer the grain and cheer the chicken on as it eats. In return, it lays a warm egg, ready to be nurtured into a feathered companion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3861-876d8cd3efbad85e0fdc/1-0000.mp3", duration = 43.8334694, start = 0},
  },
}
P.transport["quest:39"] = {
  hash = "60968a",
  fullHash = "60968a",
  text = "Deliver Thomas' Report. In eastern Elwynn, Guard Thomas sends word of two dead guards and rising danger. He asks you to carry the report to Marshal Dughan in Goldshire, where few hands remain to defend the roads. Guard Thomas watches the bridges into eastern Elwynn, where river traffic meets the wilderness. Aggressive murloc tribes have killed Guards Malakai and Rolf. Thomas has too few guards left to contain them, so he sends you down the road to Goldshire with an urgent report. Marshal Dughan receives Thomas' report in Goldshire, where he already struggles to keep patrols on the roads. Kobolds infest the area, Defias bandits threaten travelers, and Stormwind City has sent no reinforcements. The deaths of two experienced guards deepen his burden. Murlocs may soon threaten Goldshire itself, while the region's defenses grow ever thinner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_39-ae68217fadf448619f24/1-0000.mp3", duration = 52.244898, start = 0},
  },
}
P.transport["quest:3901"] = {
  hash = "28e476",
  fullHash = "28e476",
  text = "Rattling the Rattlecages. In Deathknell, newly awakened Forsaken face the Rattlecage Skeletons and a test of their freedom. Shadow Priest Sarvis sends them to destroy twelve skeletons and prove they can defend what they won. After culling the mindless zombies in Deathknell, newly risen Forsaken face a harder trial. Shadow Priest Sarvis sends recruits against the Rattlecage Skeletons roaming the settlement’s outskirts. The animated bones have no sapience or self-control, yet strike harder and fight more fiercely than the nearby decaying corpses. Surviving their clattering ambushes shows Sarvis a recruit can withstand immediate pressure. Destroying the skeletons protects Deathknell from the lingering grip of the Lich King and tests which recruits can endure the fight. Those who fail or hesitate risk becoming like the mindless wretches wandering the woods. Overcoming the Rattlecages proves to Sarvis you have the mettle to face a world that despises your existence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3901-7591ffb6f0c84c69df7f/1-0000.mp3", duration = 58.4620408, start = 0},
  },
}
P.transport["quest:3902"] = {
  hash = "f78a47",
  fullHash = "f78a47",
  text = "Scavenging Deathknell. In Deathknell, newly awakened Forsaken gather supplies for recruits rising from nearby graves. Deathguard Saltain sends them through the blighted settlement to search abandoned boxes and crates for what they need to survive. Newly raised Forsaken wake in Deathknell with little to call their own. Deathguard Saltain sends them to gather clothing and arms for recruits still climbing from their graves. Every usable piece helps outfit the newly risen. Deathknell holds remnants of its former human inhabitants and supplies abandoned during the kingdom’s fall to the Scourge. Deathguards send newly awakened Forsaken to search boxes and crates scattered through town. The living offer no charity, so the Forsaken must rely on their own effort to survive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3902-95ec51cc933869d05dce/1-0000.mp3", duration = 43.4677551, start = 0},
  },
}
P.transport["quest:3903"] = {
  hash = "97610d",
  fullHash = "97610d",
  text = "Milly Osworth. Deputy Willem sends you across Northshire Abbey to help his friend Milly Osworth. Her wagon and livelihood are in danger, and Willem's guards cannot leave the abbey grounds to help. After you drive back the Defias thieves pressing into Northshire Valley, Deputy Willem trusts you with a personal favor. His friend Milly Osworth is a civilian caught in the valley's unrest, and helping her falls beyond his guard duties. Milly waits beside her wagon near the stables on the far side of Northshire Abbey. Deputy Willem stays at his post to defend the abbey. With the guard garrison stretched thin, Milly's troubles in the valley go without help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3903-49110d0aea0ce2316879/1-0000.mp3", duration = 40.1240816, start = 0},
  },
}
P.transport["quest:3904"] = {
  hash = "4e1e1e",
  fullHash = "4e1e1e",
  text = "Milly's Harvest. Defias brigands have driven Milly Osworth from the Northshire vineyards. Her gathered grapes remain in buckets and crates among the occupied rows, at risk of theft or ruin. Milly Osworth fled the southeastern fields of Northshire Valley when Defias brigands swarmed the vines. The grapes she had gathered remain in buckets and crates among the occupied rows. Northshire's garrison is stretched thin, and Milly fears boots and fighting will crush any fruit the bandits leave behind. Defias bandits now occupy working vineyards, a sign of how little safety Northshire can offer. Stormwind's attention lies elsewhere, and the valley has too few guards. So farmers like Milly depend on recruits and wanderers to protect their property and secure the food and wine that supply the abbey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3904-358dd612e4ce9004cbd6/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["quest:3905"] = {
  hash = "32deeb",
  fullHash = "32deeb",
  text = "Grape Manifest. Milly Osworth needs you to bring her manifest to Brother Neals at Northshire Abbey. It will help the brotherhood replenish its wine stores. Defias thieves and other brigands took the eastern fields. The abbey lost its food and its grapes. Milly has recovered the crop and recorded every bushel in her manifest, including what the occupied fields had yielded. Brother Neals oversees food and drink at Northshire Abbey. In the quiet of the bell tower, he is known to sample Northshire's vintages. Brigands still threaten the gates, yet fresh grapes give the brotherhood a moment to toast the Light and take heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3905-d21d8b03e222eaa01ad9/1-0000.mp3", duration = 37.4073469, start = 0},
  },
}
P.transport["quest:3921"] = {
  hash = "37d54e",
  fullHash = "37d54e",
  text = "Wenikee Boltbucket. Near the Mor'shan Rampart, Sputtervalve needs Wenikee Boltbucket to mend a broken samophlange. He damaged it after it was retrieved from the Sludge Fen, and now his claims to his colleagues in Undermine hang on its repair. Sputtervalve's claims to his fellow engineers in Undermine rest on a broken machine. An adventurer retrieved the mysterious samophlange from the Venture Company's control console at the Sludge Fen. Sputtervalve could not resist showing it off, and his tinkering damaged the delicate contraption. Now he needs someone with sharper skill to find the fault and repair it. Wenikee Boltbucket camps beside the road just south of the Mor'shan Rampart, which divides the northern Barrens from Ashenvale. Her curious mind is drawn to intricate machinery, and the broken samophlange quickly catches her attention. Its inner gears fascinate her, so she sets to work figuring out how to rebuild it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3921-a3c037df03b903dde8b0/1-0000.mp3", duration = 53.3942857, start = 0},
  },
}
P.transport["quest:3922"] = {
  hash = "80afb3",
  fullHash = "80afb3",
  text = "Nugget Slugs. At the Sludge Fen, Wenikee Boltbucket seeks parts for a samophlange she has recovered. She sends you to the nearby Venture Company crews for spare hardware. Wenikee Boltbucket has recovered a samophlange and wants to learn how its intricate workings fit together. The goblin machine needs exact parts, so she sends you to the Venture Company crews at the Sludge Fen. Their heavy tool buckets hold the seventeen-point-five gauge nugget slugs she needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3922-19e49d23f8e876b52d30/1-0000.mp3", duration = 28.0555102, start = 0},
  },
}
P.transport["quest:3923"] = {
  hash = "f6ff72",
  fullHash = "f6ff72",
  text = "Rilli Greasygob. Wenikee Boltbucket sends a damaged samophlange to Rilli Greasygob in Orgrimmar. She hopes his knowledge of its Venture Company origins will explain the device. Wenikee Boltbucket examined the samophlange recovered from the Venture Company drilling site in the Barrens. Her extra gauges showed it was close to collapse. More levers and dials might destroy it, so she stopped and sent the problem to someone who knew its design. In Orgrimmar's Valley of Honor, Wenikee sends you to Nogg's Machine Shop. Rilli Greasygob works there as an engineer and once learned his trade within the Venture Company. He recognizes the machine at once and marvels that anyone survived exploring the company's contested operations in the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3923-dfcb8e1413f8983dd5da/1-0000.mp3", duration = 43.8334694, start = 0},
  },
}
P.transport["quest:3924"] = {
  hash = "182125",
  fullHash = "182125",
  text = "Samophlange Manual. In Orgrimmar, Rilli Greasygob needs help with a broken samophlange. The goblin engineer sends you back into the Barrens for the operating instructions, held by his former Venture Company rival. Rilli Greasygob once worked beside Boss Copperplug in the Venture Company. Copperplug oversaw the samophlange’s inner workings and guarded their secrets closely. He gave Rilli no manual. Instead, Copperplug handed separate pages only to underlings he trusted, leaving his fellow engineer without the knowledge to understand the device.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3924-36b4dc4a2eb33ba24b3f/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["quest:398"] = {
  hash = "afc180",
  fullHash = "afc180",
  text = "Wanted: Maggot Eye. In Brill, the Forsaken have set a death bounty on Maggot Eye. The notorious gnoll robs nearby graveyards and farms, supplying bodies to the Lich King's Scourge. Executor Zygand demands proof of the kill to secure the lands around Garren's Haunt. In Tirisfal Glades, the dead do not rest in peace. Maggot Eye faces a severe sentence for aiding the Lich King. Gnolls are usually savage brutes driven by hunger. Yet Maggot Eye digs up corpses and gathers remains to strengthen the Scourge army. The Forsaken fight to break free of the Lich King's control. Feeding their dead kin to the Scourge is among the gravest offenses. Executor Zygand oversees local military enforcement in Brill. He ordered the bounty to end grave robberies near Garren's Haunt. To claim the reward, bring Maggot Eye's paw as proof that the beast can trouble Tirisfal no longer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_398-06591187b3fcccc952e5/1-0000.mp3", duration = 56.555102, start = 0},
  },
}
P.transport["quest:399"] = {
  hash = "309baf",
  fullHash = "309baf",
  text = "Humble Beginnings. In Cathedral Square, Baros Alexston asks you to search his family's burned farm in Westfall. Thieves hold the ruins, and he hopes to recover the compass he treasured as a boy. Baros Alexston once worked the fields of Westfall. Now he is Stormwind City's accomplished architect, advising on stonework and city buildings. Few in the kingdom have made such a journey from farm to city. Yet Baros remains bound to the humble beginnings that shaped him. Lawlessness swept across Westfall and reached the Alexston Farmstead. Bandits and vagrants burned the house, driving Baros's father from his livelihood. Family heirlooms remained behind amid the fire and occupation. Now Baros asks you to search the ruined, bandit-held farmstead west of Sentinel Hill for his first compass, hidden before the home fell.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_399-f53a7d6c21c02b16c75a/1-0000.mp3", duration = 51.8008163, start = 0},
  },
}
P.transport["quest:40"] = {
  hash = "bdaa5a",
  fullHash = "bdaa5a",
  text = "A Fishy Peril. In eastern Elwynn, Remy \"Two Times\" fears a danger is spreading. Fishing has suffered and travelers face attacks, but he doubts the guard understands the trouble. In Goldshire seeking business, Remy grows uneasy as murlocs swim up streams and into inland shallows. He asks passersby to warn the township before the threat spreads further. Marshal Dughan hears the report but doubts it. His garrison is stretched thin, and without confirmed intelligence, he will not send scarce men after rumors of fish-men in the eastern streams.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_40-4317009edfdbfc5041f7/1-0000.mp3", duration = 33.7763265, start = 0},
  },
}
P.transport["quest:400"] = {
  hash = "98c8f1",
  fullHash = "98c8f1",
  text = "Tools for Steelgrill. At Kharanos, Tharek Blackstone sends you northeast with tools for Beldin Steelgrill at the depot. The road leads from town to the mechanics and war machines gathered there. Across Dun Morogh, Beldin Steelgrill is known as the sharpest siege engine mechanic in the mountains. His rough work breaks arclight spanners and other tools faster than Kharanos suppliers can replace them. Tharek Blackstone has a fresh batch of durable gear ready, so a traveler bound northeast carries the heavy crate to the depot. Steelgrill's Depot is crowded with idle war machines and military repairs. Beldin's backlog includes urgent work on Pilot Stonegear's siege engine. He broke his last fang-ratchet only hours before you arrive. The crate is needed to keep Ironforge's tracked armor fleet running.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_400-15568d92c5529e7af57b/1-0000.mp3", duration = 48.5877551, start = 0},
  },
}
P.transport["quest:403"] = {
  hash = "67d644",
  fullHash = "67d644",
  text = "Guarded Thunderbrew Barrel. In Kharanos, the Thunderbrew family’s ale waits under guard in the distillery cellar. Jarven watches over the stock. Jarven Thunderbrew keeps watch over the aging casks beneath the Thunderbrew Distillery in Kharanos. Sentries stand beside the barrels, guarding the brew from tampering or theft. The Thunderbrews keep their recipes close, especially the potent Thunder Ale. Dwarves give brewing the care they give smithing and mining. Troggs creep nearby, and brewing rivals compete across the Alliance. So Jarven watches until the family’s ale is ready to be tapped.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_403-ea89fdca6c06b0b0c3bc/1-0000.mp3", duration = 36.5191837, start = 0},
  },
}
P.transport["quest:404"] = {
  hash = "a530c8",
  fullHash = "a530c8",
  text = "A Putrid Task. Deathguard Dillinger sends you west from Brill to guard the old bridge against the Scourge. Bring back proof that the dead are destroyed, and Tirisfal's defenders can keep the road clear. Brill guards a crossroads in eastern Tirisfal Glades, where the Scourge threaten the Forsaken stronghold. The dead wander west across the waterways and gather around the broken old stone bridge. Without patrols to drive them back, they could block travel between Brill and the western farmsteads. For the Forsaken, the Scourge at their borders are more than a threat to face. Every mindless ghoul and rotting corpse recalls the servitude and torment they escaped under Lady Sylvanas Windrunner. Deathguards like Dillinger take grim satisfaction in crushing their former captors. Severed claws prove the mindless dead have been put to rest for good.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_404-87451187d1875c6ee092/1-0000.mp3", duration = 53.002449, start = 0},
  },
}
P.transport["quest:405"] = {
  hash = "8a5ea6",
  fullHash = "8a5ea6",
  text = "The Prodigal Lich. In the Undercity, Bethor Iceshard seeks an agent for a matter involving a wayward lich. After your work against Scourge remnants and Rot Hide gnolls in Brill, Magistrate Sevren sends you south with orders. Your service in Brill has earned Magistrate Sevren's trust for greater Forsaken work. He sends you to Bethor Iceshard, a formidable mage in the Undercity's Magic Quarter. Bethor wants an agent tested against the Scourge, and Sevren gives you official orders to carry beneath the ruins of Lordaeron into the corridors of the Forsaken capital. Magistrate Sevren does not know the full details, but the orders concern finding and recruiting a rogue lich. Liches are among the Scourge's deadliest spellcasters, so dealing with one is perilous. You bring the orders to Bethor atop his arcane sanctum. The icy mage is ready to see whether Brill's magistrate has sent someone strong enough to track such dangerous quarry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_405-c6cd18319632cc4eaaa8/1-0000.mp3", duration = 57.1297959, start = 0},
  },
}
P.transport["quest:407"] = {
  hash = "d6b64b",
  fullHash = "d6b64b",
  text = "Fields of Grief. In Brill, Apothecary Johaan tests a weapon made from pumpkins. He laces them with his latest alchemical concoction and sends you to feed one to a captive Scarlet Crusader. The Forsaken face the Scourge to the north and human incursions to the south, so Apothecary Johaan believes they must use every advantage. The Royal Apothecary Society looks beyond blades and dark sorcery. It seeks weapons among the land’s ordinary produce. Johaan has tainted pumpkins gathered from the mortal farmers at Solliden Farmstead. He means to prove that common crops can be made deadly in service of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_407-e26e889dffb1f5fde14a/1-0000.mp3", duration = 39.0008163, start = 0},
  },
}
P.transport["quest:408"] = {
  hash = "1ccc4e",
  fullHash = "1ccc4e",
  text = "The Family Crypt. Scourge forces press the Forsaken at Agamand Mills. From Brill, Magistrate Sevren sends agents to strike the undead in the family crypt. The Forsaken hold Tirisfal Glades, though the Scourge still commands much of its countryside. The Agamand Mills once ground flour for Lordaeron. Now the mills shelter the Scourge. In Brill, Magistrate Sevren watches the enemy gather with grave concern. Every stretch of land lost to the undead weakens the Forsaken's independence. Captain Dargol, a skeletal commander, has made the Agamand Family Crypt his headquarters. He uses necromancy to raise generations of the Agamand dead as Rotting and Wailing Ancestors, swelling his ranks. Magistrate Sevren sends Forsaken agents to purge the crypt and lay its disturbed dead to rest. He also wants Dargol's head, to disrupt Scourge forces in northern Tirisfal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_408-3c0a48e8e091bde19781/1-0000.mp3", duration = 54.4653061, start = 0},
  },
}
P.transport["quest:409"] = {
  hash = "b38916",
  fullHash = "b38916",
  text = "Proving Allegiance. Gunther Arcanus tests whether you serve the free-willed Forsaken or the Lich King. He sends you to summon and destroy Lillith Nefara, a Scourge operative near his island. Gunther Arcanus has lived on an island in Brightwater Lake since rising into undeath. He guards his freedom fiercely. Bethor Iceshard enchanted Gunther's spellbook and found no Scourge taint on the emissary. Yet neither words nor charms can quiet Gunther's suspicions. He needs an outsider to prove hostility toward the Lich King's minions through decisive violence before he will trust them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_409-c2e8fd27a22f338e6fb2/1-0000.mp3", duration = 36.2840816, start = 0},
  },
}
P.transport["quest:410"] = {
  hash = "20677a",
  fullHash = "20677a",
  text = "The Dormant Shade. At Gunther's Retreat in Brightwater Lake, a dark rite calls to Lillith Nefara. Set a mystic candle on the old blood-soaked table to summon the Scourge agent and prove to Gunther Arcanus that you oppose the Lich King. On Gunther's Retreat, an island in Brightwater Lake, a battered dinner table lies stained with blood. It is no abandoned piece of furniture. Dark conjuring gathers around the rough slab, where dried gore marks the place of death and magic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_410-2efe9ca1669af76e39ef/1-0000.mp3", duration = 30.6938776, start = 0},
  },
}
P.transport["quest:411"] = {
  hash = "e8ba69",
  fullHash = "e8ba69",
  text = "The Prodigal Lich Returns. In the Undercity, you carry a Nether Gem to Bethor Iceshard after winning Gunther Arcanus's trust and restoring his grimoire. Gunther Arcanus spent years alone on an island in Brightwater Lake. By will alone, he escaped the Lich King's control, not knowing Sylvanas Windrunner had freed Lordaeron. Bitter and wary, he distrusted the Undercity's emissaries. An adventurer returned his spellbook and showed him their hostility toward the Scourge. Satisfied the visitor was no enemy, Gunther entrusted them with a Nether Gem to contact his former colleague.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_411-50a7754c1d13044972e0/1-0000.mp3", duration = 36.2318367, start = 0},
  },
}
P.transport["quest:412"] = {
  hash = "859ed8",
  fullHash = "859ed8",
  text = "Operation Recombobulation. In Kharanos, Razzle Sprysprocket and Ozzie Togglevolt search for a cure for their kin. Their experimental Recombobulator needs parts taken from hostile leper gnomes outside Gnomeregan. Razzle and Ozzie are building a machine to restore their afflicted kin to health and sanity. Radiation changed most of Gnomeregan's gnomes into sickly, deranged leper gnomes. The inventors hope their Recombobulator can reverse that change. Razzle needs Restabilization Cogs and Gyromechanic Gears for the delicate prototype. The parts must come from hostile leper gnomes outside Gnomeregan's sealed gates. Debris from their altered kin may help undo the tragedy they share.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_412-431c01b1c85ac4055e3d/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["quest:413"] = {
  hash = "dacb23",
  fullHash = "dacb23",
  text = "Shimmer Stout. At Brewnall Village, Rejold Barleybrew is sending Shimmer Stout to his brother Wellart. The guard watches the pass toward Loch Modan, where a cold post makes a strong drink welcome. Rejold Barleybrew perfected Shimmer Stout with shimmering fronds gathered from Dun Morogh’s icy crags. His family tends the vats and kegs at Brewnall Village, while his brother Wellart chose life as a Mountaineer. Knowing how lonely frontier guard duty can be, Rejold sends a fresh barrel with passing travelers. It is a kindness between brothers and a chance to test the brew. Wellart Barleybrew guards the South Gate Pass into Loch Modan from the southern tower. High in the pass, Mountaineers face bitter winds and occasional beast attacks as they watch over travelers on the mountain road. Wellart is running low on drink and restless for excitement. Shimmer Stout packs quite a punch, he finds, and seems to brighten his vision in the dim mountain night.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_413-bb5ffd95cb5eacc58fa9/1-0000.mp3", duration = 57.7306122, start = 0},
  },
}
P.transport["quest:414"] = {
  hash = "33d3b8",
  fullHash = "33d3b8",
  text = "Stout to Kadrell. A cask of Rejold Barleybrew’s new Shimmer Stout is headed east to Mountaineer Kadrell in Loch Modan. You carry it from Dun Morogh’s frozen heights to the warmer valley. From Dun Morogh’s eastern border post, Mountaineer Barleybrew watches the mountain passes and the kin guarding neighboring lands. The Mountaineers’ patrols can be cold and grueling, and a stout heart calls for stout drink. Rejold’s new Shimmer Stout is too good to keep in Dun Morogh. Barleybrew wants an honest opinion from a fellow patrolman, so he sends a cask east with travelers bound for Loch Modan. For young dwarven and gnomish adventurers, the road to Loch Modan is a rite of passage after their early days in Dun Morogh’s snowbound crags. You pass southeast through the South Gate Outpost, then follow long tunnels cut through the mountain bedrock. Beyond them lies Loch Modan’s warmer, wooded basin. Mountaineer Kadrell patrols the road through Thelsamar. He pauses to tap the cask and finds that Barleybrew’s new recipe has an astonishing kick.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_414-8f3ddf4d49465878cf81/1-0000.mp3", duration = 63.1640816, start = 0},
  },
}
P.transport["quest:415"] = {
  hash = "fcbb21",
  fullHash = "fcbb21",
  text = "Rejold's New Brew. Back at Brewnall Village, Rejold Barleybrew has perfected his new recipe. He wants you, the trusted friend who secured the Shimmerweed, to taste it. Tharek Blackstone and Pilot Bellowfiz send you back to Brewnall Village. Rejold has finished fermenting his experimental batches and is ready to share them with you. You secured Shimmerweed from the bitter slopes, and now he can offer you the fruits of that effort. Rejold Barleybrew has blended local herbs into his mash to make Shimmer Stout. Before he ships barrels to neighboring outposts and thirsty patrons in Loch Modan, he gives you the honor of the first sip. You risked life and limb for the herbs, and the first taste is yours.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_415-1a308ee1037fd2ab7a22/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["quest:4161"] = {
  hash = "5d877c",
  fullHash = "5d877c",
  text = "Recipe of the Kaldorei. In Dolanaar, Zarrin teaches young cooks to gather only what they need from Teldrassil's woods. His lesson begins with food and the forest, not the battlefield. Behind the inn in Dolanaar, Zarrin tends a bubbling cauldron and teaches young adventurers the traditions of his people. Night elves once called themselves the kaldorei, or children of the stars. Zarrin begins with their bond to food and Teldrassil's boughs, and leaves the battlefield aside. Outside Shadowglen, Zarrin asks you to gather exactly seven small spider legs from woodland arachnids. The kaldorei seek harmony with nature by taking only what they need and treating the wild with kindness. Even in troubled times, that balance matters. A spider kabob makes the lesson plain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4161-63739f0ebdaecb6dee62/1-0000.mp3", duration = 47.7257143, start = 0},
  },
}
P.transport["quest:417"] = {
  hash = "477d80",
  fullHash = "477d80",
  text = "A Pilot's Revenge. Hildelve’s search ends in the crags of Dun Morogh, where Pilot Hammerfoot’s searchers find him frozen beside his journal. His last words call for vengeance. Hildelve’s journal tells of his savage fight with Mangeclaw, the huge Ice Claw bear. He drove the beast away at first, but his wounds were grave. Mangeclaw returned and killed him. Hildelve’s final plea calls for vengeance against Mangeclaw. Bring his journal and a claw torn from the beast to Pilot Hammerfoot. The grim news gives the Ironforge Siege Brigade closure and honors its lost comrade.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_417-d9cae25f5dbe7c75cf64/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["quest:418"] = {
  hash = "6a8564",
  fullHash = "6a8564",
  text = "Thelsamar Blood Sausages. At Thelsamar's Stoutlager Inn, Vidra Hearthstove keeps Thelsamar Blood Sausages on the table. A favorite across Loch Modan, they need fresh ingredients from the valley. Hungry children and miners returning from the Ironband Excavation fill Thelsamar's tavern. Vidra Hearthstove tends the stove, making sausages known across Loch Modan. Her recipe draws on wildlife from the rugged mountain pass. Vidra uses boar intestines for casings and bear meat for the filling. Spider ichor gives the sausages their sharp, pungent bite. Gathering the entrails and venomous fluid takes a steady stomach, though travelers come to appreciate this regional favorite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_418-f2783ff94e1eb7ac6c3e/1-0000.mp3", duration = 42.1355102, start = 0},
  },
}
P.transport["quest:419"] = {
  hash = "d3eb0f",
  fullHash = "d3eb0f",
  text = "The Lost Pilot. At the wreck, Pilot Hammerfoot fears for Mori Hildelve in Dun Morogh's crags. Hildelve went on foot to seek rare ore for potent blastpowder, but days have passed and roars echo through the peaks. Pilot Mori Hildelve drove his siege engine up Dun Morogh's steep ridges in search of rare ore for high-grade blastpowder. The machine broke on the slope. He left Pilot Hammerfoot at the camp to guard the wreck, then climbed higher into the frozen wilderness on foot. Days passed, and Hildelve did not return to camp. At night, vicious growls echoed from the rocky crags. Hammerfoot's impatience gave way to dread. Hildelve was tough, but the frigid heights offered little shelter from prowling predators without his engine or heavy support.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_419-a69ba9f0ff348ad892a6/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:420"] = {
  hash = "aa6cb3",
  fullHash = "aa6cb3",
  text = "Senir's Observations. Grelin Whitebeard's report reaches his brother Senir in Kharanos, carrying news from Coldridge Valley. Its arrival sends Senir back to watching hostile forces across the snowfields. Mountaineer Thalos guards the gate out of Coldridge Valley. He entrusts passing travelers with Grelin's dispatch. Beyond the gate, violent troggs ambush those crossing the tunnel and make the passage to Kharanos dangerous. Past the tunnel, the main road runs through central Dun Morogh to town. At the Thunderbrew Distillery, Senir Whitebeard warms himself over drinks when Grelin's report arrives. He chuckles at his brother's forceful words. Grelin invokes King Magni Bronzebeard to press for urgent action, Senir says, and that will agitate the stubborn Ironforge Senate.\n\nThe bitter cold has kept Senir from filing his own observations. Grelin's dispatch sends him back to watching hostile forces across the snowfields.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_420-de042a6a6cc2c50f808b/1-0000.mp3", duration = 56.6073469, start = 0},
  },
}
P.transport["quest:421"] = {
  hash = "94c724",
  fullHash = "94c724",
  text = "Prove Your Worth. At the Sepulcher, Dalar Dawnweaver's campaign against Silverpine's worgen is underway. The Forsaken seek a path south through human and dwarven lands, but feral worgen threaten the road. Their presence leads back to Archmage Arugal. Lady Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, seek to secure the lands south of Tirisfal Glades. Human and dwarven enclaves lie among them. Silverpine Forest is in their path, but the route is dangerous. Feral Moonrage worgen prowl its pine-covered hills, threatening Forsaken supply lines and forward bases. Dalar Dawnweaver says Arugal brought the worgen to Silverpine. Once a mage of Dalaran, Arugal was disgraced. During the Scourge invasion, he unleashed otherworldly worgen upon the forest. Now he has claimed Shadowfang Keep, while his feral creations roam the woods. Before Dalar trusts soldiers to investigate Arugal's sorcery further, recruits must prove their fighting skill against the nearest Moonrage Whitescalps.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_421-285d85404223da76b3ef/1-0000.mp3", duration = 65.802449, start = 0},
  },
}
P.transport["quest:422"] = {
  hash = "250782",
  fullHash = "250782",
  text = "Arugal's Folly. At the Sepulcher, Dalar Dawnweaver sends Forsaken agents to a nearby farmstead for Arugal's earliest spellbooks. The Forsaken need to understand the magic behind the worgen curse if they are to turn it against Arugal and secure Silverpine Forest. The Remedy of Arugal is the first step in unraveling the threat from Shadowfang Keep. In the Sepulcher's crypts, ambitious Forsaken mage Dalar Dawnweaver holds Archmage Arugal in contempt. He sees him as an ordinary practitioner whose place in the Kirin Tor makes no sense, and whose grasp of magic seems amateurish. Yet the monstrous beasts roaming Silverpine cannot be ignored. To break Arugal's hold on the region, Dawnweaver means to take apart the spells that unleashed the worgen upon Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_422-f19861b1afaaf8663324/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["quest:423"] = {
  hash = "a5b038",
  fullHash = "a5b038",
  text = "Arugal's Folly. In Silverpine, Forsaken agents seek shackles worn by Moonrage worgen. Dalar Dawnweaver studies Arugal's notes to learn how the renegade mage strengthened his unstable magic. The bindings may help the Forsaken break the worgen threat. Dalar Dawnweaver studies Arugal's recovered research and speaks of his former peer with open contempt. He says Arugal was unfit to serve Dalaran, let alone wield high sorcery in the kingdom's darkest hour. Short on talent, Arugal turned to enchanted relics and devices to strengthen and bind the worgen he summoned. Dalar needs samples to study the magic that tethers the beasts. Moonrage worgen roam Silverpine wearing shackles marked by Arugal's binding enchantments. Moonrage Gluttons and Moonrage Darksouls prowl north and east of the Sepulcher. Their heavy metal shackles hold residual arcane energy. Dawnweaver hopes that energy will help him find a way to counter Shadowfang Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_423-a0f6426c75d7a22fce76/1-0000.mp3", duration = 59.6897959, start = 0},
  },
}
P.transport["quest:424"] = {
  hash = "f38e0a",
  fullHash = "f38e0a",
  text = "Arugal's Folly. Worgen hold Deep Elem Mine in Silverpine's southeastern hills, keeping the Forsaken from ore needed by Varimathras's forces. Dalar Dawnweaver sends you to slay their corrupted foreman, Grimson the Pale, and carry his head to the Sepulcher. Dalar Dawnweaver learns from the Forsaken Darkstalkers that worgen have reached Deep Elem Mine in Silverpine's southeastern hills. Their feral sorcery spread from Shadowfang Keep, where Archmage Arugal unleashed dark enchantments across the forest. Ore from the mine is needed to arm the Undercity. But worgen now make their lair in its shafts, and the mine lies unusable. Grimson the Pale leads the worgen through the mine's infested shafts. Dalar Dawnweaver orders you to slay the corrupted foreman and bring his head to the Sepulcher. With Grimson gone, the worgen will lose their leader, and Forsaken laborers can claim the mine for Lord Varimathras.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_424-3f92e0323e3593c17480/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["quest:425"] = {
  hash = "45b126",
  fullHash = "45b126",
  text = "Ivar the Foul. At the Ivar Patch in northern Silverpine, Rane is guarding her badly mauled brother while Ivar the Foul prowls nearby. She asks Horde travelers to kill the savage ghoul so Quinn can recover and they can finish their report to High Executor Hadrec. In northern Silverpine Forest, Deathstalkers Rane and Quinn Yorick were sent to survey the forest for High Executor Hadrec at the Sepulcher. Their work ended in violence at a farmstead, where Ivar the Foul ambushed them. Rane and Quinn escaped, but Quinn was badly mauled. An alchemical remedy made from forest beasts has helped, though he is still too weak to travel. Ivar prowls the nearby barn, waiting for Rane's guard to fail. She asks Horde travelers to enter and kill him, so the homestead can be secured.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_425-bbde3ccc9285165c3eb5/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["quest:426"] = {
  hash = "93d8d7",
  fullHash = "93d8d7",
  text = "The Mills Overrun. The Scourge mass at Agamand Mills in Tirisfal, close to Forsaken settlements. Deathguard Dillinger sends soldiers from Brill to break their ranks before the ruined mills become a base for attacks deeper into the glades. The Agamand Mills once anchored Tirisfal Glades' agriculture. Since the Third War, Scourge forces have gathered beneath their windmills, held in thrall by the Lich King. These mindless undead threaten the young Forsaken holdings. If they seize the mills, they will have a base for attacks deeper into Tirisfal and against its settlements. Deathguard Dillinger helps fortify Brill and patrols the territory. He sends recruits after Rattlecage and Cracked Skull Soldiers, along with Darkeye Bonecasters. Dillinger asks for notched ribs and blackened skulls as proof that the skeletal ranks have broken and been driven back toward the Plaguelands before their offensive begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_426-c9cb66f356846a3d7653/1-0000.mp3", duration = 54.5959184, start = 0},
  },
}
P.transport["quest:427"] = {
  hash = "8c3f64",
  fullHash = "8c3f64",
  text = "At War With The Scarlet Crusade. In Tirisfal Glades, Executor Zygand sends you against the Scarlet Crusade. Executor Arren has recovered intelligence, and your first target is Scarlet Warriors at a tower west of Solliden Farmstead. The strike begins the Forsaken campaign to drive the crusaders from their borders. Lady Sylvanas Windrunner's Forsaken face threats on several fronts. The Deathguard watches the Lich King's growing armies, while the Scarlet Crusade challenges Forsaken rule over their former homeland. The Crusade calls all undead abominations to be purged with fire and blade. Its zealots do not see that the Forsaken have broken free of the Scourge's control. At Deathknell, Executor Arren secured documents showing where Scarlet encampments and outposts lie across Tirisfal Glades. The Deathguard is busy containing the Scourge, so independent Forsaken champions strike the zealots directly. Their first target is a guard tower west of Solliden Farmstead. Scarlet Warriors gather there and threaten the western approaches to Brill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_427-05a4bfa095937957265c/1-0000.mp3", duration = 64.3918367, start = 0},
  },
}
P.transport["quest:428"] = {
  hash = "7fb414",
  fullHash = "7fb414",
  text = "Lost Deathstalkers. In northern Silverpine, two Forsaken scouts have been missing for weeks. High Executor Hadrec sent Rane and Quinn Yorick to watch the abandoned farms, and now you seek word of them. At the Sepulcher, High Executor Hadrec has heard nothing from Rane and Quinn Yorick for weeks. He sent the pair into northern Silverpine Forest to watch the abandoned farms and track enemy movements. Deathstalkers are the Forsaken’s hidden scouts and killers. They serve Lady Sylvanas, and Hadrec fears the Scourge or another threat has cut them down. Northern Silverpine lies between Lordaeron’s ruined estates and the shadowed borders of Tirisfal Glades. Undead roam there, beasts prowl, and feral worgen make travel perilous even for seasoned rogues. Search the decaying farmsteads where Rane and Quinn Yorick began their survey. Any intelligence they gathered may be vital, if danger has not overtaken them first.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_428-482096997ee7d05f0446/1-0000.mp3", duration = 56.2677551, start = 0},
  },
}
P.transport["quest:429"] = {
  hash = "016d97",
  fullHash = "016d97",
  text = "Wild Hearts. In Silverpine, Rane Yorick seeks help while her brother Quinn lies badly wounded. She needs discolored worg hearts for Apothecary Renferrel at the Sepulcher, whose alchemy may help Quinn recover. Rane Yorick stays beside her brother Quinn, badly wounded after the Deathstalkers' disastrous mission left them pinned down at a farm in northern Silverpine. The feral ghoul Ivar the Foul mauled him, and he is failing to recover. Ordinary rest cannot mend an undead body torn by such savagery. So Rane turns to the Royal Apothecary Society and its grim arts for a way to put her brother back together. Silverpine's worgs carry the corruption spreading through northern Lordaeron. Their hearts are discolored and hold potent essences. The Royal Apothecaries can distill these blighted organs into concoctions that restore withered Forsaken flesh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_429-c76e16e89a1ca76f69c5/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["quest:430"] = {
  hash = "0d50b1",
  fullHash = "0d50b1",
  text = "Return to Quinn. At the Ivar Patch, Quinn Yorick waits for a draught that may let him travel again. Apothecary Renferrel sends you from the Sepulcher with the mixture, while Quinn remains wounded in dangerous country. After you gather wild beast hearts for the Royal Apothecary Society, Apothecary Renferrel brews a restorative draught for Quinn Yorick at the Sepulcher. He hands it to you, then returns to his secret alchemical research. You carry the mixture back into the wilderness. At the ruined Ivar Patch, Quinn Yorick shelters beside his sister, Deathstalker Rane Yorick. The ghoul Ivar the Foul wounded him so badly he cannot cross hostile ground. Quinn drinks the draught as soon as you arrive. It restores enough strength for him to travel in time, though danger still surrounds the farmstead and Ivar lurks nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_430-4f0dfe64bc412aa70f14/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:431"] = {
  hash = "21d76d",
  fullHash = "21d76d",
  text = "Candles of Beckoning. In Tirisfal Glades, candles from Gunther's island are bound for a grim test. Gunther Arcanus keeps them for a trial of allegiance. Gunther asks you to carry a candle from the crate on Gunther's Retreat to the old, bloody altar off the island's southern coast. Light it there, and Lillith Nefara, the Scourge agent, will face you. On Gunther's Retreat, the island in Brightwater Lake where Gunther Arcanus dwells, a crate holds the candles. For his test in Proving Allegiance, one candle is enough. Lit on the old, bloody altar off the island's southern coast, it awakens Lillith Nefara, the Scourge agent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_431-8d9d4805d4d5cd3121e1/1-0000.mp3", duration = 41.0906122, start = 0},
  },
}
P.transport["quest:432"] = {
  hash = "1d5546",
  fullHash = "1d5546",
  text = "Those Blasted Troggs!. In Gol'Bolar Quarry, troggs wreck the workings while Foreman Stonebrow calls for help. They have broken his equipment and powder barrels. His fading aim keeps him from fighting them himself, so he asks willing fighters to thin the Skullthumpers. Troggs have overrun the lower terraces of Gol'Bolar Quarry in eastern Dun Morogh. They broke through the bedrock and flooded the tunnels, ending the dwarven excavation's productive days. Now they smash scaffolding and blow apart powder barrels, leaving the quarry in ruin. From the ridge, Foreman Stonebrow watches his life's work crumble. Age has weakened his hands and spoiled his aim, so he relies on passing wanderers and Alliance recruits to fight in his place. He wants the burly Rockjaw Skullthumpers thinned. Only their complete destruction would satisfy his anger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_432-9b6ac880a6d081f7f370/1-0000.mp3", duration = 50.8342857, start = 0},
  },
}
P.transport["quest:433"] = {
  hash = "79cc51",
  fullHash = "79cc51",
  text = "The Public Servant. At Gol'Bolar Quarry, Senator Mehr Stonehallow calls for aid against troggs that have halted mining in Dun Morogh. He wants the Rockjaw Bonesnappers driven out so miners can return to work. Mehr Stonehallow serves in Ironforge's Senate and belongs to the Explorers' League. He has come to Gol'Bolar Quarry to direct the response himself. There, he hires travelers and mercenaries to drive the invaders from the mine. Deep digging at Gol'Bolar Quarry broke into sealed hollows underground. Rockjaw troggs poured into the pits, smashed mining equipment, and drove out the workers. Stonehallow wants the Rockjaw Bonesnappers cleared away so Mountaineers can secure the quarry and mining can resume.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_433-0cd025056e631e2dc4ac/1-0000.mp3", duration = 44.277551, start = 0},
  },
}
P.transport["quest:435"] = {
  hash = "a39bd0",
  fullHash = "a39bd0",
  text = "Escorting Erland. In Silverpine, Deathstalker Erland is trying to reach his partner, Rane Yorick. Wolves have trapped him in a shelter, and the way to Rane crosses their hunting ground. Deathstalker Erland is trapped in a shelter by hungry wolves. Even a seasoned Forsaken scout can be overcome by Silverpine's wilds. Wolves circle the ruined refuge, drawn to the little flesh left on Erland's withered frame. Alone, he cannot break through their pack. Deathstalker Erland needs to reach his partner, Rane Yorick, near the Ivar Patch. Wolves prowl the ground between them. Once you guide Erland past the pack, he runs the last stretch to Rane Yorick's outpost. There, the scouts can bring their intelligence together for the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_435-2369567a8ab48abe05fe/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["quest:436"] = {
  hash = "630e5d",
  fullHash = "630e5d",
  text = "Ironband's Excavation. Jern Hornhelm has sent you from Thelsamar to find out why Ironband's Excavation is making so little progress. Supplies reach Prospector Ironband's team, and Jern trusts his diligence, but the work remains slow. Jern Hornhelm watches from Thelsamar as provisions and tools cross Loch Modan to the Explorers' League. They arrive steadily, yet the dig makes little progress. Jern suspects something is disrupting the work. He needs you to find out what is holding the team back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_436-86bf94ae7a94dc865083/1-0000.mp3", duration = 30.1453061, start = 0},
  },
}
P.transport["quest:437"] = {
  hash = "64fafb",
  fullHash = "64fafb",
  text = "The Dead Fields. In northern Silverpine, Forsaken forces face a Scourge threat at the Dead Fields. High Executor Hadrec sends champions from the Sepulcher against the Rot Hide gnolls and the banshee who shields them. North of the Sepulcher, Rot Hide gnolls overrun an abandoned farmstead. Ordinary farms once stood in these fields. Now plague-ridden scavengers infest the Silverpine countryside. High Executor Hadrec sent small raiding parties to drive them out, but each attack stalled against a strange magical resistance. Nightlash, a Scourge banshee, directs the Rot Hide gnolls. When the gnolls face defeat, she scatters Forsaken skirmishers with dark sorcery. Hadrec sends Horde champions to cut down the gnolls and draw Nightlash into the open. He asks for her spectral essence as proof of her destruction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_437-e1fefc1d05da4d86f9c9/1-0000.mp3", duration = 52.9502041, start = 0},
  },
}
P.transport["quest:438"] = {
  hash = "6998bf",
  fullHash = "6998bf",
  text = "The Decrepit Ferry. At the Decrepit Ferry, the Scourge gathers along Lordamere Lake’s shore. High Executor Hadrec sends Forsaken champions east to learn what draws them there. After the Scourge presence in the Dead Fields is suppressed, High Executor Hadrec turns his attention east. The Decrepit Ferry lies among Silverpine Forest’s eastern waterways, where mainland Lordaeron once connected to the island estates of Lordamere Lake. Now undead gather around its rotted piers. Hadrec sends scouts to discover what draws the Lich King’s servants there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_438-9bbabce2faecc94ccbb6/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["quest:439"] = {
  hash = "f48b73",
  fullHash = "f48b73",
  text = "Rot Hide Clues. At Lordamere Lake, Rot Hide Clues come to light with an engraved ring on a recently deceased woman's hand. When you report the grim find to High Executor Hadrec at the Sepulcher, he sees that Rot Hide gnolls are taking bodies from Tirisfal's mass graves and carrying them to Fenris Isle. Forsaken scouts find a ferry laden with corpses on the shore of Lordamere Lake. Among the dead is the unwrapped, plague-marked hand of a recently slain woman. A plain band on it bears the words “For Deliah.” The ferry points to an organized effort to move the dead, not scavengers feeding at random.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_439-1593978443863a441249/1-0000.mp3", duration = 37.0155102, start = 0},
  },
}
P.transport["quest:440"] = {
  hash = "858caf",
  fullHash = "858caf",
  text = "The Engraved Ring. High Executor Hadrec sends you across the border to Brill with a ring bearing Deliah's name. Magistrate Sevren searches the town records to learn who she was and where the ring came from. Scouts searching for the Rot Hide gnolls in northern Silverpine Forest found Deliah's ring. Magistrate Sevren keeps Tirisfal's civic records and burial registers, though Hadrec doubts any Forsaken still cares for such keepsakes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_440-777e0358726b035c5411/1-0000.mp3", duration = 27.1934694, start = 0},
  },
}
P.transport["quest:441"] = {
  hash = "dfc96c",
  fullHash = "dfc96c",
  text = "Raleigh and the Undercity. In Brill and the Undercity, a ring draws Raleigh into an old tragedy. Magistrate Sevren sends you to return Deliah's ring to her widowed husband, found after her stolen corpse was bound for Fenris Isle. In Brill, Magistrate Sevren has pieced together clues about a stolen corpse and an engraved ring. The ring belonged to Deliah, and Sevren hopes to learn where it came from and return it to her family. He sends you into the Undercity to find Raleigh, Deliah's surviving husband.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_441-70ee77709cabc4db3fec/1-0000.mp3", duration = 31.1379592, start = 0},
  },
}
P.transport["quest:443"] = {
  hash = "aeab09",
  fullHash = "aeab09",
  text = "Rot Hide Ichor. In Silverpine Forest, High Executor Hadrec seeks Rot Hide Ichor before the Forsaken attack Fenris Isle. He wants the fluid studied to understand the gnolls infesting the island. Rot Hide gnolls on Fenris Isle decay and fight with a fury unlike ordinary wild humanoids. They hold strategic ground across Lordamere Lake. High Executor Hadrec believes the strange fluid in their veins may explain their unnatural resilience. He needs samples before the Forsaken commit soldiers to a costly assault. The Royal Apothecary Society works from the Sepulcher, where Apothecary Renferrel studies biological and chemical anomalies. Bring him samples of the putrid fluid. The Forsaken hope to learn where the gnolls came from, who is engineering them, and what weaknesses they have in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_443-3df8fb874deb184e4729/1-0000.mp3", duration = 52.8457143, start = 0},
  },
}
P.transport["quest:444"] = {
  hash = "c1ffa1",
  fullHash = "c1ffa1",
  text = "Rot Hide Origins. In Silverpine Forest, the Rot Hides carry a magic Renferrel cannot explain by alchemy alone. He sends a sample to Bethor Iceshard in the Undercity, where arcane knowledge may reveal its origin. Apothecary Renferrel has reduced fluid from the Rot Hides of Silverpine Forest to its basic elements. His first tests show the ichor bears both necromancy and warlock magic. Alchemy cannot explain the sorcery behind it, so he prepares a sample for an expert in the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_444-bde69ac1d8484f9fffbf/1-0000.mp3", duration = 32.9142857, start = 0},
  },
}
P.transport["quest:445"] = {
  hash = "ff746b",
  fullHash = "ff746b",
  text = "Delivery to Silverpine Forest. You carry Apothecary Johaan’s findings from Brill to Renferrel at the Sepulcher in Silverpine Forest. The Royal Apothecary Society needs them for its work on the New Plague. Lady Sylvanas Windrunner commands the Royal Apothecary Society, which seeks a New Plague that can wipe out the living and the Scourge. Its laboratories lie across Forsaken territory, so researchers share their findings to keep the work moving. In Brill, Apothecary Johaan has gathered experimental results for other field researchers. You carry them south to Renferrel at the Sepulcher. Silverpine Forest is the next frontier of Forsaken expansion and research. Apothecary Renferrel works from the Sepulcher, overseeing biochemical tests amid threats from Moonrage worgen, rogue humans, and the lingering Scourge. He receives Johaan’s notes from Tirisfal Glades and adds their alchemical findings to his own experiments, advancing the Society’s design.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_445-fd39957fadfdbca3bfc9/1-0000.mp3", duration = 57.9918367, start = 0},
  },
}
P.transport["quest:446"] = {
  hash = "0b1cf8",
  fullHash = "0b1cf8",
  text = "Thule Ravenclaw. At the Undercity, a courier brings Bethor Iceshard strange Rot Hide ichor. Bethor recognizes the work of Thule Ravenclaw, his traitorous former colleague, and prepares counter-incantations to help the Forsaken resist the gnolls. In the Undercity’s Magic Quarter, Bethor Iceshard recognizes an arcane mark in a courier’s sample of Rot Hide ichor. Thule Ravenclaw made the distillation. Before the Third War, Thule was a bright young mage and Bethor’s colleague. When the Lich King rose to power, Thule betrayed his peers and swore himself to the Scourge. As Lordaeron fell, he abandoned his humanity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_446-5b96a88dced875521884/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["quest:447"] = {
  hash = "8e1f1f",
  fullHash = "8e1f1f",
  text = "A Recipe For Death. In Silverpine, A Recipe For Death gathers reagents for the Forsaken's New Plague. From the Sepulcher, Apothecary Renferrel sends bear hearts and spider blood to Master Apothecary Faranell in the Undercity. In Silverpine Forest, Apothecary Renferrel sees two foes closing on Sylvanas's people. Arthas's legions press them, while remnants of humanity remain enemies. The Forsaken have little hope in conventional warfare. They seek a New Plague that can rot living humans and undead Scourge alike.\n\nRenferrel's field research found a virulent foundation for the plague. Arachnid venom from the Skittering Dark, joined with toxins in the hearts of native bears, forms that base. Bear hearts and spider blood gathered in Silverpine's wilderness travel beneath Lordaeron's ruins to the Apothecarium in the Undercity. Master Apothecary Faranell oversees the Royal Apothecary Society's design.\n\nFaranell takes Renferrel's samples to test their contaminable properties and refine formulas. The work may secure Forsaken supremacy across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_447-6bc377e08edce9190484/1-0000.mp3", duration = 69.7469388, start = 0},
  },
}
P.transport["quest:448"] = {
  hash = "19d65a",
  fullHash = "19d65a",
  text = "Report to Hadrec. In Silverpine, Renferrel sends you to Hadrec as the Scourge threat grows. Renferrel and Bethor Iceshard have investigated the Scourge presence in Lake Lordamere, and High Executor Hadrec now directs preparations against Fenris Isle. Apothecary Renferrel and Bethor Iceshard have studied the danger posed by Thule Ravenclaw, a renegade necromancer. Yet study alone cannot break the Scourge stronghold rising on Fenris Isle. Ravenclaw binds the restless dead there, and Renferrel sees that alchemy and magic will not be enough. The Forsaken military must bring its steel and discipline to bear, so Renferrel sends you to its commander. High Executor Hadrec directs Silverpine Forest's strategic operations for the Dark Lady from the Sepulcher's crypts. Bethor's warnings about Ravenclaw reach him, and Hadrec knows a necromancer entrenched on Lordamere's western shore threatens Undercity's flank. He opens the local garrison's armory to equip the vanguard before sending them against the island fortress.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_448-05011b66b6475468e2f5/1-0000.mp3", duration = 62.5110204, start = 0},
  },
}
P.transport["quest:449"] = {
  hash = "7b6c57",
  fullHash = "7b6c57",
  text = "The Deathstalkers' Report. Near the northern wilds, the Deathstalkers have found Scourge forces where the Forsaken did not expect them. You carry their report from the wounded scouts to High Executor Hadrec at the Sepulcher, bringing word that Silverpine Forest holds a greater threat than command believed. The Deathstalkers scout ahead for the Dark Lady, slipping into wild country before the main forces. Near the border of Tirisfal and Silverpine, one patrol met fierce resistance while tracking enemy movements.\n\nDeathstalker Quinn barely survived his wounds, while Erland fought his way to safety. Their patrol still gathered intelligence the Forsaken need to hold Silverpine Forest. High Executor Hadrec reads the sealed report and learns that the Scourge hold a stronger presence in Silverpine than Undercity strategists expected. Their forces are more active and aggressive than command believed.\n\nThe Forsaken had planned to secure abandoned human hamlets and drive off rogue beasts. Now the Sepulcher's command must prepare for organized Scourge opposition as it fights to claim the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_449-b65fd3c82e83a4c6b588/1-0000.mp3", duration = 68.3885714, start = 0},
  },
}
P.transport["quest:4495"] = {
  hash = "7bec66",
  fullHash = "7bec66",
  text = "A Good Friend. At Aldrassil, Dirania Silvershine grows anxious when Iverron misses his daily visit. She asks travelers to search the hills near Shadowthread Cave, north of Shadowglen. Beneath Aldrassil, Dirania Silvershine waits for Iverron, her friend who visits every day. Hours pass, and he does not come. So she asks travelers bound for Shadowglen to look for him. Iverron often wanders the hills in northern Shadowglen, close to the webwood spiders of Shadowthread Cave. The spiders make those slopes dangerous for travelers. Search west of the cave entrance, where Iverron is hiding and needs help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4495-67a327e6508d457c0b05/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["quest:45"] = {
  hash = "ae5cba",
  fullHash = "ae5cba",
  text = "Discover Rolf's Fate. Guard Thomas waits for news of Rolf and Malakai, missing near Stone Cairn Lake. Malakai's half-eaten remains and webbed tracks point toward a murloc village. Malakai's half-eaten remains lie by the shore. Webbed footprints mark the mud and lead east along the water's edge. They run straight to a ramshackle murloc camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_45-4ce37f1575cb8342f7bd/1-0000.mp3", duration = 22.4391837, start = 0},
  },
}
P.transport["quest:450"] = {
  hash = "c2fbdb",
  fullHash = "c2fbdb",
  text = "A Recipe For Death. From the Undercity, Master Apothecary Faranell sends you to Pyrewood Village in A Recipe For Death. You seek Apothecary Berard's notes on the ancient blight that wiped out Lake Lordamere's aquatic life. Apothecary Berard once stood among the Royal Apothecary Society's most promising researchers. He worked in Pyrewood Village, studying past ecological disasters for the Forsaken's alchemical pursuits. Then Archmage Arugal unleashed shadow magic across Silverpine Forest, and Berard fell under its curse. His mind gave way, binding him as a servant to the mage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_450-57cd80d9165161366f02/1-0000.mp3", duration = 37.355102, start = 0},
  },
}
P.transport["quest:451"] = {
  hash = "ce5520",
  fullHash = "ce5520",
  text = "A Recipe For Death. Across Lake Lordamere, Apothecary Renferrel sends you to gather rare reagents for the Royal Apothecary Society. Berard's journal describes mosses and a strange tumor, bound for Master Apothecary Faranell in the Undercity and his work on a New Plague. Apothecary Berard's death under Arugal's curse cost the Royal Apothecary Society a skilled researcher. His field journal survived, preserving what he learned about blighted life in Silverpine Forest and Lake Lordamere. At the Sepulcher, Apothecary Renferrel studied the recovered notes and found Berard's account of promising properties in local freshwater organisms. Now Renferrel asks you to carry forward the work his colleague began. Berard's reagents lie among the Dawning Isles, mist-shrouded islands in the eastern waters of Lake Lordamere. Lake skulkers and lake creepers on the isles carry peculiar moss strains that live in tainted water. Berard also noted a hardened tumor among the fierce Vile Fin murloc tribes that nest along the islets and the lake's southern shoreline near Ambermill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_451-e17eea3903f8d85211fd/1-0000.mp3", duration = 67.8922449, start = 0},
  },
}
P.transport["quest:4512"] = {
  hash = "2224a4",
  fullHash = "2224a4",
  text = "A Little Slime Goes a Long Way. In Ironforge, Laris Geardawdle seeks ooze samples from Felwood for his studies. He hopes to learn why the Royal Apothecary Society gathers them and what interests the Undercity's alchemists. Laris Geardawdle studies oozes with the Explorers' League. Most of its scholars seek titan relics or dwarven genealogies, but these living puddles resist ordinary classification. They appear in wetlands, cursed woods, and damp ruins. Laris has seen Forsaken apothecaries collecting slime across Lordaeron, and wants to know what draws them to it. Laris believes oozes may be primordial secretions tied to Azeroth's creation. He thinks they are neither vermin nor magical byproducts. To test his theory, you travel across the ocean to Felwood's blighted canopy. There, you gather Cursed and Tainted Oozes in specially made jars. For Laris and many displaced gnomes, these studies carry personal weight. Since Gnomeregan fell to troggs and radiation, thousands have taken refuge in Ironforge's Great Forge. A discovery for the Explorers' League could answer dwarven skeptics. It could show that welcoming gnomes into the mountain city has become an enduring asset to Alliance science.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4512-e38852b6d984b985ffb0/1-0000.mp3", duration = 80.2742857, start = 0},
  },
}
P.transport["quest:4513"] = {
  hash = "715b62",
  fullHash = "715b62",
  text = "A Little Slime Goes a Long Way. Laris Geardawdle seeks pure oozes across Kalimdor. His Felwood-tainted samples showed that oozes absorb and reflect their surroundings. Clean specimens may show him how they adapt to the places they inhabit. Laris Geardawdle needs clean samples for his study. The tainted ones showed how oozes take on the traits of their surroundings, but left him without a clear comparison. He seeks samples untouched by demonic taint or urban filth, so he can study ooze life on its own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4513-029c2dde97149618dd8d/1-0000.mp3", duration = 30.0146939, start = 0},
  },
}
P.transport["quest:452"] = {
  hash = "58ad56",
  fullHash = "58ad56",
  text = "Pyrewood Ambush. In Pyrewood Village, Deathstalker Faerleia waits while Arugal's council keeps the afflicted in line. The Forsaken aim to break his hold on the town and weaken his position in Shadowfang Keep. Deathstalker Faerleia waits in Pyrewood Village's town hall for the local leaders. Archmage Arugal tends his dark sorceries in Shadowfang Keep, leaving the Pyrewood Council to keep order among the afflicted villagers. Faerleia plans to ambush the council. Without its mediation, the Forsaken hope the worgen in the woods and village streets will break free of Arugal's control.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_452-e7f0e71f7bae02c9ded0/1-0000.mp3", duration = 35.3436735, start = 0},
  },
}
P.transport["quest:454"] = {
  hash = "fa14ad",
  fullHash = "fa14ad",
  text = "After the Ambush. Miran needs an escort to carry blasting powder to Loch Modan’s southern excavation site. Dark Iron dwarves ambushed the supply run, and the road is still dangerous. Saean and his conspirators attacked the supply run. Barrels were scattered, and the road became perilous. Huldar remains behind to guard the powder left there. Miran prepares to move ahead with the next load, so the supply line is split. The southern excavation site needs blasting powder to break stone and uncover titan relics. Miran fears another ambush from the ridges. He seeks a companion before loading his cargo and setting out past any traps the Dark Irons may have prepared.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_454-46707fef220be11c8ae9/1-0000.mp3", duration = 41.5608163, start = 0},
  },
}
P.transport["quest:456"] = {
  hash = "522383",
  fullHash = "522383",
  text = "The Balance of Nature. In Shadowglen, Conservator Ilthalaine calls newly awakened night elves to tend Teldrassil’s wildlife. Young nightsabers and thistle boars have grown too numerous, and keeping nature in balance calls for stewardship and difficult choices. Heavy spring rains have disturbed Teldrassil’s young and fragile forest cycle in Shadowglen, beneath the Great Tree’s boughs. Some wildlife populations have grown beyond what the land can sustain. They threaten to strip the glen of resources and bring famine to the ecosystem. Preserving the forest calls for active care. Conservator Ilthalaine watches over Shadowglen’s woods so no part overtakes the others. To prevent mass starvation among the animals, he sends young night elves into the grove to thin thistle boars and predatory nightsabers. The work is unglamorous but vital. Kaldorei stewardship seeks harmony with nature through active balance and difficult decisions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_456-15c5bcec3b097fd0327b/1-0000.mp3", duration = 59.2457143, start = 0},
  },
}
P.transport["quest:457"] = {
  hash = "3296d2",
  fullHash = "3296d2",
  text = "The Balance of Nature. In Shadowglen, Conservator Ilthalaine sends defenders to thin its growing wildlife. Mature thistle boars and mangy nightsabers threaten the glade's balance. Adult animals now threaten Shadowglen and the World Tree's ecosystem. Conservator Ilthalaine sends young defenders deeper into the forest to hunt mature thistle boars and older, mangy nightsabers. Their appetites can exhaust the land's limited plants and game. North of Aldrassil, younger cubs give way to mottled nightsabers and aggressive boars rooting through the soil. For kaldorei, controlled hunting is a grim duty. It protects the whole forest from collapse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_457-cca1821473b561dd8094/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["quest:458"] = {
  hash = "3d8ab2",
  fullHash = "3d8ab2",
  text = "The Woodland Protector. In Shadowglen, Melithar Staghelm hears troubling whispers from the forest spirits. He asks you to seek Tarindrella, whose return to Teldrassil after many years away from Kalimdor’s woodlands hints that something is wrong. Beneath Aldrassil’s boughs, Melithar Staghelm trains novices and listens to troubling omens from the woodland spirits. Tarindrella, a dryad known as a protector of the wild, has returned to Shadowglen after many years away from Kalimdor’s woodlands. Dryads rarely come without cause, so Melithar fears the natural order has fallen out of balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_458-a97e82ee31d9039dd837/1-0000.mp3", duration = 37.1983673, start = 0},
  },
}
P.transport["quest:459"] = {
  hash = "a78125",
  fullHash = "a78125",
  text = "The Woodland Protector. In Shadowglen, Tarindrella seeks the cause of the forest’s unrest and the furbolgs’ disappearance. Grells have grown aggressive, and Fel Moss points to dark magic in Teldrassil’s boughs. Shadowglen’s quiet woods have grown hostile. The furbolgs have left their ancestral dens and gathered as the Gnarlpine tribe. Feral grells and grellkin overrun the woodland paths, and Tarindrella sees the dark change spreading through Teldrassil. Tarindrella suspects corruption is stirring the forest’s creatures. You slay the grells and bring her samples of Fel Moss, proof of dark enchantments clinging to Teldrassil’s boughs. With the corruption confirmed, she sends young defenders to Dolanaar to speak with Druid Athridas Bearmantle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_459-0cd0cc8a201afbbb9a11/1-0000.mp3", duration = 46.837551, start = 0},
  },
}
P.transport["quest:46"] = {
  hash = "673083",
  fullHash = "673083",
  text = "Bounty on Murlocs. In eastern Elwynn, murlocs are spreading, and the Stormwind Army has set a bounty on them. With the garrison stretched thin, Guard Thomas turns to travelers to clear camps around Stone Cairn Lake and the southern waterways before murlocs overrun nearby farms and roads. Murlocs have made camps around Stone Cairn Lake and along the fork of the southern streams. Lurkers and foragers attack travelers and press toward human settlements. What began as a small nuisance now threatens eastern Elwynn, though the western roads remain comparatively secure. Guard Thomas is stationed at the eastern bridge beside the Redridge Mountains. Dangers beyond the bridge and disorder at home both call for his attention. King Varian Wrynn is missing, and bureaucracy weighs on Stormwind's military command. Town garrisons rarely receive the reinforcements they request. So Marshal Dughan and local officers offer public bounties, paying coin for murloc fins to slow the attacks along the waterways.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_46-0f3e715c8531af0d37a0/1-0000.mp3", duration = 60.8914286, start = 0},
  },
}
P.transport["quest:460"] = {
  hash = "5ac568",
  fullHash = "5ac568",
  text = "Resting in Pieces. On Fenris Isle, Alaric's severed head calls for help from beyond the grave. He asks you to carry it across Fenris Keep to an unmarked grave near the stables, where his body lies. At Fenris Keep in Silverpine Forest, Alaric served Thule Ravenclaw as chief servant and personal bodyguard. Thule was a powerful mage aligned with the Scourge. When the Plague of Undeath swept through the region, he promised his sorcery would shield Alaric. Instead, the ward trapped him in endless agony and undeath, while his awareness remained in his severed parts. Thule made the rot hide gnolls by infecting local packs with necromantic decay. Then he turned on his own bodyguard. He cut off Alaric's head and threw it to the savage gnolls as a diversion. The rot hides dragged Alaric's body to a shallow grave they had hastily dug outside the keep's stables. They kept his speaking head as a grim plaything until an outsider intervened.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_460-94a8e9f7ccdb811d4c4b/1-0000.mp3", duration = 59.8987755, start = 0},
  },
}
P.transport["quest:461"] = {
  hash = "34ab5e",
  fullHash = "34ab5e",
  text = "The Hidden Niche. In Fenris Keep, Alaric's memories guide you toward a hidden alcove. His remains point to a place of rest, and an old relic waits there. Alaric remembers Fenris Keep in its better days. Horde scouts lifted his bones from a shallow grave outside the stronghold, but he will not go quietly to the Sepulcher. He offers vital knowledge in return: a hidden niche in the keep's southwestern tower holds an item treasured by Thule Ravenclaw and his fellow mages.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_461-94acc2a66afddef972bf/1-0000.mp3", duration = 29.1526531, start = 0},
  },
}
P.transport["quest:4681"] = {
  hash = "b1f742",
  fullHash = "b1f742",
  text = "Washed Ashore. Along Darkshore's coast, dead sea creatures have drawn Gwennyth Bly'Leggonde into a troubling inquiry. She serves the Temple of the Moon in Darnassus and seeks the cause of the strandings and deaths. Dead sea creatures line Darkshore's beaches and shallows, leaving the night elves of Auberdine puzzled. Gwennyth Bly'Leggonde has already examined one stranded creature on the beach. Now she asks you to dive west of the docks, near a sunken vessel, and inspect the bones of a massive sea turtle. Those remains will help her report to the Temple of the Moon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4681-45a66cc3af3d651a507f/1-0000.mp3", duration = 33.3322449, start = 0},
  },
}
P.transport["quest:47"] = {
  hash = "94e362",
  fullHash = "94e362",
  text = "Gold Dust Exchange. At Goldshire's crossroads, Gold Dust Exchange brings Remy \"Two Times\" coin for gold dust from kobolds in Elwynn's mines. Travelers gather the dust and trade it to the nervous broker for pay. Goldshire sits where Elwynn Forest's roads meet. Travelers, merchants, and guards pass through town. Remy \"Two Times\" is a shady broker with a sharp eye for profit. He repeats his words, and instead of hiring mining crews to dig raw minerals, he offers coin to travelers passing through the Lion's Pride Inn for gold dust taken from kobolds in the region. Kobolds have overrun Fargodeep Mine south of Goldshire and Jasperlode Mine to the northeast. These rat-like tunnelers chip through the dark for candles and shiny baubles, gathering flecks of unrefined ore in their pouches. Driving them back serves the kingdom. Their gold dust also turns the work into a trade for coin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_47-7708b6fba878cdfc320f/1-0000.mp3", duration = 55.5102041, start = 0},
  },
}
P.transport["quest:4722"] = {
  hash = "45daae",
  fullHash = "45daae",
  text = "Beached Sea Turtle. Along Darkshore, a Beached Sea Turtle lies among the surf as murlocs scavenge its remains. Auberdine naturalists seek sound samples to send to Darnassus for study. Dead sea turtles drift ashore along Darkshore’s coast, or beach themselves in confusion. Their remains soon draw scavengers. Greymist murlocs have made crude camps around this turtle’s skeletal frame and carve away its flesh and shell. Yet bone, shell, or tissue may remain intact in the wreckage. Gwennyth Bly'Leggonde works in Auberdine as a field researcher, recording unusual marine life and disturbances along the coast. Night elves regard stranded beasts with reverence and scientific curiosity. Suitable remains are cataloged and prepared for shipment to scholars in Darnassus. They seek to learn why so many giants of the open sea wash ashore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4722-b12e9e96f2a05b8d0d64/1-0000.mp3", duration = 53.1069388, start = 0},
  },
}
P.transport["quest:4723"] = {
  hash = "9dad5f",
  fullHash = "9dad5f",
  text = "Beached Sea Creature. At Mist's Edge, a giant sea thresher lies stranded as murlocs feed on its carcass. In Auberdine, Gwennyth Bly'Leggonde gathers samples for night elf researchers in Darnassus, who seek to learn why deep-sea giants wash ashore. Along Mist's Edge, enormous thresher remains have joined the shipwrecks and debris washed in by the tide. The beast dwarfs the wildlife of Darkshore's shallows. Its size suggests it came from beyond the Veiled Sea, from waters far from the calm waters here. Murlocs swarm over the corpse, but they lack the strength and coordination to bring down such a creature. Something else killed the predator before the sea carried it ashore. In Auberdine, Gwennyth Bly'Leggonde coordinates the salvage of bones and biological samples from Darkshore's stranded sea giants. Night elf researchers in Darnassus hope the remains will show whether illness, disturbances in the deep sea, or arcane corruption drives the giants onto the killing sands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4723-bf643ba8417d16ebba55/1-0000.mp3", duration = 61.6489796, start = 0},
  },
}
P.transport["quest:4725"] = {
  hash = "b92471",
  fullHash = "b92471",
  text = "Beached Sea Turtle. Along Darkshore's shore, a broken carriage rests on the shell of a Beached Sea Turtle. Greymist murlocs gather around the great carcass. You find a broken carriage strapped across a giant sea turtle's shell on Darkshore's misty shore. Many sea creatures have washed up along this coast, but this turtle carried a load. Its handlers drove it onto the beach. Now the carriage lies abandoned in the tide. Greymist murlocs swarm the turtle's remains. They have made a den among the rotting meat and scavenged timber. A marked container lies among their refuse and the broken carriage frame. The turtle's former masters left it there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4725-2aa131a59e7fc3293a0f/1-0000.mp3", duration = 40.2285714, start = 0},
  },
}
P.transport["quest:4727"] = {
  hash = "86edc5",
  fullHash = "86edc5",
  text = "Beached Sea Turtle. Along Darkshore’s northern shore, a Beached Sea Turtle lies untouched by nearby Greymist murlocs. A sample goes to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon. Naturalists and priestesses seek to learn why great sea creatures wash ashore and scavengers leave them alone. Greymist murlocs crowd Darkshore’s northern coast and scavenge food washed up from the Veiled Sea. Yet the great turtle’s bones lie mostly untouched. Those who study the shore wonder whether the murlocs missed it or avoid it for some unknown reason. In Auberdine, Gwennyth Bly'Leggonde gathers samples from beached sea turtles for the Temple of the Moon. The night elf priestesses study disturbances in Darkshore’s waters. Skeletal fragments may help them learn whether sickness, magic, or dangerous sea predators are killing the ancient creatures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4727-d466fcd29a023ab030e9/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["quest:4728"] = {
  hash = "9fb67a",
  fullHash = "9fb67a",
  text = "Beached Sea Creature. Along Darkshore, a giant sea mammal lies washed ashore beside an abandoned dig site. Its carcass and scattered tools draw murlocs and travelers. On Darkshore's sand lies a giant sea mammal, partly gutted and worn by the sea. A rusted wheelbarrow and discarded tools mark where an orderly study began. The researchers left before they could finish. Dwarven field researchers from the Explorer's League were studying the carcass in Darkshore. Their work stopped when local murlocs swarmed the site to scavenge. In Auberdine, Gwennyth Bly'Leggonde acts for the Temple of the Moon. She accepts salvaged bone samples to help study the unnatural wash-ups along the coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4728-06c8b0c9d0e70e9f7777/1-0000.mp3", duration = 44.7738776, start = 0},
  },
}
P.transport["quest:4730"] = {
  hash = "fd9c57",
  fullHash = "fd9c57",
  text = "Beached Sea Creature. Along Darkshore, a great sea mammal lies half-devoured on the sand. Murlocs gather around it, and Priestess Gwennyth Bly'Leggonde in Auberdine seeks bone samples to learn why gentle sea beasts are dying on the shore. Far north along Darkshore's lonely beaches, a great sea mammal lies rotting and half-eaten. Murlocs pick over its bones, more vicious than usual. These beasts were gentle in life, and their deaths trouble the coast as much as the blighted forests inland. Priestess Gwennyth Bly'Leggonde says these gentle mammals live in the waters around Teldrassil's base. Unlike aggressive threshers, they have never been known to drive themselves onto the rocks. The Temple of the Moon is gathering bone samples to learn what corruption or threat drives them from the deep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4730-5db865cd48437d7a0e8d/1-0000.mp3", duration = 50.155102, start = 0},
  },
}
P.transport["quest:4731"] = {
  hash = "726728",
  fullHash = "726728",
  text = "Beached Sea Turtle. Along Darkshore's coast, a Beached Sea Turtle lies dead beneath the carriage it once hauled. A box marked with strange runes rests in the wreckage. A dead sea turtle lies among the ancient bones along Darkshore's coast. Splintered carriage boards cling to its broad shell. It was driven onto the rocks while hauling cargo, not stranded by sickness or confusion. A container carved with unfamiliar, serpent-like marks lies in the wreckage, where scavengers feed on the remains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4731-904a2feba4c4b83ab7c0/1-0000.mp3", duration = 29.9102041, start = 0},
  },
}
P.transport["quest:4732"] = {
  hash = "d2f174",
  fullHash = "d2f174",
  text = "Beached Sea Turtle. Along Darkshore, Beached Sea Turtle remains wash ashore in growing numbers. Their bones give Gwennyth Bly'Leggonde in Auberdine specimens to study as Kalimdor's marine life dwindles. Great sea creatures and turtles lie along Darkshore's shore. Many ancient turtles drift onto the shoals or crawl onto the sand to die. Greymist murlocs gather at the carcasses and strip away the flesh. Soon, only shell and bone remain, beside crude camps they make there. Before the Third War, sea turtles thrived in the sacred waters around Mount Hyjal and the roots of Nordrassil, the World Tree. After Nordrassil's sacrifice against the Burning Legion and Teldrassil's planting off Kalimdor's northern shore, their numbers collapsed.\n\nGwennyth Bly'Leggonde and other priestesses of Elune study the remains for the Temple of the Moon. They seek to learn whether dark magic, changing seas, or the loss of the turtles' ancient sanctuary drives them to their deaths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4732-f38c614478d61372e7ee/1-0000.mp3", duration = 59.6114286, start = 0},
  },
}
P.transport["quest:4733"] = {
  hash = "5f9c5d",
  fullHash = "5f9c5d",
  text = "Beached Sea Creature. A colossal thresher lies stranded on Darkshore's rocky Twilight Shore. Its death and stranding deepen the sea troubles worrying the night elves. Along the Twilight Shore in southern Darkshore, driftwood and sea debris wash into the inlets. In one, you find the remains of an enormous thresher. Tides and scavengers have begun to pick it apart, yet its skeleton dwarfs the ordinary predators in these coastal shallows. The giant does not belong in these waters. Sickness or disorientation may have driven it onto the rocks, or a deeper disturbance may lie in the Veiled Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4733-01c154650a24fc97a148/1-0000.mp3", duration = 34.8734694, start = 0},
  },
}
P.transport["quest:4740"] = {
  hash = "5cd8e2",
  fullHash = "5cd8e2",
  text = "WANTED: Murkdeep!. Auberdine's council wants Murkdeep dead for a Sentinel's death and ships lost off Darkshore. Find the Greymist chieftain south along the coast. Greymist murlocs are usually a nuisance along Darkshore. Murkdeep has turned against Auberdine, and the wanted poster outside the inn names him as the killer of at least one night elf Sentinel. It also suspects him of sabotaging or wrecking two cargo vessels offshore. With ships lost and raids along the coast, the Auberdine Village Council has set a public bounty on their leader. Murkdeep lurks off the southern coast near murloc huts clustered around a bonfire. Trespassers face an organized defense as Greymist coastrunners and shore-crawlers surge from the surf to protect their settlement. Then Murkdeep emerges with his vanguard to strike the intruders. Proof of Murkdeep's death answers the Sentinels' grim need. Sentinel Glynda Nal'Shea handles the council's bounty payout. With Greymist leadership broken, travelers and ships on Darkshore's foggy coast gain a reprieve from sabotage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4740-2a6ab4074110c82b7440/1-0000.mp3", duration = 65.2277551, start = 0},
  },
}
P.transport["quest:475"] = {
  hash = "2b33a3",
  fullHash = "2b33a3",
  text = "A Troubling Breeze. Athridas Bearmantle awaits word from Starbreeze Village, where reports have gone silent. In the Ban'ethil Barrow Den, Great Warden Gaerolas Talvethren watches the sleeping Druids of the Talon, and his silence points to danger in Teldrassil. Athridas Bearmantle relies on regular word from Gaerolas Talvethren, the Great Warden who watches over the Druids of the Talon in the Ban'ethil Barrow Den. The druids sleep there to keep their sacred pact with Ysera in the Emerald Dream. Their sanctuary guards the spiritual balance of the young World Tree. Now reports from the east have ceased, and unease spreads through the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_475-b0453607ecbeabce06b7/1-0000.mp3", duration = 39.1314286, start = 0},
  },
}
P.transport["quest:476"] = {
  hash = "bf2dd6",
  fullHash = "bf2dd6",
  text = "Gnarlpine Corruption. Near Starbreeze Village, Gnarlpine Corruption threatens Teldrassil. Wounded Great Warden Gaerolas Talvethren sends word to Dolanaar. Gnarlpine furbolgs have overrun the village and fallen to demonic corruption. Their violence may reach the sleeping druids of Ban'ethil Barrow Den. Near the ruins of Starbreeze Village, Gaerolas Talvethren lies grievously wounded. His former allies, the Gnarlpine furbolgs, ambushed him. Once peaceful neighbors and stewards of the wild, they have turned feral.\n\nToo badly hurt to carry warning himself, Gaerolas sends you to Athridas Bearmantle in Dolanaar. He fears the madness will spread farther through Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_476-959686c62cdcbe9499eb/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["quest:4761"] = {
  hash = "25c427",
  fullHash = "25c427",
  text = "Thundris Windweaver. In Auberdine, Thundris Windweaver hears that the Blackwood furbolgs have grown hostile. Terenthis sends you with news of their growing aggression, and Thundris seeks the cause of the corruption spreading through Darkshore. You bring Terenthis’s report to Thundris Windweaver in Auberdine after scouting corrupted furbolg camps in Darkshore. Terenthis stays in the wilds to investigate the spreading corruption. As village elder, Thundris watches over daily life and weighs the spiritual and environmental dangers facing the kaldorei. Your report gives Auberdine’s leaders proof that the furbolgs’ troubles reach beyond territory: an unnatural malice is taking hold of them. Thundris has heard that the forest dwellers near Auberdine have grown hostile. Yet the furbolgs are not his only concern. Corruption spreads through Darkshore’s soil, plants, and waters. Thundris believes the land cannot heal until someone finds the source of the blight. So he turns to the waterways and calls on capable allies to trace the taint upstream.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4761-c8e3e4e905d4d4a0245b/1-0000.mp3", duration = 60.9697959, start = 0},
  },
}
P.transport["quest:4762"] = {
  hash = "3242ed",
  fullHash = "3242ed",
  text = "The Cliffspring River. Foul water now runs down the Cliffspring River toward Auberdine. Thundris Windweaver sends Alliance investigators to collect a sample from the pool beneath a road bridge waterfall. He suspects the corruption began beyond the riverbanks. From the eastern highlands, the Cliffspring River runs to the coastal shoals of Mist's Edge, just north of Auberdine. Now its waters carry an unnatural rot toward the night elf settlement. Thundris Windweaver fears the foul water will poison the shores and the town's supplies. So he sends scouts upriver to take samples from the waterfall pool beneath the road bridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4762-0e335874d74056c71a48/1-0000.mp3", duration = 36.7020408, start = 0},
  },
}
P.transport["quest:4763"] = {
  hash = "b67c13",
  fullHash = "b67c13",
  text = "The Blackwood Corrupted. In northern Darkshore, the Blackwood Corrupted are caught in a dark influence. Evidence in the tainted waters of Cliffspring River leads Thundris Windweaver to send you against it. You gather their food and purify it with moonwell water, drawing the demonic handler into the open and breaking his hold on the northern camp. In Auberdine, the night elves have long wondered why the once-peaceful Blackwood furbolgs turned on their neighbors. Their search along Cliffspring River traced the rot to satyr meddling. These ancient servants of the Burning Legion manipulate the tribe with fel magic. Insidious talismans twist the furbolgs' minds and drive them into feral aggression.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4763-95292d6886b9acb25af9/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:477"] = {
  hash = "2346b1",
  fullHash = "2346b1",
  text = "Border Crossings. At the Sepulcher, Shadow Priest Allister sends you after Dalaran's supplies and the reason the Kirin Tor support Ambermill. Their crates pass through Silverpine Forest on the way to a Dalaran camp near Pyrewood Village. Wagons bring Dalaran's supplies and arcane goods from the Hillsbrad Foothills through Silverpine Forest. They serve the outposts and staging grounds along the way. Just north of Pyrewood Village, a camp holds Dalaran personnel who watch the road. Ambermill is the main human stronghold still standing in eastern Silverpine, and Dalaran continues to support it. Shadow Priest Allister and the Forsaken leaders at the Sepulcher want to know why Dalaran gives Ambermill so much support. They suspect the Kirin Tor would not risk lives and supplies deep in Forsaken territory for a provincial town alone. Some greater strategic or magical purpose may be behind it. Intercepting the crates could show the Forsaken what Dalaran is sending west.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_477-1b86174b1e5dcf702442/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["quest:478"] = {
  hash = "ffea80",
  fullHash = "ffea80",
  text = "Maps and Runes. In Silverpine, maps and runes reveal Dalaran's interest in Ambermill. Horde agents recover a hidden crate for Shadow Priest Allister at the Sepulcher. Horde agents find a Dalaran crate hidden along the border routes near Ambermill. Detailed regional charts and a rune-inscribed pendant lie inside. Human sentries stand nearby, so the scouts retrieve the artifact carefully. Dalaran's arcane reach lies close to their borders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_478-8a9e182234c72d23f4c4/1-0000.mp3", duration = 29.1265306, start = 0},
  },
}
P.transport["quest:479"] = {
  hash = "3b0961",
  fullHash = "3b0961",
  text = "Ambermill Investigations. At Ambermill, Dalaran wizards weave magic that threatens the Forsaken’s hold on Silverpine Forest. From the Sepulcher, Shadow Priest Allister sends agents to disrupt their work and seize the magical foci. Ambermill lies in the eastern hills of Silverpine Forest. Its human residents are wizards and defenders pledged to the Kirin Tor of Dalaran. The mages weave powerful magic in a vast ritual. At the Sepulcher, Shadow Priest Allister and his companion Dalar see the danger. If the Kirin Tor channel their power unchecked, the Forsaken risk losing Silverpine entirely. As Dalar scries the forest and traces the magic, Allister sends agents against the practitioners in Ambermill. Dalaran conjurers, mages, and their protectors wear enchanted pendants that focus and coordinate their arts. Take the talismans from slain sorcerers, and the ritual falters. This buys the Sepulcher time to find the ringleader directing the arcane weave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_479-8da0e6ce6183567c0a50/1-0000.mp3", duration = 60.5779592, start = 0},
  },
}
P.transport["quest:481"] = {
  hash = "adffce",
  fullHash = "adffce",
  text = "Dalar's Analysis. In Silverpine, Allister's report sends a Dalaran relic to Dalar for study. A rune-inscribed pendant taken from a supply crate reaches Dalar Dawnweaver at the Sepulcher. The relic shows that Dalaran's surviving mages are gathering great magical power for a hidden purpose. A supply crate from Dalaran is raided at a camp north of Pyrewood Village. Beneath old maps, Shadow Priest Allister finds a rune-inscribed pendant. Its enchantment is beyond his spiritual knowledge, so he sends it to Dalar Dawnweaver at the Sepulcher. Dalar's skill as an arcane scholar makes him better suited to read Dalaran's magical warding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_481-8da904160e5e5a78780b/1-0000.mp3", duration = 39.5232653, start = 0},
  },
}
P.transport["quest:4811"] = {
  hash = "bcf3b3",
  fullHash = "bcf3b3",
  text = "The Red Crystal. Sentinel Glynda Nal'Shea asks you to investigate a red crystal in Darkshore's eastern mountains. Moonkin are multiplying nearby and seem drawn to it, and the Sentinels need to know whether the crystal is real. Moonkin were once gentle, mystical creatures bound to Kalimdor's wilds. Now aggressive packs multiply along the slopes east of Auberdine. Some night elves still revere them, but Sentinel Glynda Nal'Shea puts the town's safety first as danger grows. Reports point to a single spot among the eastern peaks. Scouts and wanderers speak of an unnatural red crystal jutting from a rocky hillside high above Darkshore. Rumors travel easily along the fogbound coast, so Glynda wants you to see the place for yourself. The crystal is real. The Sentinels still need to learn why moonkin gather there and whether it threatens the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4811-cacb10133b75b80632d7/1-0000.mp3", duration = 52.6889796, start = 0},
  },
}
P.transport["quest:4812"] = {
  hash = "aeff8f",
  fullHash = "aeff8f",
  text = "As Water Cascades. At Auberdine, Sentinel Glynda Nal'Shea hopes moonwell water will reveal what lies beneath Darkshore's red crystal. Sacred water may pierce its opaque surface. Sentinel Glynda Nal'Shea seeks a safe way to study the red crystal high on Darkshore's eastern cliffs. Moonwell water bears divine, restorative magic, blessed by the night elves' devotion to Elune. Glynda believes water from Auberdine's moonwell may react with the strange stone and pierce its opaque shell without destroying it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4812-f1d5d6514b8673c6af21/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["quest:4813"] = {
  hash = "b2399e",
  fullHash = "b2399e",
  text = "The Fragments Within. At the eastern cliffs, you return to the red crystal with water from a moonwell. It may reveal what lies within, and you carry the finding back to Sentinel Glynda Nal'Shea in Auberdine. Back in Auberdine, you tell Sentinel Glynda Nal'Shea what you found. The discovery gives the local night elf leaders more cause for concern, but no clear answers. Glynda will present the findings to the town council. The crystal rests high on the eastern cliffs, far enough from town to bring her some comfort; it poses no immediate danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4813-5ee4d3ba0bfd9f95cf24/1-0000.mp3", duration = 33.0187755, start = 0},
  },
}
P.transport["quest:482"] = {
  hash = "766f4f",
  fullHash = "766f4f",
  text = "Dalaran's Intentions. In Silverpine Forest, Dalar Dawnweaver sends Shadow Priest Allister a warning. A pendant bound for the Kirin Tor in Ambermill reveals their plan to awaken a dormant ley energy node beneath the town. At the Sepulcher, the Forsaken prepare to answer. Dalar Dawnweaver studies a rune-inscribed pendant from a Dalaran supply crate. It recalls an old Kirin Tor survey of Ambermill. The quiet village was chosen for a reason: it sits atop a dormant ley energy node. Dalar realizes the wizards intend to tap its power.\n\nAwakening such a nexus takes immense magical reserves. The enchanted pendants the wizards wear are key to channeling and catalyzing that power. The Forsaken cannot abide a fortified Kirin Tor outpost fueled by ley energy. It would threaten the southern approaches to the Sepulcher and Tirisfal Glades. Whatever ritual the magi prepare, raw ley energy would give Dalaran an enormous strategic advantage in Lordaeron.\n\nSo Dalar urgently sends word to Shadow Priest Allister. He asks Allister to devise a way to stall the wizards before their ritual is complete.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_482-e5e758376ca75ea8fbac/1-0000.mp3", duration = 73.7436735, start = 0},
  },
}
P.transport["quest:483"] = {
  hash = "bfd1af",
  fullHash = "bfd1af",
  text = "The Relics of Wakening. At Ban'ethil Barrow Den, danger closes around the sleeping Druids of the Talon. Corrupted Gnarlpine furbolgs have overrun the sacred mounds, while the druids' spirits wander the Emerald Dream. Four ritual relics are needed to bring the sleepers safely back to the waking world. West of Dolanaar, corrupted Gnarlpine furbolgs have overrun the winding corridors of Ban'ethil Barrow Den. Barrow dens are secluded sanctuaries where night elf druids hibernate while their spirits walk the Emerald Dream. A foul taint spreading across Teldrassil has driven these former allies mad. The furbolgs have desecrated the sanctum, while the sleepers remain unaware that danger threatens their bodies. Athridas Bearmantle needs four sacred relics for the delicate ceremony that can safely awaken the Druids of the Talon. A druid's spirit needs an anchor when returning from the Dream. Without one, sudden awakening can shatter the mind or strand the spirit. The relics lie in chests across the den: the Raven Claw Talisman, the Black Feather Quill, the Sapphire of Sky, and the Rune of Nesting. They are the sleepers' only hope before the Gnarlpine butcher or abduct them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_483-6db2d2ca0776e2dac9ef/1-0000.mp3", duration = 74.997551, start = 0},
  },
}
P.transport["quest:486"] = {
  hash = "a04c90",
  fullHash = "a04c90",
  text = "Ursal the Mauler. In Teldrassil, Athridas Bearmantle seeks to rouse the Druids of the Talon from an unnatural sleep. Their kin are trapped in the Barrow Den, and Ursal the Mauler's corruption must be broken. The Druids of the Talon went to the Barrow Den of Ban'ethil to sleep and commune with the Emerald Dream. Their peaceful trance became a prison, with no path back to waking. Athridas Bearmantle traced the trouble to the gnarlpine furbolgs and their vicious leader, Ursal the Mauler. Ursal meddled with the druids' sacred rite, leaving them caught between waking and the Dream. The Relics of Wakening alone cannot carry Athridas through the spiritual fog to the druids. The source of the interference must end. Ursal the Mauler lairs in Gnarlpine Hold, home to the tribe in far southwestern Teldrassil. Slaying the furbolg warlord breaks his hold on the sleepers' minds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_486-5e3411353249a081b69d/1-0000.mp3", duration = 56.7640816, start = 0},
  },
}
P.transport["quest:487"] = {
  hash = "af2954",
  fullHash = "af2954",
  text = "The Road to Darnassus. Travelers on Teldrassil’s western road face attacks from corrupted Gnarlpine furbolgs. Moon Priestess Amara coordinates scouts and travelers to keep the route from Dolanaar to Darnassus clear for trade and messages. You travel west from Dolanaar toward Darnassus on Teldrassil’s main road. Goods, political messages, and travelers pass this way each day, linking the capital with the boughs of the great tree. Teldrassil is young and wild, so its kaldorei communities depend on safe roads. The Gnarlpine furbolgs have been driven mad by a sickness in the boughs of the World Tree. They attack from dens beneath the ridges. Along the road, ambushers stalk the tree line and prey on couriers and travelers, making the passage through the forest deadly. Moon Priestess Amara watches over the road outside Dolanaar. She joins the spiritual authority of Elune’s priesthood with the Sentinels’ vigilance. Amara directs capable travelers to strike at ambushers near their dens below the road. The route to Darnassus’s gates depends on keeping them at bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_487-1ce2de2317fbddd6f34d/1-0000.mp3", duration = 69.1461224, start = 0},
  },
}
P.transport["quest:488"] = {
  hash = "158980",
  fullHash = "158980",
  text = "Zenn's Bidding. Zenn Foulhoof draws newcomers into his schemes north of the road from Shadowglen to Dolanaar. The solitary satyr asks them to gather animal parts, counting on their trust and inexperience. Travelers on the path from Shadowglen to Dolanaar may find Zenn Foulhoof beneath the Great Tree. He offers material rewards and secrets in return for simple work. From the surrounding woods, he asks for nightsaber fangs, strigid owl feathers, and webwood spider silk. Then he whispers that their bargain should stay between them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_488-eafaef9ec84acda7916a/1-0000.mp3", duration = 32.5485714, start = 0},
  },
}
P.transport["quest:489"] = {
  hash = "eaa72c",
  fullHash = "eaa72c",
  text = "Seek Redemption!. In Dolanaar, the Council of the Forest demands that you make amends. Adventurers were tricked into doing Zenn Foulhoof's bidding, and the council now sends you to fool him into eating corrupted fel cones. Just outside Dolanaar, the solitary satyr Zenn Foulhoof tricks passersby into doing his bidding. Adventurers who unknowingly killed nightsabers, strigid owls, and webwood spiders to satisfy his twisted appetites have drawn the Council of the Forest's sharp disapproval. The council will not accept harm to nature, least of all from its own allies. Syral Bladeleaf, Sentinel Kyra Starsong, or Sentinel Shayla Nightbreeze warns you to make amends if you wish to remain welcome in Teldrassil. Dolanaar's guardians tell you to turn Foulhoof's wicked gluttony against him instead of meeting him with steel. Gather the billowing, corrupted fel cones from the forest floor, then offer the unsuspecting satyr a taste of his own foul medicine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_489-87029e745025d40b0f89/1-0000.mp3", duration = 58.9322449, start = 0},
  },
}
P.transport["quest:491"] = {
  hash = "eb8bc2",
  fullHash = "eb8bc2",
  text = "Wand to Bethor. At Fenris Keep, the Woven Wand is bound for Bethor Iceshard in the Undercity. Three apprentice mages made it as a sign of fellowship, but Thule Ravenclaw hid it after choosing the Scourge. Its return brings a piece of Bethor's mortal youth back to the Magic Quarter. Before Lordaeron fell, three young mages joined their training wands into one: the Woven Wand. It marked their friendship and their shared hopes in the magical arts.\n\nThen Thule Ravenclaw gave his loyalty to the Lich King and embraced the Scourge. Their fellowship was broken. He came to despise the friendship they had shared, yet could neither destroy the wand nor leave it with his former companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_491-44221b4bd4dcddd090ab/1-0000.mp3", duration = 42.997551, start = 0},
  },
}
P.transport["quest:492"] = {
  hash = "f13738",
  fullHash = "f13738",
  text = "A New Plague. In Brill, A New Plague faces its first test on a captive dwarf. Apothecary Johaan sends you to the cellar of Gallows' End Tavern with the brew he made from reagents gathered across Tirisfal Glades. Apothecary Johaan has brought his research to a dangerous trial. The Royal Apothecary Society serves Lady Sylvanas Windrunner, seeking a plague that kills the living while leaving undead bodies unharmed. Johaan has brewed what he calls a “special drink.” He sends you to give it to an imprisoned enemy of the Forsaken. In Brill, the Deathguard keeps captives in a damp cellar beneath Gallows' End Tavern. They await interrogation or disposal. One prisoner is a Dwarven Mountaineer, an Ironforge scout caught trespassing in Tirisfal Glades. Defiant and thirsty, he eagerly accepts the drink, unaware of what Johaan mixed into it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_492-4758b7c23aec9788fc3d/1-0000.mp3", duration = 53.3159184, start = 0},
  },
}
P.transport["quest:5041"] = {
  hash = "f9f40f",
  fullHash = "f9f40f",
  text = "Supplies for the Crossroads. Thork needs supplies back at the Crossroads after Razormane quilboar raids. The stolen crates carry provisions the outpost needs as conflict spreads across the Barrens. Thork needs provisions returned to the Crossroads after a supply caravan is ambushed. The outpost links Horde travel, trade, and defense across the Barrens. Its cargo comes from Durotar and Mulgore. Without those goods, shortages of provisions, tools, and arms threaten daily life in the harsh wilderness. Razormane quilboar have taken the crates. These swine-beasts contest Horde control across central Kalimdor. They hauled the cargo to their thorn-bush camps and keep it there. Thork sends trusted warriors into Razormane territory to recover supplies for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5041-333f99d95198601e7514/1-0000.mp3", duration = 47.2293878, start = 0},
  },
}
P.transport["quest:5061"] = {
  hash = "9870fa",
  fullHash = "9870fa",
  text = "Aquatic Form. You bring the restored Pendant of the Sea Lion back to Darnassus. The rite teaches Alliance druids to attune their spirits to deep waters. For Cenarion Circle initiates, shapeshifting binds a druid’s spirit to the wild aspects of Azeroth. Young night elf druids endure trials in the dark coastal depths and in Moonglade. There, Dendrite Starblaze gives them the assembled Pendant of the Sea Lion. They carry this sacred token back to Teldrassil, proof of their respect for the laws of air, water, and breath. Mathrengyl Bearwalker awaits your return in the Cenarion Enclave. Your trials along the coasts of Darkshore and Westfall have tested your endurance and attunement. Present the completed pendant to show Bearwalker that your mind and body are ready to shed their mortal skin. Then you can take the swift, breathing form of the sea lion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5061-6da5a2b1faff1b37f389/1-0000.mp3", duration = 51.6963265, start = 0},
  },
}
P.transport["quest:52"] = {
  hash = "b01176",
  fullHash = "b01176",
  text = "Protect the Frontier. At Elwynn's eastern bridge, Guard Thomas asks you to thin the wolves and bears threatening travelers and workers near Eastvale Logging Camp. The beasts have grown bold, putting roads and logging crews at risk. Goldshire and Northshire Valley have visible Stormwind garrisons. The eastern frontier has far fewer guards. Guard Thomas watches the river crossing, one of the few sentries between the settled heartlands and the wilderness. Travelers help keep the supply roads open. Eastvale Logging Camp sends timber to Stormwind City. Woodsmen cutting trees at the forest's edge face prowlers, gray forest wolves, and young forest bears near the roads and lumber yards. Culling the beasts eases the danger to local workers for a time. Thomas suspects something deeper in the woods is driving them toward settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_52-2ee031a6e73baa31b885/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:5261"] = {
  hash = "d6ce80",
  fullHash = "d6ce80",
  text = "Eagan Peltskinner. Timber wolves threaten Northshire Valley, and Eagan Peltskinner has work for recruits outside the abbey. The local furrier needs hunters to thin the packs and bring back pelts. Deputy Willem often sends abbey recruits to find Eagan Peltskinner on the nearby grounds. Northshire Valley's orchards and fields meet wild woods where timber wolves prowl. Eagan asks newcomers to hunt the aggressive packs and gather pelts for his craft. Timber wolves threaten workers, acolytes, and supplies traveling to and from Northshire. Sending young champions to Eagan helps keep nearby paths safe and leaves Stormwind's few remaining guards free for other duties. Those guards are already occupied by rising tensions across Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5261-08baa850204f0f8e63f0/1-0000.mp3", duration = 46.1061224, start = 0},
  },
}
P.transport["quest:543"] = {
  hash = "98b65c",
  fullHash = "98b65c",
  text = "The Perenolde Tiara. Count Remington Ridgewell sends mercenaries into the Ruins of Alterac for a lost heirloom. The Perenolde Tiara once adorned Alterac's royal family and now rests with an ogre mage. Alterac's royal family wore an emerald-set tiara made by master dwarven jewelers in Ironforge. During the Second War, King Aiden Perenolde betrayed the Grand Alliance and joined the Orcish Horde. Alterac was conquered and collapsed. When Alterac City fell, many royal treasures vanished among the snowy rubble of the Alterac Mountains. Grel'borg the Miser, an ogre mage among the Crushridge ogres, holds the tiara in the ruins. He searches the broken stones for baubles and abandoned wealth. Count Remington Ridgewell, a collector of historical oddities in Stormwind City, learns the tiara survived. He hires mercenaries to enter ogre-held territory, defeat Grel'borg, and return the jewel to his gallery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_543-555479ea65e9b746214e/1-0000.mp3", duration = 58.5142857, start = 0},
  },
}
P.transport["quest:5481"] = {
  hash = "e0ceff",
  fullHash = "e0ceff",
  text = "Gordo's Task. Along the road to Brill, Gordo gathers plants for the Royal Apothecary Society. His clumsy hands make the work too fine, so he asks travelers to gather Gloom Weed for Junior Apothecary Holland. Between Deathknell and Brill, Gordo trudges through the countryside on the Royal Apothecary Society's behalf. Abominations can fight with brute strength and carry heavy loads, but their huge, stitched hands struggle with delicate work. Sent to gather ingredients in the meadows, Gordo crushes more stems than he plucks. So he turns to passersby, bullying or bribing them to do the careful work for him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5481-969f159ac91086d695bb/1-0000.mp3", duration = 38.3216327, start = 0},
  },
}
P.transport["quest:5482"] = {
  hash = "ab9f31",
  fullHash = "ab9f31",
  text = "Doom Weed. In Brill, Junior Apothecary Holland seeks doom weed for his research. The plant grows by Tirisfal's northern mass graves, where Rot Hide gnolls prowl. Junior Apothecary Holland studies alchemy in Brill for the Royal Apothecary Society. He wants doom weed for his experiments, but Gordo cannot tell one plant from another. So Holland asks capable hands to gather what he needs. Doom weed grows around the mass gravesite just north of the Brill graveyard. Death and plague have tainted the soil there. Rot Hide gnolls prowl the burial mounds, scavenging among the remains and guarding the overgrown trenches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5482-55609446704085fb4d60/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["quest:5502"] = {
  hash = "3c93c9",
  fullHash = "3c93c9",
  text = "A Warden of the Horde. In Orgrimmar, Grunth returns to Orphan Matron Battlewail as Children's Week ends. After seeing the world with you, the young orphan hopes to become a hero himself. After your travels together, Grunth thanks you for showing him more than he ever dreamed he would see. He recalls his parents' advice to rise above hardship and hopes to become a hero like you. Now he asks to return home and tell the matron about your time together. You bring Grunth back to Orphan Matron Battlewail at the orphanage in the Valley of Honor. In the new Horde, caring for the young is a solemn duty, for war has left countless children without parents. Battlewail praises your compassion as the true measure of a Horde hero. Grunth gives you a beloved pet so you will remember the bond formed on your travels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5502-fb624c7a458febe34424/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["quest:5541"] = {
  hash = "f9383e",
  fullHash = "f9383e",
  text = "Ammo for Rumbleshot. Outside Anvilmar, Hegnar Rumbleshot needs ammunition for the riflemen at practice. A courier fled wendigo near the Grizzled Den and left a crate behind. Loslor Rudge at Steelgrill's Depot supplies tradesmen across Dun Morogh, though wildlife often disrupts his shipments. His courier had camped near the Grizzled Den cave system when local wendigo crossed his path. He fled for his life and left the heavy wooden crate in the snow. Hegnar Rumbleshot runs a gun shop beside the main road leading away from Anvilmar. Ironforge riflemen, mountaineers, and dwarven mortar squads gather in the clearing outside his forge to sight their weapons and practice with live fire. Without regular deliveries of powder and lead from suppliers like Loslor, the riflemen's marksmanship practice soon comes to a halt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5541-5451f25608a79fc3f67b/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["quest:5545"] = {
  hash = "5d73d7",
  fullHash = "5d73d7",
  text = "A Bundle of Trouble. At Eastvale Logging Camp, Supervisor Raelen races to meet a timber shipment deadline for Stormwind. Wolves and bears have driven her woodcutters from the northern woods, leaving the cut bundles behind. Eastvale's timber rebuilds towns and strengthens bridges across the kingdom, yet this vital shipment has fallen behind. The delivery deadline is drawing near, and Supervisor Raelen has little time to spare. North of the camp, wolves and bears drove the woodcutters from the bundles they cut and tied. Raelen cannot wait for guards to clear the woods, so she asks you to bring the timber back before the contract is lost.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5545-b3dba8723e94c6d8d679/1-0000.mp3", duration = 39.0008163, start = 0},
  },
}
P.transport["quest:5621"] = {
  hash = "58b3da",
  fullHash = "58b3da",
  text = "Garments of the Moon. In Dolanaar, Laurna Morninglight sends a young priest to aid a wounded Sentinel south of town. The duty tests an initiate's devotion and earns formal recognition in the Sisterhood of Elune. The Sisterhood of Elune guides kaldorei in worship and helps guard Teldrassil's borders. Sentinel Shaya was wounded while patrolling the wilds south of Dolanaar, and priest trainer Laurna Morninglight cannot leave her post to help. So she asks a newly trained initiate to tend Shaya's wounds and strengthen her with protective magic. After restoring Sentinel Shaya's vigor, you return to Dolanaar and receive formal robes of office from Laurna Morninglight. The robes mark an acolyte's passage from lessons to practical service that can save lives. For the kaldorei, aiding the Sentinels serves Elune and helps keep Teldrassil safe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5621-a29f6772ad19f24a333d/1-0000.mp3", duration = 51.9836735, start = 0},
  },
}
P.transport["quest:5622"] = {
  hash = "e03120",
  fullHash = "e03120",
  text = "In Favor of Elune. In Shadowglen, young night elf priests set out for guidance and training in Dolanaar. Priestess Shanda sends them along the forest path to Laurna Morninglight. Priestess Shanda trains initiates who serve Elune in Aldrassil's secluded shelter. Under her eye, they begin with simple prayers and spells of defense. Yet Shadowglen's quiet life cannot prepare them for the turmoil beyond the glade. Once an initiate shows steady faith and discipline, Shanda sends them down the forest path to Dolanaar for further teaching. In Dolanaar, a young night elf takes an important step in the service of Elune. Priestess Laurna Morninglight prepares her disciples for the trials facing Teldrassil. There, an acolyte can learn more advanced moonlit spellcraft and receive formal vestments. Those robes mark their place in the Sisterhood of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5622-7959409e7bc72ae2dffd/1-0000.mp3", duration = 50.3118367, start = 0},
  },
}
P.transport["quest:5623"] = {
  hash = "63e87b",
  fullHash = "63e87b",
  text = "In Favor of the Light. At Northshire Abbey, Priestess Anetta sends you south to continue your training in Goldshire. Priestess Josetta waits at the Lion's Pride Inn to guide your next steps in the Holy Light. Your training carries you beyond Northshire Abbey's cloistered halls and into the lives of Elwynn's people. You leave secluded study for active ministry, where the Holy Light must answer everyday needs beyond the abbey's walls. At the Lion's Pride Inn, Priestess Josetta tends to Goldshire's spiritual needs and guides rising acolytes. She builds on your lessons and teaches you to offer comfort, protect the faithful, and heal the injured. Under her guidance, you learn the duties of the Church's servants across the kingdom, including caring for a wounded guard and receiving ceremonial clerical vestments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5623-e4825d8e1b44703bd10d/1-0000.mp3", duration = 48.3787755, start = 0},
  },
}
P.transport["quest:5624"] = {
  hash = "797da4",
  fullHash = "797da4",
  text = "Garments of the Light. Priestess Josetta sends you east of Goldshire to Crystal Lake, where Guard Roberts lies wounded. His recovery matters to the town, and the Church of the Holy Light will recognize your service. Josetta asks you to put divine power to use before the Church recognizes a novice priest. Guard Roberts needs healing, giving you a chance to serve someone in need. Tending him is your first step toward formal standing in the Church of the Holy Light. Close Roberts's wounds with restorative prayers, then strengthen him with a blessing of fortitude. He needs healing and resilience to return to his duties. Your care helps a town guard withstand danger, and supports the township. Josetta expects a priest to sustain defenders as well as mend them. Once Roberts has been treated, return to the Lion’s Pride Inn for your first formal robes. They mark the approval and fellowship of Stormwind's priesthood, though further training does not require them. The Church recognizes you as a servant of the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5624-f4f993b25eab8918842d/1-0000.mp3", duration = 59.5330612, start = 0},
  },
}
P.transport["quest:5625"] = {
  hash = "df9b09",
  fullHash = "df9b09",
  text = "Garments of the Light. At Maxan Anvol’s urging, you go south of Kharanos to help a wounded mountaineer before you receive the Garments of the Light. Maxan Anvol, the priest trainer, asks for practical aid before ceremony. Acolytes usually face formal trials to prove they deserve church vestments. But Mountaineer Dolf is wounded, and he needs help now. South of Kharanos, you find Mountaineer Dolf wounded in the line of duty. Restorative prayers mend his injuries. Power Word: Fortitude strengthens him and helps keep an Ironforge defender alive. Once Dolf has received aid, Maxan Anvol presents you with formal garments. The robes give warmth against Dun Morogh’s chill and mark you as a servant of the Light. You are ready to aid wounded wanderers and local guards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5625-6825da927f41d35fd00c/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["quest:5626"] = {
  hash = "081556",
  fullHash = "081556",
  text = "In Favor of the Light. Branstock Khalder sends a young priest from Coldridge Valley through the mountain pass to Kharanos for further study. There, Priest Trainer Maxan Anvol prepares the novice for greater duties and a chance to earn their first formal vestments. You leave Anvilmar after showing dedication and understanding of Holy magic. Branstock Khalder sends promising novices beyond the mountains, where priests meet Dun Morogh’s needs and help defend its people. The Coldridge Pass tunnel opens into central Dun Morogh, where Priest Trainer Maxan Anvol guides you beyond basic prayers. He teaches that service to the Holy Light calls for moral character, physical hardiness, and an unyielding will. Prove your resolve under his guidance, and you may receive your first formal garments of office.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5626-53cb37617e23d3983876/1-0000.mp3", duration = 48.5093878, start = 0},
  },
}
P.transport["quest:5627"] = {
  hash = "25dc80",
  fullHash = "25dc80",
  text = "Stars of Elune. At the Temple of the Moon in Darnassus, night elf acolytes answer the Sisterhood of Elune's summons. Their devotion has earned them sacred instruction in their faith. Night elf priests draw their holy power from Elune, their goddess. Humans and dwarves turn to the Light. When an acolyte serves the realm with steadfast devotion, the Sisterhood in Darnassus takes notice. The acolyte is summoned to the Temple of the Moon and judged ready for deeper communion.\n\nThere, the priest learns sacred spells passed down through thousands of years of worship. Priestess Alathea calls the initiate to learn the holy mysteries of the night elf faith, including Starshards. These spells channel the radiant wrath and grace of the White Lady. The teaching carries an acolyte beyond basic training, ready to venture beyond Teldrassil's protective canopy in Elune's name.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5627-b1e0a8952d5586f35ab7/1-0000.mp3", duration = 54.517551, start = 0},
  },
}
P.transport["quest:5628"] = {
  hash = "54a37e",
  fullHash = "54a37e",
  text = "Returning Home. In Goldshire, a novice night elf priest hears an urgent call from Darnassus. Priestess Josetta carries the message: return to the Temple of the Moon and continue training under Priestess Alathea. Night elves are rare in Elwynn Forest, and a young acolyte among its human settlements draws attention. When you reach Goldshire, Priestess Josetta greets you with news. A Sister of Elune has traveled across continents seeking you, bearing an urgent command from the Temple of the Moon. Your calling now leads back to Kalimdor, where your training can advance. Darnassus looks to the Temple of the Moon for night elf faith and leadership. Priestess Alathea and High Priestess Tyrande Whisperwind oversee the Sisterhood’s instruction, keeping watch over disciples even when curiosity carries them overseas. When you return, the priestesses welcome you with motherly concern. Then they begin your deeper studies of the Moon Goddess’s celestial mysteries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5628-47f6eb5163117f540c29/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["quest:5629"] = {
  hash = "2cd7f1",
  fullHash = "2cd7f1",
  text = "Returning Home. Young night elf priests are summoned to Darnassus in Returning Home. After serving in Teldrassil’s wilds, they are called to the Temple of the Moon to meet Priestess Alathea and High Priestess Tyrande Whisperwind. Around Dolanaar, priests tend the wounded and cleanse corruption. Their service draws the Sisterhood of Elune’s notice. Trainer Laurna Morninglight brings promising initiates word that Priestess Alathea has asked to meet them. Aid to local settlements matters, yet each devotee must also deepen their communion with the Moon Mother and answer the faith’s higher calling. From Teldrassil’s boughs, the road leads to the Temple of the Moon in Darnassus. Elune’s gentle glow fills the sanctuary above the city. It is the kaldorei’s chief house of worship and spiritual capital. An invitation into its halls marks an initiate’s recognition by the priesthood’s leaders, no longer only a young student. Priestess Alathea warmly greets the returning initiates. She says she and High Priestess Tyrande Whisperwind take pride when initiates venture into the uncertain world and return unharmed. This homecoming opens deeper sacred trials under Alathea’s direct guidance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5629-e9478af4110d095b870e/1-0000.mp3", duration = 74.4228571, start = 0},
  },
}
P.transport["quest:5630"] = {
  hash = "319396",
  fullHash = "319396",
  text = "Returning Home. In Dun Morogh, a summons calls night elf priests back to Darnassus. Maxan Anvol sends them to Priestess Alathea at the Temple of the Moon. In Kharanos, Maxan Anvol sees a night elf endure Dun Morogh's bitter cold, far from Teldrassil's serene forests. The dwarven priest trainer brings urgent news. A priestess of Elune passed through seeking you with orders from Darnassus. They call you back at once. Your road leads across the sea to the Temple of the Moon in Darnassus, beneath Teldrassil's sacred boughs. Priestess Alathea welcomes you back to the Sisterhood of Elune, relieved that you returned safely from foreign lands. She prepares your next rites of devotion, beginning with the Stars of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5630-7a71884fb92a240518d7/1-0000.mp3", duration = 47.1771429, start = 0},
  },
}
P.transport["quest:5631"] = {
  hash = "020fb3",
  fullHash = "020fb3",
  text = "Returning Home. A summons brings a night elf priest from human lands back to Teldrassil. Brother Joshua carries Priestess Alathea’s call to the Temple of the Moon in Darnassus, where the young priest will receive advanced guidance in Elune’s mysteries. Night elf priests sometimes travel to human lands like Stormwind to share fellowship with the Church of the Holy Light. Their strongest ties remain with the Sisterhood of Elune. Brother Joshua tells you that a night elf emissary has come searching for you. Your early travels are over, and your home temple calls you back for deeper training with High Priestess Tyrande Whisperwind’s inner circle. Across the sea, the Temple of the Moon in Darnassus welcomes you home. Priestess Alathea greets you warmly and celebrates your safe passage through a troubled world. Your return brings joy to Alathea and Tyrande. More demanding spiritual trials await.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5631-777e0cb56fbd74f7793e/1-0000.mp3", duration = 54.9093878, start = 0},
  },
}
P.transport["quest:5632"] = {
  hash = "9b101f",
  fullHash = "9b101f",
  text = "Returning Home. Priestess Alathea calls promising night elf priests back to Darnassus. At the Temple of the Moon, the Sisterhood of Elune will recognize them and guide their next steps. A messenger from the Sisterhood finds you while you visit Nara Meideros in Stormwind's Park. You have served your people abroad, and now the order's leaders call you back to Darnassus. They have watched your spiritual growth and summon you for an evaluation and a rite of recognition. This journey marks your passage from new initiate to active servant of the Mother Moon. The summons brings you to Priestess Alathea at the Temple of the Moon, Darnassus's highest sanctuary. High Priestess Tyrande Whisperwind oversees the Sisterhood, which watches over its members wherever they serve. Your safe return honors your community and Elune. It also shows how the goddess's grace has guided and preserved you through your early trials in the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5632-0f53b7c53bcdef8d5c1c/1-0000.mp3", duration = 56.7118367, start = 0},
  },
}
P.transport["quest:5633"] = {
  hash = "220a56",
  fullHash = "220a56",
  text = "Returning Home. Night elf priests in Ironforge are being summoned back to the Temple of the Moon in Darnassus. A Sisterhood emissary seeks acolytes abroad and sends them to Priestess Alathea for further training and sacred duties. In Ironforge, night elf priests remain bound to the Sisterhood of Elune, though Teldrassil lies far away. Braenna Flintcrag, a dwarven priest trainer in the Mystic Ward, bears a message from a visiting night elf priestess. The emissary sought young disciples traveling abroad and said their mentors needed them back in the capital at once. At the Temple of the Moon in Darnassus, returning acolytes report to Priestess Alathea. Beneath the gaze of High Priestess Tyrande Whisperwind, Alathea welcomes her student and is relieved they crossed the seas safely. Their return begins further devotion and sacred duties, including the Stars of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5633-0aa3485e42bbef63c713/1-0000.mp3", duration = 55.0661224, start = 0},
  },
}
P.transport["quest:5634"] = {
  hash = "070a97",
  fullHash = "070a97",
  text = "Desperate Prayer. At Stormwind's Cathedral of Light, High Priestess Laurena teaches human acolytes a prayer for when their lives are in danger. It calls on the Holy Light to heal a priest's wounds when all else fails. Priests of the Cathedral of Light use their faith to shield companions, heal wounds, and strike at evil. Even the devout may be isolated, cornered, or close to death. In that moment, an acolyte can call to the Holy Light for help, with their own life at stake. High Priestess Laurena guides the clergy in Stormwind's Cathedral Square and decides when an acolyte is ready for deeper teachings. Human initiates who show devotion to the Light across the kingdom receive this lesson as protection and as a charge to keep serving the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5634-457dc9c3112f6686e871/1-0000.mp3", duration = 46.7591837, start = 0},
  },
}
P.transport["quest:5635"] = {
  hash = "fae88d",
  fullHash = "fae88d",
  text = "Desperate Prayer. In Stormwind, promising priests from Elwynn Forest come for deeper training in the Church of the Holy Light. After proving their devotion and discipline, they present themselves to High Priestess Laurena at the Cathedral of Light. Priestess Josetta guides novice priests in Goldshire, while local mentors serve Elwynn Forest's outlying settlements. When a disciple proves capable in spirit and deeds, word reaches Stormwind's senior priesthood. A summons to the Cathedral of Light marks a move to deeper duties in the faith and formal training at the spiritual heart of the Kingdom of Stormwind. At the Cathedral, acolytes come before High Priestess Laurena, a senior leader of the Church in Stormwind. She oversees their spiritual grounding and practical training as newly elevated priests. Her instruction prepares them for the Alliance's harsh trials and teaches the Light's miracles, including Desperate Prayer, a plea for salvation known among human practitioners.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5635-c56cd965b3856c8c4a2b/1-0000.mp3", duration = 58.6710204, start = 0},
  },
}
P.transport["quest:5636"] = {
  hash = "1de298",
  fullHash = "1de298",
  text = "Desperate Prayer. In Dolanaar, word from home calls human priests back to Stormwind for further training. A fellow priest has crossed continents to summon them to the Cathedral of Light. In Dolanaar, Priestess Laurna Morninglight brings you a message from home. A fellow priest has crossed continents to find you, so Laurna urges you to return without delay. She offers Elune’s blessing and good wishes for your faith as you leave Teldrassil. Your road leads across the Great Sea to the Cathedral of Light in Stormwind City. High Priestess Laurena guides the Alliance faithful in their spiritual growth. She summons promising acolytes to deepen their devotion and learn Desperate Prayer, an emergency prayer that can save a life in its darkest hour.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5636-87b1d8bb03ffbf475239/1-0000.mp3", duration = 45.322449, start = 0},
  },
}
P.transport["quest:5637"] = {
  hash = "546bdc",
  fullHash = "546bdc",
  text = "Desperate Prayer. In Stormwind, High Priestess Laurena calls promising dwarven acolytes to the Cathedral of Light. There they deepen their service to the Light and take on wider duties among the Alliance. Dwarven priests trained in Dun Morogh may outgrow the lessons of local mentors like Maxan Anvol in Kharanos. When an acolyte shows promise, High Priestess Laurena sends a formal summons from the Cathedral of Light. Her attention means the young priest is ready for deeper study and greater duties in the faith. Ironforge keeps its holy traditions in the Mystic Ward, while Stormwind's Church of the Holy Light welcomes humans and dwarves alike. Traveling south by Deeprun Tram brings dwarven acolytes into the wider church community. The journey strengthens the spiritual bond between the allied kingdoms.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5637-de9478cb76d368987c4f/1-0000.mp3", duration = 49.0840816, start = 0},
  },
}
P.transport["quest:5638"] = {
  hash = "97942d",
  fullHash = "97942d",
  text = "Desperate Prayer. In Stormwind, a summons carries a young priest from the Park to the Cathedral of Light. Nara Meideros sends you to High Priestess Laurena for further instruction. In Stormwind’s Park, Nara Meideros keeps faith with Elune. The city’s spiritual guides maintain ties across their traditions. So when the Cathedral seeks a promising student, Nara sends you across the canals with quiet encouragement. The message brings good tidings, not alarm. At the Cathedral of Light in Cathedral Square, you report to High Priestess Laurena. One of Stormwind’s senior clerical leaders, she guides young acolytes beyond their first prayers. Laurena teaches the sacred invocation called Desperate Prayer, a personal plea for divine aid. Near death, a servant of the Light can use it to mend grievous wounds in an instant.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5638-2f38cf2f0c58ee8ecc97/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:5639"] = {
  hash = "5b02e6",
  fullHash = "5b02e6",
  text = "Desperate Prayer. High Priest Rohan sends you from Ironforge to Stormwind to learn healing and survival. There, High Priestess Laurena teaches dwarven acolytes the deeper mysteries of the Church. In Ironforge's Mystic Ward, Rohan guides dwarven initiates devoted to the Holy Light. Seeing your discipline and faith, he sends you southwest to Stormwind. Human and dwarven clerics share close spiritual ties, and the city's grand halls hold advanced teaching. You reach Stormwind by the Deeprun Tram and climb to Cathedral Square. In the Cathedral of Light, High Priestess Laurena tests you on the Church's behalf. She teaches the desperate prayers a priest calls upon in battle, seeking divine aid when strength fails and death draws near.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5639-1ff5fef5eccee84964db/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["quest:5640"] = {
  hash = "993179",
  fullHash = "993179",
  text = "Desperate Prayer. In Darnassus, young human and dwarven priests seek guidance in another faith. Priestess Alathea teaches the ways of Elune and directs followers of the Holy Light to Stormwind, where High Priestess Laurena welcomes returning acolytes to the Cathedral of Light. Alliance priests follow different sacred paths. In Darnassus, the priesthood serves Elune and channels the moon goddess's radiance and wrath. Priestess Alathea honors Elune and respects the Holy Light. Yet she cannot teach another race the deeper prayers bound to a different devotion. Human and dwarven acolytes who seek those prayers must look elsewhere. Initiates of the Holy Light return home to learn its rites, including the prayer for divine aid in a moment of peril. In Stormwind's Cathedral of Light, High Priestess Laurena guides returning priests beneath its marble arches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5640-d8d51281384b6adb4c05/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:5648"] = {
  hash = "07cebe",
  fullHash = "07cebe",
  text = "Garments of Spirituality. In Razor Hill, new priests put their healing to the test in the field. They seek Grunt Kor'ja, wounded while fighting Kul Tiras survivors, and tend her injuries. Those who succeed earn ceremonial vestments and recognition among the Horde's spiritual practitioners. South of Razor Hill, the Horde still fights remnants of Grand Admiral Daelin Proudmoore's forces. Tai'jin, the troll priest trainer, tests new priests in the work of battle triage. She sends them to find Grunt Kor'ja, a warrior badly wounded while repelling human infiltrators. You tend her injuries and strengthen her before she succumbs. Healing Kor'ja proves a young priest is ready to serve the Horde's spiritual tradition. Tai'jin awards the Garments of Spirituality for saving a frontline defender. To orcs and Darkspear trolls alike, the robes mark their wearer as more than an apprentice of incantations. They can be trusted to keep Horde warriors alive in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5648-002cc408473a64945ca4/1-0000.mp3", duration = 59.0628571, start = 0},
  },
}
P.transport["quest:5649"] = {
  hash = "3cd0ef",
  fullHash = "3cd0ef",
  text = "In Favor of Spirituality. In the Valley of Trials, young Darkspear priests begin their lives beyond the training grounds. Under Ken'jai's direction, they travel to Tai'jin in Razor Hill and meet Durotar's wider challenges. Their path holds both ancestral troll ways and service in the Horde. Darkspear acolytes leave the Valley of Trials after learning their basic rites from Ken'jai. The road from those secluded grounds leads to Razor Hill, a crossroads settlement in Durotar. There, a young priest steps beyond survival drills and begins to shoulder the spiritual and cultural duties of the tribe. Ken'jai speaks plainly about the Darkspear's place in Thrall's Horde. The trolls value the orcs' loyalty and lessons of honor, though some ancestral traditions sit uneasily among their allies. So Darkspear spiritual leaders teach their pupils to preserve their heritage quietly while serving the Horde.\n\nAt Razor Hill, Tai'jin welcomes the acolytes. He guides them toward self-sufficiency and strength within the community.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5649-87758ece72f6b8bd99f2/1-0000.mp3", duration = 60.3167347, start = 0},
  },
}
P.transport["quest:5650"] = {
  hash = "d21499",
  fullHash = "d21499",
  text = "Garments of Darkness. In Brill, Dark Cleric Beryl tests fledgling Forsaken priests before they enter deeper shadow. The trial asks whether they can heal and strengthen an injured Deathguard, for their calling demands more than afflicting enemies. Forsaken priests are known for shadow and darkness, yet Dark Cleric Beryl teaches that mastering darkness also means learning light and restoration. Those who seek only ruin are urged to study arcane magic instead. A priest must strengthen and preserve comrades as well as afflict enemies. North of Brill's cemetery, Deathguard Kel holds the line against prowling gnoll packs, though he has been wounded. Beryl sends you to bind Kel's wounds with healing spells and bolster his stamina with protective enchantments. By doing so, you show you can sustain Tirisfal Glades' defenders. Beryl grants you his vestment and welcomes you into the priesthood's higher mysteries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5650-daada4abcea2821259b5/1-0000.mp3", duration = 55.4579592, start = 0},
  },
}
P.transport["quest:5651"] = {
  hash = "281e62",
  fullHash = "281e62",
  text = "In Favor of Darkness. Dark Cleric Duesten sends you from Deathknell to Brill for In Favor of Darkness. There, you continue training with Dark Cleric Beryl and study the Holy Light and Shadow. Dark Cleric Duesten teaches that corruption forged the Forsaken, then cast them aside like carrion. To survive, they must understand both Light and Shadow without sentiment. You leave Deathknell's graveyard and enter the wider world beyond its walls. You follow the road northeast from Deathknell, cross a wooden covered bridge, and reach ruined Brill. Dark Cleric Beryl waits in the upper quarters of the local inn to test your resolve. He prizes ambition and cold practicality over blind devotion. A Forsaken priest must wield divine power as a weapon and a tool, never as a moral crutch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5651-2b40135078f077461bdf/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["quest:5654"] = {
  hash = "7ab0b8",
  fullHash = "7ab0b8",
  text = "Hex of Weakness. From Razor Hill to Orgrimmar, Hex of Weakness marks a young Darkspear priest’s next step. Tai'jin sends an initiate north to Ur'kyo, who welcomes new students into the tribe’s spiritual circle and teaches the loa’s darker arts. Tai'jin watches over young Darkspear priests as they study in Razor Hill’s barracks. When an acolyte has mastered spiritual communion and shadow magic, those first lessons come to an end. Tai'jin sends the promising priest north across Durotar’s red dirt canyons to Orgrimmar, the Horde capital. There, elder practitioners teach the tribe’s wider magical traditions. In Orgrimmar’s Valley of Spirits, the Darkspear keep a sanctuary apart from the orcs’ forges and warrior grounds. Ur'kyo, an elder priest, welcomes new initiates there. Joining his circle means honoring the loa and learning the ancestral ways of the jungle trolls. It also means mastering potent curses and hexes that sap an enemy’s strength in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5654-acb5d11977c3d751e683/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["quest:5713"] = {
  hash = "44229e",
  fullHash = "44229e",
  text = "One Shot. One Kill.. On the road to Auberdine, Sentinel Aynasha is ambushed and cannot carry her message onward. Poisoned by Marosh the Devious and his furbolg trackers, she must mix an antidote before she can travel. Sentinel Aynasha carries important communications toward Auberdine when hostile furbolgs intercept her on a trail in northern Kalimdor. Marosh the Devious leads them. Their venom leaves the scout unsteady and unable to continue on foot. Aynasha knows how to make natural remedies, but the antidote takes time to mix and take effect. Marosh's trackers are closing in, so she needs travelers to guard her as she works. Though her strength is failing, she keeps her bow steady and fires into the brush to hold the attackers back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5713-31587a6a1512ad1cdb07/1-0000.mp3", duration = 44.9567347, start = 0},
  },
}
P.transport["quest:5722"] = {
  hash = "bcb0f7",
  fullHash = "bcb0f7",
  text = "Searching for the Lost Satchel. Rahauro sends you from Thunder Bluff’s Elder Rise into Ragefire Chasm, where Magatha Grimtotem awaits news of her missing emissary Maur. Magatha Grimtotem learns on Thunder Bluff’s Elder Rise that her emissary, Maur Grimtotem, entered the cavern beneath Orgrimmar. He meant to study the troggs and try to parley with them, but never returned. Rumors say he found something unusual shortly before his death. While Warchief Thrall and his advisers attend to the Shadow Council in Ragefire Chasm, the Grimtotem clan pursues its own interests.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5722-af5397ff532eba2a38b5/1-0000.mp3", duration = 33.3322449, start = 0},
  },
}
P.transport["quest:5723"] = {
  hash = "a9444d",
  fullHash = "a9444d",
  text = "Testing an Enemy's Strength. At Thunder Bluff, Rahauro answers the slaughter of Magatha Grimtotem's emissaries beneath Orgrimmar. He sends warriors into Ragefire Chasm to thin the troggs' ranks. Magatha Grimtotem sent tauren emissaries into the fiery depths beneath Orgrimmar to make peace with the troggs. The creatures slaughtered the delegates on arrival. Magatha took the massacre as an insult to the tauren and a growing danger to the Horde. So she resolved to answer with force. From Thunder Bluff, Rahauro carries out Magatha’s orders. He sends warriors into Ragefire Chasm to find and kill trogg warriors and shamans. The Horde strikes deep into their underground home, thinning their numbers before they can pour through the tunnels into Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5723-e428bf6ee96488bb02c7/1-0000.mp3", duration = 47.8302041, start = 0},
  },
}
P.transport["quest:5724"] = {
  hash = "c46be9",
  fullHash = "c46be9",
  text = "Returning the Lost Satchel. In Ragefire Chasm beneath Orgrimmar, you find Maur Grimtotem's satchel and carry it to Rahauro on Elder Rise in Thunder Bluff. Troggs slew Maur Grimtotem in the fiery depths of Ragefire Chasm beneath Orgrimmar. Even in death, his arms held fast to his personal satchel. Freeing it from his grasp gives you the only clue to why a member of the Grimtotem clan entered the volcanic caverns beneath Thrall's capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5724-221240b596b2755adb5e/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["quest:5725"] = {
  hash = "7a76b3",
  fullHash = "7a76b3",
  text = "The Power to Destroy.... From the Undercity, Varimathras sends Horde adventurers beneath Orgrimmar. Lady Sylvanas Windrunner seeks two dark tomes from the Searing Blade cult, hoping their power will aid her war against the Scourge and the Lich King. Thrall's orcs hunt the Searing Blade cult beneath their capital. The Forsaken covet the cult's occult stores. On Sylvanas Windrunner's orders, Varimathras sends operatives into Ragefire Chasm to seize two demonic grimoires: Spells of Shadow and Incantations from the Nether. The Dark Lady believes disciplined Forsaken will can use these gifts better than the lesser cultists. Once the tomes are secured, Varimathras explains their purpose. Their dark magic is meant to strengthen Sylvanas's campaign against the Scourge. The Forsaken hope to claim every scrap of forbidden power, break the Lich King's hold across Lordaeron, and free the remaining undead from his mental enslavement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5725-181a9ab0bcea0ee4f1a3/1-0000.mp3", duration = 57.5477551, start = 0},
  },
}
P.transport["quest:5726"] = {
  hash = "1d2958",
  fullHash = "1d2958",
  text = "Hidden Enemies. Thrall begins a covert search for the Burning Blade in Durotar. He asks a promising young adventurer to recover a Lieutenant's Insignia from Skull Rock, opening a way to uncover cultists working under the Horde's nose. In Durotar, the new Horde struggles to secure a home, and Warchief Thrall faces betrayal from within. The Burning Blade has taken root just outside Orgrimmar's gates. Its cultists prey on lingering demonic corruption and hunger for dark power. Thrall needs someone to watch and listen without drawing notice. Skull Rock lies east of Orgrimmar. Its rugged caverns hold warlocks, voidwalkers, and fanatical cultists. Thrall sends you to take a Lieutenant's Insignia from one of the Burning Blade leaders. The emblem is meant to open the cult's hidden ranks, so Thrall can learn who directs its movements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5726-f967f464bf3c1154992a/1-0000.mp3", duration = 53.0285714, start = 0},
  },
}
P.transport["quest:5727"] = {
  hash = "ce0a73",
  fullHash = "ce0a73",
  text = "Hidden Enemies. In Orgrimmar, Thrall sends you to learn what the Burning Blade knows. Cult activity at Skull Rock has brought you to Neeru Fireblade with a lieutenant's insignia, to test his loyalties. Thrall chooses cunning over a strike at the Cleft of Shadow. He knows Neeru Fireblade pretends to serve the Horde while secretly aiding the cultists. A direct attack could warn Neeru's masters and end the trail into the conspiracy. So Thrall gives you an insignia taken from the cult in Durotar and asks you to pose as an initiate, learning what Neeru knows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5727-2953e6c09594c969c2b2/1-0000.mp3", duration = 34.4555102, start = 0},
  },
}
P.transport["quest:5728"] = {
  hash = "934ea6",
  fullHash = "934ea6",
  text = "Hidden Enemies. Thrall sends you against the Searing Blade beneath Orgrimmar. You have won Neeru Fireblade's trust by pretending to share the cult's cause. Now Thrall sends you into Ragefire Chasm to strike at its leaders. Orgrimmar was built as a haven for a free Orcish race. Yet beneath its markets, the Cleft of Shadow opens onto the tunnels of Ragefire Chasm. There, remnants of the Shadow Council gather strength as the Searing Blade. They practice dark arts and scheme to seize the young Horde from within its own capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5728-c1b7ef729dce3acfbd74/1-0000.mp3", duration = 33.5934694, start = 0},
  },
}
P.transport["quest:5729"] = {
  hash = "b5f93f",
  fullHash = "b5f93f",
  text = "Hidden Enemies. In Orgrimmar, Thrall's watch reaches into the Cleft of Shadow. After Bazzalan and Jergosh the Invoker die beneath the city, Thrall sends you to win Neeru Fireblade's trust. Thrall sees a chance after Bazzalan and Jergosh the Invoker are killed in Ragefire Chasm. He chooses to leave Neeru Fireblade in place. Neeru has lost the lieutenants who led the local cult. So Thrall sends you back to the Cleft of Shadow, offering yourself as an ally who can fill that gap.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5729-e2fe5d5980268b40bd48/1-0000.mp3", duration = 31.6342857, start = 0},
  },
}
P.transport["quest:5730"] = {
  hash = "d6b516",
  fullHash = "d6b516",
  text = "Hidden Enemies. In Orgrimmar, Thrall awaits your report on the Burning Blade. Neeru Fireblade trusts you, and the Warchief needs to know how far the cult's reach extends across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5730-9407c301bf41fa1c969d/1-0000.mp3", duration = 11.3371429, start = 0},
  },
}
P.transport["quest:5761"] = {
  hash = "e197f7",
  fullHash = "e197f7",
  text = "Slaying the Beast. Neeru Fireblade sends Horde adventurers from Orgrimmar into Ragefire Chasm to hunt Taragaman the Hungerer. He says Warchief Thrall ordered the hunt and asks for the felguard’s heart as proof the demonic cult has fallen. Ragefire Chasm runs beneath Orgrimmar’s red earthen streets. Its fiery fissure shelters troggs, beasts, and covert Searing Blade agents. In the Cleft of Shadow above, Neeru Fireblade claims to serve Thrall and cleanse the demonic rot. He points to Taragaman the Hungerer, a massive felguard in the cavern’s heart, and calls him the mastermind behind the cult beneath the city.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5761-2b690c65810dfc5c88a7/1-0000.mp3", duration = 38.9485714, start = 0},
  },
}
P.transport["quest:579"] = {
  hash = "a6b265",
  fullHash = "a6b265",
  text = "Stormwind Library. In Stormwind Keep, Donyal Tovald copies the kingdom’s histories for those bearing library scrips. Young King Anduin Wrynn funds the work, opening accounts of Azeroth to citizens and scholars. Young King Anduin directs royal funds toward learning. They pay for copies of ancient manuscripts and historical journals. In Stormwind Keep, the Royal Library preserves these accounts and copies them for those in royal service. Hand copying delicate parchment takes time, ink, and royal sanction. Donyal Tovald accepts official library scrips issued to adventurers and scholars across Alliance territories. In return, he provides copies of historical works, from ancient Eastern Kingdoms histories to accounts of distant lands. These books tell of conflicts beyond the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_579-47ea948cb0e6d117d68f/1-0000.mp3", duration = 49.92, start = 0},
  },
}
P.transport["quest:59"] = {
  hash = "1c94bb",
  fullHash = "1c94bb",
  text = "Cloth and Leather Armor. In Goldshire, Cloth and Leather Armor sends a trusted traveler east for gear. Marshal Dughan issues an armor marker for Sara Timberlain at Eastvale Logging Camp. Beyond Guard Thomas's bridge, recruits seek armor for the realm's defense. Guard Thomas watches Elwynn's eastern river crossing, where murlocs and gnolls threaten the border. You carry his report to Goldshire, and Marshal Dughan marks your service with an official Stormwind Armor Marker. Goldshire's garrison has few stores, so Dughan gives you a marker instead of equipment. It is a military voucher recording your service to the crown. East of Guard Thomas's bridge lies Eastvale Logging Camp, Elwynn's main timber operation. Sara Timberlain works there under commission from the Stormwind Army, making cloth and leather gear. The kingdom's central armories are strained, so local artisans like Sara outfit troops and auxiliary scouts on the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_59-ab08a0ddf33da91f5051/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["quest:590"] = {
  hash = "1505bf",
  fullHash = "1505bf",
  text = "A Rogue's Deal. Calvin Montague offers newly awakened Forsaken work in Deathknell. He promises wealth for delivering a letter, but you do not know whether he will honor the bargain. Deathknell is a ruined village in southwestern Tirisfal Glades.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_590-20f45fa2282d6af22575/1-0000.mp3", duration = 14.9420408, start = 0},
  },
}
P.transport["quest:5921"] = {
  hash = "bfdd17",
  fullHash = "bfdd17",
  text = "Moonglade. In Darnassus, young night elf druids learn a spell that carries them across the world to Moonglade. There, they meet Dendrite Starblaze in Nighthaven and begin the path toward mastering bear form. Moonglade offers an ancient sanctuary devoted to the teachings of Cenarius. Keeper Remulos watches over its groves, where druids find peace and communion with nature. Young druids learn a spell to carry themselves across the world to Moonglade. There they find wisdom beyond mortal distances. Moonglade welcomes all who follow the wild, though the Cenarion Circle knows tension. In Darnassus, Arch Druid Fandral Staghelm and Keeper Remulos disagree over nature’s care and the making of Teldrassil. Their differences do not close Nighthaven to young acolytes. They are welcomed to pursue their studies. In Nighthaven, Dendrite Starblaze guides young druids in the ways of the Claw. Before an initiate takes up the bear’s mantle, the trials teach endurance, fury, and defense of the wild. Starblaze welcomes each student in reverence to Father Cenarius. Then the trials of the Great Bear Spirit begin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5921-86e69262efbfa4372c17/1-0000.mp3", duration = 72.8032653, start = 0},
  },
}
P.transport["quest:5922"] = {
  hash = "3ce5dd",
  fullHash = "3ce5dd",
  text = "Moonglade. A young tauren druid learns to reach nature’s ancient keepers in Moonglade. Guided by Turak Runetotem in Thunder Bluff, you learn to cross the waking world and commune with them directly. Beyond Kalimdor’s faction struggles, Moonglade offers a refuge to all who follow nature. Keeper Remulos, son of Cenarius, watches over the ancient valley. Night elf and tauren druids enter Nighthaven as equals beneath the Cenarion Circle’s timeless mantle. Turak Runetotem teaches you a transport spell bound to Moonglade. It aids your spiritual and martial growth, carrying you across hundreds of leagues in a heartbeat through your bond with the natural world. The valley gives you a place to study and a lasting refuge throughout your journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5922-9eba67ba07d68cf361c8/1-0000.mp3", duration = 46.7330612, start = 0},
  },
}
P.transport["quest:5923"] = {
  hash = "68dca7",
  fullHash = "68dca7",
  text = "Heeding the Call. In Darnassus, Mathrengyl Bearwalker calls druids from Teldrassil and beyond to begin their training. An apprentice now faces the path toward mastering the bear aspect. Novice druids receive a personal summons when their instructors judge them ready for trials. Kal in Dolanaar, Denatharion in Darnassus, and Theridran in Stormwind carry Mathrengyl Bearwalker’s invitation to train. As Arch Druid Fandral Staghelm’s direct assistant, Mathrengyl is one of the night elves’ most respected and knowledgeable mentors. His guidance marks an apprentice as ready for true trials. Mathrengyl Bearwalker receives candidates on the upper level of Fandral Staghelm’s residence in the Cenarion Enclave. Druids must learn to embody nature’s living creatures, not merely watch them. He tells each candidate that the first great undertaking is to embrace the bear’s strength, endurance, and spirit. The path reaches far beyond Teldrassil, to sacred ancestral grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5923-9b7156b56ce13d397d02/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["quest:5926"] = {
  hash = "e37015",
  fullHash = "e37015",
  text = "Heeding the Call. Across Horde settlements, word reaches novice druids that Turak Runetotem wants to instruct them in person. Heeding the Call brings them to Elder Rise in Thunder Bluff, where the sacred trials toward the bear's form begin. Across Mulgore and Orgrimmar, you hear that Turak Runetotem has noticed your early progress. The message may come from Innkeeper Gryshka in Orgrimmar, Innkeeper Pala in Thunder Bluff, or Gennia Runetotem in Bloodhoof Village. The Cenarion Circle does not call practitioners lightly. Your work with herbs and simple spells has earned you a chance to deepen your bond with nature's wild spirits. On Elder Rise, Turak Runetotem guides young tauren in their ancestral duty. He assists Archdruid Hamuul Runetotem and welcomes you into the large Cenarion tent. Turak teaches that animals and plants are allies, and that these bonds carry solemn duties. His guidance opens a way beyond basic lessons, toward trials of body and heart and communion with the Great Bear Spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5926-8db5fa7182e14ddd8023/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:5931"] = {
  hash = "bd5a31",
  fullHash = "bd5a31",
  text = "Back to Darnassus. You leave Moonglade after meeting the Great Bear Spirit and return to Darnassus. In the Cenarion Enclave, Mathrengyl Bearwalker awaits to guide your practical shapeshifting trials. Dendrite Starblaze sends you from Nighthaven back to Darnassus after your meeting with the Great Bear Spirit in Moonglade. There, you leave the sanctuary where you communed with the spirit and return to the unsettled world beyond. In Darnassus, local mentors watch over Teldrassil and guide the next stage of your training. Mathrengyl Bearwalker waits for you in the Cenarion Enclave, guarding nature as its balance falters. The Great Bear Spirit's blessing is only the first step. Mathrengyl prepares you for trials of body and heart, so you can give physical form to the spirit's fierce ancestral wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5931-9a2996f84cfa329ee5d5/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:5932"] = {
  hash = "8addc6",
  fullHash = "8addc6",
  text = "Back to Thunder Bluff. At Elder Rise, Turak Runetotem awaits your return from Moonglade. Dendrite Starblaze sends you home after your communion with the Great Bear Spirit, so your training can continue among your people. In Moonglade, night elf and tauren practitioners of nature magic meet in the Cenarion Circle. There, they set aside the divides between mortal factions. After your communion with the Great Bear Spirit, Dendrite Starblaze sends you back to your people. Night elves often see tauren as fledglings in Cenarius’s formal teachings. Yet Starblaze recognizes the wisdom and balance of Turak Runetotem. You climb to Elder Rise in Thunder Bluff and stand before Turak Runetotem, changed by your rite. Communion with ancient totemic spirits such as the Great Bear Spirit runs deep in tauren culture. Yet the Path of the Claw asks for serious commitment. Your spiritual bond is forged, and Turak prepares you to put your new strength and endurance into practice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5932-051dc008d03ee7a85f76/1-0000.mp3", duration = 60.395102, start = 0},
  },
}
P.transport["quest:6"] = {
  hash = "bfc834",
  fullHash = "bfc834",
  text = "Bounty on Garrick Padfoot. Near Northshire Abbey, an Alliance bounty calls recruits to hunt Garrick Padfoot by the vineyards. The notorious thief and his gang threaten the valley's farmers and merchants. Northshire Valley offered a safe place to train recruits and tend its sacred vineyards. But as order falters across Elwynn, thieves have reached the valley. Garrick Padfoot, a cutthroat, quickly rose to lead them. For weeks, he and his gang have plundered shipments, robbed merchants on the roads, and threatened local farmers. Stormwind's guards are stretched thin, protecting the capital and its outer borders. So local marshals and deputies rely on volunteers to keep Northshire peaceful. Deputy Willem posts a public bounty on Garrick's head, hoping to rid the valley of his gang. Padfoot's rundown shack lies east of the river. Bringing him down there strikes at the lawlessness spreading through the human heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6-bd3ffd6080133df6e296/1-0000.mp3", duration = 55.1706122, start = 0},
  },
}
P.transport["quest:60"] = {
  hash = "cc8a7a",
  fullHash = "cc8a7a",
  text = "Kobold Candles. At the Lion's Pride Inn in Goldshire, William Pestle seeks candles from kobolds crowding Elwynn's mines. The alchemist has come from his Stormwind shop for their thick wax. His errand brings adventurers face to face with the creatures encroaching on the kingdom's gold veins. William Pestle runs Pestle's Apothecary with his brother in Stormwind City's Trade District. He needs wax for the remedies, ointments, and concoctions he brews. So he turns to Elwynn's kobolds instead of buying polished candles from city merchants. They carry hefty lumps of tallow and wax on their brows, ready for an adventurer to pry loose. Kobolds have overrun Fargodeep Mine south of Goldshire and Jasperlode Mine to the northeast. They prize their candles above almost everything. The flames guide them through dark shafts as they dig for gold and shiny trinkets. Taking the candles replenishes Pestle's alchemy stocks and weakens the vermin choking off the kingdom's precious mining claims.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_60-2da7a09491a74e16da31/1-0000.mp3", duration = 60.2644898, start = 0},
  },
}
P.transport["quest:6001"] = {
  hash = "b2ea1b",
  fullHash = "b2ea1b",
  text = "Body and Heart. In Darnassus, a night elf initiate stands near the end of the path of the claw. Mathrengyl Bearwalker sends them to Darkshore, where Lunaclaw will test their body and heart before they take the form of the bear. Mathrengyl Bearwalker sends night elf initiates east of Auberdine, the coastal settlement in Darkshore. There, a natural cavern shelters wild moonkin and an ancient Moonkin Stone. Anointing the stone with Cenarion Moondust awakens Lunaclaw, its ancient defender. The guardian challenges each initiate who seeks the sacred strength of the claw.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6001-7619d8bd0e97ecbd945b/1-0000.mp3", duration = 36.1273469, start = 0},
  },
}
P.transport["quest:6002"] = {
  hash = "52ce4f",
  fullHash = "52ce4f",
  text = "Body and Heart. At the Moonkin Stone, you face a trial of strength and heart to master Bear Form. Turak Runetotem sends young tauren druids from Thunder Bluff to summon and defeat Lunaclaw near the dry frontier where Mulgore meets the Barrens. Turak Runetotem tests young tauren druids who seek the path of the Druid of the Claw. You have communed with the Great Bear Spirit in Moonglade. Now your training turns to a trial of strength. Turak, the elder druid trainer atop Thunder Bluff's Elder Rise, gives worthy aspirants Cenarion Lunardust. He sends you to a sacred stone near the dry frontier where Mulgore meets the Barrens. West of Camp Taurajo, the Moonkin Stone marks a rare Cenarion site in southern Kalimdor. Moonkin are not native to the sun-scorched plains of central Kalimdor, and Lunaclaw guards the stone. Scatter the lunardust across the ancient monument to call Lunaclaw into battle. Defeating the guardian proves your strength and clarity of heart. Its blessing awakens the bear's inner essence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6002-6bd6da1cdf250249c0c9/1-0000.mp3", duration = 64.8620408, start = 0},
  },
}
P.transport["quest:6061"] = {
  hash = "a91c94",
  fullHash = "a91c94",
  text = "Taming the Beast. At Bloodhoof Village, Yaw Sharpmane begins a young tauren hunter’s training with Taming the Beast. The first trial leads into Mulgore, where the hunter tames an adult plainstrider and begins a bond with the Earthmother’s creatures. Tauren hunters seek more than meat and hides. Their ancestral traditions teach that meeting Mulgore’s wild creatures can bring them closer to the Earthmother. A tamed companion may once have been an adversary. Now beast and hunter join as partners in the natural balance of the plains. Yaw Sharpmane begins a hunter’s training with the plainstriders roaming Mulgore’s grasslands. Carrying an enchanted taming rod, the hunter faces an adult plainstrider and calms its wild instincts to earn its trust. This first trial tests the hunter’s resolve and prepares them to face more demanding beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6061-cc577c89bcf45deb39c1/1-0000.mp3", duration = 52.0097959, start = 0},
  },
}
P.transport["quest:6062"] = {
  hash = "ec641e",
  fullHash = "ec641e",
  text = "Taming the Beast. In Razor Hill, Taming the Beast puts young Horde hunters to their first test with a taming rod. Thotar sends them to face a fierce dire mottled boar. In Durotar, orc and Darkspear troll hunters must learn to command the wild as well as survive it. Thotar gives young hunters an enchanted taming rod and sends them against a fierce wild boar. They must subdue the beast without killing it, then make it a loyal ally. Dire mottled boars roam the dry brush around Razor Hill. Their strength and temper make them a fitting first test for young hunters. The rod can subdue a charging boar, but using it takes patience and resolve. Every Horde tracker needs those qualities.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6062-4ee167932db7b624130d/1-0000.mp3", duration = 42.0310204, start = 0},
  },
}
P.transport["quest:6063"] = {
  hash = "b5b39b",
  fullHash = "b5b39b",
  text = "Taming the Beast. In Dolanaar, a young night elf hunter faces the first trial of Taming the Beast with a wild Webwood Lurker. Dazalar lends an enchanted taming rod, and the hunter must earn the spider’s trust through a bond with nature. For the kaldorei, hunting asks more than skill at tracking prey or survival in the wild. It binds a hunter to nature, greater than any mortal. Animals are their own creatures, not tools to bend to a hunter’s will. Dazalar teaches novice hunters to meet them with respect. Before gaining a lifelong beast companion, a hunter must master the local wildlife through ancient techniques, never brute force. Giant arachnids infest Teldrassil’s boughs, so Dazalar gives the hunter a taming rod. In shadowed thickets, the hunter seeks a Webwood Lurker and faces the venomous spider’s attacks. To reach it, the hunter must answer with empathy. A brief mental bond proves the hunter can commune with the World Tree’s eerie, skittering predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6063-1f2dc2630d53d518597f/1-0000.mp3", duration = 63.2685714, start = 0},
  },
}
P.transport["quest:6064"] = {
  hash = "e3eb99",
  fullHash = "e3eb99",
  text = "Taming the Beast. In Dun Morogh, Taming the Beast sets a hunter on the first trial toward mastering companion beasts. In Kharanos, Grif Wildheart guides young trackers as they calm a Large Crag Boar with an enchanted taming rod. Dwarven mountaineers and trackers depend on guns, traps, and their wits in the wild. Yet a hunter's calling is to make a lifelong bond with a wild beast. Outside the Thunderbrew Distillery in Kharanos, Grif Wildheart oversees this rite. He tests novices against several species native to Dun Morogh before asking them to bind any beast for good. A Large Crag Boar is the first test for a young tracker. These thick-hided swine roam Dun Morogh's snowy foothills, where their bristling fur and tough flesh make them stubborn and fierce. Grif provides an enchanted Taming Rod. The hunter faces the boar's charge and tries to calm its fury until it submits to command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6064-2eadf82f3f5d066d76ce/1-0000.mp3", duration = 55.4579592, start = 0},
  },
}
P.transport["quest:6065"] = {
  hash = "6797a2",
  fullHash = "6797a2",
  text = "The Hunter's Path. In Mulgore, The Hunter's Path sends young tauren to Bloodhoof Village for advanced training. There they seek Yaw Sharpmane and begin the trials of taming and bonding with wild beasts. Among the Shu'halo, hunting is sacred. A hunter learns nature's balance, honors the plains' spirits, and respects the animals that sustain the tribes. After young hunters prove they can survive in the wild and use a bow or gun, their elders send them to seasoned mentors. The journey marks their step beyond solitary tracking and toward adulthood in tauren culture. The road to Bloodhoof Village crosses Mulgore's grasslands and reaches the settlement beside Stonebull Lake. There, Yaw Sharpmane teaches hunters about the local beasts. Meeting him marks a hunter's readiness for the trials of beast taming. They learn to commune with predators as well as hunt them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6065-6f613a51226a6478e770/1-0000.mp3", duration = 52.8718367, start = 0},
  },
}
P.transport["quest:6068"] = {
  hash = "86cf73",
  fullHash = "86cf73",
  text = "The Hunter's Path. In Durotar, The Hunter's Path leads young orc and troll hunters to Razor Hill. There, Thotar teaches them to bind wild predators. In Durotar, young hunters learn to follow prey with bow and cunning. Trails through red clay canyons and harsh scrubland teach them patience. To master the Horde's way of hunting, they must also learn to bond with wild beasts. When class trainers judge a student ready, they send them to Razor Hill. At Razor Hill, Thotar teaches young hunters to subdue Durotar's fierce beasts without breaking their spirit. His lessons begin their path toward traveling the wilderness with a loyal companion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6068-2af5400ae4dc40e1fac8/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["quest:6074"] = {
  hash = "15f9c7",
  fullHash = "15f9c7",
  text = "The Hunter's Path. In Dun Morogh, the trainers send ready hunters to Kharanos to begin learning how to tame wild beasts. Grif Wildheart oversees the trials there. Novice hunters cross Dun Morogh’s snowy crags alone until they learn to bond with beasts. Olmin Burningbeard and Tristane Shadowstone watch their pupils closely. They wait until a hunter can face a savage creature calmly and spare its life. Then the trainers send the disciplined novice down the mountain roads toward Kharanos. In Kharanos, Grif Wildheart oversees the final trials of dwarven huntsmanship. Taming a beast takes more than bringing it down for meat or pelt. A hunter needs patience, physical endurance, and an instinctive bond with the wild predators of the mountains. Wildheart prepares each hunter to test their will against Dun Morogh’s fiercest wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6074-64474af42a42105886e8/1-0000.mp3", duration = 51.4612245, start = 0},
  },
}
P.transport["quest:6081"] = {
  hash = "27c1ab",
  fullHash = "27c1ab",
  text = "Training the Beast. In Durotar, young orc and troll hunters are sent to learn from veteran master hunter Ormak Grimshot. After proving themselves with the plains beasts, they travel from Razor Hill to Orgrimmar. There they learn to care for, feed, and train a lifelong animal companion. In Durotar's arid canyons, skill with a bow and survival in the wild are only part of a hunter's duty. Young hunters first tame the plains beasts: fierce boars, crab scavengers, and armored scorpid stalkers. Once they prove their resilience, Thotar sends them from Razor Hill north through the red clay gulches to Orgrimmar's fortified gates. There, they must take responsibility for a companion. Orgrimmar's Valley of Honor is where veteran stalkers and warriors hone their craft. There, young hunters seek Ormak Grimshot, one of the Horde's revered master hunters. He looks beyond their youth to judge whether they have the patience to command a beast and care for it through famine, battle, and loss. A beast won through force remains wild until hunter and companion understand one another. Ormak teaches the traditions that keep their bond: which foods nourish each creature's spirit, how discipline teaches a beast lethal techniques, and the spiritual focus needed to revive one that falls in the line of duty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6081-d265ce311730aa03a24b/1-0000.mp3", duration = 80.5616327, start = 0},
  },
}
P.transport["quest:6082"] = {
  hash = "bb3d02",
  fullHash = "bb3d02",
  text = "Taming the Beast. In Durotar, a young Horde hunter faces the last trial of Taming the Beast. Thotar in Razor Hill sends the hunter to tame an armored scorpid. Success grants the power to tame, call, and dismiss a lasting companion. A hunter must first prove they can command Durotar's harsh wildlife before traveling Kalimdor with an animal companion. Thotar trains hunters in Razor Hill and sends them to subdue three kinds of creature with an enchanted taming rod. Dire boars and swift surf crawlers have already tested them. Now they face an armored scorpid, a venomous predator with heavy plates, known for its resilience and speed. Taming an armored scorpid tests focus and control under attack, not a hunter's skill at killing. Thotar urges hunters to meet the beast's quick, confident strikes. Once the scorpid is charmed, the hunter returns to Razor Hill and gives the taming rod back to Thotar. Then Thotar teaches the wild's innate techniques, so the hunter can seek out and bind a permanent companion of their choosing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6082-a207f9afa553f31b7636/1-0000.mp3", duration = 64.0522449, start = 0},
  },
}
P.transport["quest:6083"] = {
  hash = "16ff65",
  fullHash = "16ff65",
  text = "Taming the Beast. Along Durotar's coast, Taming the Beast sends young hunters to face their second trial. Thotar, the hunter trainer in Razor Hill, directs aspiring orc and troll hunters to tame a surf crawler near the Echo Isles and extend their bond to coastal wildlife. You have mastered a dire mottled boar, and now Thotar sends you toward the sea. Durotar's harsh shores are jagged, and shallow reefs teem with armored crustaceans. A surf crawler resists intrusion into its coastal domain. Taming one calls for patience and fortitude. Thotar teaches that a bound beast should add to a hunter's strength. With the taming rod, you subdue a surf crawler and learn to command creatures of different temperaments in different surroundings. This trial proves you are ready for permanent companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6083-09c8cc8736f9c39e2d0e/1-0000.mp3", duration = 49.9983673, start = 0},
  },
}
P.transport["quest:6084"] = {
  hash = "59a5c2",
  fullHash = "59a5c2",
  text = "Taming the Beast. Grif Wildheart sends you to face a snow leopard in the second taming trial. The test reaches beyond the crag boar. Snow leopards prowl southeast of Kharanos. The crag boar tested your strength against hard blows. Now Grif expects you to face a swift, graceful predator on its own terms. Beneath its white coat lies dangerous strength, ready to strike. With an enchanted taming rod, you face a wild snow leopard and seek to turn its hunting instincts toward partnership. Its speed, agility, and sharp reflexes test you in ways the crag boar did not. Learn to work alongside a predator that strikes swiftly from the snowy crags, and you draw closer to mastering the beasts of the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6084-c3734c40d3f000171b30/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["quest:6085"] = {
  hash = "769d58",
  fullHash = "769d58",
  text = "Taming the Beast. In Dun Morogh, Grif Wildheart tests your control of an Ice Claw Bear east of Kharanos. With an enchanted rod, you subdue the bear and learn to understand it. Then you earn the power to tame, call, and dismiss a lasting wild companion. Dun Morogh’s mountaineers and scouts depend on hardy beasts in its freezing crags. You have practiced on swift, cunning predators. Now Grif Wildheart sends you to capture an Ice Claw Bear in the snowdrifts east of Kharanos. Its strength and endurance test the control every dwarven huntsman must learn. The Taming Rod keeps the bear docile while you learn how wild instincts answer to will and calm intent. Your bond lasts only for the trial, which teaches discipline. Return the rod to Grif and the trials are complete. He then teaches you to pacify a compatible wild creature and call it throughout your life of adventure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6085-89c67d38f620d6f1edf2/1-0000.mp3", duration = 52.8718367, start = 0},
  },
}
P.transport["quest:6086"] = {
  hash = "2cd115",
  fullHash = "2cd115",
  text = "Training the Beast. In Dun Morogh, Grif Wildheart sends young dwarven hunters to Ironforge to learn care for a lasting animal companion. After taming the mountain’s wild predators, they learn to feed and train their beasts. Young hunters finish their trial near Kharanos under Grif Wildheart’s watch. They have tamed large crag boars, snow leopards, and sturdy ice claw bears with a taming rod. Then Grif sends them up the mountain pass to Ironforge. They seek the Hall of Arms in the military district. Belia Thundergranite teaches animal care in Ironforge’s Hall of Arms. Revered among the dwarven kingdom’s master animal trainers, she shows young hunters how to nourish their pets and teach them new battlefield skills. She also teaches them to call their spirits back if they fall defending their master. Her lessons turn a frightened wild beast into a loyal partner. Dwarven tradition asks for respect between hunter and beast, never subjugation. Belia reminds young hunters that an animal companion reflects the care it receives. Fed well, respected, and properly trained, a beast will fight loyally against troggs, frost trolls, and any threat to Khaz Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6086-d13672a07a8949acd5fc/1-0000.mp3", duration = 73.3257143, start = 0},
  },
}
P.transport["quest:6087"] = {
  hash = "4df97c",
  fullHash = "4df97c",
  text = "Taming the Beast. In Bloodhoof Village, Yaw Sharpmane sets a young tauren hunter a new trial. The hunter must master the swift prairie stalker. After mastering the adult plainstrider’s endurance, you face a new kind of hunter. Prairie stalkers rely on speed and travel in packs. They attack without fear. To tame one, you must approach without breaking stride and match the wolf’s decisive nature. Yaw Sharpmane teaches you that hunting beside a beast takes neither servitude nor brute force. You and the predator must fight as one, joined by respect and shared rhythm. Under Mulgore’s open skies, bonding with a prairie stalker teaches you to complement your companion’s attacks and move with it in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6087-ff5de0b8d218015e8151/1-0000.mp3", duration = 45.5053061, start = 0},
  },
}
P.transport["quest:6088"] = {
  hash = "0a0a6d",
  fullHash = "0a0a6d",
  text = "Taming the Beast. In Mulgore, a young tauren hunter faces the final trial with Yaw Sharpmane in Bloodhoof Village. With an enchanted rod, you tame a wild swoop and prove you can master the sky. The trial earns you the Earthmother’s trust and lasting knowledge to tame, call, and dismiss a companion. After you subdue predators on Mulgore’s plains, Yaw Sharpmane turns your training to the open sky. A swoop is a fierce bird of prey, with a sharp beak, sweeping dives, and an intimidating air. Its talons test your reflexes and calm as you use the enchanted rod to bring its instincts into accord with your own. For the tauren, hunting and companionship with beasts are spiritual pursuits, not mere subjugation. Mastering creatures of earth and sky teaches the balance and respect needed to walk the plains without disturbing nature. Yaw Sharpmane takes back his temporary taming rod, then teaches you lasting ways to call, dismiss, and permanently tame a companion of your choosing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6088-f1fb4d203e55f17b05b7/1-0000.mp3", duration = 60.5518367, start = 0},
  },
}
P.transport["quest:6089"] = {
  hash = "363208",
  fullHash = "363208",
  text = "Training the Beast. In Mulgore, Training the Beast brings young tauren hunters to the next step in learning beside a beast. After soothing the plains’ wild creatures, they travel to Thunder Bluff to learn the lasting bond of care and command. Tauren hunters in Mulgore have faced plainstriders, prairie stalkers, and swoops. Now Yaw Sharpmane, their mentor in Bloodhoof Village, sends each novice to Hunter Rise in Thunder Bluff to take up the full mantle of the hunter. There, Holt Thunderhorn teaches them. The shu'halo honor him for communing with the wilds, and his reverence for the Earthmother is greater still. To the tauren, a beast is a partner joined through harmony with the natural world, never a weapon or thrall. Holt Thunderhorn teaches hunters how to keep that bond strong. They learn to guide a creature's combat instincts, feed it regularly, and mend its injuries. If it falls defending its companion on the plains, they can call its spirit back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6089-a6c510bce7dc74beb73f/1-0000.mp3", duration = 58.7232653, start = 0},
  },
}
P.transport["quest:61"] = {
  hash = "b59927",
  fullHash = "b59927",
  text = "Shipment to Stormwind. William Pestle sends a parcel from Goldshire to his brother in Stormwind. Its candles carry wax gathered from kobolds in Elwynn Forest to Morgan at Pestle's Apothecary. William Pestle gathers herbs, reagents, and raw goods in Goldshire. His brother Morgan runs Pestle's Apothecary in Stormwind's Trade District. William cannot easily leave the Lion's Pride Inn, so he trusts travelers bound for the city to carry his goods. William's parcel holds large candles gathered from kobolds in Elwynn's mines. He collects them for their wax, but does not say how the brothers use it. You carry the shipment to Morgan at Pestle's Apothecary in the Trade District.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_61-e0d1dfe5617cfed9c59f/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["quest:6101"] = {
  hash = "dc9ed1",
  fullHash = "dc9ed1",
  text = "Taming the Beast. In Dolanaar, Dazalar guides you through a second trial for night elf hunters. With an enchanted taming rod, you subdue a nightsaber stalker and learn how wild beasts differ. Dazalar teaches you that the forest's creatures do not all behave alike. Each kind has its own temper, and a hunter must learn how to meet it. Beneath Teldrassil's canopy, this trial sets you against beasts more cunning and predatory than webspinners. Kaldorei revere nightsabers as sacred predators, fierce guardians, and companions of the Sentinels. With the taming rod, you face a nightsaber stalker and must keep a steady nerve and calm authority. Winning its trust proves you can handle a predator, not only the gentler creatures of the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6101-e52e172785a59091f124/1-0000.mp3", duration = 46.9159184, start = 0},
  },
}
P.transport["quest:6102"] = {
  hash = "b8ae97",
  fullHash = "b8ae97",
  text = "Taming the Beast. In Dolanaar, Taming the Beast brings a young night elf hunter to the last trial of basic training. Under Dazalar’s direction, the hunter tames a predatory owl of the skies before gaining the power to choose a lifelong companion. Night elf hunters must make peace with creatures across Teldrassil to finish their basic beastcraft. After facing beasts of the underbrush, they meet the spirit of the skies: the Strigid Screecher. These watchful birds of prey roost high in the boughs west of Dolanaar. Patience and a steady nerve are needed to pacify one with the enchanted Taming Rod. Taming the Strigid Screecher completes the ancient lessons in communion between kaldorei hunters and nature. The apprentice returns the spent rod to Dazalar, and the training exercises end. Then the hunter gains the full art of calling, dismissing, and permanently taming beasts of their own choosing across Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6102-b6408fb4da9f59784c04/1-0000.mp3", duration = 57.1559184, start = 0},
  },
}
P.transport["quest:6103"] = {
  hash = "472ef5",
  fullHash = "472ef5",
  text = "Training the Beast. In Teldrassil, night elf hunters leave the wilds for Darnassus after taming beasts among the boughs. There, Jocaste teaches them to care for and discipline a companion. Dazalar sends you from the wilds near Dolanaar to Darnassus after you prove you can tame a beast. Before traveling Kalimdor with a loyal companion, you need more than skill with a taming rod. Subduing a wild creature tests your strength and will, but an untrained beast can still be unpredictable. In Darnassus's Cenarion Enclave, Jocaste teaches you to care for a companion. She shows you how to feed your pet, bring it back if tragedy strikes, and train it to fight. For night elves, this bond reflects reverence for nature, not simple control.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6103-95824d11326fd4ae53aa/1-0000.mp3", duration = 47.36, start = 0},
  },
}
P.transport["quest:6121"] = {
  hash = "f68e94",
  fullHash = "f68e94",
  text = "Lessons Anew. Mathrengyl Bearwalker sends Alliance druids from Darnassus to Moonglade to learn the ways of cleansing poison. There, Dendrite Starblaze begins their instruction in venom and toxins. Cenarius teaches druids and blesses them with a bond to the living world. Among his gifts is the power to cleanse venom with a simple incantation. Such power comes with a burden. Before young druids wield it, they learn the hard, ordinary work of fighting toxins without nature's magic. Mathrengyl Bearwalker trains druids in the Cenarion Enclave of Darnassus. Now he sends his student beyond local practice to Moonglade. In Nighthaven, Dendrite Starblaze coordinates the Cenarion Circle's wider efforts. He has practical work for the novice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6121-69614b787490e1b137b5/1-0000.mp3", duration = 48.9534694, start = 0},
  },
}
P.transport["quest:6122"] = {
  hash = "536e7e",
  fullHash = "536e7e",
  text = "The Principal Source. At Cliffspring Falls, sick deer have drawn the Cenarion Circle to the water. Dendrite Starblaze sends young druids from Moonglade to gather a sample for Auberdine naturalist Alanndarian Nightsong. Cliffspring Falls feeds northern Darkshore with fresh water. When deer began to suffer a lingering sickness, the Cenarion Circle looked to the river for its cause. Dendrite Starblaze in Moonglade suspects the water is tainted. He sends novice druids to gather a sample at the cavern mouth beneath the falls. Vicious naga dwell inside Cliffspring River Cave, near the falls' headwaters. Their presence endangers anyone who comes to study the blight. The Cenarion Circle needs a sample from the cave mouth to learn what is making the wilderness sick.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6122-7c24f02ed1b5269eb43c/1-0000.mp3", duration = 45.9493878, start = 0},
  },
}
P.transport["quest:6123"] = {
  hash = "f07ec4",
  fullHash = "f07ec4",
  text = "Gathering the Cure. In Darkshore, sick deer need a salve, and Alanndarian Nightsong in Auberdine shows a young druid how to make one. The remedy calls for water and healing plants gathered nearby. Alanndarian Nightsong seeks a cure for Darkshore's sick deer. A contaminated water source has harmed the local wildlife, so sampled Cliffspring water will form the salve's base. Natural ingredients with healing power must complete the mixture. The deer cannot recover alone, and the Cenarion Circle needs a remedy soon. Earthroot and Lunar Fungus lend healing power to the salve. Earthroot grows in rocky soil, where a practiced herbalist's eye helps find it. Lunar Fungus blooms in caves east of Auberdine. The moonkin there have grown territorial and agitated, making the gathering more dangerous.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6123-513b93f34a8be199f1e5/1-0000.mp3", duration = 49.8677551, start = 0},
  },
}
P.transport["quest:6124"] = {
  hash = "c2d6cc",
  fullHash = "c2d6cc",
  text = "Curing the Sick. Across Darkshore, deer are falling sick, and Curing the Sick brings you a way to help them. Alanndarian Nightsong gives you salve for the poisoned animals before you report to the Cenarion Circle in Moonglade. Deer are falling sick across Darkshore, from the Cliffspring River south to the border of Ashenvale. They wander the misty woods, weakened by toxins in the soil and streams. After you gather the needed reagents, Alanndarian Nightsong gives you freshly brewed animal salve to treat them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6124-c4b43d252175736d1b29/1-0000.mp3", duration = 31.0073469, start = 0},
  },
}
P.transport["quest:6125"] = {
  hash = "3d2640",
  fullHash = "3d2640",
  text = "Power over Poison. In Darnassus, Power over Poison brings a young druid back to finish the Cenarion Circle's trial. It began in Darkshore, where the initiate learned to brew a remedy by hand. In Darkshore, Alanndarian Nightsong sends young druids to gather Earthroot and Lunar Fungus by hand. They use them to brew a salve for stricken wildlife. Before teaching the magic that purges toxins, the Cenarion Circle asks initiates to learn the hardship of treating poison without spiritual aid. That work shows them what common folk endure when venom strikes, and why a druid must meet their suffering with care. The remedy proves effective in Auberdine, and Starblaze sends the druid across the sea to Darnassus. Mathrengyl Bearwalker waits in the Cenarion Enclave. Pleased by the initiate's grace under pressure, he teaches them to cleanse toxins through nature's power. Yet virulent poisons in the wilds around Auberdine trouble him. They point to an unnatural blight that disturbs the land's balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6125-8c55cc4fbde9649e0d62/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["quest:6126"] = {
  hash = "6ab9d1",
  fullHash = "6ab9d1",
  text = "Lessons Anew. In Thunder Bluff, Turak Runetotem sends young tauren druids to sacred Moonglade to learn the cleansing of poisons. Under Dendrite Starblaze, a night elf druid, apprentices begin that study as real poisonings call for more than practice. Cenarius granted druids an incantation to purge virulent toxins, and charged them to protect the wilds. Turak Runetotem teaches that such magic needs a firm grounding. Before using it to clear a blight, a druid must understand venom’s physical toll and learn to treat it by ordinary means. Turak sends promising acolytes north from Mulgore along sacred pathways to Moonglade. There, in the peaceful village of Nighthaven, ancient night elf mentors such as Dendrite Starblaze teach practitioners of both elf and tauren kind. Their shared study reflects the Cenarion Circle’s delicate truce, rising above the political strife between Horde and Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6126-ec0309a9bd3da1576dbe/1-0000.mp3", duration = 59.637551, start = 0},
  },
}
P.transport["quest:6127"] = {
  hash = "219ff9",
  fullHash = "219ff9",
  text = "The Principal Source. From Moonglade, Dendrite Starblaze sends Horde druids to Dreadmist Peak for a sample of water. She asks them to carry it to Tonga Runetotem at the Crossroads, where it may explain the poison harming wildlife. Dendrite Starblaze fears the Burning Blade has tainted Dreadmist Peak. The mountain rises northwest of the Crossroads, above the dry northern Barrens. Springs and pools crown its heights, shaping the local weather and moisture. Now a cult devoted to demons has taken hold on the crags, and its foul sorcery may poison the basin. Sick gazelles stumble across the northern savanna, north of the main east-west trail through the Crossroads. Tonga Runetotem seeks help for the local tauren and asks the Cenarion Circle to learn what is poisoning the herd. A water sample from the peak will let him study the sickness and brew an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6127-1da486e325d35f5bdebd/1-0000.mp3", duration = 53.6293878, start = 0},
  },
}
P.transport["quest:6128"] = {
  hash = "294bdc",
  fullHash = "294bdc",
  text = "Gathering the Cure. At the Crossroads, Tonga Runetotem guides young tauren druids through a sacred passage. You gather earthroot and sturdy kodo horns for a salve to treat the poisoned gazelles of the Barrens. Tonga Runetotem needs ingredients for an antidote, using the water sample you secured at Dreadmist Peak. Earthroot gives the salve its medicinal qualities, while ground kodo horn lends it the strength to drive venom from a creature's system. For a young druid, gathering these means relying on the earth's gifts and hunting local beasts. As Tonga Runetotem prepares the salve, he teaches the limits of physical medicine. Herbal lore and alchemy can counter certain toxins, but most poisons need their own cure. Rather than carry endless herbs and horns, druids learn to attune to nature's healing energies. That lesson leads to the druidic art of Cure Poison.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6128-cc807659cc612f4260b0/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["quest:6129"] = {
  hash = "683a6e",
  fullHash = "683a6e",
  text = "Curing the Sick. Sick gazelles are suffering across the northern Barrens. Tonga Runetotem sends young Horde druids to treat them with a freshly made herbal salve, then sends them before the Cenarion Circle in Moonglade. An unnatural sickness is spreading among gazelles in the northern Barrens. You have gathered earthroot and kodo horns for a curative remedy, and Tonga Runetotem at the Crossroads now entrusts the animals to your care. Search north of the main crossroads and tend to ten suffering gazelles. The salve brings them relief before the affliction takes deeper hold in the ecosystem. After you apply the salve, you travel to Moonglade’s tranquil druidic sanctuary. Dendrite Starblaze recognizes your compassion and vigilance there. He says the gazelles’ suffering points to a deeper corruption stalking Kalimdor’s wilderness. By tending even the lowliest beasts, tauren druids show that reverence for Cenarius reaches beyond tribal boundaries. They earn deeper secrets of poison cleansing and nature magic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6129-08562bb685ca10e1e594/1-0000.mp3", duration = 61.3616327, start = 0},
  },
}
P.transport["quest:6130"] = {
  hash = "07b8ef",
  fullHash = "07b8ef",
  text = "Power over Poison. At Thunder Bluff, a young Horde druid returns to claim the gift of Cure Poison. The initiate has treated poisoned gazelles near the Crossroads with herbal mixtures and now faces Turak Runetotem on the Elder Rise. The Cenarion Circle asks a druid to learn how affliction feels before granting the power to cleanse venom. Dendrite Starblaze sends the novice to the Crossroads, where Tonga Runetotem has them gather ingredients for a salve. By treating the Barrens' poisoned gazelles by hand, without spiritual aid, the druid sees how ordinary creatures struggle against natural and unnatural toxins. After the trial, Dendrite sends the initiate to Turak Runetotem, the grand druid trainer on Thunder Bluff's Elder Rise. Turak warns that strange, virulent poisons near the Crossroads threaten the plains' natural balance. He commends the initiate's grace under pressure and grants the spiritual art of curing poisons. The living creatures of Kalimdor are now in the initiate's care.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6130-d29c21bb03dfe7a10638/1-0000.mp3", duration = 60.3689796, start = 0},
  },
}
P.transport["quest:6181"] = {
  hash = "a6723d",
  fullHash = "a6723d",
  text = "A Swift Message. Quartermaster Lewis needs armor for Westfall's militia, and he sends an urgent note to Stormwind by gryphon. With little help from the kingdom's forces, he asks you to take the requisition to Thor at Sentinel Hill for the flight to the capital. At Sentinel Hill, the People's Militia faces Defias outlaws and gnolls with little help from Stormwind's forces. Quartermaster Lewis relies on private contacts in the capital for weapons and armor. As the militia's supplies run low, he turns to Osric Strang, an armorer in Old Town. Lewis asks travelers to carry the urgent requisition note to Thor, Westfall's gryphon master. Gryphons carry people and messages swiftly across the Kingdom of Stormwind. Thor manages the air route to the capital from Sentinel Hill. When you give him Lewis's note, he carries the requisition to Stormwind by air. This route links Westfall's frontier garrison to the capital despite the lack of official aid.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6181-bd23dd9c3c984b0195df/1-0000.mp3", duration = 54.2040816, start = 0},
  },
}
P.transport["quest:62"] = {
  hash = "e8eaf2",
  fullHash = "e8eaf2",
  text = "The Fargodeep Mine. South of Goldshire, Marshal Dughan sends you to scout the kobold-held Fargodeep Mine. It lies between the Stonefield and Maclure farms, and its fall points to trouble beyond its tunnels. Kobolds have taken the Fargodeep Mine south of Goldshire, between the feuding Stonefield and Maclure homesteads. It once supplied stone and ore for the realm. Now shrill chattering echoes through its damp tunnels, where tallow candles burn. Marshal Dughan sends you to scout the depths and learn how bad the trouble is. When Dughan hears your report, he worries about other mineral sites, including the Jasperlode Mine to the northeast. The news adds to the Stormwind Guard's strain. Its troops are already stretched thin defending against Defias bandits and gnoll incursions, leaving too few to clear the tunnels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_62-ffa76af611ac7a794ce0/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:6261"] = {
  hash = "93dbaa",
  fullHash = "93dbaa",
  text = "Dungar Longdrink. At the roost in Stormwind's Trade District, Dungar Longdrink arranges swift gryphon flights for supplies bound to Westfall's defenders. Defias outlaws and feral harvest golems have brought Westfall close to breaking. Quartermaster Lewis and the People's Militia badly need provisions. Lewis sent word to the capital, and armorer Osric Strang packed the equipment they asked for. Carrying military cargo on foot through bandit-ridden Elwynn and Westfall takes precious time. Stormwind's new aerial routes offer a vital link to the frontier. In Stormwind's Trade District, the gryphon roost is where Dungar Longdrink coordinates courier and passenger flights. Wildhammer dwarves have long raised and handled these great beasts. Gryphons carry people and cargo across human lands when roosts at both ends know the route. Bringing Osric's heavy crate straight to Dungar shows how aerial transport works. It links the capital's stockpiles to frontier outposts such as Sentinel Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6261-a023da119500202d0202/1-0000.mp3", duration = 60.2122449, start = 0},
  },
}
P.transport["quest:6281"] = {
  hash = "77db79",
  fullHash = "77db79",
  text = "Continue to Stormwind. You carry a requisition from Sentinel Hill to Stormwind by gryphon, where Osric Strang awaits in Old Town. Quartermaster Lewis prepares a requisition note at Sentinel Hill. Thor, the local gryphon master, offers you the fastest way out of the contested plains. For a modest fee, you ride one of the kingdom’s trained gryphons above dusty farmlands and Elwynn Forest’s river border. Then the gryphon carries you over Stormwind City’s high white ramparts. You land at the capital’s trade roosts, then make your way into Old Town. There you find Osric Strang at his shop, Limited Immunity. Osric supplies the frontier, yet his grim reception shows the growing rift between Westfall’s beleaguered People’s Militia and the distracted rulers in Stormwind Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6281-7b308e76724bc0b682cd/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["quest:6285"] = {
  hash = "93eac9",
  fullHash = "93eac9",
  text = "Return to Lewis. A crate of armor is bound for the People's Militia at Sentinel Hill, and Dungar Longdrink sends it from Stormwind by gryphon. The flight crosses Elwynn and Westfall to reach defenders under pressure. Osric, an armorer in Stormwind's Old Town, has packed a heavy crate of armor for the People's Militia volunteers at Sentinel Hill. Defias bandits, hungry gnolls, and mechanical harvest reapers threaten Westfall. A lone wagon is an easy target on those roads, so the flight master network gives the armor a safer way to the defenders. Gryphons are loyal and well trained, but they need a known destination before they carry a rider there. Dungar Longdrink explains that they instinctively return to their capital roost in Stormwind. For a remote outpost, you first meet its flight master in person. You have already checked in with Thor at Sentinel Hill, opening the skies over the frontier to swift travel. At Sentinel Hill, Quartermaster Lewis receives the crate and begins distributing its armor among the frontier defenders. He outfits Gryan Stoutmantle's volunteer force. Each shipment helps the militia hold its ground against the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6285-7023af6f19e9abce3002/1-0000.mp3", duration = 70.5828571, start = 0},
  },
}
P.transport["quest:6321"] = {
  hash = "f38c5d",
  fullHash = "f38c5d",
  text = "Supplying the Sepulcher. At the Sepulcher, Deathguard Podrig seeks arms for a garrison worn down by the fighting. He sends an order to the Undercity as beasts, Scourge and other threats drain its stores. Deathguard Podrig says the Sepulcher has fair stores, yet fighting in Silverpine Forest steadily uses them up. Feral beasts, Scourge remnants and other local threats damage weapons and armor or leave them behind after skirmishes. Under Executor Hadrec's orders, Podrig writes a request to Gordon Wendham, a weapon dealer in the Undercity. Replacement arms and armor help the Forsaken hold their fragile footholds beyond Tirisfal Glades. Silverpine's roads make a slow and dangerous way to carry vital messages and supplies. So the Forsaken send them by trained vampire bats. At the Sepulcher, Karos Razok handles the bats and links its soldiers to the Undercity's aerial network. Those routes connect outlying garrisons to Sylvanas's capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6321-4af48c44e93cc6bcc79c/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["quest:6322"] = {
  hash = "7ab697",
  fullHash = "7ab697",
  text = "Michael Garrett. In the Undercity, Michael Garrett waits for a crate bound for the Sepulcher. Gordon Wendham packs field supplies in the Trade Quarter, and you bring them to Garrett for the Forsaken bats to carry toward Silverpine Forest. The Forsaken send supplies from the Undercity to outposts such as the Sepulcher in Silverpine Forest. In the Trade Quarter, Gordon Wendham packs field supplies into a crate. Ground travel through blighted forests is slow, and Scourge remnants or wild beasts may ambush the freight. The Forsaken avoid dangerous roads with captive vampire bats, bred and kept by skilled handlers. Michael Garrett tends the bats from his roost in the Undercity's Trade Quarter. When you bring him the cargo, he can strap it to a bat for flight over the hills toward Silverpine. The bats link the capital with its outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6322-bd836ae68c81680e1b10/1-0000.mp3", duration = 50.7036735, start = 0},
  },
}
P.transport["quest:6323"] = {
  hash = "a98666",
  fullHash = "a98666",
  text = "Ride to the Undercity. From the Sepulcher, a courier carries Podrig's weapons request to the Undercity. A dread bat bears the message over Silverpine Forest to the Forsaken capital. Karos Razok handles the dread bats at the Sepulcher in Silverpine Forest. The bats carry messengers and supplies between the Forsaken capital and its frontline outposts. Roads below run through danger from hostile beasts, Moonrage worgen, and Scourge remnants. So the bats give military requests a swift route to the capital. In the Undercity's Trade Quarter, the courier brings Podrig's equipment request to Gordon Wendham. The weaponsmith prepares arms for the Dark Lady's cause. He keeps outposts such as the Sepulcher supplied with weapons ready for battle. Those outposts defend the young Forsaken nation from its surrounding enemies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6323-b2f720b29486dc1b6467/1-0000.mp3", duration = 51.435102, start = 0},
  },
}
P.transport["quest:6324"] = {
  hash = "db8ba4",
  fullHash = "db8ba4",
  text = "Return to Podrig. At the Undercity, you carry weapons bound for the Sepulcher after bringing a dispatch to the capital. Forsaken bats take you across Lordaeron to Deathguard Podrig. Deathguard Podrig's garrison at the Sepulcher needs weapons from the Undercity. Its sentries in Silverpine Forest face worgen, Dalaran remnants, and Scourge stragglers. Fresh arms help the Forsaken hold the region and keep the outpost ready. Bat Master Michael Garrett tends the central roost in the Undercity's Trade Quarter. Forsaken bats know the way back to the capital, but you speak with local handlers such as Karos Razok before flying to a distant outpost. Carrying Gordon's Crate across Lordaeron joins the Undercity's supplies to its scattered strongholds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6324-495a4612d4588bf02cc4/1-0000.mp3", duration = 47.2555102, start = 0},
  },
}
P.transport["quest:6341"] = {
  hash = "0212a2",
  fullHash = "0212a2",
  text = "The Bounty of Teldrassil. Nessa Shadowsong is comparing Teldrassil's fish with the mainland catch. She sends samples from Rut'theran Village to Auberdine to learn whether the island fish are larger and more plentiful. Nessa Shadowsong asks you to carry fish bones and scales to Laird in Auberdine. Fishers in Rut'theran Village bring in large, plentiful catches. Nessa wants to learn whether the mainland waters yield the same kind of fish. The samples let Laird compare the island catch with fish from the coast of Darkshore. Nessa Shadowsong sends you to Vesprystus, the hippogryph master in Rut'theran Village, with the collection for Auberdine. Give him the samples, and he arranges your passage across the water to Darkshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6341-7ce720790c0168ff1d1c/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:6342"] = {
  hash = "50c1c2",
  fullHash = "50c1c2",
  text = "Flight to Auberdine. You carry unusual fish specimens from Teldrassil to Auberdine for Laird. Vesprystus sends you from Rut'theran Village by hippogryph. From Rut'theran Village, you fly by hippogryph toward Darkshore with fish specimens for Nessa Shadowsong. The village is a sanctuary at the edge of the wider world for young adventurers leaving Teldrassil. A ferry also crosses the strait between the island and mainland Kalimdor, while night elves travel by bonded hippogryph. At Auberdine's docks, Laird examines Nessa's findings. The scales are as large as fists, and the jawbone is nearly twice the size of mainland specimens. Waters around the base of the World Tree seem to yield altered or abnormally large life. The strange catches may be tied to Teldrassil's potent, restless nature.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6342-8b5b6eb54e7f45c60c6e/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["quest:6343"] = {
  hash = "3b8271",
  fullHash = "3b8271",
  text = "Return to Nessa. Laird sends you from Auberdine to Nessa Shadowsong in Rut'theran Village with his findings. This introductory errand teaches young travelers to cross between Kalimdor and Teldrassil. Laird sends you back across the water with his written observations. Fish caught off Darkshore differ sharply from those near Teldrassil. He suspects the great World Tree changes the life in these waters. You can hire a flight from Caylais Moonfeather, the hippogryph master, or take the regular ferry from Auberdine's pier to Rut'theran Village. At Rut'theran Village, Nessa Shadowsong receives Laird's reply and is fascinated by the difference in marine life. Fish near the World Tree grow so large that local fishermen benefit at once, though the Kaldorei do not know why. Nessa plans to share the findings with her fellow villagers. For now, she harvests the abundant sea life and watches for whatever forces may be responsible.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6343-8598f92cc37d17ab6148/1-0000.mp3", duration = 53.9428571, start = 0},
  },
}
P.transport["quest:6344"] = {
  hash = "409a5e",
  fullHash = "409a5e",
  text = "Nessa Shadowsong. Below the World Tree in Darnassus, Mydrannul sends a courier to meet Nessa Shadowsong. The delivery runs from Rut'theran Village to Darkshore, linking the city in the canopy with the shore. In Darnassus, Mydrannul watches over travelers looking for work and purpose. Fishing merchant Nessa Shadowsong needs a package carried across the sea to Darkshore, so Mydrannul sends capable couriers toward the coast. Many young night elves begin their journeys among Teldrassil's boughs. This delivery takes them beyond the tree. From the Temple Gardens, the western portal in Darnassus leads down through the World Tree to Rut'theran Village. At the ocean-level roots, fishing docks and hippogryph perches connect Teldrassil with the rest of Kalimdor. Nessa Shadowsong tends her trade there and prepares shipments for Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6344-b83f347febcbc465df1d/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:6361"] = {
  hash = "220eef",
  fullHash = "220eef",
  text = "A Bundle of Hides. Jahan Hawkwing sends cured hides from the Crossroads to Thunder Bluff for leatherworking. You carry them across central Kalimdor and see how the Crossroads wind rider roost links Horde settlements. Hunters bring hides and meat to the Crossroads. There, Jahan Hawkwing gathers pelts from across the Barrens. The outposts cannot work every raw hide, so he asks you to carry them west to Thunder Bluff. Its master leatherworkers can make the pelts into gear for the Horde. The trail through the Barrens and into Mulgore is rough. Quilboar and predators threaten anyone carrying cargo on foot. So Jahan sends you to Devrak, the Crossroads wind rider master. A trained wyvern can carry the goods through the air and link the Horde’s scattered settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6361-923421bd7d597ace9460/1-0000.mp3", duration = 46.4718367, start = 0},
  },
}
P.transport["quest:6362"] = {
  hash = "2fbff5",
  fullHash = "2fbff5",
  text = "Ride to Thunder Bluff. Your wind rider carries cured hides from the Crossroads to Thunder Bluff, high above the plains. The flight joins the Barrens to the Horde capital. Devrak carries travelers over the Barrens on a wind rider. For many, it is their first flight across Kalimdor. These wyverns link the young Horde’s scattered settlements and spare travelers the ground roads, where quilboar and centaur packs roam. Cured hides from the Barrens are bound for Ahanu, a craftsman at Hewa’s Armory in Thunder Bluff. He works beneath the great wind rider roost on the central mesa. Supplies from hunting outposts across the plains help him outfit local warriors and hunters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6362-395289c2e883857569b3/1-0000.mp3", duration = 41.5608163, start = 0},
  },
}
P.transport["quest:6363"] = {
  hash = "c90702",
  fullHash = "c90702",
  text = "Tal the Wind Rider Master. In Thunder Bluff, Tal the Wind Rider Master waits for Ahanu’s parcel. It is bound for Jahan Hawkwing at the Crossroads, where Mulgore’s leatherworkers trade with Barrens merchants. From Thunder Bluff’s lower rise, Ahanu sends finished hides to Jahan Hawkwing’s trade stall at the Crossroads. Trade between Mulgore and the Barrens matters to the young Horde. The journey down the bluffs and across the plains takes hours on foot, so winged couriers carry parcels over the divide. On Thunder Bluff’s highest central tier, Tal tends the city’s wind riders, also called wyverns. They cross Kalimdor’s rugged peaks and shifting thermal drafts. Tal arranges flights to outposts such as the Crossroads, carrying messengers and cargo between the tauren capital and its orcish allies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6363-5c735b38a071ab6104f9/1-0000.mp3", duration = 48.8489796, start = 0},
  },
}
P.transport["quest:6364"] = {
  hash = "b6bc02",
  fullHash = "b6bc02",
  text = "Return to Jahan. You return finished leather goods to Jahan Hawkwing at the Crossroads. The journey begins after you bring hides to Ahanu, Thunder Bluff’s skinner, and introduces you to the Horde’s wind rider routes between Mulgore and the Barrens. Tal, Thunder Bluff’s wind rider master, arranges flights across central Kalimdor from the central mesa. For many travelers, this is their first ride on a trained wind rider. Once you have met another settlement’s wind rider master, such as Devrak at the Crossroads, a rider can carry you there. The beasts cross leagues that would otherwise make for a dangerous overland journey through the Red Rocks and northern Barrens. Jahan Hawkwing trades from the Crossroads, where hunters, scouts, and mercenaries gather each day. The flights carry goods between settlements too. Hides sent to Ahanu on Thunder Bluff’s high rises become durable armor and equipment. Then they fly back to the Barrens crossroads to supply the Horde’s growing frontier efforts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6364-bc457014a0173ee5980d/1-0000.mp3", duration = 59.1412245, start = 0},
  },
}
P.transport["quest:6365"] = {
  hash = "ead76d",
  fullHash = "ead76d",
  text = "Meats to Orgrimmar. At the Crossroads, Zargh sends Barrens meat toward Orgrimmar. He asks young orc and troll adventurers to deliver it to Devrak, the wind rider master, and learn the route to the Horde capital. Wild game runs across the Barrens, from zhevras and plainstriders to kodos and thunder lizards. Zargh has cut meat for Gryshka, the innkeeper in Orgrimmar's Valley of Strength. He sends runners from the Crossroads to the wind rider perch instead of risking the long, dusty trek across the Southfury River into Durotar. Meeting Devrak gives a young Horde warrior a first glimpse of the wind rider routes. Wind rider masters link remote places like the Crossroads to the Horde's fortified seat in Orgrimmar. Devrak prepares you and the cargo for a swift flight over the savannah.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6365-4bae1f411a06ac54265d/1-0000.mp3", duration = 48.5355102, start = 0},
  },
}
P.transport["quest:6384"] = {
  hash = "efb544",
  fullHash = "efb544",
  text = "Ride to Orgrimmar. From the Crossroads, you fly with Zargh’s fresh cuts of meat to Orgrimmar’s Skytower. There, you deliver them to Innkeeper Gryshka. Devrak sends trained wind riders between the Crossroads and Orgrimmar. Their flight crosses the dry Barrens and reaches Durotar’s red cliffs, sparing travelers the hard journey on foot. High above the dusty canyon trails, wyverns carry messengers and travelers to the capital, along with dispatches and trade goods. Zargh has prepared fresh cuts of meat for Innkeeper Gryshka in Orgrimmar’s Valley of Strength. From the central Skytower, her inn is a short walk away. Gryshka accepts the parcel and fondly remarks that Zargh knows how to win a lady’s heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6384-0b41b886278d04275213/1-0000.mp3", duration = 42.7885714, start = 0},
  },
}
P.transport["quest:6385"] = {
  hash = "601dcf",
  fullHash = "601dcf",
  text = "Doras the Wind Rider Master. Innkeeper Gryshka has thanks for Zargh at the Crossroads and needs a courier to carry them. She sends you to Doras the Wind Rider Master at Orgrimmar’s skytower to arrange your flight back to the Barrens. Innkeeper Gryshka sends Zargh her thanks after his shipment of meat arrives safely from the Barrens hunting grounds. She has no time to travel through Durotar herself. So she trusts the aerial couriers who link Horde settlements to carry her letter across the frontier. At the flight tower in the Valley of Strength, Doras oversees Orgrimmar’s wind rider roost. Trained wyverns carry military messages and supplies between the capital and outposts such as the Crossroads. They travel far faster than anyone on foot or in a kodo cart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6385-d6a5b64de09ce43c21d3/1-0000.mp3", duration = 45.6620408, start = 0},
  },
}
P.transport["quest:6386"] = {
  hash = "665667",
  fullHash = "665667",
  text = "Return to the Crossroads.. Gryshka's reply travels from Orgrimmar to Zargh at the Crossroads. A wind rider bears it across Durotar and the Barrens. You carry Gryshka's written reply to Zargh after bringing her a parcel of prime meat in Orgrimmar. Doras, the wind rider master atop Orgrimmar's high bluffs, provides your mount for the return to the Barrens.\n\nYou have already met Devrak at the Crossroads, so the wyverns know the flight path. The ride crosses the desert sky and spares you the long march overland across the Southfury River. Zargh's courtship has won Gryshka's warm reply. The fine provisions pleased her, and Zargh celebrates, even musing about an impending wedding.\n\nThe delivery also brings you back to the Barrens' central hub for travel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6386-b7c24fcd6bf41252afa0/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["quest:6387"] = {
  hash = "a5d1e6",
  fullHash = "a5d1e6",
  text = "Honor Students. Brock Stoneseeker sends an order from Thelsamar to Ironforge for honorary mining picks. He asks you to enlist Thorgrum Borrelson to carry it there. Brock teaches new miners about rock composition and tunnel safety. He rewards the apprentices who distinguish themselves with honorary picks. Mining sustains Thelsamar, and dwarves take pride in the craft. Local supplies are limited, so the picks must come from Ironforge across Khaz Modan. Thorgrum tends the gryphon roost beside Thelsamar, linking the frontier to Ironforge through the kingdom's aerial courier network. Bring Brock's order to him, and he can arrange a swift courier run to the capital's foundries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6387-27c03933368f92c7f886/1-0000.mp3", duration = 42.1093878, start = 0},
  },
}
P.transport["quest:6388"] = {
  hash = "a703ce",
  fullHash = "a703ce",
  text = "Gryth Thurden. In Ironforge, Gryth Thurden can send you back toward Loch Modan with a parcel. You carry the Honorary Picks from Golnir Bouldertoe for Brock Stoneseeker's mining apprentices, and the city's gryphon roost offers a way over the mountain roads. You have traveled from Loch Modan to the Great Forge, where Golnir Bouldertoe gives you Honorary Picks for Brock Stoneseeker's mining apprentices. He points you to Ironforge's gryphon network instead of the mountain passes on foot. Carry the bundle across the city to the master handler, who can arrange your flight back. Gryth Thurden oversees Ironforge's flight roosts in the great mountain hall. Gryphon routes link the city with dwarven settlements across Khaz Modan. After scouting the route and speaking with the local handler, you can ask Gryth to arrange transport back to Thorgrum Borrelson in Thelsamar. The picks are bound for Brock Stoneseeker's apprentices, and the route joins mountain settlements by air.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6388-6bc821d8598441690dcd/1-0000.mp3", duration = 57.5738776, start = 0},
  },
}
P.transport["quest:6391"] = {
  hash = "56c8bc",
  fullHash = "56c8bc",
  text = "Ride to Ironforge. Brock Stoneseeker sends you from Thelsamar to Ironforge with the names of his finest mining students. You carry his list to Golnir Bouldertoe at the Great Forge. Thorgrum Borrelson carries you from Thelsamar over Dun Morogh's snowy ridges to the mountain fortress. For many young mountaineers and travelers, this is their first flight on a gryphon. At the Great Forge, Golnir Bouldertoe carves the students' names into ceremonial honorary picks. These honors recognize their hard work in Loch Modan's quarries and mines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6391-be2fa242a1c3797c9c4d/1-0000.mp3", duration = 33.9853061, start = 0},
  },
}
P.transport["quest:6392"] = {
  hash = "561a8c",
  fullHash = "561a8c",
  text = "Return to Brock. You carry Brock Stoneseeker’s missive to Ironforge and receive Honorary Picks for his apprentices. Gryth Thurden can fly you back to Thelsamar. Gryth Thurden oversees Ironforge’s gryphon flights from the city’s central platform. To fly to Thelsamar, you first need to have met its handler, Thorgrum Borrelson. Then Gryth can carry you and the picks over the mountains, returning Brock’s message and tools to the Loch. Brock Stoneseeker teaches mining in Thelsamar and needs tools for his apprentices. The Honorary Picks will let young miners work the rich copper and tin veins in the hills around the Loch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6392-1f5a5f4085d30b1ef8c8/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["quest:6395"] = {
  hash = "1ec06f",
  fullHash = "1ec06f",
  text = "Marla's Last Wish. In Deathknell, Marla's Last Wish brings a husband and wife together in death. Novice Elreth asks you to find Samuel Fipps, still bound to the Scourge, so he may be buried beside Marla. The Forsaken honor the ties of life and set themselves apart from the Scourge. Before the Third War, Marla and Samuel Fipps were husband and wife in Lordaeron. The war devastated their home, and when the plague swept through their lands, Samuel succumbed. He rose as a mindless thrall of the Scourge. Marla escaped undeath, but Samuel killed her in his frenzy. She bore him no hatred. Novice Elreth remembers Marla's final wish: to rest beside Samuel in the Deathknell graveyard. Novice Elreth sends you northeast of Deathknell, where Samuel Fipps still wanders among a ruined campsite. Ending his torment removes a Scourge minion from the valley. Then his remains can be carried back to Marla's resting place. Elreth believes that honoring the dead and their final wishes sets the newly freed Forsaken apart from the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6395-382c6daf7e1f9e90cc16/1-0000.mp3", duration = 66.8995918, start = 0},
  },
}
P.transport["quest:64"] = {
  hash = "e8c6ab",
  fullHash = "e8c6ab",
  text = "The Forgotten Heirloom. In Westfall, The Forgotten Heirloom is a pocket watch left behind as the Furlbrows fled their farm. Recovering it gives them a chance to reclaim something personal amid the chaos. Farmer Furlbrow and Verna were driven from their Westfall farm by violence. Shouts from the pumpkin patches woke them in the night, leaving little time to gather what they could carry. In their flight, Furlbrow left behind the pocket watch Verna's father gave him on their wedding day. It remains in the wardrobe of their occupied farmhouse. Defias thugs and thieves, including Benny Blaanco, now pick through the abandoned Furlbrow farm. Returning for a keepsake could mean death for ordinary folk. You can take the pocket watch from the wardrobe and restore a measure of dignity to a family that has lost nearly everything to Westfall's lawlessness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_64-3207d7912bd0ae312aa5/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:6401"] = {
  hash = "aadeb6",
  fullHash = "aadeb6",
  text = "Kaya's Alive. Makaba Flathoof has word that Kaya Flathoof survived the Grimtotem attack in Stonetalon. He sends you to Sun Rock Retreat, where her aunt Tammra Windfield waits anxiously. The Grimtotem strike along Stonetalon's contested trails. When their village came under attack, young Kaya Flathoof was feared dead or taken by the renegades. Her rescue brings relief while tribes still fight among the crags. Makaba Flathoof sends you from Kaya to Sun Rock Retreat with news of her safety. Her aunt, Tammra Windfield, waits there anxiously for word from the trails. Your message comforts the family and keeps the remote Horde outpost connected.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6401-2a10ed4f13c828a2aee1/1-0000.mp3", duration = 41.0644898, start = 0},
  },
}
P.transport["quest:6421"] = {
  hash = "865f47",
  fullHash = "865f47",
  text = "Boulderslide Ravine. Kobolds dig for Resonite in the Stonetalon Mountains, while Mor'rogal at Sun Rock Retreat fears a growing unrest in the earth. At Sun Rock Retreat, Mor'rogal watches the Stonetalon peaks and feels the earth stir. An unnatural agitation rises from the southeast. In Boulderslide Ravine, kobolds have abandoned their usual foraging and now dig fiercely for Resonite, a rare mineral from beneath the surface. Mor'rogal sends Horde scouts past the kobolds and into the cave's deepest reaches. He asks them to bring back raw samples and learn why the kobolds mine with such frenzy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6421-bf12369fd19aac6b2753/1-0000.mp3", duration = 36.8326531, start = 0},
  },
}
P.transport["quest:6441"] = {
  hash = "c88ce9",
  fullHash = "c88ce9",
  text = "Satyr Horns. At Splintertree Post, Satyr Horns offer Pixel a chance to trade in Ratchet. The traveling goblin seeks them for the journey south to the port town. At Splintertree Post, Pixel sees a chance to profit while resting between travels. Satyr horns fetch a high price in Ratchet, and Pixel wants them for the journey back south to the port town. Rather than face the corrupted creatures, Pixel hires passing adventurers to bring back sixteen intact horns. Demonic satyrs haunt scattered, fel-tainted ruins across Ashenvale. They are remnants of a betrayal during the ancient sundering. You can search their strongholds at Night Run, the fortified camp of Satyrnaar, and the shadowed groves of Xavian. Pixel seeks horns from any of these places for Ratchet's merchant wharves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6441-eb2303237c86210ce712/1-0000.mp3", duration = 48.1436735, start = 0},
  },
}
P.transport["quest:6442"] = {
  hash = "e1c342",
  fullHash = "e1c342",
  text = "Naga at the Zoram Strand. Along Ashenvale's coast, Naga threaten the Horde's hold at Zoram Strand. From Zoram'gar Outpost, Marukai seeks to drive the Wrathtail away from the sunken ruins of ancient Zoram. The Horde's hold at Zoram Strand is fragile. The outpost stands amid hostile night elf territory and bitter woodland fighting, yet its coast gives the Horde a link to the sea. Now aggressive naga have crawled ashore. They could cut off that route and overwhelm the small garrison before its defenses are ready. Beneath Zoram Strand's sandy shoals lie the shattered remains of Zoram, an ancient elven city swallowed by the Great Sundering thousands of years ago. Marukai and the outpost's defenders do not know why the Wrathtail have come from the deep trenches now. Their sudden interest in the sunken ruins threatens anyone walking above them. Marukai sees a simple fight for survival. With swords and tridents drawn, reason matters little. She demands twenty severed heads from the Wrathtail. She hopes force will drive the naga back into the depths and secure the shore for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6442-364df2ca9b202ff749eb/1-0000.mp3", duration = 68.9632653, start = 0},
  },
}
P.transport["quest:6461"] = {
  hash = "ea406a",
  fullHash = "ea406a",
  text = "Blood Feeders. In Malaka'jin, Blood Feeders begin with butchered game drawing Deepmoss spiders toward the trolls' camps. Xen'Zilla asks the Horde to drive the predators back from the settlement. The trolls founded Malaka'jin as a frontier outpost in southeastern Stonetalon Mountains, where they could hunt. The craggy slopes offer plenty of game, but its meat draws nocturnal predators into camp. Deepmoss spiders are aggressive arachnids native to the crags and canyons to the north. Under cover of darkness, they slip in to scavenge the trolls' stores or hunt the hunters themselves. Xen'Zilla asks you to track the predators north into the mountain passes. That will help keep Malaka'jin safe and protect its supplies. Deepmoss Creepers and Venomspitters gather thickest around the rocky ravines and webs of Sishir Canyon. Thin their numbers, and the brood will retreat from the settlement. Then the hunters can rest without fearing an ambush from the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6461-403ce7feb46fc16e5b27/1-0000.mp3", duration = 56.6073469, start = 0},
  },
}
P.transport["quest:6462"] = {
  hash = "33be41",
  fullHash = "33be41",
  text = "Troll Charm. At Zoram'gar Outpost, Mitsuwa mourns kin slain on the road and seeks their stolen sacred charms. The Thistlefur furbolgs took the talismans into their den. You are at Zoram'gar Outpost, a remote Horde refuge on Ashenvale's western coast. Woodland paths make the way dangerous. A party of Darkspear trolls never arrived after the Thistlefur furbolgs ambushed them. Mitsuwa accepts that his kin have died and will meet him in the afterlife. Yet the furbolgs stole their sacred charms, and he cannot abide the insult. Troll charms and talismans mark identity, give spiritual protection, and bind their bearers to the Loa. Mitsuwa sees a troll without her charm as hollow and worthless, like an orc without battle scars. The Thistlefur furbolgs carried the stolen charms to Thistlefur Hold, deep in the caves beyond Thistlefur Village. There they hid the talismans in chests, far from their rightful owners.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6462-f4e5373794d265f504c8/1-0000.mp3", duration = 60.2383673, start = 0},
  },
}
P.transport["quest:6482"] = {
  hash = "7da036",
  fullHash = "7da036",
  text = "Freedom to Ruul. In northern Ashenvale, Ruul waits in a cage deep inside Thistlefur Hold. He needs a Horde ally to help him fight through the corrupted furbolg den and reach safety. Ruul Snowhoof, a druid, is trapped in Thistlefur Hold. While exploring the corrupted woods of northern Ashenvale in bear form, he strayed too close to the den. The corrupted furbolgs had lost their ancestral wisdom and, driven by feral paranoia, mistook him for an ordinary beast. They caged and starved him instead of honoring him, draining his magic until he could no longer break free alone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6482-87cb2184154d5a3a13fd/1-0000.mp3", duration = 37.4334694, start = 0},
  },
}
P.transport["quest:65"] = {
  hash = "b6e036",
  fullHash = "b6e036",
  text = "The Defias Brotherhood. From Sentinel Hill, Gryan Stoutmantle sends you east to Lakeshire, where a contact may know where the Defias Brotherhood hides. The People's Militia cannot find who directs the bandits. Gryan Stoutmantle needs the cartel's inner circle and its commander exposed before the thieves can be stopped. Wiley the Black waits upstairs at the Lakeshire inn. Stoutmantle trusts the rogue's underworld ties to reveal the Brotherhood's hideouts. Whether Wiley can offer a lead is still uncertain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_65-a82c81079f6d5f6f00ab/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["quest:6523"] = {
  hash = "ee83a8",
  fullHash = "ee83a8",
  text = "Protect Kaya. In the Stonetalon Mountains, Kaya Flathoof is held captive among hostile Grimtotem tauren. Horde adventurers guide her along dangerous trails to Camp Aparaje, then tell her anxious father, Makaba Flathoof, that she survived. Kaya Flathoof was captured deep in Grimtotem territory in the Stonetalon Mountains. The tauren clans are divided by bitter rivalries, and few face sharper hostility than the Grimtotem. Kaya has escaped captivity, but friendly ground lies beyond trails watched by enemies and predators. An armed escort gives her the best hope of getting through. Kaya aims for Camp Aparaje in the eastern Stonetalon Mountains. From there, she knows the way home and can continue on her own. You guide her along paths where ambushes threaten, helping her avoid recapture on the way to safety.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6523-0e83a0c0e9712c2d23be/1-0000.mp3", duration = 50.2334694, start = 0},
  },
}
P.transport["quest:6541"] = {
  hash = "11dd78",
  fullHash = "11dd78",
  text = "Report to Kadrak. At the Crossroads, Thork sends proven Horde fighters north to Kadrak's watch tower. The orc prepares recruits for the fighting ahead near the Ashenvale border. The Crossroads faces quilboar, centaur, and local brigands. Beyond it, the Horde looks toward Ashenvale's thick forests. Thork sends fighters who have proved themselves in the central Barrens to the tower on the northern border, where Kadrak is stationed. Kadrak watches the southern approach to Ashenvale and organizes reinforcements for the Horde's foothold across the border. Splintertree Post and an outpost along the Zoram Strand help strengthen the Horde's presence in the timber-rich woodlands. Native night elves resist them fiercely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6541-711d3ec42c9f0ba340cc/1-0000.mp3", duration = 44.3820408, start = 0},
  },
}
P.transport["quest:6542"] = {
  hash = "00530c",
  fullHash = "00530c",
  text = "Report to Kadrak. At Malaka'jin, Darn Talongrip sends Horde warriors north to Kadrak's watch post. The journey leads from Stonetalon's crags to Ashenvale, where the Horde holds outposts at Splintertree Post and the Zoram Strand. Darn Talongrip watches the Horde's southern and mountain frontiers from Malaka'jin. The orc sends capable fighters passing through Stonetalon toward the northern Barrens watch tower. Ashenvale is the greater pressure point. There, night elf sentinels clash with Warsong lumber gatherers, and the Horde needs fighters as the struggle for the forest continues. Kadrak oversees Horde troop movements from a watch tower in the northern Barrens, where the savannah meets Ashenvale. The Horde holds outposts at the Zoram Strand in the west and Splintertree Post to the north. Kadrak coordinates supplies and troops, and sends urgent reports across the contested forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6542-e5dec6f2b4da13c747a3/1-0000.mp3", duration = 56.1110204, start = 0},
  },
}
P.transport["quest:6543"] = {
  hash = "78aef1",
  fullHash = "78aef1",
  text = "The Warsong Reports. Couriers from the northern Barrens carry Kadrak's orders and gather the Warsong Reports across Ashenvale. Their field observations come from outriders near Azshara, Splintertree Post, and the Zoram Strand. Kadrak watches the mountain pass between the northern Barrens and Ashenvale from a fortified tower. The Horde needs this route because the Barrens cannot provide the timber Orgrimmar requires. So the Warsong clan has pressed into the ancient elven forest to reach those supplies. Couriers carry orders between scattered patrols and help them keep in step. Yet night elf ambushes threaten the wilderness trails. Warsong scouts watch three parts of Ashenvale. On the western coast, a runner at Zoram'gar Outpost watches naga activity and other coastal threats along the Zoram Strand. At Splintertree Post, a scout coordinates the defense against Sentinel raids. Farther east, an outrider watches the road toward the shattered ruins of Azshara. Their reports give Kadrak a view of night elf movements and weaknesses along the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6543-416f8dfe80d5e46408ea/1-0000.mp3", duration = 65.8808163, start = 0},
  },
}
P.transport["quest:6544"] = {
  hash = "88ca06",
  fullHash = "88ca06",
  text = "Torek's Assault. At Silverwing Outpost, Torek leads a strike against the night elves. Sent by Splintertree Post, the orc raider means to break Sentinel resistance and kill their commander, Duriel Moonfire, in Ashenvale's border war. Across Ashenvale, the Horde's lumber camps and the native night elves are locked in a growing border war. Torek gathers raiders from Splintertree just outside Silverwing Outpost, aiming to break the Alliance's defenses. He charges before the night elves can counterattack or gather strength for a reinforced campaign against Splintertree Post. Silverwing Outpost is a woodland garrison held by Silverwing Sentinels and fierce elven warriors. Torek sets his sights on their leader, Duriel Moonfire. If she falls, the local night elf command loses its head, and the raiders can report their bloody victory to Ertog Ragetusk at Splintertree Post.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6544-0da4a0ffceec5e2a6e8b/1-0000.mp3", duration = 55.2228571, start = 0},
  },
}
P.transport["quest:6545"] = {
  hash = "8c877b",
  fullHash = "8c877b",
  text = "Warsong Runner Update. Across Ashenvale, Warsong Runner Update warns of mounting pressure on the Warsong Clan's border. The report alerts commanders to increasingly bold naga attacks on Horde outposts. Across Ashenvale, Warsong scouts and runners watch the fighting and keep supply lines open. Night elf sentinels and the forest make their work dangerous, so frontier commanders need news quickly. Couriers carry dispatches to remote garrisons and to commanders such as Kadrak at the Mor'shan Rampart. Horde defenders expect night elves among the trees, yet outpost sentries report bolder naga attacks. The serpentine invaders strike from waterways and ancient ruins, testing barricades and drawing defenders from forest and border patrols. A dispatch to the Mor'shan Rampart warns of these coordinated assaults from the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6545-3b4d89b03b65735f063c/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["quest:6548"] = {
  hash = "3d5b06",
  fullHash = "3d5b06",
  text = "Avenge My Village. Makaba Flathoof calls on Horde travelers to answer the Grimtotem assault in southeastern Stonetalon. He barely escaped, cut off from his kin and surrounded by the dead. Now he seeks vengeance at the camp of the ruffians and hired sellswords. Near the Barrens border, Makaba Flathoof is the lone survivor of a massacre in Stonetalon's red stone passes. Grimtotem raiders struck without warning and slaughtered nearly everyone in his settlement. Makaba fought back and brought down several attackers. Then they drove him into hiding with little more than his life and his wrath. The Grimtotem have long troubled the tauren tribes united under High Chieftain Cairne Bloodhoof. Unlike Mulgore's peaceful nomads, their warbands use ruthless ruffians and opportunistic mercenaries to seize territory and strike isolated settlements. Makaba has no thought of diplomacy or tribal kinship now. Only blood repaid with blood can answer his grief.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6548-4f3411d11d43a13d9ec3/1-0000.mp3", duration = 58.5404082, start = 0},
  },
}
P.transport["quest:6608"] = {
  hash = "9fe6ea",
  fullHash = "9fe6ea",
  text = "You Too Good.. Lumak sends you from Orgrimmar to seek his friend Nat Pagle. Your skill has outgrown ordinary lessons, and Nat camps on a distant islet south of Theramore Isle. Lumak teaches fishers in Orgrimmar's Valley of Honor. He sees you have learned all he can teach about rod and reel. So he admits you are too good for ordinary lessons. Artisan fishing calls for knowledge beyond the city and the Horde. Lumak sends you to find his human friend, Nat Pagle. Though the Horde and Alliance clash across Kalimdor, he warns you not to harm or eat Nat. Nat camps on an islet in Dustwallow Marsh, south of Theramore Isle. He keeps clear of politics and cares only whether the fish are biting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6608-0db44b0b4008776a12b8/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["quest:6611"] = {
  hash = "23caae",
  fullHash = "23caae",
  text = "To Gadgetzan You Go!. In Orgrimmar, Zamja sends seasoned Horde cooks south to learn from an eccentric goblin butcher. In the Drag, Zamja trains cooks and feeds warriors and travelers passing through Durotar. When a cook has learned every recipe and technique she knows, Zamja has taught all she can. She sends her pupil to Tanaris, where only a master of strange and exotic meats can help a talented cook advance. Gadgetzan is a steam-powered trading hub in Tanaris, run by the Steamwheedle Cartel. Dirge Quikcleave works inside the town tavern. The eccentric goblin butcher has an unusual palate and no squeamishness about food. Across Kalimdor, he is known for making hearty meals from monstrous desert creatures and sometimes scraps of leather, food for hardened adventurers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6611-4ef05210a38000d208ec/1-0000.mp3", duration = 49.4236735, start = 0},
  },
}
P.transport["quest:6623"] = {
  hash = "eebe6d",
  fullHash = "eebe6d",
  text = "Horde Trauma. At Hammerfall in the Arathi Highlands, Horde Trauma calls skilled healers to the front lines. Doctor Gregory Victor needs hands ready to save lives under extreme pressure. In Orgrimmar's Valley of Spirits, Arnok, the orc first aid trainer, tells proficient healers they have caught Doctor Gregory Victor's attention. Victor oversees Horde Trauma from Hammerfall in the contested hills of the Arathi Highlands. Arnok regards the summons as the highest step in a battlefield surgeon's career. At Hammerfall, constant skirmishes with Stromgarde's forces and hostile local factions leave Doctor Victor flooded with wounded grunts, raiders, and scouts. The chief physician skips the pleasantries. He sends newcomers into their scrubs to prove their worth in fast, brutal emergency triage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6623-369451b6072afdf000e4/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["quest:6625"] = {
  hash = "a98fea",
  fullHash = "a98fea",
  text = "Alliance Trauma. Across the Alliance, accomplished medics are sent to Theramore Isle for service. There, you study under Doctor Gustaf VanHowzen, chief physician of the Alliance's elite medical corps. Your skill with needle, cloth, and triage has drawn Doctor Gustaf VanHowzen's notice. From Theramore Isle, he leads Alliance Trauma, caring for the wounded in Kalimdor's fiercest warzones and beyond. In Ironforge, Nissa Firestone treats VanHowzen's personal summons as a rare privilege. Theramore Isle faces regional threats, skirmishes, and harsh wilderness, so grievously wounded soldiers arrive in a steady stream.\n\nYou cross the sea to Dustwallow Marsh. There, VanHowzen tests how calmly you assess the wounded against his rigorous triage standards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6625-6c4d08b5ab7049800dd7/1-0000.mp3", duration = 50.5208163, start = 0},
  },
}
P.transport["quest:6629"] = {
  hash = "18cefb",
  fullHash = "18cefb",
  text = "Kill Grundig Darkcloud. At Grimtotem Post, Grundig Darkcloud waits after leading the force that sacked Makaba Flathoof's home. Makaba sends you after Grundig once you have struck down the ruffians and mercenaries. Makaba Flathoof survived the Grimtotem assault on his settlement along the Stonetalon trail, but grief still weighs on him. You have proved yourself against Grimtotem foot soldiers. Now Makaba points you toward Grundig Darkcloud, who led the slaughter that leveled the village and commands a devoted band of brutes. Grundig camps at Grimtotem Post, farther up the mountain road to the west. You climb to the stronghold to avenge Makaba's kin and guard the pass from further violence. There you fight through Grundig's brutes and kill him before his raiders can descend on other vulnerable camps.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6629-b1ad17691897f5c3fd1d/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:6641"] = {
  hash = "4a3019",
  fullHash = "4a3019",
  text = "Vorsha the Lasher. At Zoram'gar Outpost, Vorsha the Lasher's attacks threaten the Horde's foothold on Ashenvale's coast. The nearby naga honor the hydra with an offering brazier on an offshore island. Muglash means to extinguish its flame and draw Vorsha ashore. On Ashenvale's northwestern coast, Zoram Strand is one of the most dangerous stretches of shore. Zoram'gar Outpost holds a narrow strip there, facing hostile wildlife, night elves, and serpentine invaders. Vorsha the Lasher is among the strand's worst threats. The gargantuan hydra strikes the outpost without provocation.\n\nShe surges from the surf to crush its defenses and butcher its warriors. Then she vanishes into the deep tides. The nearby naga honor Vorsha's ravenous violence. On a rocky outcrop offshore, they keep an offering brazier burning for her. Muglash, an orc set on ending the outpost's constant harassment, has found a way to draw the hydra out.\n\nDefiling the ritual flame will enrage the naga guardians and Vorsha. In her fury, the hydra will surge to the surface, giving the defenders a chance to draw her into an ambush instead of waiting for another slaughter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6641-deea8bfdd5439a8f5df9/1-0000.mp3", duration = 73.1167347, start = 0},
  },
}
P.transport["quest:6962"] = {
  hash = "191903",
  fullHash = "191903",
  text = "Treats for Great-father Winter. At Smokywood Pastures' display in Orgrimmar, the Greatfather Winter performer is tired of hearing holiday wishes. He asks you for gingerbread cookies and milk. The Greatfather Winter who greets visitors in the Valley of Strength works for Smokywood Pastures. Long hours of hearing citizens speak of festive treats leave him hungry. So he asks passing travelers for warm baking and a cold drink. Holiday Spices from Smokywood Pastures peddlers and Small Eggs from wild birds make the cookies. Bring them together with Ice Cold Milk from a local tavern. Then the feast's organizers offer festive cheer and a small token of gratitude.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6962-16d0018e45dcc36890ee/1-0000.mp3", duration = 39.6277551, start = 0},
  },
}
P.transport["quest:6984"] = {
  hash = "04ff49",
  fullHash = "04ff49",
  text = "A Smokywood Pastures' Thank You!. In Orgrimmar, Kaymard Copperpinch sends you to receive thanks for the stolen holiday treats you recovered. Great-father Winter waits to honor those who brought Smokywood Pastures' supplies back. In Orgrimmar, Smokywood Pastures sells treats, recipes, and seasonal cheer for the Feast of Winter Veil. A shipment was stolen in the snowy hills of the Alterac Mountains, and business stalled. Now the treats are recovered and the Abominable Greench is dealt with. Kaymard Copperpinch sends you to receive the company's thanks. Great-father Winter waits beside the holiday tree in the Valley of Strength. The goblins have arranged for him to honor those who rescued the holiday supplies. He gives them a seasonal blessing and a Smokywood Pastures Special Gift.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6984-4d8b6804819529e98b51/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["quest:7"] = {
  hash = "778bdf",
  fullHash = "778bdf",
  text = "Kobold Camp Cleanup. In Northshire's northern woods, kobold numbers threaten the abbey grounds. Marshal McBride needs the camps cleared, and the valley's defense depends on fresh volunteers. Marshal McBride directs the valley's defense from Northshire Abbey, but he has too few soldiers. So he depends on fresh volunteers like you. Each threat he cannot answer could disrupt the abbey's work or spread into the vineyards nearby. The kobold camps cannot wait. Kobolds are timid, candle-obsessed cave-dwellers who usually pick at underground seams, away from direct sunlight. Now an entire clan has reached the northern timberline. Left alone, their numbers could turn scavenging into open raids. McBride sends you to thin their vanguard and test your resolve to defend the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7-704689ca30c74866dac1/1-0000.mp3", duration = 47.1510204, start = 0},
  },
}
P.transport["quest:7025"] = {
  hash = "aa8db6",
  fullHash = "aa8db6",
  text = "Treats for Greatfather Winter. In Ironforge, the dwarf playing Greatfather Winter asks you for a holiday treat. Bring five freshly baked gingerbread cookies and ice cold milk, and he thanks you with a festive gift. Smokywood Pastures sponsors the Winter Veil festivities in Ironforge. By the holiday tree in the Commons, a performer sits dressed as Greatfather Winter. For hours, he hears holiday wishes from citizens and eager children. He wears the guise of an immortal figure from ancient titan lore and dwarven myth. After hearing requests for gifts all day, the performer grows hungry. He asks for five freshly baked gingerbread cookies and ice cold milk. The simple meal gives the exhausted festival worker a moment of relief. Your kindness spreads goodwill through Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7025-0e5066ce6a107db5ce7f/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["quest:71"] = {
  hash = "33b58e",
  fullHash = "33b58e",
  text = "Report to Thomas. Guard Thomas waits at the eastern bridge between Goldshire and the Eastvale Logging Camp. The fate of his missing men may show whether the river murlocs threaten more than scouts. With few men to spare at the crossing, Thomas had hoped Malakai and Rolf were only cut off or delayed in the riverlands. Their recovered service medallions leave no such hope. Both guards were slain near the waterways. For months, Stormwind's leaders have treated murlocs as nuisance river-dwellers, focusing instead on bandits and the kingdom's wider borders. Now two armed Stormwind guards have been slaughtered along the inland streams. The medallions show Thomas that Elwynn's eastern frontier faces an active assault, and he calls for a response before the logging routes and settlements are overwhelmed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_71-6c389c9718b199fde953/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["quest:730"] = {
  hash = "f787fd",
  fullHash = "f787fd",
  text = "Trouble in Darkshore?. In Darnassus, Chief Archaeologist Greywhisker needs help finding his missing crew. His appeal sends you across the sea to Auberdine, where the dwarven expedition met trouble along Darkshore’s wild coast. Darnassus is the grand night elven capital, and home to dwarven researchers from Ironforge who study Kalimdor’s ancient mysteries. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to uncover ancient artifacts. Weeks have passed without word or a progress report. Greywhisker fears dangers have overtaken his field crew. Greywhisker laments that many in the Alliance dismiss dwarven archaeology as an eccentric hobby. Discoveries in Khaz Modan have convinced his colleagues that a terrifying ancient force threatens Azeroth from Lordaeron to Kalimdor. So the work in Darkshore’s ruins is more than scholarship. The expedition seeks to understand historic cataclysms and the deep-seated dangers buried beneath ancient soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_730-7b420980a562c7d66b8e/1-0000.mp3", duration = 60.3167347, start = 0},
  },
}
P.transport["quest:743"] = {
  hash = "8d8243",
  fullHash = "8d8243",
  text = "Dangers of the Windfury. Ruul Eagletalon tests your readiness against the Windfury harpies in Mulgore. Their speed and claws will challenge you on the southeastern cliffs before you leave the tauren homeland. Ruul Eagletalon watches travelers pass through Mulgore from Bloodhoof Village. He asks those coming of age or preparing to travel farther to prove their combat instincts. Beyond Mulgore's sheltered valleys, survival calls for poise against cunning foes. Ruul measures your mettle against the land's fiercest native predators. The Windfury harpies roost along Mulgore's southeastern mountain rim, far from the beaten trails. They threaten wandering wildlife and isolated travelers. They dive swiftly and strike with razor-sharp claws as they hunt for fresh flesh. Defeat them and bring back their talons to prove you can overcome a settled threat and answer an attack from the air.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_743-5b173bb9d3a987e3a4ac/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["quest:745"] = {
  hash = "031673",
  fullHash = "031673",
  text = "Sharing the Land. In Mulgore, Baine Bloodhoof asks you to stop the Palemane gnolls from killing the plains' wildlife. You help protect the herds and the tauren way of living with the Earth Mother. The tauren take only what they need from the land and honor the Earth Mother in all things. Palemane gnolls have settled south of Bloodhoof Village and in a cavern to the west. Across the plains, they slaughter wildlife and leave carcasses behind. Their wasteful hunts harm the grasslands' balance and threaten the peaceful home the tauren are building in Mulgore. Baine Bloodhoof tried to settle the matter peacefully by speaking with the Palemane gnolls. They rejected every attempt and continued killing wildlife. Now he sends young braves to their hunting camps to stop the poachers, tanners, and skinners before the grasslands suffer lasting harm. When you return, Baine teaches that life should never be taken out of malice, though it may be needed to keep harmony. Life and death form a circle. Every guardian of Mulgore must carry that truth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_745-6e2bf7526323c8a585e4/1-0000.mp3", duration = 63.0073469, start = 0},
  },
}
P.transport["quest:746"] = {
  hash = "f71b45",
  fullHash = "f71b45",
  text = "Dwarven Digging. At Bloodhoof Village, Baine Bloodhoof fears the prospectors will anger Mulgore's beasts and scar its sacred earth. He asks young Horde defenders to break their picks and halt the digging. Northwest of Bloodhoof Village, dwarven prospectors have marked a site in Mulgore's hills. The Explorer's League searches Kalimdor for titan relics and secrets of the earthen. Often, they give little thought to the lands or customs of those who live there. To the tauren, the earth is a living mother, worthy of reverence rather than excavation for stone and metal. Baine Bloodhoof sees the dwarves' machines and blasting as a threat to the plains' fragile balance. Their noise agitates local wildlife and drives the kodos into frenzy. So the tauren mean to smash the prospectors' picks at the forges. The broken tools will warn the dwarves and halt the digging before lasting harm is done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_746-488a85138236d1d97fee/1-0000.mp3", duration = 52.8457143, start = 0},
  },
}
P.transport["quest:747"] = {
  hash = "d4589f",
  fullHash = "d4589f",
  text = "The Hunt Begins. At Camp Narache, young hunters gather food and feathers for their people. Grull Hawkwind sends you to hunt plainstriders on Red Cloud Mesa, where the village relies on what its young can provide. Tauren hunt on Red Cloud Mesa to feed and clothe their people. They value the stalk and chase as tests of discipline and as sport. When Camp Narache's stores run low, young hunters gather plainstrider meat for cooking and feathers for tribal garments. Grull Hawkwind judges newcomers who hope to leave Red Cloud Mesa for Mulgore's wider plains. Before they can meet his father, Chief Hawkwind, he asks them to prove their ability. A successful hunt shows self-reliance and helps support the tribe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_747-0c5315200a67d24b9e95/1-0000.mp3", duration = 43.3893878, start = 0},
  },
}
P.transport["quest:748"] = {
  hash = "40f167",
  fullHash = "40f167",
  text = "Poison Water. Tainted wells in Mulgore threaten the water that sustains the tauren and local wildlife. Mull Thunderhorn in Bloodhoof Village asks young Horde defenders to gather parts for a cleansing totem. Goblin interlopers and their lackeys have tainted Mulgore’s wells. The pollution threatens the water that sustains the tauren tribes and local wildlife. Mull Thunderhorn, an elder in Bloodhoof Village, has discovered the harm. The tauren settled here recently, and these wells are vital to life on their sacred plains. Mull turns to tauren shamanism to cleanse the Winterhoof Water Well. He needs a ritual totem made with the strength of Mulgore’s native beasts. You gather paws from prairie wolves and talons from mature plainstriders on the southwestern plains. The land’s own strength will be brought against the pollution.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_748-ead79600b8f7ec3b465e/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["quest:749"] = {
  hash = "9b8957",
  fullHash = "9b8957",
  text = "The Ravaged Caravan. Near Stonebull Lake, The Ravaged Caravan still draws Venture Company salvagers. Tauren warriors burned the convoy after losing companions in a skirmish. Intact crates show the scale of Venture Company operations in Mulgore. Tauren warriors burned a Venture Company convoy after an earlier skirmish cost them two companions. Morin Cloudstalker and his warriors struck swiftly, then set the wagons alight to drive out the armed intruders. They left the wreckage behind, believing the fire would consume whatever the goblins had come to haul. Venture Company salvagers have returned to the blackened wreckage, suggesting the fire failed to destroy all the cargo. Morin sends scouts to inspect the remains rather than risk more lives blindly. Intact crates among the soot-stained debris bear the Venture Company Mining Division insignia. They are packed for shipment to central processing facilities.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_749-49f2b961f3d96dab80f2/1-0000.mp3", duration = 53.9689796, start = 0},
  },
}
P.transport["quest:7493"] = {
  hash = "392a81",
  fullHash = "392a81",
  text = "The Journey Has Just Begun. In Orgrimmar, skilled leatherworkers learn how Onyxia's scales can guard against the black dragonflight. Overlord Runthak teaches them a rare cloak-making technique for the flames of Blackrock Spire. Onyxia's fall is a triumph for the Horde, but the black dragonflight remains a threat. Her scaled hide resists draconic flame. So Horde leaders seek craftsmen who can turn the dragon's remains into defensive armor instead of letting them go to waste.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7493-d83ade72441009feed7c/1-0000.mp3", duration = 29.1265306, start = 0},
  },
}
P.transport["quest:7497"] = {
  hash = "1528de",
  fullHash = "1528de",
  text = "The Journey Has Just Begun. In Stormwind, Major Mattingly honors the artisan who brought down Onyxia. He teaches the craft of making a cloak from her scales. Few who helped bring down Onyxia can work her hide. When a master leatherworker comes to Major Mattingly in Stormwind, the officer sees how much that skill may matter in battles ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7497-cbc1b3e79fbce658b7bc/1-0000.mp3", duration = 20.4538776, start = 0},
  },
}
P.transport["quest:751"] = {
  hash = "8d3aa7",
  fullHash = "8d3aa7",
  text = "The Ravaged Caravan. In Mulgore, The Ravaged Caravan leaves the Bloodhoof Outrunners with proof of an illegal foothold in tauren territory. The Venture Company is stripping the land's mineral wealth, and the Outrunners prepare to defend their ancestral plains. East of Bloodhoof Village, a ravaged caravan lies beside the road. Inside a sealed supply crate are mined ore and minerals, along with a bound sheaf of Venture Company documents. The papers prove the company has begun mining deep in Mulgore's tranquil valleys without permission. Morin Cloudstalker and his fellow Outrunners watch Mulgore's borders with care. They fear outside factions will exploit their peaceful homeland. When Morin receives the recovered documents, they confirm his worst fears. Smoke rising over the eastern foothills signals an escalating commercial invasion. The tauren must push back against the defilers before their hills are gutted entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_751-54672bb318d32eba67d9/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["quest:752"] = {
  hash = "d1b1c6",
  fullHash = "d1b1c6",
  text = "A Humble Task. On the Red Cloud Mesa, Chief Hawkwind asks a young adventurer to check on his mother. His pressing tribal concerns keep him at Camp Narache, so he sends you southeast to the well where Greatmother Hawkwind went for water. Every member of the tribe is expected to share in its harmony and do their part. For young tauren, duty begins with care for the community, not only prowess against quilboars or predators. Chief Hawkwind is bound to his post by the work of leading and defending the camp. So he trusts young adventurers to watch over the elders. The wells beyond the encampment provide water for the Red Cloud Mesa. Greatmother Hawkwind left Camp Narache early in the morning to fetch fresh water from a spring southeast of the encampment. Territorial wildlife and Bristleback quilboars range across the land. When an elder is away for hours, Chief Hawkwind grows concerned and sends you to make sure she is unharmed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_752-212f70aba3ef3f2ae5eb/1-0000.mp3", duration = 56.7379592, start = 0},
  },
}
P.transport["quest:753"] = {
  hash = "03db08",
  fullHash = "03db08",
  text = "A Humble Task. At Red Cloud Mesa, young tauren carry well water to Camp Narache at Greatmother Hawkwind's request. The work teaches humility and care for the tribe. Greatmother Hawkwind tends her duties beside the well on Red Cloud Mesa's southern edge. Age has slowed her, though she has walked many trails across the plains. When young tauren who hope to defend their people meet her, she turns their energy toward the needs of the community. Service lets them prove themselves by caring for others. You carry a filled pitcher northwest to Camp Narache and give it to Chief Hawkwind, the settlement's leader and Greatmother Hawkwind's son. Across Mulgore's dry plains, life depends on shared labor and steady supplies of fresh water. Carrying a burden for an elder shows respect for the people whose care holds the tribe together. When you bring his mother's water to Camp Narache, Chief Hawkwind sees more than a chore completed. Tauren custom asks those who would champion their people in distant lands to begin with humility and a ready hand. Your quiet discipline catches the chief's eye. He recommends you for the Rites of the Earthmother, spiritual tests that open the gates to Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_753-f1b827fd035d4f86b8b1/1-0000.mp3", duration = 71.6016327, start = 0},
  },
}
P.transport["quest:754"] = {
  hash = "c30f4d",
  fullHash = "c30f4d",
  text = "Winterhoof Cleansing. The Winterhoof Water Well in Mulgore has been fouled. Mull Thunderhorn gives you a consecrated totem in Bloodhoof Village to cleanse it. Goblin operations have tainted the nearby springs, and clearing this well is the first step toward healing central Mulgore’s waters. Mulgore’s grassy plains rely on ancestral wells to sustain wild game and scattered tauren tribes. The Venture Company has recently brought its industrial mercenaries into the hills southeast of Bloodhoof Village. Their work has contaminated local aquifers and left the Winterhoof Water Well toxic. Wild beasts avoid its water, and nearby camps face danger if the corruption spreads through the earth. Mull Thunderhorn carves a cleansing totem and blesses it in the name of the Earth Mother. Armed Venture Company goons have claimed the spring, so you must brave them to reach the well. Set the totem at its head, and it will drive out the foul runoff. Then clean water can rise from deep within the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_754-0386b2e9e9e20e9554a6/1-0000.mp3", duration = 59.7681633, start = 0},
  },
}
P.transport["quest:756"] = {
  hash = "4e8700",
  fullHash = "4e8700",
  text = "Thunderhorn Totem. In Bloodhoof Village, Mull Thunderhorn asks young Horde champions to help shape a sacred cleansing totem. Venture Company pollution spreads through Mulgore's wells, and predator claws will bind the plains' primal strength into its wood. Mull Thunderhorn needs natural claws for a cleansing totem. The Venture Company poisons Mulgore's water as it exploits the land, and Mull works to make a remedy. Prairie stalkers and flatland cougars roam east and west of Bloodhoof Village. Their claws carry the predators' natural essence and channel their raw, uncorrupted vigor into the totem. Tauren tradition sets hunting for food or spiritual balance apart from the goblins' wholesale plunder. Mull believes native predators' pure way of hunting can help cleanse corrupted earth. Goblin machinery fouls the springs with oil and industrial waste. The beasts' natural strength can provide the spiritual force to restore the Thunderhorn Water Well.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_756-7483fa4d678d051cc63c/1-0000.mp3", duration = 59.6114286, start = 0},
  },
}
P.transport["quest:757"] = {
  hash = "438c25",
  fullHash = "438c25",
  text = "Rite of Strength. At Camp Narache, young tauren face the Rite of Strength against Bristleback quilboar. They bring belts to Chief Hawkwind to prove their courage and defend the tribe. Seer Graytongue calls young tauren to begin the Rites of the Earthmother with the Rite of Strength. To earn recognition from the tribal elders and acceptance in Thunder Bluff, each initiate must face this duty. The trial tests whether they can meet the tribe's mortal foes with courage and defend Red Cloud Mesa. East of Camp Narache, Brambleblade Ravine is home to Bristleback quilboar. They trespass on ancestral lands, ambush hunting parties and raid camp supplies under cover of darkness. You are asked to slay them and bring back their belts. The belts prove your valor and help keep the settlement secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_757-fa296155d93c86b1dd9b/1-0000.mp3", duration = 46.2889796, start = 0},
  },
}
P.transport["quest:758"] = {
  hash = "6725b0",
  fullHash = "6725b0",
  text = "Thunderhorn Cleansing. In Mulgore, Thunderhorn Cleansing calls you to purify the Thunderhorn Water Well. Mull Thunderhorn prepares a totem for the rite, and the Thunderhorn ancestors give their thanks when the spring is clean. Water wells sustain the tauren tribes who have settled Mulgore's grasslands. When poison taints an underground spring, the wildlife and nearby settlements suffer. The Thunderhorn Water Well lies north of Bloodhoof Village, and its waters need spiritual cleansing. Mull Thunderhorn makes a Cleansing Totem for the rite. Carry it to the poisoned spring and channel ancestral power through it to drive out the toxins. When the cleansing succeeds, the Thunderhorn ancestors visit Mull in a dream and give thanks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_758-868aad706c54bfebe0b3/1-0000.mp3", duration = 44.277551, start = 0},
  },
}
P.transport["quest:759"] = {
  hash = "5aa369",
  fullHash = "5aa369",
  text = "Wildmane Totem. At the Wildmane Well, Mull Thunderhorn seeks to heal Mulgore's last poisoned waters. He needs prairie wolf alpha teeth for a totem that can cleanse them. The Wildmane Well is the last poisoned source in central Mulgore. Mull Thunderhorn has gathered what he needs for the Winterhoof and Thunderhorn wells, yet poisoned water still harms migrating wildlife and settlements across the plains. Powerful ingredients from the land are needed to restore its balance. Prairie wolf alphas roam Mulgore's grasslands, especially beneath the high bluffs below Thunder Bluff. Mull Thunderhorn needs their teeth for a cleansing totem meant for the northern waters. Their strength and endurance will lend the totem the power of these fierce hunters. For tauren, taking from the land's creatures carries solemn weight. Mull Thunderhorn sees the alpha teeth as a necessity, not a conquest. The predators' sacrifice may help heal the Earth Mother's poisoned waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_759-071d4d00117e63d5f7dc/1-0000.mp3", duration = 59.6636735, start = 0},
  },
}
P.transport["quest:76"] = {
  hash = "e39310",
  fullHash = "e39310",
  text = "The Jasperlode Mine. Scouts are bound for The Jasperlode Mine in eastern Elwynn, where kobolds may have spread. Marshal Dughan needs to know how far they have reached. After kobolds swarmed the Fargodeep tunnels south of Goldshire, Marshal Dughan feared they had reached other mines. Jasperlode lies in the rocky foothills northeast of the Tower of Azora. Its stone and metal supply the kingdom. With Stormwind guards needed on town patrols, Dughan sends independent adventurers east to learn whether kobolds have taken this mine too. Scouts reaching Jasperlode's chambers find kobolds have driven out the human miners and fortified the dark passages. Marshal Dughan faces another blow as the crisis grows. King Varian Wrynn is missing, and royal troops remain withheld from outlying lands. The local garrison has too few soldiers to clear the mine. The kingdom's heart is left short of minerals and hemmed in by threats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_76-a8c40cb7c8da4c5a0f3e/1-0000.mp3", duration = 56.0587755, start = 0},
  },
}
P.transport["quest:760"] = {
  hash = "91de07",
  fullHash = "91de07",
  text = "Wildmane Cleansing. In Mulgore, the tauren's cleansing work reaches its final well. Mull Thunderhorn in Bloodhoof Village sends you north with the completed Wildmane Totem to cleanse the poisoned water and protect the tauren's way of life. Mulgore's wells sustain the herds, the soil, and the tauren tribes gathered around Thunder Bluff. The Venture Company and encroaching goblins have fouled them with toxic industrial runoff. The tauren elders see the danger to their people and their land.\n\nThe Winterhoof and Thunderhorn wells are purified. Now the Wildmane Water Well remains, the third and final corrupted site. Its waters still need spiritual cleansing. The Wildmane Cleansing Totem is made from elements gathered across the region. It draws on the restoring power of ancestral spirits and elemental earth. Plant it beside the foul waters north of Thunder Bluff. The ritual disperses chemicals, draws out toxins, and revives the natural flow.\n\nThe cleansing guards the tauren against disease. It also makes clear they will not tolerate the despoiling of their sacred ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_760-33089097acf1d8db2f89/1-0000.mp3", duration = 68.7542857, start = 0},
  },
}
P.transport["quest:761"] = {
  hash = "1ab25d",
  fullHash = "1ab25d",
  text = "Swoop Hunting. Harken Windtotem asks you to track swoops across Mulgore. Their quills test patience, cleverness, and marksmanship, and honor the trials of the Earth Mother. Across Mulgore's open grasslands, swoops test a hunter's eye. These large birds blend into sky and plain, wheeling overhead or skimming low through tall grass. They demand focus and swift feet, unlike lumbering plainstriders or grazing kodo. Young hunters pursue them to prove their skill and earn standing among the tribes. Harken Windtotem asks for trophy quills to teach discipline, not to cull wildlife. Tauren carry tokens from a hard-won stalk as signs of cleverness and perseverance. Unblemished quills presented to the elders in Bloodhoof Village show a hunter can sustain and defend the community. Swift hooves and sharp senses prepare them for the wider world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_761-e4514029ecd018475275/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["quest:763"] = {
  hash = "7dd127",
  fullHash = "7dd127",
  text = "Rites of the Earthmother. At Camp Narache, Chief Hawkwind sends you beyond Red Cloud Mesa to continue the Rites of the Earthmother. After the first trials, you carry a carved totem north to Bloodhoof Village and Baine Bloodhoof. Young tauren have tested their strength at Camp Narache on Red Cloud Mesa for generations. The first trials teach discipline and resolve. Yet the sacred Rites of the Earthmother reach beyond surviving the mesa's wildlife. Chief Hawkwind knows when an initiate is ready to leave the sheltered hunting grounds and join the wider community. Chief Hawkwind gives you a hand-carved totem to introduce you on the road from Narache to the central settlements. Carry it down the winding path to Bloodhoof Village and present yourself to Baine Bloodhoof, the young chieftain and son of High Chieftain Cairne Bloodhoof. The totem is your credential and seal of approval. It marks your readiness for the rites of spirit and wisdom ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_763-ff925e578cf13299f180/1-0000.mp3", duration = 53.7077551, start = 0},
  },
}
P.transport["quest:764"] = {
  hash = "5ac997",
  fullHash = "5ac997",
  text = "The Venture Co.. In Mulgore's eastern hills, goblins dig despite the tauren's refusal. The Venture Co. brings them in force to quarry the Earth Mother's soil, and Morin Cloudstalker calls for a lethal answer. The tauren honor Mulgore as part of the Earth Mother. They value its open plains and the balance of its wildlife. When the Venture Company asks to blast and excavate the hills for ore, the tribes refuse. The company ignores them and brings machinery, laborers, and overseers into the eastern ridges to mine without permission. Morin Cloudstalker and the other tauren scouts see no use in further appeals once the mining begins. Documents from a ravaged Venture Co. caravan confirm the operation. Morin sends you against the overseers who crack the whips and the laborers who drive the drills. He means for the company to pay dearly for trespassing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_764-78d3515a7e998513d49b/1-0000.mp3", duration = 52.0097959, start = 0},
  },
}
P.transport["quest:765"] = {
  hash = "228711",
  fullHash = "228711",
  text = "Supervisor Fizsprocket. In Mulgore, Morin Cloudstalker calls for help against the Venture Company mine. Documents from a ruined caravan show a plan to drive the tauren from their homeland, and Morin needs Supervisor Fizsprocket's clipboard. A Venture Company caravan lies destroyed, and its documents reveal a plan to drive the tauren from Mulgore. The company wants the plains and the veins beneath them for itself. It means to take their resources without the tauren in its way.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_765-818b6dd59bcfd9c27a55/1-0000.mp3", duration = 27.0889796, start = 0},
  },
}
P.transport["quest:766"] = {
  hash = "41ef22",
  fullHash = "41ef22",
  text = "Mazzranache. In Bloodhoof Village, Mazzranache's bite leaves Maur Raincaller feverish and near death. A generation ago, the plainstrider haunted his grandfather's tales. Now Maur suffers delirious nightmares as the venom threatens his life. Maur Raincaller knew Mazzranache only through his grandfather's tales. The elder tauren spoke of a savage plainstrider with glowing red eyes, razor-sharp talons, and a toxic bite unlike that of most Mulgore wildlife. Then Maur met the beast on the open grass. His grandfather's warning came true, and the bite left him badly wounded as he struggled to reach safety. Mazzranache's venom brings Maur a high fever and nightmarish delirium. He needs a remedy before the infection turns fatal. Traditional tauren medicine draws on the vitality of local beasts, so Maur needs a prairie wolf heart, a flatland cougar femur, a plainstrider scale, and a swoop gizzard. Together, these parts can make a brew to halt the necrotic spread and nurse him back to health.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_766-24bc6c31a9c37df93da9/1-0000.mp3", duration = 64.0261224, start = 0},
  },
}
P.transport["quest:767"] = {
  hash = "b9c5e2",
  fullHash = "b9c5e2",
  text = "Rite of Vision. Baine Bloodhoof sends travelers across Mulgore to seek Zarlman Two-Moons before the Rite of Vision. The trial belongs to the Rites of the Earthmother, and elders on the rises of Thunder Bluff regard it as a sign of spiritual readiness. For generations, the nomadic tauren have followed the Earthmother’s guidance across Kalimdor’s plains. Now they have gathered within Mulgore’s safe borders, where spiritual traditions remain at the heart of their society. Earlier trials test an initiate’s strength and bond with the hunt. The Rite of Vision turns inward, calling young tauren and honored allies to commune with the spirits. Before seeking a vision, an initiate needs guidance in the ancient ways. In Bloodhoof Village, the revered shaman Zarlman Two-Moons offers that counsel. Baine Bloodhoof entrusts travelers to his care. Zarlman recognizes those who walk the ancestors’ path, then gives them the first rites and sacred preparations to look beyond the physical world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_767-fc5a0efd422af1c7d82c/1-0000.mp3", duration = 61.1787755, start = 0},
  },
}
P.transport["quest:768"] = {
  hash = "b8d85f",
  fullHash = "b8d85f",
  text = "Gathering Leather. On Thunder Bluff, Veren Tallstrider asks hunters to bring light leather for the capital. He trades crafted goods for the hides, following the tauren way of making clothing and armor from the plains hunt. Thunder Bluff needs skilled hands to make clothing and armor for its growing population. Veren Tallstrider works skins into useful goods and asks young hunters returning from the plains to bring him their quarry. Their hunts help supply the capital and feed the tribe. Tauren hunt across the grasslands to feed, clothe, and shelter the tribe. Veren Tallstrider asks hunters who would bring honor to their clan for light leather from local wildlife. In return, he trades crafted goods for twelve well-kept hides, sustaining the ties that bind tauren society.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_768-5a565a6e14ce8f1cd121/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:769"] = {
  hash = "148d3a",
  fullHash = "148d3a",
  text = "Kodo Hide Bag. Veren Tallstrider teaches Thunder Bluff's apprentice leatherworkers a craft drawn from the plains. He asks for cured light leather and sturdy thread. Veren Tallstrider teaches leatherworking on Thunder Bluff's crafting rises. He follows the nomadic way of wasting nothing from the hunt. Bring cured light leather and sturdy thread, and he will teach you. With these basic materials, apprentices show they can make goods to carry survival gear across Kalimdor's rugged expanses. To the tauren, the kodo is a sign of endurance, strength, and steady resolve. Its thick hide guards against brambles, biting wind, and beast claws. Making bags and garments from kodo hide is useful work, and it honors the animal that has fed and carried the Shu'halo across Mulgore's plains for generations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_769-f9855467c3914645cc5c/1-0000.mp3", duration = 49.4236735, start = 0},
  },
}
P.transport["quest:770"] = {
  hash = "73ba08",
  fullHash = "73ba08",
  text = "The Demon Scarred Cloak. In Mulgore, The Demon Scarred Cloak carries the wounds of Ghost Howl's torment. The hide came from a legendary white wolf scarred by the Burning Legion. Its arrival in Bloodhoof Village brings the beast's troubled story to a close. Ghost Howl is a legendary white wolf whose sorrowful howl carries across Mulgore. The hide left by the beast bears the scars of demonic corruption. Those marks came from desperate battles against the invading demons of the Burning Legion. The wounds lingered in Ghost Howl's flesh and spirit long after the Third War. Mulgore's tauren revere the wild beasts of their homeland as children of the Earth Mother. In Bloodhoof Village, Skorn Whitecloud receives the scarred cloak as proof that the tormented predator is dead. He recognizes the skill it took to track and defeat Ghost Howl. Somberly, he hopes the wolf's tortured spirit has found peace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_770-5bd85728ff7b236583da/1-0000.mp3", duration = 54.4391837, start = 0},
  },
}
P.transport["quest:771"] = {
  hash = "54ce9a",
  fullHash = "54ce9a",
  text = "Rite of Vision. Across Mulgore, young tauren gather offerings for the Rite of Vision. In Bloodhoof Village, Zarlman Two-Moons guides them as they brew the Water of the Seers and seek counsel from ancestral spirits. Zarlman Two-Moons sends you across Mulgore for well stones and ambercorn. The stones rest near sacred communal wells, while ambercorn falls beneath the roots of ancient trees. To the tauren, these are more than gifts from the land. They carry the Earth Mother's latent magic and lifeblood, ready for the rite. Zarlman combines the well stones and ambercorn to brew the Water of the Seers. You drink it beside the village's tribal flame. The draught clears your mind and summons an ethereal guide. Then you follow the guide across the plains, testing whether you can walk between the physical world and the land's spiritual whispers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_771-beb09df865fb2d6c30a5/1-0000.mp3", duration = 51.6702041, start = 0},
  },
}
P.transport["quest:772"] = {
  hash = "dd1bf7",
  fullHash = "dd1bf7",
  text = "Rite of Vision. At Bloodhoof Village, young tauren drink the Water of the Seers and glimpse the path before them. A spectral guide rises beside the tribal bonfire. After gathering the ritual herbs and passing the first trials of faith, you receive the Water of the Seers from Zarlman Two-Moons. You drink it before the tribal fire at the heart of Bloodhoof Village. Keep your mind focused and respectful, and the sacred water opens your sight beyond the physical world. It joins the material and spiritual realms. Once you drink the brew, an ancestral ghost wolf appears in the flames. It neither speaks nor fights, but lopes northwest across Mulgore's rolling plains. Follow its quiet path away from the village and into the rocky hills. There, the hermit Seer Wiserunner waits in secluded meditation. The vision ends when you reach Seer Wiserunner at the mouth of his mountain cavern. The walk across grassy hills tests your patience, your trust in ancestral guidance, and your attunement to the Earth Mother. Pass the rite, and you earn the right to face the Rite of Wisdom, the ultimate test of adulthood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_772-f1edab384ee457d714b8/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["quest:773"] = {
  hash = "8e8a9e",
  fullHash = "8e8a9e",
  text = "Rite of Wisdom. At Red Rocks, the Rite of Wisdom brings the Rites of the Earthmother to their final trial. After the Rite of Vision clears your sight, you travel to commune with an Ancestral Spirit and seek the dead’s blessing. After the Rite of Vision clears your sight, you travel east of Thunder Bluff to Red Rocks. Those buried here fought and died so Mulgore could know peace, and their spirits still linger. Approach their resting place with reverence and seek communion. The hills are guarded by threats as you seek counsel from the honored dead. At Red Rocks’ summit, you commune with an Ancestral Spirit. The meeting tests your spiritual readiness and your place in the generations, not your strength in battle. These spirits fought beside Cairne Bloodhoof to establish Thunder Bluff and protect the tribes. Their blessing marks you as an adult and defender. You are charged with protecting the city and may enter Thunder Bluff with pride.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_773-0d3bd19a09be769dfe27/1-0000.mp3", duration = 56.3983673, start = 0},
  },
}
P.transport["quest:775"] = {
  hash = "a7d0f1",
  fullHash = "a7d0f1",
  text = "Journey into Thunder Bluff. The spirits send you from Mulgore to Thunder Bluff after the Rites of the Earthmother. Cairne Bloodhoof, High Chieftain of the tauren, awaits you there. Across Mulgore, the Rites of the Earthmother test your strength, vision, and wisdom. The trials lead across the plains and through the land’s ancestral sites. When the Ancestral Spirit acknowledges your final rite, you have proved yourself worthy to enter Thunder Bluff as a defender of the tauren people. From the sacred ground where spirits wander, you travel upward to Thunder Bluff. The city crowns red stone mesas, joined by rope bridges and great wooden elevators. Cairne Bloodhoof, High Chieftain of the tauren, awaits you on the High Rise, ready to greet those who have followed the ancestors’ path.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_775-d965adc99e4bc02bb9a5/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:776"] = {
  hash = "581e59",
  fullHash = "581e59",
  text = "Rites of the Earthmother. High Chieftain Cairne Bloodhoof sends you across Mulgore to track down the great kodo Arra'chea. Even after the old rites, he asks his people to prove their strength, tracking, and devotion anew. Arra'chea's horn shows Cairne you are ready to serve the wider Horde. In Thunder Bluff, a young tauren's childhood gives way to duty. High Chieftain Cairne Bloodhoof asks young hunters to keep proving themselves. Reaching the high bluffs begins a life of service to the United Tauren Tribes. Cairne asks for more than a hunt for small pests: he wants proof of fieldcraft, shown by tracking and cleanly harvesting one of Mulgore's renowned wandering beasts. Arra'chea is a massive, legendary kodo whose looping path crosses the golden grasses northeast of Thunder Bluff. Bringing down this great beast takes patient stalking across the open savannah, not brute force alone. Return Arra'chea's horn to the high rise, and Cairne sends skinners and gatherers to use every part of the sacred beast for the city's provisions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_776-afb50a6bcb618f5d0a60/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["quest:7781"] = {
  hash = "2be4e0",
  fullHash = "2be4e0",
  text = "The Lord of Blackrock. Nefarian's severed head reaches Stormwind Keep after his defeat in Blackwing Lair. Highlord Bolvar Fordragon receives it as proof that the master of Blackrock Mountain has fallen. The victory ranks among the Alliance's greatest military triumphs in recent history. Nefarian, brood-master of the Black Dragonflight and ruler of Upper Blackrock Spire, has long threatened the surrounding human kingdoms. His defeat ends his twisted experiments and schemes. His battle-scarred head is carried back to Stormwind, proof that the Alliance's greatest heroes have brought down the Lord of Blackrock. Highlord Bolvar Fordragon governs the kingdom from Stormwind Keep's throne room. The dragon's severed head shocks the royal court and commands reverence. The kingdom faces internal political strife and threats from beyond. This victory lifts morale and earns a place in Alliance history.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7781-8bac7dd7a3f982c3ece7/1-0000.mp3", duration = 54.6742857, start = 0},
  },
}
P.transport["quest:7782"] = {
  hash = "c8ff2c",
  fullHash = "c8ff2c",
  text = "The Lord of Blackrock. At Stormwind's gates, the Alliance gathers to honor its victory over Blackrock. After you report to Highlord Bolvar Fordragon in Stormwind Keep, the heroes make for the Valley of Heroes. Field Marshal Stonebridge is ready to lead the city's public commemoration. Field Marshal Stonebridge raises Nefarian's severed head above the great arches at Stormwind's main entrance. The sight carries across the city, and the Rallying Cry of the Dragonslayer inspires defenders, visiting dignitaries, and citizens. They know Deathwing's brood has suffered a crushing blow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7782-a11247690411d2bbafe6/1-0000.mp3", duration = 34.8473469, start = 0},
  },
}
P.transport["quest:7783"] = {
  hash = "b8655b",
  fullHash = "b8655b",
  text = "The Lord of Blackrock. In Orgrimmar, Nefarian's severed head is brought before Thrall as proof of victory. Its arrival marks the fall of a great enemy of the Horde. Nefarian has fallen at last. He masterminded Blackwing Lair and led the black dragon brood in the Eastern Kingdoms. His battle-scarred head proves his death. For Horde warriors, carrying this prize from the burning heights of Blackrock Mountain across the Great Sea to Durotar brings great honor. The trophy is brought before Warchief Thrall, who knows Blackrock Mountain's corruption well. He freed his people from the internment camps and led them away from the old Horde's demonic bloodlust. Now the son of Deathwing has fallen, and the Blackrock orcs are free of the dark dragon's cruel dominion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7783-7b74b04ccf68ec6328a9/1-0000.mp3", duration = 47.3077551, start = 0},
  },
}
P.transport["quest:7784"] = {
  hash = "34a876",
  fullHash = "34a876",
  text = "The Lord of Blackrock. Before the Horde in Orgrimmar, Nefarian's severed head bears witness to his defeat. Thrall confirms the black dragon's death, then sends you to High Overlord Saurfang in the Valley of Strength to show the trophy to all. Nefarian's head comes to Orgrimmar after the black dragon falls atop Blackwing Lair. Warchief Thrall confirms that Deathwing's son is dead, then sends you to High Overlord Saurfang in the Valley of Strength. There, the remains are prepared for all to see. The trophy warns the Horde's enemies and rallies the true Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7784-d2eaf11211225be723b6/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["quest:780"] = {
  hash = "1b24ef",
  fullHash = "1b24ef",
  text = "The Battleboars. At Camp Narache, young tauren hunt battleboars to guard their lands and feed the tribe's youth. East of Red Cloud Mesa, Brambleblade Ravine lies in Bristleback quilboar hands. Tensions between the Shu'halo and the quilboar have grown into open war. The Bristlebacks train vicious battleboars to test tauren borders and trouble their old hunting grounds. Left unchecked, the beasts endanger game trails and Camp Narache alike. Hunting keeps the tauren safe and feeds the tribe. Grull Hawkwind asks the young hunters to bring back the battleboars' snouts and flanks. Even these beasts, trained by quilboar hands, are put to use. Their meat and gristle go into stew for the tribe's youth, turning a quilboar weapon into food for the next generation of tauren defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_780-0e08ee867b3de239d9ba/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["quest:781"] = {
  hash = "d76a9a",
  fullHash = "d76a9a",
  text = "Attack on Camp Narache. At Camp Narache, you carry a warning that could give the tauren time to call for aid. The Bristleback quilboar are planning a siege, and Chief Hawkwind needs to know. In Brambleblade Ravine, you find a crude map on the cavern floor. Its dirt-stained markings reveal the Bristleback quilboar plan a long siege against Camp Narache. This is more than a string of scattered attacks. You bring the attack plans to Chief Hawkwind at Camp Narache. Few defenders guard the camp, which shelters young initiates, so Hawkwind prepares to send word to Bloodhoof Village for reinforcements. Your warning gives the camp time to prepare for the siege.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_781-227645928c09b4d11d84/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["quest:783"] = {
  hash = "6ff10a",
  fullHash = "6ff10a",
  text = "A Threat Within. In Northshire Valley, volunteers answer Stormwind's call as local defenses falter. At Northshire Abbey, Marshal McBride directs the response, and you begin serving on the threatened grounds. Northshire Valley once gave people quiet for prayer, farming, and monastic study. Now it is Elwynn Forest's first defense against unrest at home. Few guards remain nearby, so the Stormwind Guard calls on each willing volunteer who reaches the abbey. Trouble spreads across the surrounding countryside. From Northshire Abbey, Marshal McBride directs the valley's defenses as danger grows. Bandits, vermin, and pests from below ground threaten the people nearby. You begin by clearing the ground around the abbey, where these threats press close to the valley's defenders and the place they protect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_783-06516fa448783762d716/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["quest:784"] = {
  hash = "42022e",
  fullHash = "42022e",
  text = "Vanquish the Betrayers. At Tiragarde Keep, Kul Tiran forces still hold a foothold on Durotar's coast. Gar'Thok calls the Horde to strike at Lieutenant Benedict's garrison, whose presence has broken the fragile peace with Theramore. Thrall led the Horde across the Great Sea to Kalimdor. There, he and Lady Jaina Proudmoore fought the Burning Legion at Mount Hyjal. Peace broke when Jaina's estranged father, Grand Admiral Daelin Proudmoore, brought Kul Tiras's navy to Durotar. He blamed every orc for the Old Horde's atrocities and seized coastal strongholds, among them Tiragarde Keep. Daelin died at Theramore, but remnants of his fleet still reject any pact and keep their hatred. Tiragarde Keep fell for a time after the Grand Admiral's defeat. Then Kul Tiras reserves under Lieutenant Benedict took it back. The fortress lies between Razor Hill and Sen'jin Village. From there, sailors and marines harass travelers and threaten Durotar's eastern sea approaches. Gar'Thok sees their presence as an immediate danger to Durotar's security. So he calls on Horde warriors to strike at Benedict's command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_784-315debf344b3b75d0c49/1-0000.mp3", duration = 68.9110204, start = 0},
  },
}
P.transport["quest:786"] = {
  hash = "d57fa9",
  fullHash = "d57fa9",
  text = "Thwarting Kolkar Aggression. Lar Prowltusk has uncovered a plan to strike Durotar's settlements and Orgrimmar. The Kolkar centaurs have divided the invasion plans among three leaders at Kolkar Crag, west of Sen'jin Village. Lar Prowltusk is a troll tracker scouting western Durotar. Under cover of night, he slipped into Kolkar Crag and found the Kolkar centaurs preparing more than scattered coastal raids. Three leaders hold the invasion plans. Their targets are the Valley of Trials, Sen'jin Village, and the gates of Orgrimmar. The Kolkar leaders hold three attack scrolls in their camps in the dry canyons of Kolkar Crag. You are sent to destroy the scrolls before the centaurs can strike. Lar Prowltusk believes the Horde could defeat a full invasion, but burning the plans can spare Durotar's defenders costly fighting as their young nation finds its footing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_786-6d4f9029ecc0e3b838b9/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["quest:787"] = {
  hash = "ebed8b",
  fullHash = "ebed8b",
  text = "The New Horde. In the Valley of Trials, Eitrigg calls the Horde's newest recruits to the Den. He sends you to Gornek for training and explains why he returned to the Horde and what Thrall hopes it can become. Under Warchief Thrall's orders, Eitrigg watches over the newest hopefuls in the Valley of Trials. After the Second War, he left the Old Horde, sickened by its corruption under the Burning Legion. He lived in quiet exile until humans captured him. Thrall rescued Eitrigg, and the veteran returned when he learned of the young Warchief's dream: an honorable Horde rooted in ancestral shamanism and free of demonic masters. Before you leave the Valley of Trials' harsh canyons, Eitrigg sends you to the shaded cavern called the Den to speak with Gornek. Gornek speaks plainly about how rough new aspirants are. He watches over their training so only those who master discipline and survival reach the wider lands of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_787-3198e325d7900a1c9afb/1-0000.mp3", duration = 55.8759184, start = 0},
  },
}
P.transport["quest:791"] = {
  hash = "fae4be",
  fullHash = "fae4be",
  text = "Carry Your Weight. Atop the watchtower overlooking Razor Hill, Furl Scornbrow asks young Horde adventurers to gather canvas from human and centaur foes. Age and old injuries keep him from the front lines, so he makes supplies to help them on their way. Furl Scornbrow fought beside Warchief Thrall in Durotar and at Mount Hyjal. Age and old injuries have slowed him, and he no longer wields his axe in battle. From the watchtower above Razor Hill, Furl keeps a steady vigil and sounds the alarm when danger comes. Though he has left the front lines, he still serves the next generation of defenders from his post. As the Horde's hold on the region grows stronger, signal horn alerts come less often. Furl has more hours to make useful gear, but sturdy canvas is scarce in Durotar's dry canyons. Along the eastern shore, Kul Tiran interlopers carry canvas in abundance. So do the nomadic Kolkar centaur roaming the plains. Furl salvages canvas from these hostile forces and stitches it into utility bags for active scouts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_791-c9caf26a4968e4948e73/1-0000.mp3", duration = 64.6008163, start = 0},
  },
}
P.transport["quest:792"] = {
  hash = "f592b3",
  fullHash = "f592b3",
  text = "Vile Familiars. In the Valley of Trials, Vile Familiars pour from a nearby cavern. Zureetha Fargaze found a hidden Burning Blade coven while watching over the trials. Now recruits hunt the familiars spreading across Durotar's red earth. Young orcs and Darkspear trolls face tests of strength, discipline, and loyalty to Thrall's Horde in the Valley of Trials. They were meant to face scorpids and boars, not demonic corruption. Yet a cave to the northeast shelters Burning Blade agents. They have formed a secret coven beneath the valley overseers' watch. Zureetha Fargaze guides newcomers near the Den. She spotted the taint before it could overrun the canyon. Now Vile Familiars pour from the cave mouth and hurl fire at anyone who wanders too close. Before the Horde can root out the hidden masters, young recruits are sent to cut down these lesser servants and keep the valley secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_792-03efa2390d8cfdc4936d/1-0000.mp3", duration = 53.0808163, start = 0},
  },
}
P.transport["quest:794"] = {
  hash = "8bb509",
  fullHash = "8bb509",
  text = "Burning Blade Medallion. Zureetha Fargaze sends young Horde initiates into the Valley of Trials cave, where the Burning Blade has gathered. They face a hidden cultist and seek the Burning Blade Medallion. Its presence points to demonic corruption near the Horde. Young orcs and trolls face trials of combat and survival in the Valley of Trials. A menace gathers nearby. Through divination, the warlock Zureetha Fargaze senses that the vile familiars on the northern bluffs are only the vanguard of a darker presence. Deep in a nearby cavern, the Burning Blade cult has formed a hidden coven. Its followers practice dark arts and keep dangerous relics of demonic power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_794-0f315bba549964f3dea8/1-0000.mp3", duration = 38.9485714, start = 0},
  },
}
P.transport["quest:8"] = {
  hash = "62d231",
  fullHash = "62d231",
  text = "A Rogue's Deal. In Deathknell, Calvin Montague asks you to carry an unmarked message to Brill. He calls it a simple delivery and promises generous coin. Calvin Montague lounges among Deathknell's graves and ruined chapels. He says Scourge zombies and creeping spiders have worn him down, then asks you to carry an unmarked letter to Brill. He promises generous coin. For a newly awakened Forsaken, it seems a simple way to reach the region's main town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8-17b64508ad53e4e14037/1-0000.mp3", duration = 29.1004082, start = 0},
  },
}
P.transport["quest:804"] = {
  hash = "d447bd",
  fullHash = "d447bd",
  text = "Sarkoth. On the Valley of Trials' high bluffs, Hana'zua waits for help after Sarkoth's venom leaves him stranded. You have slain the scorpid that wounded him. Now Gornek needs word at the Den so aid can reach the scout. Hana'zua, a Darkspear scout, lies stranded on the high bluffs of the Valley of Trials. Sarkoth's venom has left him too weak to descend the treacherous paths alone. You have avenged him by slaying the scorpid, but he still cannot cross the arid stones without help. So a passing initiate must carry word down to the training encampment. Gornek waits at the Den for your report. When he hears of Hana'zua's plight, he recognizes the danger from Sarkoth and organizes aid for the scout. Horde commanders honor those who set aside their own training to defend and rescue a fallen stranger. Such conduct proves an initiate's worth before they march into Durotar proper.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_804-33fdd3af54850e6e9244/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["quest:805"] = {
  hash = "04d1ee",
  fullHash = "04d1ee",
  text = "Report to Sen'jin Village. Zureetha Fargaze sends young initiates from the Valley of Trials to warn the Darkspear trolls in Sen'jin Village. Burning Blade cultists have been active in the valley. Master Gadrin tells them dark magic threatens the nearby Echo Isles. After proving their combat mettle and recovering dark medallions from the Burning Blade Coven, young initiates leave the Valley of Trials. Zureetha Fargaze sees that demons in the sacred proving grounds are no isolated nuisance. They point to a blight spreading across Durotar. She sends the proven fighters east past the ravine's mouth, then south toward the coast, to warn the Darkspear tribe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_805-de5eb2073518261ba048/1-0000.mp3", duration = 40.0457143, start = 0},
  },
}
P.transport["quest:806"] = {
  hash = "2fe6af",
  fullHash = "2fe6af",
  text = "Dark Storms. In Durotar, Burning Blade cultists corrupt the land from Thunder Ridge. Orgnil Soulscar in Razor Hill has learned that Fizzle Darkstorm leads them, and asks you to end his threat. Orgnil Soulscar has learned that dark magic has taken hold in Thunder Ridge, northwest of Razor Hill. Burning Blade cultists prowl its ravine while young Horde defenders guard Durotar’s borders. The cultists bring ruin to the wildlife and land. Fizzle Darkstorm is a goblin warlock allied with the Burning Blade. He directs the cultists in Thunder Ridge and wields fel power for the cult, not for commerce or cartel interests. Slay him and bring back his twisted claw. Then Orgnil will know the ravine’s leaders have been struck down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_806-4b56beb52d9dc2385ae4/1-0000.mp3", duration = 46.1583673, start = 0},
  },
}
P.transport["quest:808"] = {
  hash = "4bc8d6",
  fullHash = "4bc8d6",
  text = "Minshina's Skull. In Sen'jin Village, Master Gadrin hears his dead brother Minshina's desperate cries. Zalazane slew Minshina on the Echo Isles and bound his spirit to his severed skull. You can free him from torment by reclaiming the skull from Zalazane's ritual grounds. Master Gadrin is one of the Darkspear tribe's spiritual anchors in Sen'jin Village. Yet dark visions torment him. His brother Minshina fell when Zalazane betrayed the tribe and seized the Echo Isles. Minshina died in the conflict, but death brought him no peace. Troll tradition and voodoo mysticism hold that a spirit can remain bound after the body dies. Now Minshina's tormented voice reaches Gadrin in his dreams, pleading to be saved from a fate worse than death. Zalazane does more than kill his former brethren. He traps their souls to fuel his dark sorcery. He bound Minshina's spirit to his own skull, now set in a circle of power on the largest of the Echo Isles. Hexed trolls guard the circle as candles burn through the rites. The skull focuses Zalazane's twisted mojo. While it remains there, Minshina is captive to the witch doctor's will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_808-f1aec5e7466b64610099/1-0000.mp3", duration = 70.2955102, start = 0},
  },
}
P.transport["quest:809"] = {
  hash = "66c8a9",
  fullHash = "66c8a9",
  text = "Ak'Zeloth. Near Orgrimmar, Neeru Fireblade sends you into the Barrens as demonic corruption stirs. His contact waits near the border. Neeru Fireblade says the Burning Blade still threatens the Horde with demonic corruption. You have brought him a Burning Blade insignia collar from Durotar, and now he sends you into the Barrens. A cult gathers around the Demon Seed, an artifact of vile power. Neeru wants you to find his contact near the border.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_809-30f343e93f30e9c3573b/1-0000.mp3", duration = 28.395102, start = 0},
  },
}
P.transport["quest:812"] = {
  hash = "e205c3",
  fullHash = "e205c3",
  text = "Need for a Cure. On Durotar’s northwestern cliffs, Rhinag is poisoned and far from the cure he needs. The Darkspear troll has little time before the venom kills him, so he sends a passing courier to Orgrimmar for Kor'ghan’s remedy. Rhinag fought venomtail scorpids near Durotar’s border when one stung him. Their venom can kill in less than an hour. The poison keeps him from walking to Orgrimmar, leaving his survival to a traveler who reaches his remote camp in time. Rhinag sends you beneath Orgrimmar to the Cleft of Shadow, where Kor'ghan knows how to counter the poisons of Durotar’s wastes. Kor'ghan can brew a cure, though he rarely helps those who have not proved themselves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_812-d5701803bec823242874/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["quest:813"] = {
  hash = "b7df0d",
  fullHash = "b7df0d",
  text = "Finding the Antidote. Kor'ghan in Orgrimmar races to brew a cure for the poisoned hunter Rhinag. You gather venomtail poison sacs from scorpids beyond the city walls before their venom proves fatal. Durotar's wilds are unforgiving, and survival depends on preparing for their dangers. Rhinag, a Darkspear troll, was hunting in Durotar when venomtail scorpids struck him. Their venom acts quickly, and he needs aid at once. Kor'ghan, an experienced hunter in Orgrimmar, must brew a draught before the poison kills him. Mature venomtail scorpids outside Orgrimmar's gates carry the sacs Kor'ghan needs for an antidote. He says there will be time to chastise Rhinag for going unprepared, but each moment matters now. Bring the sacs back into the city so Kor'ghan can brew a draught for the dying hunter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_813-7dc34c7283fa16947c95/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["quest:816"] = {
  hash = "a2e0ba",
  fullHash = "a2e0ba",
  text = "Lost But Not Forgotten. Misha Tor'kren waits at her Durotar homestead for news of her son, Kron. He went west to hunt crocolisks along the Southfury River, and she fears the worst. Misha Tor'kren lives at a farmstead northwest of Razor Hill. Days ago, her son Kron went west to hunt fierce crocolisks along the Southfury River, near the Barrens border. Misha warned him how deadly the beasts were, but pride drove him to prove his strength. No one has seen him since.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_816-eaefc8e78c5082debad1/1-0000.mp3", duration = 28.6302041, start = 0},
  },
}
P.transport["quest:817"] = {
  hash = "1fd6eb",
  fullHash = "1fd6eb",
  text = "Practical Prey. Vel'rin Fang calls for tiger hides from the Echo Isles to supply Sen'jin Village. The Darkspear's numbers grow, and their stores run low. Along Durotar's harsh coast, the Darkspear of Sen'jin Village make every resource last. Tiger pelts become tents, blankets and armor. Refugees arrive and scouts return, thinning the village stores. So leatherworker Vel'rin Fang sends hunters to bring back more hides. The Darkspear hunt Durotar's tigers only when the tribe needs more supplies. Their hunters cross the water to the Echo Isles and track the predators there. For the trolls, each hunt also tests patience, discipline and skill in the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_817-29f2fb237d27522a0b2d/1-0000.mp3", duration = 42.1355102, start = 0},
  },
}
P.transport["quest:818"] = {
  hash = "cae79a",
  fullHash = "cae79a",
  text = "A Solvent Spirit. In Sen'jin Village, Master Vornal tests those who seek his teaching as his sight fades. He sends them to Durotar's coast for makrura eyes and crawler mucus, measuring their patience and resolve. Master Vornal lives in Sen'jin Village, where age has dimmed his sight. Primal magic once came easily to him, but now he relies on alchemy to sharpen his perceptions and weave his arts. His body weakens, yet the stubborn troll refuses an apprentice. He says neither the Darkspear nor Durotar's orcs have produced anyone worthy of his teaching. Vornal asks for raw materials from Durotar's harsh coast: intact makrura eyes and vials of crawler mucus. Taking undamaged eyes from armored, snapping makrura calls for careful strikes. Gathering enough mucus tests whether a would-be pupil can endure tedious work. For Vornal, the hunt is less about reagents than learning who can keep their focus. For Master Vornal, time and patience measure strength. He expects brash youths to grow frustrated or abandon the work. Pristine ingredients brought back to Sen'jin Village show survival skills along the dangerous reefs of the Echo Isles channel. They also show the discipline needed to master alchemy's subtle arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_818-cf103e78453717874c4d/1-0000.mp3", duration = 79.0726531, start = 0},
  },
}
P.transport["quest:819"] = {
  hash = "205705",
  fullHash = "205705",
  text = "Chen's Empty Keg. In the Barrens, Chen Stormstout’s marked keg lies abandoned. Its discovery recalls the brewmaster’s old ties to Durotar. Across the dry Barrens, travelers sometimes find an abandoned wooden barrel. Razormane quilboar and Kolkar centaur leave ordinary casks behind, but this one is carefully made and bears a plaque: “Chen Stormstout - May your spirit be raised and always raise your spirits.” It is an odd relic beneath Kalimdor’s sun. To learn how it came here, you seek someone who knows brewing. In Ratchet, Brewmaster Drohn recognizes the keg’s craft and names Chen Stormstout as its owner. Chen is a wandering Pandaren who traveled with Rexxar during the battles that secured Durotar for Thrall’s Horde. Years have passed since Chen walked Kalimdor’s red earth. Yet seasoned brewers still remember his recipes and wandering spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_819-ef1324835b4de3b1bb0e/1-0000.mp3", duration = 56.4244898, start = 0},
  },
}
P.transport["quest:821"] = {
  hash = "a4ae22",
  fullHash = "a4ae22",
  text = "Chen's Empty Keg. In Ratchet, Brewmaster Drohn hopes to bring Chen Stormstout's potent brew back with wild Barrens ingredients. A marked keg recalls Chen Stormstout to Brewmaster Drohn in Ratchet. Chen entrusted the secrets of his namesake brew to Drohn's mentor, who passed them on to Drohn. The recipe calls for raw, potent parts from the Barrens' fierce wildlife. To those outside the brewing trade, that is an unusual choice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_821-ba43168fb748572e18a0/1-0000.mp3", duration = 27.2979592, start = 0},
  },
}
P.transport["quest:823"] = {
  hash = "8ec018",
  fullHash = "8ec018",
  text = "Report to Orgnil. Master Gadrin sends a warning from Sen'jin Village to Razor Hill about the Burning Blade. Demonic corruption is spreading through Durotar. Sen'jin Village has troubles of its own, especially Zalazane's treachery on the Echo Isles. Yet the Burning Blade threatens more than the village. Demonic corruption has been uncovered in the Valley of Trials, and Master Gadrin knows the danger cannot be faced alone. So he sends you north along the road to Razor Hill, where orc authorities watch over Durotar. Orgnil Soulscar is at Razor Hill's military encampment, charged with rooting out evils in Durotar and guarding its central lands. When you bring Gadrin's warning, Orgnil joins the reports from Sen'jin Village and the Valley of Trials. The Burning Blade is dangerously close. He quickly gathers forces to break up the cultists before their rituals can unseat the young nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_823-efae1e305c49ab498467/1-0000.mp3", duration = 51.9836735, start = 0},
  },
}
P.transport["quest:825"] = {
  hash = "b08781",
  fullHash = "b08781",
  text = "From The Wreckage..... Gar'Thok sends Horde scouts to the Scuttle Coast wrecks to recover Gnomish Tools. The Horde hopes to study Alliance engineering and put that knowledge to use. Grand Admiral Daelin Proudmoore brought Kul Tiras's fleet to Kalimdor. Its ships crowded the shore near Tiragarde Keep. After his defeat, broken hulls sank along the Scuttle Coast. The surviving Kul Tiran soldiers fortify the keep, while the wrecks lie scattered on the shoals beneath the tide. Alliance ingenuity can give its enemies an edge over orcish strength, iron, and blood. Gnomish technicians sailed with the expeditionary fleet and fitted its ships with complex machinery and precise tools. Gar'Thok wants the Horde to recover those tools from the wrecks. Then its craftspeople can learn how they work. Gar'Thok sends the salvaged tools by caravan from Razor Hill to Orgrimmar. There, Horde craftspeople and tacticians hope to study the gnomish instruments. They seek ways to counter Alliance devices in future conflicts and strengthen their own industries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_825-305f5f802ed06750a5ac/1-0000.mp3", duration = 66.7428571, start = 0},
  },
}
P.transport["quest:826"] = {
  hash = "ec7c88",
  fullHash = "ec7c88",
  text = "Zalazane. On the Echo Isles, dark magic has driven Zalazane mad and turned him against his tribe. Master Gadrin of Sen'jin Village calls Horde champions to end the witch doctor's rule. Zalazane enslaved his fellow tribesmen, seized the Darkspear trolls' rightful home, and drove them into exile on Durotar's coast. After fleeing their sunken island, the Darkspear followed Thrall across the Great Sea and settled on the Echo Isles, just off Durotar's southeast coast. Zalazane was once a respected and powerful witch doctor, but he hungered for power. His hexes enslaved the minds of his kin, and violence followed. Vol'jin led those who remained free, yet they were driven from their ancestral camps and forced to build a temporary refuge at Sen'jin Village. From his hilltop stronghold on the largest Echo Isle, Zalazane still sends raiding parties across the channel. They seize more Darkspear and bring them under his control. The captured trolls become mindless voodoo and hexed thralls, lost to their tribe. Master Gadrin sees a threat to more than Darkspear land: Zalazane endangers the tribe's survival. Until his severed head is brought before the elders, no Darkspear can be safe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_826-4ee8536f852f697bed27/1-0000.mp3", duration = 76.1730612, start = 0},
  },
}
P.transport["quest:827"] = {
  hash = "99c941",
  fullHash = "99c941",
  text = "Skull Rock. Margoz sends you east of Orgrimmar, where Burning Blade cultists hold Skull Rock. They bind themselves to dark magic with painful demonic devices. Margoz needs the cursed artifacts to study the cult near the capital. In northeastern Durotar, Burning Blade cultists gather close to Orgrimmar's gates. Their cave lies among the hills, away from the open roads but near the Warchief's seat. The cult has long plagued orcish society, and now its followers perform rituals in the tunnels. Nearby, the Warchief's scouts keep watch. Burning Blade cultists wear Searing Collars around their necks. The metal bands scorch and brand their flesh. Margoz believes the pain and fel sorcery attune their wearers to demonic power. He asks you to recover the collars so he can study the spells and bindings that empower them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_827-da02d2719f57573110f2/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["quest:828"] = {
  hash = "14021e",
  fullHash = "14021e",
  text = "Margoz. In northern Durotar, Margoz keeps watch for the Burning Blade's growing threat. After the clash with fel corruption at Thunder Ridge, Orgnil Soulscar sends champions to seek the shaman at his lonely camp before they strike a nearby cultist stronghold. Margoz's counsel reveals Skull Rock as the Burning Blade's concealed cavern base. After Thunder Ridge revealed the depth of fel taint, Orgnil Soulscar sees that strength alone cannot cleanse Durotar. So he sends champions to Margoz, an experienced orc shaman at a lonely camp in the crags northeast of Razor Hill. Between Drygulch Ravine and the eastern sea, Margoz watches the northern reaches for dark omens that Orgrimmar's busy warriors often miss. Margoz knows where the Burning Blade has built its power in northern Durotar: Skull Rock, a concealed cavern system carved into the mountain cliffs outside Orgrimmar's southern gates. The cultists are closer to Thrall's capital than the Warchief's guards realize. Hidden passages there could shelter a demonic ambush, so Margoz gives counsel to those sent against the coven before they enter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_828-a72f1fd4c9e82e6e4e15/1-0000.mp3", duration = 67.9183673, start = 0},
  },
}
P.transport["quest:829"] = {
  hash = "819275",
  fullHash = "819275",
  text = "Neeru Fireblade. In Orgrimmar, Neeru Fireblade studies dark arts he claims can guard the Horde. Margoz sends you from Durotar with a Searing Collar taken from the Burning Blade, hoping the warlock can explain its demonic power. Margoz has reached the edge of shamanic craft. The collars taken from Burning Blade cultists at Skull Rock bear demonic sorcery he cannot unravel. Shamans draw on the elements and ancestral spirits. So Margoz sends you to a warlock in the capital to learn what the collars do. Beneath Orgrimmar's red cliffs lies the Cleft of Shadow. Warlocks and other practitioners of forbidden magic work there beneath Thrall's wary eye. Neeru Fireblade lives in the cavern and says he studies fel power to thwart demonic threats. When you bring him the collar, his curiosity turns Durotar's investigation toward the warlock enclave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_829-5c47c55e789d92754e7e/1-0000.mp3", duration = 55.4840816, start = 0},
  },
}
P.transport["quest:83"] = {
  hash = "43bfde",
  fullHash = "43bfde",
  text = "Red Linen Goods. At Eastvale Logging Camp, Sara Timberlain needs linen for her tailoring. She asks you to recover bandanas from Defias bandits so she can keep making goods for travelers. Across Elwynn, Defias bandits wear red linen bandanas. Their less organized kin in Northshire make do with cheap burlap masks. The linen gives Sara workable cloth for her tailoring. At Eastvale Logging Camp, Sara Timberlain needs textiles for her trade. Taking bandanas from Defias camps scattered through the woods supplies her with cloth and helps check the bandits' encroachment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_83-6225e022531e7f8488fe/1-0000.mp3", duration = 36.2057143, start = 0},
  },
}
P.transport["quest:830"] = {
  hash = "2ecfa3",
  fullHash = "2ecfa3",
  text = "The Admiral's Orders. On Durotar’s coast, the Admiral’s Orders carry word of a threat to the young Horde. Sealed by the late Grand Admiral Daelin Proudmoore, they show that the Kul Tiran garrison is organized and entrenched. Gar'Thok in Razor Hill needs to know what they contain. On the upper floors of Tiragarde Keep, a heavy chest holds an aged envelope under Lieutenant Benedict’s watch. Grand Admiral Daelin Proudmoore sealed it with his crest. Its parchment gives naval commands from Kul Tiras’s bloody invasion of Durotar. Though the Grand Admiral fell at Theramore, his officers still hold their fortifications and cling to their mission against the Horde settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_830-6bbce4a1a0a2e5151d93/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["quest:8311"] = {
  hash = "46aecb",
  fullHash = "46aecb",
  text = "Hallow's End Treats for Jesper!. During Hallow's End, Jesper lies sick in Stormwind and longs for treats and fun beyond the orphanage. Too ill to go out, he asks Alliance adventurers to gather sweets for him. Jesper lies sick in Stormwind's orphanage in Cathedral Square during Hallow's End. While the children gather sweets across Azeroth, he must stay inside. So he hopes passing adventurers will share the holiday spirit and bring him treats. To bring Jesper the sweets he hopes for, you travel beyond Elwynn Forest. You visit the innkeepers of Stormwind, Ironforge, and Darnassus, then the gnome exile Talvash del Kissel. Each asks you to perform before giving you a treat. You cluck like a chicken, dance, flex, or chug like a train, and earn regional sweets such as Stormwind Nougat and Gnomeregan Gumdrops.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8311-0693fb2eb6281a5d5df9/1-0000.mp3", duration = 53.237551, start = 0},
  },
}
P.transport["quest:832"] = {
  hash = "b52007",
  fullHash = "b52007",
  text = "Burning Shadows. In Skull Rock, the Eye of Burning Shadow carries warnings from the Burning Blade. Its voice threatens Gazz'uz with Neeru Fireblade's wrath. After Gazz'uz falls deep within Skull Rock, the Eye of Burning Shadow is found among his remains. The stone carries a voice into the mind of anyone who holds it. The speaker demands a report from Gazz'uz. His secret work east of Orgrimmar has been compromised.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_832-6450dde7d3e23a12ce65/1-0000.mp3", duration = 25.9918367, start = 0},
  },
}
P.transport["quest:833"] = {
  hash = "ef8bd5",
  fullHash = "ef8bd5",
  text = "A Sacred Burial. At Red Rocks in eastern Mulgore, Lorekeeper Raintotem calls on Horde adventurers to protect the sacred burial grounds. Bristleback quilboar have overrun the graves of tauren warriors who gave their lives founding and defending Thunder Bluff. Red Rocks is among Mulgore's most revered sanctuaries, set in the crags beneath the eastern mountains. Only the most valiant tauren are laid to rest there. These legendary warriors shed blood to protect their tribes and their chieftains, and to carve out a lasting homeland atop Thunder Bluff's mesas. To the Shu'halo, disturbing their rest insults both tradition and the Earth Mother. The nomadic Bristleback quilboar have long contested tauren control over central Kalimdor. Their recent push into Red Rocks is a grave escalation. Bands of Bristleback Interlopers have crept onto the holy grounds, ravaging the earth and disturbing the resting places. Lorekeeper Raintotem is too aged to drive them away alone, so young Horde champions must take up arms and defend the honored dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_833-fa1383ec2404c062ff29/1-0000.mp3", duration = 63.2685714, start = 0},
  },
}
P.transport["quest:834"] = {
  hash = "c744ec",
  fullHash = "c744ec",
  text = "Winds in the Desert. Rezlak waits in Durotar for a stolen supply caravan. Dustwind harpies ambushed it in Razorwind Canyon and scattered the building materials among the cliffs. Rezlak came from Ratchet at Chief Engineer Gazlowe's command, to help the Horde build across Durotar. The harsh, barren land makes fortification work hard enough. Now shipments vanish before they reach the building sites, and without the cargo, work stops. The irritable goblin supervisor has nothing to build with. Dustwind harpies ambushed the latest supply run in Razorwind Canyon. They roost in the high ravines beside the road from Razor Hill to Orgrimmar, then swoop on passing wagons. They neither eat nor destroy the freight. Instead, they hoard crates and sacks near their nests, where the supplies wait for anyone willing to fight through their territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_834-338a30452a6be36822e9/1-0000.mp3", duration = 50.6253061, start = 0},
  },
}
P.transport["quest:835"] = {
  hash = "297c41",
  fullHash = "297c41",
  text = "Securing the Lines. Near Razorwind Canyon, Rezlak needs the goblin supply routes through Durotar kept safe. Harpies in Drygulch Ravine intercept and plunder caravans, so he hires help to drive them out. Dustwind harpies make travel through Durotar’s dry valleys dangerous. Rezlak oversees regional supply operations for his boss, Gazlowe. From their roost in Drygulch Ravine, the harpies raid caravans in Razorwind Canyon and seize shipments before they reach their destinations. Rezlak believes the right price can get anything done. He hires adventurers to break the roost by eliminating Dustwind Savages and Dustwind Storm Witches, rather than entering the canyon himself. Clearing the harpies keeps trade corridors open and secures shipments of engineering gadgets. It also points helpful travelers toward greater opportunities in Ratchet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_835-45f0c37d868292f3a938/1-0000.mp3", duration = 52.6367347, start = 0},
  },
}
P.transport["quest:8353"] = {
  hash = "b5abb6",
  fullHash = "b5abb6",
  text = "Chicken Clucking for a Mint. At Hallow's End, Innkeeper Firebrew asks Ironforge visitors to cluck for a mint for Jesper, a young orphan in Stormwind. Alliance champions gather sweets from their capitals to bring him cheer. Jesper is sick, orphaned in Stormwind, and longs for Hallow's End sweets. Alliance champions gather treats for him from innkeepers in their capitals. So seasoned adventurers have reason to go door to door during the harvest-to-winter celebration. Innkeeper Firebrew keeps the Ironforge Mints at the Stonefire Tavern in Ironforge's Commons. A polite request won't do. Visitors flap their arms and cluck like chickens before he parts with one. The performance gives the tavern's patrons a laugh, and the mint helps bring holiday cheer to Jesper.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8353-c9cb0f3ec0a85b8aad6d/1-0000.mp3", duration = 46.837551, start = 0},
  },
}
P.transport["quest:8354"] = {
  hash = "4456c0",
  fullHash = "4456c0",
  text = "Chicken Clucking for a Mint. At Hallow's End, Innkeeper Norman of the Undercity offers a sweet to travelers helping an ailing child. Earn the Undercity Mint by setting dignity aside and flapping like a chicken. Laughter is scarce in the Undercity, built beneath Lordaeron's ruins by the liberated Forsaken. Yet when Hallow's End comes, even the grim folk of the Trade Quarter join the revelry. Innkeeper Norman keeps Undercity Mints for travelers gathering treats for Spoops, a sick orphan who needs holiday cheer. Innkeeper Norman will not hand a treat to seasoned adventurers without a show. He believes grown warriors and spellcasters should earn their sweets. So the petitioner must mimic a barnyard chicken right before his counter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8354-1189b4f68863c2a25fcd/1-0000.mp3", duration = 45.0873469, start = 0},
  },
}
P.transport["quest:8355"] = {
  hash = "21691c",
  fullHash = "21691c",
  text = "Incoming Gumdrop. Talvash del Kissel keeps a Gnomeregan Gumdrop in Ironforge for a sick child in Stormwind. To earn it, you must give him a convincing train impression. At Hallow’s End, trick-or-treaters visit the Alliance strongholds for treats. In Ironforge’s Mystic Ward, Talvash del Kissel keeps the Gnomeregan Gumdrop. He feels for the young orphan who hopes to receive it. Yet Talvash asks you to bring some mischief to the holiday with a convincing train impression. Jesper is an ailing orphan in Stormwind City, hoping for four treats from across the Alliance. He wants nougat from Stormwind, a mint from Ironforge, marzipan from Darnassus, and a gumdrop from Gnomeregan. Your locomotive impression entertains Talvash and earns you the gumdrop. It brings Jesper closer to his holiday wish.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8355-887aab9ca26c9f9b157c/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["quest:8356"] = {
  hash = "3068c4",
  fullHash = "3068c4",
  text = "Flexing for Nougat. At the Gilded Rose, Innkeeper Allison asks you to flex before she gives you Stormwind Nougat. During Hallow's End, you gather festive sweets for Jesper, an orphan in Stormwind. Hallow's End brings a lighter mood to Stormwind. The holiday marks the turn of the seasons and guards against dark spirits. Common folk celebrate with disguises, revelry and trick-or-treating. Alliance innkeepers offer traditional sweets to those who perform a harmless trick. At the Gilded Rose in the Trade District, Innkeeper Allison asks for a show before handing out holiday candy. You are gathering sweets for Jesper, an orphaned boy. Allison playfully comments on your physique and asks you to flex your muscles. When you do, she gives you a piece of chewy Stormwind Nougat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8356-6976fd3efa60e429acbc/1-0000.mp3", duration = 48.6661224, start = 0},
  },
}
P.transport["quest:8357"] = {
  hash = "17827a",
  fullHash = "17827a",
  text = "Dancing for Marzipan. At Hallow's End, travelers in Darnassus gather sweets for Jesper, a sick orphan in Stormwind. Innkeeper Saelienne keeps the trick-or-treat custom, asking for a dance before she gives her Darnassus Marzipan. At Hallow's End, Darnassus takes on a lighter spirit. It is the sacred forest city of the long-lived night elves. You come seeking sweets for Jesper, a sick child recovering in Stormwind. Innkeeper Saelienne keeps the season's custom, even for a child in need. First, she asks for a trick. Saelienne asks you to dance on the inn floor before she gives you Darnassus Marzipan. Your performance earns the sweet for the holiday care package bound for Jesper.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8357-4f02d0df93e6ca2bfd5c/1-0000.mp3", duration = 44.1991837, start = 0},
  },
}
P.transport["quest:8359"] = {
  hash = "e7f493",
  fullHash = "e7f493",
  text = "Flexing for Nougat. In Orgrimmar, Innkeeper Gryshka trades nougat for a little show. During Hallow's End, you flex for a sweet meant to cheer Spoops, a bedridden child. Hallow's End fills Azeroth's capitals with pranks and sweet-gathering. In Orgrimmar's inn, Innkeeper Gryshka keeps holiday sweets for those who join the custom. Your travels may bring dragons and dark sorcery, but here the bargain is plain: perform a trick or leave without a treat. Innkeeper Gryshka asks you to show Orcish strength before she gives you Orgrimmar Nougat for young Spoops. Whatever disguise or armor you wear, strike a muscular pose. Even the Horde's feared fighters can amuse the common folk for candy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8359-7f9c641e7a39969100e9/1-0000.mp3", duration = 44.1208163, start = 0},
  },
}
P.transport["quest:8360"] = {
  hash = "0a9ab0",
  fullHash = "0a9ab0",
  text = "Dancing for Marzipan. During Hallow's End, Innkeeper Pala asks visitors to dance for Thunder Bluff Marzipan. The treat is meant for a sick orphan, and the custom brings holiday cheer to Mulgore's high mesas. During Hallow's End, Innkeeper Pala keeps the trick-or-treat custom in Thunder Bluff. You come seeking a sweet for an ailing child, but Pala asks for a festive dance first. Then she gives you Thunder Bluff Marzipan. For Pala, the custom is simple. Step forward and dance to earn a sweet. Once you have entertained her, she gives you the marzipan and warm wishes for the sick youth waiting for it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8360-242149d6d0aba24feed3/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["quest:84"] = {
  hash = "a14f26",
  fullHash = "a14f26",
  text = "Back to Billy. Bernice Stonefield sends you across the road with a pork belly pie for Billy Maclure. He has information about her missing necklace, and the delivery carries on the feud between their families in central Elwynn Forest. The feud between the Stonefields and Maclures leaves little room for kindness. Auntie Bernice Stonefield baked a pork belly pie because Billy Maclure would not share what he knew about her family heirloom without one. She hands you the pie with plain irritation. Bernice hopes Billy chokes on every bite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_84-98e165b9ce2df42f1ec1/1-0000.mp3", duration = 29.8318367, start = 0},
  },
}
P.transport["quest:840"] = {
  hash = "c3360e",
  fullHash = "c3360e",
  text = "Conscript of the Horde. Along Durotar’s western road, recruits head toward the Barrens under the name Conscript of the Horde. Takrin Pathseeker watches beyond Razor Hill and gives them a letter for Kargal Battlescar, whose outpost guards the crossing. You have proved your strength around Razor Hill, and now you are called west to serve the wider Horde. Takrin Pathseeker watches the road out of Durotar for his friend, veteran Kargal Battlescar. He gives capable travelers a recruitment letter to carry across the Southfury River. For a recruit, it marks a first formal assignment beyond the orcs’ new homeland. Kargal Battlescar holds the outpost beyond the bridge, between Durotar’s red canyons and the dry Barrens. He gathers recruits to guard the frontier, where centaur, quilboar, and Alliance expeditions test the border. Yet the Horde needs more than guards there. Raw manpower is also bound for the settlement of the Crossroads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_840-a576f8cf2f83111e51fa/1-0000.mp3", duration = 55.5102041, start = 0},
  },
}
P.transport["quest:842"] = {
  hash = "8c0519",
  fullHash = "8c0519",
  text = "Crossroads Conscription. Kargal Battlescar sends recruits west from the Far Watch Post to report at Crossroads Conscription. With his signed letter, you make for Sergra Darkthorn at the Barrens’ central hub. After you prove your worth, Kargal Battlescar sends you west from the Far Watch Post. He gives you a signed letter of recruitment for the journey along the packed dirt road through the Barrens’ arid brush. The road reaches a central junction where the Crossroads links northern Kalimdor with the southern wilderness. At the Crossroads, Sergra Darkthorn receives new arrivals. Warchief Thrall chose the sharp-tongued orc shaman to oversee its operations. Kargal Battlescar grumbles that she is difficult and talks too much, though Thrall holds her in high esteem.\n\nSergra is fierce and unyielding. She reminds recruits, especially arrogant men, that female warriors and leaders stand as equals in Thrall’s Horde. Insolence has no place here.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_842-7855a94e53ebaec53619/1-0000.mp3", duration = 59.5853061, start = 0},
  },
}
P.transport["quest:844"] = {
  hash = "daf5ea",
  fullHash = "daf5ea",
  text = "Plainstrider Menace. East of the Crossroads, plainstriders threaten the outpost’s food stores. Sergra Darkthorn sends new Horde arrivals to hunt them, giving the newcomers their first measure of the Barrens. The Crossroads coordinates supplies across Kalimdor. Now plainstriders east of the outpost are picking at its food crates. Sergra Darkthorn, an orc shaman, sends newly arrived Horde adventurers to hunt the birds before they damage the stores. The settlement depends on those provisions. Sergra Darkthorn uses the hunt to test newcomers and protect the settlement’s supplies. To her, plainstriders are simple prey, fit to teach young hunters to endure the elements and track quarry across the sun-baked plains. Bringing back their sharp beaks shows patience and the basic martial skill needed to face fiercer beasts of the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_844-9af3ee93864b4c14b171/1-0000.mp3", duration = 51.5134694, start = 0},
  },
}
P.transport["quest:845"] = {
  hash = "7638c0",
  fullHash = "7638c0",
  text = "The Zhevra. At the Crossroads, Sergra Darkthorn sends young Horde warriors to hunt zhevra. Their trial prepares them for the Barrens' more dangerous beasts. After the plainstriders, Sergra Darkthorn sets you after tougher prey. Zhevras run in herds across the northern and southern Barrens. They are swift and stubborn, though not the savanna's fiercest beasts. Their kicks can break bone. Sergra uses the hunt to test your growing skill. She asks for four intact hooves as proof of the kill. A zhevra's rear kick can knock a grown tauren onto their haunches. Pass this trial, and you draw closer to facing the plains' predatory prowlers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_845-bdbe1af74eb4eaa41015/1-0000.mp3", duration = 41.482449, start = 0},
  },
}
P.transport["quest:848"] = {
  hash = "16a1d1",
  fullHash = "16a1d1",
  text = "Fungal Spores. At the Barrens oases, Horde adventurers gather Fungal Spores for Apothecary Helbrim of the Royal Apothecary Society. Strange, mutative energies flow through the springs and alter local plants into potent reagents. Helbrim seeks the specimens to brew concoctions for his colleague in Thunder Bluff. The Barrens is dry savanna, yet the Forgotten Pools, Lushwater Oasis, and Stagnant Oasis brim with unnatural life. A curious surge of life energy flows from their waters, warping and invigorating plants and beasts that drink there. Laden mushrooms grow along the muddy banks and absorb those currents. Their spores hold rare properties that draw passing alchemists. Apothecary Helbrim works at the Crossroads, far from the Undercity, yet remains devoted to the Royal Apothecary Society's research. He gathers the altered spores because native Kalimdor reagents have strange potency, then uses them to craft powerful mixtures. The specimens are bound for Apothecary Zamah in Thunder Bluff, as part of the Forsaken's scientific work across allied lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_848-b35b8803a3709d4d78d5/1-0000.mp3", duration = 67.8922449, start = 0},
  },
}
P.transport["quest:85"] = {
  hash = "436b7d",
  fullHash = "436b7d",
  text = "Lost Necklace. In southern Elwynn, Bernice Stonefield looks for her missing necklace. She suspects Billy Maclure, the young son of the family across the road, and asks you to find him. The Stonefields and Maclures live on adjoining land in southern Elwynn Forest, but goodwill between them is scarce. When “Auntie” Bernice Stonefield finds her cherished necklace missing, she blames the youngest Maclure. Certain Billy Maclure came onto her farm and took it, the bitter widow asks you to cross the road to the vineyards, find the boy, and demand its return.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_85-f2d99ef1a8b169cd31f1/1-0000.mp3", duration = 33.6718367, start = 0},
  },
}
P.transport["quest:850"] = {
  hash = "89ca9a",
  fullHash = "89ca9a",
  text = "Kolkar Leaders. Regthar Deathgate moves against Kolkar leaders gathering strength in the Barrens. The nomadic centaur have plagued the tauren for generations. Now new chieftains are uniting scattered bands into a military threat, and Regthar sends Horde champions against Barak Kodobane at the Forgotten Pools before his influence spreads. Centaur have terrorized Kalimdor for countless years. Before Thrall's Horde arrived and turned the tide, they drove the nomadic tauren nearly to extinction. In the Barrens, the dominant Kolkar tribe usually roams in scattered marauding bands. Now aggressive chieftains are joining those bands together, making raiders strong enough to challenge the Horde's fortified outposts. Regthar Deathgate, an orc warrior, is stationed in an encampment west of the Crossroads. He knows boldness and brute force hold the Kolkar together. Without strong commanders, their raiders fall to infighting. So Regthar sends Horde champions against the leaders to blunt their advance. Barak Kodobane, an ambitious chieftain, is the first target. He is camped near the waters of the Forgotten Pools.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_850-28d7c518b18a531e12c1/1-0000.mp3", duration = 68.5714286, start = 0},
  },
}
P.transport["quest:851"] = {
  hash = "c7c300",
  fullHash = "c7c300",
  text = "Verog the Dervish. Across the southern Barrens, Verog the Dervish keeps moving while Regthar Deathgate tries to draw him out. The orc sends Horde champions to strike the Kolkar command tent at the Stagnant Oasis and bring the nomadic leader into the open. After Barak Kodobane fell, Regthar Deathgate turned to the Kolkar warlords still standing. Barak had kept near the northern waters of the Forgotten Pools, but Verog roams the sun-baked plains and seldom stays long in one camp. Horde scouts struggle to follow him across that wide country. So they must make the commander come to them. Verog works from the Kolkar command post at the Stagnant Oasis, southeast of the Crossroads. Regthar sends you against the camp to strike the Kolkar warriors near their command tent. Their alarm calls Verog back to defend the outpost. There, the Horde blades can reach him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_851-a9964ce19ead706b566d/1-0000.mp3", duration = 51.8008163, start = 0},
  },
}
P.transport["quest:852"] = {
  hash = "4a5c0d",
  fullHash = "4a5c0d",
  text = "Hezrul Bloodmark. At Lushwater Oasis, Hezrul Bloodmark directs the Kolkar incursions across the Barrens. Regthar Deathgate sends you to end his command and break the centaur's hold on the region. Barak Kodobane and Verog the Dervish have fallen. Hezrul Bloodmark remains the Kolkar's paramount chieftain in the Barrens. Regthar Deathgate calls him brutal and cunning, the spearhead of the centaur incursions across the savanna. The Horde hopes his death will sow chaos and break the Kolkar ranks beyond repair before they overwhelm Horde settlements. Hezrul commands his warbands from Lushwater Oasis, south of the Crossroads. Watering holes are scarce in the Barrens, so this oasis is vital to survival. It is also a strategic hub and a staging ground for Kolkar raiders. On Hezrul's own ground, you deny the centaur their most vital stronghold and sever their hold on the southern trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_852-8c3d7048db4c65cb08d9/1-0000.mp3", duration = 59.4546939, start = 0},
  },
}
P.transport["quest:853"] = {
  hash = "99f243",
  fullHash = "99f243",
  text = "Apothecary Zamah. In Thunder Bluff, Apothecary Zamah awaits a fragile brew from the Barrens. It must reach her laboratory beneath Spirit Rise before it loses its strength. Apothecary Helbrim has turned fungal blooms from the Barrens oases into a delicate emulsion. The brew weakens soon after it is made. Helbrim cannot reach Mulgore in time, so he entrusts the flask to a reliable runner bound for Thunder Bluff. Apothecary Zamah works in the Pools of Vision, a cavern beneath Spirit Rise's sacred heights. Forsaken mages and priests share this refuge underground. Below the tauren sanctuary, the Royal Apothecary Society quietly studies raw materials gathered across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_853-a5946c472b62a1bd253d/1-0000.mp3", duration = 44.6955102, start = 0},
  },
}
P.transport["quest:854"] = {
  hash = "f80fa9",
  fullHash = "f80fa9",
  text = "Journey to the Crossroads. At Camp Taurajo, Kirge Sternhorn sends travelers north to aid Thork at the Crossroads. Their road leads from Mulgore into the Barrens, where the Horde’s struggles widen. At Camp Taurajo, many tauren first meet the Barrens beyond Mulgore. Just beyond the mountain pass, mystic Kirge Sternhorn watches travelers descend into the dry grasslands. When Kirge sees one ready to go farther, Kirge points north along the dusty trade route to the Crossroads. The tauren of Thunder Bluff and Thrall’s new Horde now share their fortunes. Kirge says their fates are bound together, and orcs at the Crossroads need reinforcements as they struggle to establish an outpost. At the settlement, Thork welcomes travelers from even the high bluffs. He is ready to test their strength against the dangers of the savanna.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_854-8e55664a66bc072e7eea/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["quest:855"] = {
  hash = "1f66cc",
  fullHash = "1f66cc",
  text = "Centaur Bracers. West of the Crossroads, Regthar Deathgate seeks proof against the Kolkar. Their raids threaten Horde control of the central Barrens. The young Horde is still securing its lands across Kalimdor. The Barrens stretch between Durotar and Mulgore, where Kolkar centaurs contest the watering holes and open plains. Their attacks fall on supply trains and scouting parties. From his bunker west of the Crossroads, the orc warrior Regthar Deathgate directs the defense. Regthar asks for proof that Kolkar warriors have fallen. Soldiers who enter Kolkar territory return with bracers taken from slain centaurs. These trophies support claims for Horde bounties, and Regthar hopes they will frighten the surviving raiders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_855-cf84c0254a61b6be5343/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["quest:8569"] = {
  hash = "3c4c22",
  fullHash = "3c4c22",
  text = "Past Efforts in Warsong Gulch. In Warsong Gulch, soldiers hold Ashenvale’s southern border while commanders honor their sacrifices. The Ribbon of Sacrifice marks steadfast service, even when battle brings no clear victory. Along Ashenvale’s southern border, the Silverwing Sentinels and Warsong Outriders fight brutal skirmishes. Many battles end without a clear victory. Stormwind, Orgrimmar and other capitals honor those who hold their ground against the odds. The Ribbon of Sacrifice marks fighters who gave themselves to the struggle. Far from the front, Alliance Brigadier Generals and Horde Warbringers oversee their forces. Recruiters send new fighters to Warsong Gulch, while quartermasters and tacticians account for veterans returning from hard campaigns. By honoring courage in stalemate or defeat, leaders help keep soldiers committed to holding Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8569-5a30214cbd55dc07b23e/1-0000.mp3", duration = 55.0138776, start = 0},
  },
}
P.transport["quest:858"] = {
  hash = "0e3f13",
  fullHash = "0e3f13",
  text = "Ignition. At a Venture Company camp in the northern Barrens, a trapped pilot needs the key to get free. The spy has taken a shredder without its ignition key and sends you to fetch one from the site supervisor. Sputtervalve sent a spy into a Venture Company shredder at the northern Barrens drilling grounds. The operative plans to take the machine and study its workings. Yet its steering and movement column remains locked without the ignition key. A goblin worker has spotted the idle shredder, so the hijacker claims its engine has failed. Trapped beneath the glass canopy with workers nearby, the operative points you toward the central derrick. The supervisor keeps spare ignition keys in the upper control office. One of those keys is the pilot’s only way out before the bluff fails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_858-2c55ab5418262f6d3eab/1-0000.mp3", duration = 44.9044898, start = 0},
  },
}
P.transport["quest:86"] = {
  hash = "650b3e",
  fullHash = "650b3e",
  text = "Pie for Billy. In Elwynn, you gather meat for Bernice's pie while Billy holds back what he knows about her necklace. Bernice agrees to bake, though she believes Billy stole her family's jewelry. Billy Maclure gives no apology when you ask about the necklace. He will neither return it nor name who has it until he gets a freshly baked pork belly pie. He knows Bernice is the finest cook in the valley, and means to enjoy the bargain. Bernice is furious at the thought of feeding the boy she believes stole her family's jewelry. Still, she agrees to bake before you gather the meat. You bring her meat from wild boars roaming nearby pastures. She sets aside her pride, hoping to get her prized necklace back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86-2f87a4e4f5cafee764f3/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["quest:860"] = {
  hash = "fc62ff",
  fullHash = "fc62ff",
  text = "Sergra Darkthorn. At the Crossroads, Sergra Darkthorn awaits tauren hunters leaving Mulgore behind. Melor Stonehoof sends them north into the Barrens, where danger grows harsher and the Horde's lands reach beyond their home. When their first trials are done, Melor Stonehoof sends young tauren hunters east from Mulgore. Bloodhoof Village and its valleys are familiar ground, where patient tracking has prepared them for what comes next. Now he tells them to pack their gear and cross the mountain pass into the Barrens, leaving their homeland's safety for harsher country. The road winds through red rock canyons before opening onto the Barrens' broad, sun-scorched savanna. There, where Kalimdor's central trade routes meet, the Crossroads is a fortified settlement shared by orcs, trolls, and tauren.\n\nSergra Darkthorn waits on its eastern side. The experienced orc shaman demands much of the hunters she guides. She teaches those who come to stalk the Barrens' fierce wildlife, testing their eagerness against the discipline the wilderness requires.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_860-da63ef04e17822c81780/1-0000.mp3", duration = 64.1828571, start = 0},
  },
}
P.transport["quest:861"] = {
  hash = "3bd9b9",
  fullHash = "3bd9b9",
  text = "The Hunter's Way. In Mulgore, young adventurers follow The Hunter's Way under Skorn Whitecloud's guidance. You hunt flatland prowlers and take their claws to Melor Stonehoof on Thunder Bluff's Hunter Rise, proving your skill and respect for the wild. Among the tauren, hunting is one of the highest honors. It asks for patience, care for the Earth Mother's balance, and respect for the beasts of the plains. Elder Skorn Whitecloud tracked across Kalimdor for decades before coming to rest in Mulgore. Seeing young adventurers eager to roam, he gives them a traditional trial to turn ambition into discipline. Flatland prowlers test a candidate's tracking skill. Great cats, they move swiftly and quietly through Mulgore's high grass, then ambush their prey. Bring four sets of claws to show you can find a predator before it finds you. Then turn its own ferocity against it. With the claws gathered, you climb the wooden towers and bridges to Hunter Rise in Thunder Bluff. Melor Stonehoof receives the trophies there. A master tracker, Melor values Skorn Whitecloud's ancient wisdom. He accepts the claws as proof that you have the spirit to learn more of Kalimdor's hunting ways.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_861-997210198ae8e9843260/1-0000.mp3", duration = 71.7844898, start = 0},
  },
}
P.transport["quest:863"] = {
  hash = "8b7ebd",
  fullHash = "8b7ebd",
  text = "The Escape. At the Sludge Fen in northern Barrens, Wizzlecrank fights his way out of a Venture Company drill site. Trapped in a stolen prototype shredder, the goblin pilot needs your protection from company mercenaries. Then you carry word to his contact, Sputtervalve, in Ratchet. At the Sludge Fen, Wizzlecrank struggles to control the stolen shredder. He lit the prototype deep inside the Venture Company drill site, but knows little of its levers and switches. The heavy machine lurches across the muddy quarry floor. Its erratic driving and roaring joints alert nearby laborers and armed guards, turning a stealthy escape into a running battle up the excavation pit’s western ramp. Venture Company mercenaries move to stop the stolen prototype. As the machine claws up the slope toward open ground, squads try to intercept and disable it. The shredder lashes out, but cannot withstand their sabotage without your protection. It clears the rim and staggers from the main drilling depression. Soon, the machine suffers a critical failure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_863-23955ceec918ba6a5690/1-0000.mp3", duration = 64.0261224, start = 0},
  },
}
P.transport["quest:8642"] = {
  hash = "9d3057",
  fullHash = "9d3057",
  text = "Silvervein the Elder. During the Lunar Festival, travelers find Silvervein the Elder on the hills above Thelsamar in Loch Modan. They honor him and the ancient ties among Azeroth’s elder peoples, and he grants them an ancestral blessing. Above Thelsamar, Silvervein keeps watch as travelers honor him. He holds memories from ages past. Though trogg invasions and local disputes trouble Loch Modan, the elder spirit remains peaceful on his overlook. Silvervein welcomes travelers who honor Azeroth’s olden races. His greeting carries ancestral appreciation. To those who pay homage, he offers a commemorative token.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8642-79c0a234b042e6998f06/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["quest:8646"] = {
  hash = "138bda",
  fullHash = "138bda",
  text = "Hammershout the Elder. During the Lunar Festival, you meet Hammershout the Elder in Stormwind's Park and honor the old races with a ceremonial token. Ancestor spirits walk Azeroth for the festival, offering wisdom and blessings to travelers who pay their respects. In Stormwind's Park, Hammershout the Elder recalls the ancient races who walked the land before today's kingdoms rose. Hammershout the Elder asks only that you acknowledge the past. He is relieved and grateful when people still honor the old races. In return, he gives you a ceremonial token, binding the living to the spirits who came before.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8646-4c85cf8fc715ad656d14/1-0000.mp3", duration = 38.6873469, start = 0},
  },
}
P.transport["quest:8648"] = {
  hash = "aadaf7",
  fullHash = "aadaf7",
  text = "Darkcore the Elder. During the Lunar Festival, travelers find Darkcore the Elder in the Undercity and honor Azeroth's ancient spirits. In return, they receive a Coin of Ancestry. During the Lunar Festival, spirits of ancient night elven and earthen ancestors appear across the continents. They offer wisdom and blessings to those who seek them. Elder Darkcore dwells in the Undercity's shadowed halls, watching the world as it is now and remembering those who sought its roots. Approaching Elder Darkcore honors an ancient custom. It shows respect for the venerable dead and Azeroth's timeless wardens. In return for the pilgrimage, the spirit gives travelers a Coin of Ancestry, a token of goodwill and enduring memory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8648-38f0e26f8d097117ae82/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:8649"] = {
  hash = "b421f0",
  fullHash = "b421f0",
  text = "Stormbrow the Elder. Near Goldshire, Stormbrow the Elder greets travelers during the Lunar Festival. They honor Azeroth’s ancient traditions and olden races, and receive a commemorative coin in return. Behind Goldshire’s smithy, a quiet pond lies beneath the forest canopy. There Stormbrow the Elder appears as an honored spirit. Guards, tradesfolk, and travelers pass through the town as visitors come to honor the realm’s long history. During the Lunar Festival, the spirits of great ancestors return to walk among the living. Stormbrow commends travelers who remember those who came before. For honoring the elder peoples’ wisdom and legacy, visitors receive a blessing and a commemorative coin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8649-5c996d9df343c61c735b/1-0000.mp3", duration = 42.9453061, start = 0},
  },
}
P.transport["quest:865"] = {
  hash = "b6ac07",
  fullHash = "b6ac07",
  text = "Raptor Horns. In Ratchet, Mebok Mizzyrix seeks intact raptor horns for a scheme of his own. He believes the Barrens raptors owe their cunning to their horns, and pays travelers to hunt Sunscale Scytheclaws. Mebok Mizzyrix chases fortune in Ratchet, where goblins are forever trying one scheme after another. He has watched the Barrens raptors act with more craft and coordination than beasts elsewhere. So Mebok decided their intelligence must lie in their horns. He seeks no formal inquiry. He means to turn the idea to profit. Mebok wants undamaged horns from Sunscale Scytheclaws, among the Barrens' deadliest predators. They prowl the southern stretches of the Barrens and the northern borders near Ashenvale. These raptors hunt in packs and defend their territory fiercely. Bringing one down and taking its horns intact calls for skill in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_865-3f550f219dba00ebf8ba/1-0000.mp3", duration = 52.8718367, start = 0},
  },
}
P.transport["quest:8652"] = {
  hash = "c7e029",
  fullHash = "c7e029",
  text = "Graveborn the Elder. During the Lunar Festival, Graveborn the Elder waits outside Brill in Tirisfal Glades. Travelers find him among its blighted groves to honor Azeroth’s ancient forebears and receive his blessing and a holiday token. In Tirisfal Glades, the Forsaken make their homes among ruined manors and grave sites. During the Lunar Festival, an ancient spirit appears just outside Brill. Elder Graveborn welcomes pilgrims who pause to honor the old ways, even in a land shattered by the Scourge and reclaimed by the undead. During the Lunar Festival, spirits from long ago return with wisdom and gratitude. When you approach Elder Graveborn, he says it heartens him that Tirisfal’s people still honor their ancestors despite the land’s decay. He gives you a Coin of Ancestry when you greet him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8652-65cdb6817ece6a0e6aee/1-0000.mp3", duration = 51.957551, start = 0},
  },
}
P.transport["quest:8653"] = {
  hash = "f5532b",
  fullHash = "f5532b",
  text = "Goldwell the Elder. During the Lunar Festival, Elder Goldwell welcomes travelers in Kharanos and invites them to honor the ancestors. Your visit keeps their memory alive across the snowy dwarven lands. Beside the Thunderbrew Distillery, Elder Goldwell greets those who follow the trade path to Ironforge's gates. Weary travelers, adventurers, and locals all pass before him. He remembers the ancient days when the first mortals walked beneath Azeroth's stars. Goldwell is glad that mortals still remember the ancient races and their deeds. He thanks you for pausing to honor them. Then he gives you a Coin of Ancestry as a sign of his blessing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8653-eb6f6a973bb10d4871cb/1-0000.mp3", duration = 40.202449, start = 0},
  },
}
P.transport["quest:867"] = {
  hash = "9bbe9c",
  fullHash = "9bbe9c",
  text = "Harpy Raiders. Across the northwestern Barrens, Witchwing harpies prey on supply caravans. Darsok Swiftdagger at the Crossroads sends you after their raiders and roguefeathers, whose talons will prove each kill. Witchwing harpies make the northwestern Barrens dangerous for every caravan. From rocky crags, they swoop on merchant trains and supply wagons. They kill pack animals and seize goods bound for orcish outposts. Darsok Swiftdagger, an orc rogue, has watched the flock's habits and ranks for days. He believes an unfocused attack on their mountain roosts would scatter them. So he means to break the Witchwing from the lowest rank upward, beginning with raiders before turning to their commanders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_867-d91467c0445d101f6e55/1-0000.mp3", duration = 41.8742857, start = 0},
  },
}
P.transport["quest:8670"] = {
  hash = "1f2164",
  fullHash = "1f2164",
  text = "Runetotem the Elder. In Razor Hill, travelers can honor Runetotem the Elder during the Lunar Festival. This ancestral spirit waits beneath a beam of heavenly light and offers blessings and festival tokens to those who remember the past. During the Lunar Festival, ancient elders appear across Azeroth to commune with the living. Elder Runetotem waits just inside Razor Hill's southern entrance. Starlight falls on her as she watches over the orcish settlement. Travelers may pause to honor the wisdom of those who came before. Pay Elder Runetotem homage and she gives you a festival token of fortune. She also tells you where other spirits can be found. Her directions lead to Elder Darkhorn and Elder High Mountain elsewhere across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8670-fa38a6b544fd51e3b459/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["quest:8673"] = {
  hash = "63e2b2",
  fullHash = "63e2b2",
  text = "Bloodhoof the Elder. During the Lunar Festival, travelers honor Bloodhoof the Elder near the bridge north of Bloodhoof Village. The ancestral spirit offers them a Coin of Ancestry. During the Lunar Festival, spirits of heroes and elders from ages past return to Azeroth. Elder Bloodhoof appears near the bridge north of Bloodhoof Village. Travelers honor the sacrifices of the past by approaching him. He offers words of encouragement and a Coin of Ancestry. On Mulgore’s ancestral lands, Elder Bloodhoof joins the living tauren tribes to the memory of their forebears. Honoring the dead is central to tauren spiritual life. It keeps the Earth Mother, the ancestors, and those walking the plains in harmony.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8673-aa2d5327aa30c2532bec/1-0000.mp3", duration = 44.1208163, start = 0},
  },
}
P.transport["quest:8675"] = {
  hash = "a2c4c2",
  fullHash = "a2c4c2",
  text = "Skychaser the Elder. During the Lunar Festival, Skychaser the Elder watches over Westfall from Sentinel Tower. Travelers climb to honor her as an ancestral spirit, and she recognizes the living with a blessing. Sentinel Hill is Westfall's lone fortified redoubt. Below, weary soldiers and settlers face threats from Defias raiders and roving scavengers across the scrublands. During the Lunar Festival, Elder Skychaser appears on the open platform atop Sentinel Tower, watching from above the dust and wind. Anyone may climb and pay her respect. Across Azeroth, the Lunar Festival honors wisdom, heritage, and the deeds of ancient spirits. When you approach, Elder Skychaser recognizes the living spark within you and accepts your homage. She gives you a token of her favor, binding the living to the honored dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8675-4030725b3344bf657906/1-0000.mp3", duration = 52.3493878, start = 0},
  },
}
P.transport["quest:8677"] = {
  hash = "26bac4",
  fullHash = "26bac4",
  text = "Darkhorn the Elder. At the Lunar Festival, Darkhorn the Elder welcomes travelers within Orgrimmar. Honored among the ancestors, she carries age, survival, and ancestral pride. During the Lunar Festival, revered ancestors appear across Azeroth to share wisdom with the living. Elder Darkhorn rests within Orgrimmar’s fortified ramparts and watches the young warrior city. Approach her to honor those who walked the earth generations ago, whether you fight for the Horde or enter as an Alliance traveler. Travelers greet Elder Darkhorn and pay her reverence, and she recognizes the spark of life in them. For honoring the old ways, you receive a Coin of Ancestry and her blessing. The tokens celebrate victory over ancient perils and remind the living to cherish the strength passed down through unbroken bloodlines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8677-c6f9f73e30e970292b88/1-0000.mp3", duration = 52.2710204, start = 0},
  },
}
P.transport["quest:8678"] = {
  hash = "e85fbf",
  fullHash = "e85fbf",
  text = "Proudhorn the Elder. During the Lunar Festival, Proudhorn the Elder welcomes visitors on Thunder Bluff's high mesas. Tauren honor him as an ancestral spirit and seek the wisdom of those who watch over Mulgore and the Horde. During the Lunar Festival, Proudhorn the Elder appears on Thunder Bluff's windblown mesas. Tauren hold their ancestors' voices in the highest regard. They believe ancient leaders and sages remain as spirits, offering guidance and strength to the living. Travelers who climb Thunder Bluff's heights to honor Elder Proudhorn are welcomed as vital flames of life. In return, he gives them a Coin of Ancestry. The coin marks a bond between the enduring past and the living champions who fight for the world's future.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8678-f06720c13497e1b6ec28/1-0000.mp3", duration = 45.557551, start = 0},
  },
}
P.transport["quest:86784"] = {
  hash = "ed3ea4",
  fullHash = "ed3ea4",
  text = "Sticks and Bones. Deathguard Bartholomew asks travelers to bring dry branches to Eleanor Shackleton in the western hills of Tirisfal Glades. She camps far from the settlements and knows how to live in the wilds. Between patrols in Tirisfal Glades, Deathguard Bartholomew looks out for Eleanor Shackleton. Deathguards guard against the Scourge and Scarlet crusaders, yet Bartholomew also cares for his acquaintance. Eleanor spends her unlife in the harsh elements, so he asks you to bring dry branches for her campfire. Eleanor Shackleton survives alone in Tirisfal's blighted wilderness. The Forsaken are undead, yet they still feel the damp, bitter chill rolling off the northern moors. Eleanor's rule is simple: when you think you have enough firewood, gather five times more. Grateful for the extra timber, she lets you keep Bartholomew's basket and shares the warmth of her fire.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86784-216e014355d497229b82/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["quest:8680"] = {
  hash = "4a9afb",
  fullHash = "4a9afb",
  text = "Windtotem the Elder. During the Lunar Festival, travelers find Windtotem the Elder on a bluff above Ratchet. She welcomes those who honor the wisdom of ages past and offers an ancestral blessing and guidance to elders across Kalimdor. From a grassy hill northwest of Ratchet’s flight master, Windtotem the Elder watches the goblin docks and the open sea. Iron, gunpowder, and coin pass through the harbor below. Above it all, the Barrens winds blow quietly beneath a shaft of celestial light. During the Lunar Festival, Windtotem the Elder guides wandering mortals, as do the other ancestral spirits. Those who seek her receive her blessing and a token of her favor. She also whispers the way to nearby elders across the continent, including Elder Runetotem and Elder Bloodhoof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8680-0030e1123e3be62bad17/1-0000.mp3", duration = 49.162449, start = 0},
  },
}
P.transport["quest:869"] = {
  hash = "9f584a",
  fullHash = "9f584a",
  text = "Raptor Thieves. At the Crossroads, a raptor has stolen the guards' pay, and Gazrog fears another strike. The defenders are left without coin and with no clear answer. The Crossroads relies on mercenary and grunt guards to keep trade routes open across the Barrens. Their pay keeps morale and discipline firm. When silver vanished from the guard tower, the leaders suspected Centaur raiders or Quilboar scavengers. Instead, a raptor was caught stealing in the dead of night. The settlement was stunned, and short of coin. Gazrog cannot fathom why wild beasts would hoard shiny coins, and has no wish to study their ways. The guards are restless without their pay, so he calls for blood to deter another attack. He sends hunters after a dozen raptors across the savannah. He hopes to curb their boldness before the search for the silver begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_869-54eba251d730207b4ef7/1-0000.mp3", duration = 52.8457143, start = 0},
  },
}
P.transport["quest:87"] = {
  hash = "fe592e",
  fullHash = "fe592e",
  text = "Goldtooth. Near Fargodeep Mine, Billy Maclure's careless play has set the Stonefield and Maclure families against each other. His trail leads you to the kobold Goldtooth. Auntie Bernice Stonefield's missing necklace has stirred trouble between the Stonefield and Maclure families. Bernice suspects her rivals, but Billy Maclure lost the trinket while playing near Fargodeep Mine. He tries to hide his guilt. He says he found the necklace before a creature snatched it away. Billy says a large kobold with gleaming fangs took the shiny necklace and fled to a den above Fargodeep Mine. Yet Goldtooth lurks on the mine's lower level. Slaying the kobold returns Bernice's necklace and settles the families' dispute. Bernice also gives you an old campaign keepsake left by her late husband.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_87-f3503da075b6c57d47e7/1-0000.mp3", duration = 48.5616327, start = 0},
  },
}
P.transport["quest:870"] = {
  hash = "6b460c",
  fullHash = "6b460c",
  text = "The Forgotten Pools. At the Forgotten Pools, life rises in the Barrens for reasons the Cenarion Circle cannot explain. Tonga Runetotem at the Crossroads asks Horde adventurers to inspect the oasis northwest of the settlement, where druids feel unseen forces stirring below the earth. Long ago, the Barrens flourished as fertile land. Ages of war and the Sundering shattered the continent and left this region a sun-baked scrubland. Now lush oases are taking root in its dry basin. The Cenarion Circle’s druids find this sudden growth unnatural. They feel powers below the earth pressing upward and stirring plants and wildlife to life in scattered pockets across the wastes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_870-7cb13846b4125e8fad21/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["quest:871"] = {
  hash = "880beb",
  fullHash = "880beb",
  text = "Disrupt the Attacks. Thork needs the Crossroads defended as Razormane quilboar cut its supply roads. Their ambushes have stopped caravans from Durotar, leaving the outpost short on food and gear. You strike at the quilboar while scouts search for the one directing their warband. The Crossroads guards a key junction for Horde traffic through central Kalimdor. Freight wagons and caravans carry food, iron, and equipment west from Durotar, and the outpost depends on those supplies. Razormane ambushes along the northeast trails have stopped the deliveries. Stores are running low, and Thork cannot wait for peaceful talks. Thork sends you to the quilboar bramble dens northeast of the settlement, before they can assault the town walls. Striking their Water Seekers, Thornweavers, and Hunters weakens the Razormane scouting perimeter and deprives raiding parties of magical and logistical support. These skirmishes buy time while Horde trackers search the brush for the one organizing the raids.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_871-9c2fca32b9da3251624c/1-0000.mp3", duration = 59.1412245, start = 0},
  },
}
P.transport["quest:8717"] = {
  hash = "e12033",
  fullHash = "e12033",
  text = "Moonwarden the Elder. At the Crossroads, Moonwarden the Elder receives travelers beneath a beam of light. During the Lunar Festival, people honor ancestral spirits and seek his wisdom and directions to elders across Kalimdor. At the Crossroads, a column of light falls around Elder Moonwarden. He is among the ancient spirits honored during the Lunar Festival. Mortals set aside their conflicts then and seek the wisdom of generations past. Elder Moonwarden looks to the stars for answers to earthly mysteries. He offers ancestral blessings and directs seekers to other elders across Kalimdor, including Elder Bloodhoof, Elder High Mountain, Elder Morningdew, and Elder Runetotem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8717-a23ce627cc30429938df/1-0000.mp3", duration = 42.4489796, start = 0},
  },
}
P.transport["quest:8718"] = {
  hash = "5f2925",
  fullHash = "5f2925",
  text = "Bladeswift the Elder. During the Lunar Festival, Bladeswift the Elder is honored beneath the boughs of Darnassus. Travelers seek his wisdom in the Cenarion Enclave and receive a blessing rooted in night elf tradition. During the Lunar Festival, ancestral spirits appear across Azeroth to share wisdom and bless travelers. In Darnassus, Bladeswift the Elder appears among the boughs of the Cenarion Enclave. He looks to the night sky and its mysteries while the living face the trials of the present. Night elves have long read the heavens as reflections of Elune and signs of deeper truths. Bladeswift urges the wise and fortunate to seek answers among the stars. Those who honor him receive a Coin of Ancestry and join a ceremony linking the living with spirits of the past.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8718-9dbdb383a42caacf7b49/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:872"] = {
  hash = "0c7210",
  fullHash = "0c7210",
  text = "The Disruption Ends. Along the Horde road, Thork orders a strike to end the Razormane raids. Kreenig Snarlsnout leads the attacks from the northern Barrens, and his death is meant to break the warband's hold on the route between Durotar and the Crossroads. The road between Durotar and the Crossroads carries provisions and reinforcements through the northern Barrens. Razormane quilboar ambushes threaten that passage. Scout reports name Kreenig Snarlsnout as their leader. His raiding party organizes the attacks, so Thork orders a strike against him to break the warband's unity and secure the road. Kreenig's war party holds craggy hills northeast of the Crossroads. Hardy Razormane Defenders and geomancers who manipulate the arid earth shield his position. Thork orders a breach through their guard and a strike against Kreenig in his redoubt. His tusk will prove the leader's death and warn the plains that the Horde will not accept attacks on its lifelines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_872-6a07c611329e0180db8c/1-0000.mp3", duration = 55.0138776, start = 0},
  },
}
P.transport["quest:8721"] = {
  hash = "28d3e4",
  fullHash = "28d3e4",
  text = "Starweave the Elder. In Auberdine, Elder Starweave welcomes visitors during the Lunar Festival. Travelers honor Kalimdor's ancestral spirits and seek her wisdom and blessing. During the Lunar Festival, ancestral spirits appear across Azeroth beneath pillars of celestial light. Elder Starweave joins the night elves in Auberdine, a harbor on Darkshore's coast. Travelers come to honor her and seek guidance from ages past. Elder Starweave looks to the heavens above Kalimdor. She tells visitors that the stars hold answers to mortal doubts and worldly riddles. Those who seek her counsel are urged to look skyward for truth and receive ancestral favor, along with tidings of other wandering spirits across the wild frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8721-06a25de4b31109b15d57/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["quest:8725"] = {
  hash = "1082f3",
  fullHash = "1082f3",
  text = "Riversong the Elder. Beneath a shrine in Astranaar, Riversong the Elder receives pilgrims during the Lunar Festival. The night elf spirit offers wisdom and points them toward honored ancestors across Kalimdor. In Astranaar, an open night elf shrine shelters Riversong the Elder. Light falls through the Ashenvale canopy onto her spirit. During the Lunar Festival, pilgrims gather there to honor those who came before. Riversong the Elder recalls how night elves seek truth and mystery among the stars. She urges patience and contemplation, then guides pilgrims toward other spirits, including Elder Starweave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8725-da092efa03c5b0bafc9a/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["quest:875"] = {
  hash = "a6440e",
  fullHash = "a6440e",
  text = "Harpy Lieutenants. In the northern Barrens, Darsok Swiftdagger sends Horde champions against the Witchwing coven. In the Dry Hills, they target the flock’s officers to break its command. After the first clashes with Witchwing raiders, Darsok Swiftdagger turns the Horde’s attack toward the harpies in the Dry Hills. Scouts seek out the Witchwing Slayers who lead the flock. These officers keep lesser harpies in line and direct raids on Horde supply paths. Their deaths are vital to securing the Barrens’ northern approaches. Witchwing Slayers rule through strength, and the most vicious among them wear ornate rings to mark their authority in the matriarchy. Taking the rings proves the lieutenants are dead and disrupts the roost’s coordination. It also warns the coven that attacks on Horde territory will meet decisive retribution.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_875-b7902a155eb4f4abad43/1-0000.mp3", duration = 49.7110204, start = 0},
  },
}
P.transport["quest:877"] = {
  hash = "9ad7e7",
  fullHash = "9ad7e7",
  text = "The Stagnant Oasis. From the Crossroads, Tonga Runetotem sends you southeast to search the Stagnant Oasis. He wants to know whether its murky waters hide a fissure like the one beneath the Forgotten Pools. Tonga Runetotem sends you to search the Stagnant Oasis after a strange fissure is found beneath the Forgotten Pools. He suspects the sudden patches of lush growth across the Barrens have a cause beneath the earth. You search the murky shallows for another opening while predators haunt the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_877-be4ba28f3cc44b4ebdce/1-0000.mp3", duration = 29.3093878, start = 0},
  },
}
P.transport["quest:88"] = {
  hash = "399d8a",
  fullHash = "399d8a",
  text = "Princess Must Die!. At Stonefield Farm, Ma Stonefield asks you to kill Princess before the sow ruins the harvest. The enormous prize-winning pig from Brackwell Pumpkin Patch keeps raiding the Stonefields’ vegetables, putting the family’s crops at risk. The sow belongs to the Brackwells. She grew enormous by crossing onto the Stonefield plots. Ma has had enough of Princess eating the crops she worked to grow. She wants the pig put down before the season’s yield is lost. Princess stays at Brackwell Pumpkin Patch, east beyond the Maclure homestead. Protective boars surround her. Get past her guards and bring Ma the distinctive brass collar from Princess’s neck. It will prove the sow can trouble the Stonefield fields no more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_88-ebe171fd6d887ce79052/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["quest:880"] = {
  hash = "6c748b",
  fullHash = "6c748b",
  text = "Altered Beings. At the Crossroads, Tonga Runetotem investigates strange changes in the Barrens' oasis waters. Fissures beneath the pools may be changing the creatures there, so he asks you to bring him shells from altered snapjaws. Tonga Runetotem seeks the cause of strange changes in the Barrens' oases. Though the savanna is dry, a handful of pools keep fertile ground alive. Beneath the waters, Tonga found peculiar fissures that send out potent energies. He cannot tell whether that force came from outside or rose from deep within the earth.\n\nNow Tonga studies the creatures that drink from and live in the pools. He hopes they will show what the fissures are doing to them. You are sent to the Lushwater Oasis and the Stagnant Oasis to gather altered snapjaw shells. Snapjaws live in the shallows, taking in the strange essence through food and exposure. Their changed carapaces may show Tonga how the fissures affect local wildlife. He hopes the shells will help him understand the disturbance before it spreads farther across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_880-007465f9e8ce8a4227df/1-0000.mp3", duration = 62.6938776, start = 0},
  },
}
P.transport["quest:881"] = {
  hash = "83d776",
  fullHash = "83d776",
  text = "Echeyakee. At the Crossroads, hunters prepare to summon Echeyakee, the white lion of the northern Barrens. Sergra Darkthorn sends young Horde hunters to test their strength against him. Across the central plains, a white-maned lion rules the savannah cats. Taur-ahe speakers call him Whitemist, or Echeyakee. Legend says he moves without a sound, like morning mist over red earth. His strikes are swift, and prey knows neither fear nor suffering. Local hunters honor him as a sign of mercy and swift death. At the Crossroads, Sergra Darkthorn trains fledgling warriors. The experienced orc shaman sends them against the king of beasts once they have proven themselves against lesser savannah prowlers.\n\nWith a special horn, you travel northeast past the mountain ridges to a graveyard of massive kodo bones. Sound it to challenge Echeyakee and draw the elusive predator from hiding. There, your strength and cunning face their trial.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_881-c6c41726983d45c0665b/1-0000.mp3", duration = 60.395102, start = 0},
  },
}
P.transport["quest:882"] = {
  hash = "f836b5",
  fullHash = "f836b5",
  text = "Ishamuhale. At Camp Taurajo, Jorn Skyseer sends you after Ishamuhale, the fiercest sunscale raptor in the Barrens. The hunt tests your skill and respect for nature's deadliest predators. Sunscale raptors hunt the Barrens in cunning, vicious packs. Yet none inspires more dread than Speartooth. Jorn Skyseer says Ishamuhale kills by instinct and passion, not for food or territory. He hunts because killing is his nature. Facing him tests whether you can withstand a predator's unbridled ferocity. Ishamuhale will not be found resting in a nest. To draw him out, follow the plains' natural rhythm. Jorn tells you to kill a fresh zhevra and carry its carcass to a lone, withered dead tree on the plains northwest of Ratchet. The scent of blood on the arid wind brings Ishamuhale swiftly to claim his prey. When you bring Ishamuhale's fang back to Camp Taurajo, Jorn Skyseer sees a profound spiritual milestone, not merely a victory. Tauren belief holds that overcoming such a fierce predator lets you absorb some of its raw strength. Then the test turns inward. You must bear that might with temperance, honor, and restraint, rather than surrender to blind bloodlust.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_882-cc728135a7ff3a4a4760/1-0000.mp3", duration = 72.724898, start = 0},
  },
}
P.transport["quest:8827"] = {
  hash = "cc244f",
  fullHash = "cc244f",
  text = "Winter's Presents. In Ironforge, revelers gather for the Feast of Winter Veil. They direct travelers to Greatfather Winter beside the Smokywood Pastures stalls, where gifts wait beneath the holiday tree. Winter settles over Khaz Modan, and Ironforge fills with cheer for the Feast of Winter Veil. Revelers and holiday enthusiasts point passersby toward the decorated tree near the Smokywood Pastures vendors. Smokywood Pastures, a goblin enterprise, shares the season with Greatfather Winter. He greets visitors as goblin merchants remind gift recipients that festive treats and seasonal wares make gifts for friends and family.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8827-156c5f01e7b44cf2e73f/1-0000.mp3", duration = 40.5159184, start = 0},
  },
}
P.transport["quest:8828"] = {
  hash = "c2d758",
  fullHash = "c2d758",
  text = "Winter's Presents. The Feast of Winter Veil brings gifts beneath Orgrimmar’s festive tree. Holiday organizers and goblin apparatus tenders send Horde heroes to Great-father Winter to receive them. Late-year winds sweep across Durotar as Orgrimmar pauses for the Feast of Winter Veil. Promoters from Smokywood Pastures and holiday enthusiasts spread word through the capital that gifts wait beneath the decorated tree. Warriors, hunters, and wanderers resting in the city are invited to share in the season’s generosity. Great-father Winter sits near the Smokywood Pastures market among holiday ribbons and packaged cartons. The ancient figure marks the season’s renewal. Nearby, goblin merchants offer seasonal wares and festive treats to visitors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8828-d2f74e38a0326110cdb2/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["quest:8846"] = {
  hash = "5d8a60",
  fullHash = "5d8a60",
  text = "Five Signets for War Supplies. In Ironforge, Field Marshal Snowfall trades commendation signets for supplies bound for the Grand Alliance’s war effort. You can exchange them for field rations, bandages, and combat gear to keep those serving on the home front equipped for the conflicts ahead. Couriers and heroes bring Snowfall commendation signets earned through civic service. He trades them for survival rations and tactical gear bound for the fronts. Armies there need steady supplies as much as courage. Royal heralds offer public honor and civic standing for commendation signets. Snowfall offers another choice: five signets buy field gear, without pomp, glory, or official recognition. These goods help soldiers and volunteers stay alive as they march into hostile lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8846-7ebcf4cfdc58d357382e/1-0000.mp3", duration = 47.7518367, start = 0},
  },
}
P.transport["quest:8851"] = {
  hash = "481151",
  fullHash = "481151",
  text = "Five Signets for War Supplies. Across Kalimdor, the Horde gathers what its campaign needs. Workers earn commendation signets for their contributions, and Warlord Gorchuk trades them for supplies to equip the fighters. Across Kalimdor, the Horde gathers raw goods, weapons, and provisions for a vast campaign. Gatherers and tradesfolk bring bandages, metals, and herbs into the cities. There, military overseers award commendation signets for their work. Each token marks a contribution to the stockpile growing along Orgrimmar's central avenues. Warlord Gorchuk knows the wider war effort needs supplies. Each warrior also needs gear and provisions to survive the march into battle. Fighters can trade their commendation signets back to the Horde's stores for field supplies and surplus materiel. They give up personal recognition for what they need on the front.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8851-38c570fab0f21c9adc33/1-0000.mp3", duration = 51.4873469, start = 0},
  },
}
P.transport["quest:886"] = {
  hash = "6ce533",
  fullHash = "6ce533",
  text = "The Barrens Oases. Beneath the Barrens, strange power stirs, and Arch Druid Hamuul Runetotem takes heed from Thunder Bluff's Elder Rise. He sends travelers east through Mulgore to meet Tonga Runetotem at the Crossroads and investigate the new waters. For generations, the Barrens have known drought while Mulgore flourishes under the Earth Mother's care. Now tauren druids on Thunder Bluff's Elder Rise feel strange currents waking beneath the plains. Life stirs where it should not, and the Cenarion Circle fears the power behind it may endanger the land and its creatures. Arch Druid Hamuul Runetotem sends Tonga Runetotem to investigate the strange stirrings. The wilderness is too dangerous for one investigator, so Hamuul asks travelers leaving Mulgore to follow. Go east past Bloodhoof Village and through the mountain passes to the Crossroads, where Tonga waits for news. There, in the Barrens, stands the Horde's busy heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_886-b4b7de64a5011afc85a7/1-0000.mp3", duration = 58.7493878, start = 0},
  },
}
P.transport["quest:8866"] = {
  hash = "44433b",
  fullHash = "44433b",
  text = "Bronzebeard the Elder. During the Lunar Festival, travelers honor Bronzebeard the Elder beneath Ironforge. His greeting offers wisdom and a token of esteem. Across Khaz Modan, people revere their forebears and their long-lived heritage. During the Lunar Festival, spirits and venerable elders appear across Azeroth to share wisdom with travelers who honor the past. In Ironforge, Elder Bronzebeard carries the Bronzebeard clan’s stalwart resilience. He is quietly pleased when travelers come to pay their respects and the people honor the lineage of the old races. No great trial or perilous journey is needed. Travelers pause to greet Elder Bronzebeard and offer their good wishes. He returns the greeting with a Coin of Ancestry, a festival token recalling the living bond between the present and the generations who forged Khaz Modan from stone and fire.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8866-2b76a61b38782576751e/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["quest:887"] = {
  hash = "794764",
  fullHash = "794764",
  text = "Southsea Freebooters. Along the Merchant Coast south of Ratchet, pirates strike goblin trading vessels. Gazlowe hires adventurers to attack the Southsea Freebooters' camp and curb the raids. Pirates on the Merchant Coast are hurting Ratchet's trade. The port lies in central Kalimdor, along the route merchant vessels take between Kalimdor and the eastern continents. South of town, the Southsea Freebooters hold a fortified beach camp. From there, they attack goblin cargo ships coming and going, cutting profits and disrupting local shipping lanes. Gazlowe blames the pirates and the Steamwheedle Cartel's naval leaders. The Trade Princes have spent immense sums on defensive fleets, yet Vice Admiral Grezzlik has failed to patrol the waters effectively. Frustrated by Undermine's slow response, Gazlowe hires independent mercenaries to thin the pirate brigands and cannoneers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_887-a9007476f941c3bfb32f/1-0000.mp3", duration = 54.5697959, start = 0},
  },
}
P.transport["quest:888"] = {
  hash = "4dc210",
  fullHash = "4dc210",
  text = "Stolen Booty. Along Ratchet’s coast, Gazlowe weighs two stolen goods against the rest of the cargo. Boots for local laborers and a delicate lens are needed to finish his observatory. For years, Southsea Freebooters have troubled merchant lanes across the Great Sea. Their fortified camp just south of Ratchet brought them into direct conflict with Gazlowe. Pirates intercepted merchant vessels bound for the port and seized valuable supplies from the Steamwheedle Cartel. Some cargo could be counted as a shipping loss. Other goods mattered enough for Gazlowe to hire mercenaries to break into the pirate stronghold. Gazlowe has two practical priorities. Drizzlik sent a needed shipment of boots from Booty Bay for local laborers. The other item is a ground telescopic lens made for the observatory tower overlooking Ratchet. Its twin came safely by caravan through Durotar, but pirates seized this lens at sea. Until it is recovered, the observatory remains an empty frame.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_888-8d328fef1d97664fef95/1-0000.mp3", duration = 59.6636735, start = 0},
  },
}
P.transport["quest:890"] = {
  hash = "97d339",
  fullHash = "97d339",
  text = "The Missing Shipment. In Ratchet, Gazlowe waits for goods sent from Booty Bay across the Great Sea. He sends couriers to Wharfmaster Dizzywig to check the dock records, while the Southsea Freebooters remain a possible cause of the delay. Ratchet is the Steamwheedle Cartel's trading port on Kalimdor. Ships cross the Great Sea from Booty Bay, bringing manufactured goods, exotic supplies, and heavy freight for building and trade. When cargo goes missing, business suffers. Chief Engineer Gazlowe tracks every crate brought into port. The Southsea Freebooters haunt the coast south of Ratchet and often intercept merchant ships. Gazlowe checks his records before accusing the pirates or sending anyone into a fight. He sends his inventory ledger to Wharfmaster Dizzywig at the docks.\n\nDizzywig oversees the unloading and storage of ship cargo. He can check whether goods were lost at sea or misplaced in a warehouse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_890-d73cd41f1309c9439fbf/1-0000.mp3", duration = 56.6595918, start = 0},
  },
}
P.transport["quest:892"] = {
  hash = "72853f",
  fullHash = "72853f",
  text = "The Missing Shipment. At Ratchet’s docks, Gazlowe is searching for a shipment that never arrived. Dizzywig’s ledger points away from the harbor and toward the Southsea Freebooters, while Gazlowe prepares to reclaim his cargo. Ratchet’s trade keeps its docks busy and its accounts difficult to manage. When a shipment goes missing, Gazlowe suspects bad harbor accounts or foul play on the piers. Wharfmaster Dizzywig checks the manifest and says his books are clean. The intake records account for everything. The missing goods never reached the dock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_892-f4ceb659916abe377d78/1-0000.mp3", duration = 34.1420408, start = 0},
  },
}
P.transport["quest:894"] = {
  hash = "ef29a7",
  fullHash = "ef29a7",
  text = "Samophlange. At a Venture Company outpost in the northern Barrens, Sputtervalve seeks a device called a samophlange. He sends you southwest of the Sludge Fen to find it. In the northern Barrens, Sputtervalve cannot say what the Venture Company is building. The goblin engineer and tinker works in Ratchet, while the rival company experiments southwest of the Sludge Fen. Its workers call one device a samophlange. Sputtervalve knows neither its purpose nor its value, but wants to study its design before his competitors profit from it. Armed overseers, deforesters, and machinery guard the Venture Company research site. Sputtervalve gives you an intercepted operating manual to help shut down the rig safely. At the central control station, you find a locked console fitted with levers, lights, and gauges. Three control valves keep the rig's pressure in order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_894-2babdfc010bf691e06b9/1-0000.mp3", duration = 51.1477551, start = 0},
  },
}
P.transport["quest:895"] = {
  hash = "68e0df",
  fullHash = "68e0df",
  text = "WANTED: Baron Longshore. On Ratchet's docks, Chief Engineer Gazlowe posts a bounty for the pirate Baron Longshore. From Gilneas, Longshore commands vessels of the Southsea Freebooters. His raids along the Merchant Coast threaten goblin shipping across the region. South of Ratchet, the Southsea Freebooters keep fortified camps along the Merchant Coast. Their pirates harass merchant vessels and disrupt the sea lanes the Steamwheedle Cartel relies on between Ratchet, Booty Bay, and points beyond. Under captains such as Baron Longshore, the raids drain the local goblin administration and threaten trade along the coast. Baron Longshore comes from Gilneas, the isolated human kingdom across the sea. On Kalimdor, he commands the pirate vessel Heedless and leads crews ashore just north of Northwatch Hold. Chief Engineer Gazlowe answers with a bounty and calls for Longshore's identifiable head.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_895-455d70ba7687c0c64c45/1-0000.mp3", duration = 57.0514286, start = 0},
  },
}
P.transport["quest:896"] = {
  hash = "c83266",
  fullHash = "c83266",
  text = "Miner's Fortune. Wharfmaster Dizzywig has word of a great emerald at Boulder Lode Mine. He wants you to take it from the Venture Company's overseers and share the proceeds. Merchants sailing between Ratchet and Booty Bay bring news to Wharfmaster Dizzywig. Now word has reached him of a huge gem found deep in Boulder Lode Mine. The Venture Company strips the northern Barrens for its own gain, so few are likely to ask questions if its finest recent find vanishes. Northeast of the Sludge Fen, laborers work the rocky shaft of Boulder Lode Mine. The Venture Co. Overseers and Enforcers hold the Cats Eye Emerald, and an ordinary digger cannot claim so rare a prize. Face the armed managers, take the stone, and bring it to Dizzywig. He can weigh its worth against the market in Undermine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_896-02494d49027c6b018644/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["quest:9"] = {
  hash = "32d675",
  fullHash = "32d675",
  text = "The Killing Fields. In Westfall, The Killing Fields begins with Farmer Saldean's crops under threat. Rogue Harvest Watchers overrun his fields and neighboring farms, while the Defias Brotherhood's disruption has left local agriculture in ruin. Many Westfall farmers abandoned their land when bandits and outlaws swept through. Farmer Saldean and his family chose to stay. Thieves are not the only danger on their farm. Harvest Watchers built to tend and guard the grain have run wild, pacing the furrows and attacking anyone who comes near. Farmer Saldean asks passing travelers to dismantle twenty hostile Harvest Watchers across his fields and the adjoining plots. Clearing them gives his harvest a little relief. For now, his farm remains one stubborn hope that Westfall's breadbasket can be reclaimed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9-84d20c3967670102cdf2/1-0000.mp3", duration = 49.7893878, start = 0},
  },
}
P.transport["quest:900"] = {
  hash = "e2bc33",
  fullHash = "e2bc33",
  text = "Samophlange. At the Sludge Fen, Samophlange machinery keeps the Venture Company's digging rig running. Seal its three valves before the central apparatus can be shut down safely. At the Sludge Fen, the Venture Company's machinery is complex and dangerous. The central console shows that one switch cannot stop its core. First, the feed lines must be handled by hand. Otherwise, the apparatus could fail or explode. Three valves feed the rig: the Main Control Valve, the Fuel Control Valve, and the Regulator Valve. Each must be sealed by hand against high pressure. As they close, the console's green indicators fade to yellow. Then the central shutoff is safe to engage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_900-430ff2bcc24a343ee7fd/1-0000.mp3", duration = 43.4155102, start = 0},
  },
}
P.transport["quest:901"] = {
  hash = "577a53",
  fullHash = "577a53",
  text = "Samophlange. At the Sludge Fen, Samophlange machinery sits idle, its pressure relieved and valves shut. Tinkerer Sniggles holds the key to open the control unit and free the samophlange within. You have turned the auxiliary valves and relieved the pressure. The dials and gauges have settled, but the housing remains locked against tampering. The goblin engineer overseeing the drilling site holds its key. Tinkerer Sniggles oversees the Venture Company’s equipment at the Sludge Fen. His hut lies just northeast of the main rig, and he keeps the console key there. You need it to open the housing and reach the samophlange.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_901-36b5ee3853a800d7b93d/1-0000.mp3", duration = 37.7469388, start = 0},
  },
}
P.transport["quest:902"] = {
  hash = "317851",
  fullHash = "317851",
  text = "Samophlange. At the Venture Company console, you uncover the samophlange and bring it to Ratchet. Its controls and defenses are shut down, and Sputtervalve is ready to examine the delicate device. You find strange engineering behind the Venture Company console's faceplate. Wiring and purposeless tubing crowd the space. Deep inside lies the samophlange, a core component that has baffled engineers across the region. With a firm tug, you free it from its housing and carry it back to the goblin who began the recovery effort.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_902-04babefbe08c178e1dc6/1-0000.mp3", duration = 31.9738776, start = 0},
  },
}
P.transport["quest:903"] = {
  hash = "5d80c0",
  fullHash = "5d80c0",
  text = "Prowlers of the Barrens. At the Crossroads, Sergra Darkthorn sends you to hunt prowlers of the Barrens. Their claws will show whether you can face the land’s greatest beasts. Hunters who have faced plainstriders and zhevras now face Sergra Darkthorn’s test. Southwest of the Crossroads, savannah prowlers vanish into the scrub of the central Barrens. Unlike the herds, these great cats hunt. They wait in tall grass and ambush their prey, so unwary travelers can fall to them. Sergra warns you that prowlers know how to hunt. Read the grasses and strike before a cat leaps. Bring Sergra seven prowler claws to prove you have the cunning and quick reflexes to survive Kalimdor’s deadliest wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_903-3c8fd96e1c96b013e321/1-0000.mp3", duration = 43.1020408, start = 0},
  },
}
P.transport["quest:905"] = {
  hash = "38dfa4",
  fullHash = "38dfa4",
  text = "The Angry Scytheclaws. South of the Crossroads, Sergra Darkthorn sends hunters against the scytheclaws stalking the Barrens. Carry sunscale raptor feathers to their nests, and show you can face these beasts without fear. Sergra Darkthorn tests hunters against the Barrens' beasts. After lesser trials, she sends you south of the Crossroads to hunt vicious sunscale raptors and gather their feathers. Then you carry them southwest of the Stagnant Oasis, deep into raptor territory. Place the feathers in the nests, and prove you can face the scytheclaws without fear. Southwest of the Stagnant Oasis, three raptor nests lie near the Gold Road. Red, blue, and yellow eggs mark the separate clutches. Scytheclaws fiercely defend their nests from anything that draws near. Place feathers from fallen raptors among the eggs, and the challenge is plain to the beasts. After entering the nests, return to the Crossroads. Sergra can see you faced the danger and lived. Walking out of a raptor den takes raw courage. The Barrens test every hunter; each fight may harden you or leave your bones among the kodo ribs scattered across the dirt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_905-55fd5d39d339b98a2285/1-0000.mp3", duration = 70.7657143, start = 0},
  },
}
P.transport["quest:907"] = {
  hash = "7f235e",
  fullHash = "7f235e",
  text = "Enraged Thunder Lizards. In the southern Barrens, thunder lizards roam the plains around Camp Taurajo. Jorn Skyseer calls hunters to face the great beasts and bring back their blood for a wider rite of passage. After defeating the raptor Ishamuhale, you return to Camp Taurajo. Jorn Skyseer, the tauren elder, now tests your strength against the land's largest grazers. Stormsnouts and Thunderheads roam the southern Barrens. Their heavy strides can crush an unwary hunter beneath them. Tauren and orc hunters prize poise, position, and strength against a thunder lizard. Jorn asks you to bring back samples of their potent blood. They prove you stood before the rumbling beasts and survived with your bones unbroken. That trophy opens the way to Jorn's final quarry in the skies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_907-2d56c6c08da869c65c4b/1-0000.mp3", duration = 47.882449, start = 0},
  },
}
P.transport["quest:90902"] = {
  hash = "2d5e3d",
  fullHash = "2d5e3d",
  text = "Rediscovering the Light. In Deathknell, newly risen Forsaken paladins learn that the Light still answers them, though it burns. The Holy Light still answers newly risen Forsaken paladins, but it burns their withered bodies. Many once served as champions of the Silver Hand or knights of Lordaeron. Aramis Hammerhand teaches them that powers they once used without thought now bring fierce pain. The Light clashes with the foul magic that sustains undeath, so calling on it takes resolve and endurance. Deathguards in Deathknell suffer grievous wounds fighting mindless zombies, and Forsaken paladins are called to heal them. Aramis teaches that enduring the burning pain is like exercising an atrophied muscle. The paladins bear that agony as a badge of honor and proof that the Light has not forsaken them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_90902-ae94bcdda4055178bdb9/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["quest:91208"] = {
  hash = "946d64",
  fullHash = "946d64",
  text = "Coming to Terms. A frightened former paladin has fled into the hills west of the chapel. Aramis Hammerhand asks a newly risen knight to reach her with compassion. The Silver Hand's former paladins wake among the Forsaken in shock. In life, they served the Holy Light and fought the undead. Now their souls are bound to decomposing flesh. Aramis Hammerhand guides some through this change, while others flee into the Tirisfal wilderness, unable to face their new existence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91208-42c74526e3ff45bb37a7/1-0000.mp3", duration = 29.3616327, start = 0},
  },
}
P.transport["quest:91209"] = {
  hash = "c21968",
  fullHash = "c21968",
  text = "Continue Your Training. In Deathknell, newly risen Forsaken paladins begin their training before setting out for Brill. Aramis Hammerhand sends them east through Tirisfal Glades, where danger and distrust greet those who wield the Holy Light. After learning martial combat and channeling holy power in Deathknell's graveyard, you travel east through Tirisfal Glades to Brill. The town is the regional outpost and administrative hub for central Tirisfal. There, Shari Stilwell oversees the training of those who follow the paladin's path in undeath. Aramis warns that an undead paladin's calling is perilous. Lordaeron still needs defenders against threats from beyond, yet wielding the Holy Light under Sylvanas Windrunner's banner invites suspicion. Many Forsaken suffered agony or death at the hands of holy zealots. Among their undead kin, the Light's presence breeds distrust.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91209-456289c81bd489e34058/1-0000.mp3", duration = 54.2040816, start = 0},
  },
}
P.transport["quest:916"] = {
  hash = "879825",
  fullHash = "879825",
  text = "Webwood Venom. In Shadowglen, Gilshalan Windwalker studies the giant webwood spiders of Shadowthread Cave. He asks young night elves for venom sacs to learn how Teldrassil's growth has affected the forest's wildlife. Gilshalan Windwalker has come to Shadowglen to study the webwood spiders in Shadowthread Cave. They are far larger and more aggressive than their cousins elsewhere. He suspects Teldrassil's immense magical energies are changing the local wildlife. So he asks for venom sacs to compare with those of ordinary spiders and learn what has changed. Webwood spiders live in and around Shadowthread Cave, where they threaten young night elves in the glen. Gathering their venom can help thin their numbers. It also gives Darnassian researchers evidence of Teldrassil's effect on the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_916-e4ff2d52e6658f9d7895/1-0000.mp3", duration = 49.0840816, start = 0},
  },
}
P.transport["quest:917"] = {
  hash = "fe007f",
  fullHash = "fe007f",
  text = "Webwood Egg. In Shadowglen, Gilshalan Windwalker seeks a Webwood Egg for his study of Teldrassil’s wildlife. Venom samples are in hand, but he needs a living specimen to study the unnatural aggression in the forest’s creatures. An egg can be examined safely, without capturing a full-grown spider. Gilshalan Windwalker needs living subjects to understand the unnatural corruption affecting Webwood spiders around Shadowglen. You have gathered venom from the aggressive spiders, but taking a thrashing giant from the depths could prove deadly for a novice. So Gilshalan asks you to bring an unhatched egg from the brooding clutches inside Shadowthread Cave. Webwood spiders brood in Shadowthread Cave, where the increasingly hostile arachnids make their nests. An intact egg gives scholars a subject they can hatch under containment. Gilshalan plans to send it to Darnassus with his venom samples for examination. With his local study complete, he directs recruits toward higher duties in the boughs of Aldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_917-60d8103677cccbb80a26/1-0000.mp3", duration = 61.3355102, start = 0},
  },
}
P.transport["quest:918"] = {
  hash = "655f12",
  fullHash = "655f12",
  text = "Timberling Seeds. At Lake Al'Ameth, botanist Denalan studies the growing hostility of Teldrassil's nature elementals. He seeks Timberling Seeds to test whether enriched soil can help them grow calmer. His work joins the quiet efforts of night elf herbalists to understand the subtle afflictions troubling the World Tree. Timberlings are nature elementals native to Teldrassil's boughs, bound closely to the health of the surrounding flora. Usually they reflect the forest's balance in peaceful form. Their recent hostility alarms the local night elves, though no cause is known. Botanist Denalan seeks to learn what stirred them before choosing to cull them. Denalan suspects the blemish lies deep in the ground. He hopes to raise a gentler generation of timberlings in enriched, carefully treated loam. By gathering seeds from wandering timberlings near Lake Al'Ameth, he will test whether the land's corruption can be countered from the roots up.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_918-220d62139999b90c9305/1-0000.mp3", duration = 58.0963265, start = 0},
  },
}
P.transport["quest:919"] = {
  hash = "52edfa",
  fullHash = "52edfa",
  text = "Timberling Sprouts. Around Lake Al'Ameth, Timberling Sprouts are spreading across Teldrassil. Denalan asks you to uproot them before they grow into hostile timberlings. Corrupted sprouts spread along Lake Al'Ameth's banks. Denalan lives beside the lake and knows these young plants cannot be healed. Left alone, they quickly become aggressive, bark-covered timberlings that threaten wildlife and travelers. Uprooting them helps protect the grove. Denalan is troubled by how quickly new sprouts appear across Teldrassil. Their spread points to sickness in the World Tree's roots and soil. Denalan and the druids of Darnassus seek its cause.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_919-cf0734cffa13e732941c/1-0000.mp3", duration = 38.8702041, start = 0},
  },
}
P.transport["quest:92"] = {
  hash = "78ad66",
  fullHash = "78ad66",
  text = "Redridge Goulash. In Lakeshire, Redridge Goulash feeds a town under strain. During the recent Blackrock orc uprising, Chef Breanna fed the Stormwind garrison until her pantry was bare, and now seeks hearty ingredients in the mountains. Blackrock orcs, gnolls, and fierce wild beasts still besiege Lakeshire. When the recent orc uprising began along the ridges, Chef Breanna took charge of feeding the Stormwind brigade stationed in town. The active garrison soon emptied her cupboards, while many hungry mouths remained. With her cupboards bare, Chef Breanna turns to the dangerous wilderness beyond Lakeshire's gates. Her signature goulash calls for tough mountain condor meat, seasoned snouts from Great Goretusks, and crisp leg meat from giant tarantulas prowling the hills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92-283afe78b26f1d8edc56/1-0000.mp3", duration = 49.5020408, start = 0},
  },
}
P.transport["quest:920"] = {
  hash = "b6fd52",
  fullHash = "b6fd52",
  text = "Tenaron's Summons. In Shadowglen, Gilshalan Windwalker sends you to meet Tenaron Stormgrip in Aldrassil. Your work against dangers in the woods has brought the elder's attention. Your fight against venomous spiders and corrupted wildlife has reached Tenaron Stormgrip. Gilshalan Windwalker tells you the elder wants to see you. Even night elves know better than to keep an elder waiting atop Aldrassil. Tenaron waits in Aldrassil's highest chamber and looks across Shadowglen's boughs. His concerns reach beyond the glen, to Teldrassil's moonwells and the corruption spreading through the young World Tree's ecosystem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_920-0229cdd4f1f230fa383a/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["quest:921"] = {
  hash = "f889d7",
  fullHash = "f889d7",
  text = "Crown of the Earth. At Aldrassil, Tenaron Stormgrip prepares young night elves for their departure from Shadowglen. They draw sacred water in a rite that recalls Mount Hyjal and the immortality their people surrendered there. Before young night elves leave Shadowglen, their elders teach them what their people lost. At Mount Hyjal, the kaldorei sacrificed the World Tree Nordrassil to defeat Archimonde and banish the Burning Legion. The blast took their ageless immortality and sacred shield. Tenaron Stormgrip teaches this history through a rite, so the novices leave with humility and purpose in a changing world. You draw water from the moonwell north of Aldrassil with a crystal phial. Moonwell waters bear remnants of the ancient Well of Eternity. Druids channel their restorative power into the wild, while Sentinels honor the wells as tranquil shrines to Elune. The kaldorei remain wary of arcane sorcery, which is forbidden. The wellspring sustains their land, yet recalls the reckless magic that nearly broke the world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_921-d204ba74e9378bd0637b/1-0000.mp3", duration = 66.037551, start = 0},
  },
}
P.transport["quest:92124"] = {
  hash = "0c93e8",
  fullHash = "0c93e8",
  text = "Book Inventory. At Northshire Abbey, Brother Paxton needs help finding missing books. He sends young adventurers to Daniel, his daydreaming assistant, to count the library's archives. But Daniel's thoughts turn to local tradeskills, making a clear answer hard to get. Northshire Abbey keeps scholarly works, spiritual writings, and records of Stormwind's history that survived the First War. Brother Paxton, a careful monk, takes pride in the collection. Now books are missing from the shelves, and he needs a clear count to learn how many are gone. He has little patience for chasing his daydreaming helper. Daniel assists Brother Paxton in the abbey library, but his thoughts stray from parchment and catalog numbers. He is fascinated by the practical trades and professions of Elwynn Forest, including smithing, leatherworking, tailoring, and herbal craft. So when Paxton asks him to count the books, Daniel rambles about local crafters instead of looking for lost scriptures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92124-c5fb292f2bda822121c3/1-0000.mp3", duration = 60.4995918, start = 0},
  },
}
P.transport["quest:922"] = {
  hash = "11fea2",
  fullHash = "11fea2",
  text = "Rellian Greenspyre. At Denalan’s retreat by Lake Al’Ameth, you carry a timberling seed to Rellian Greenspyre in Darnassus. The handoff brings word of trouble spreading through Teldrassil’s boughs. Denalan has studied the plants and elemental life around Lake Al’Ameth. After you gather seeds from nearby timberlings, he sends you to Darnassus with one for his colleague, Rellian Greenspyre. Rellian is a druid who walks the Cenarion Enclave’s terraces. He has taken an interest in Denalan’s research and hopes to grow a timberling of his own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_922-21be8d6dd06c17924b0b/1-0000.mp3", duration = 33.6718367, start = 0},
  },
}
P.transport["quest:923"] = {
  hash = "bf62f3",
  fullHash = "bf62f3",
  text = "Tumors. In Darnassus, the Cenarion Circle works to contain the sickness spreading through Teldrassil. You are sent to Wellspring Lake to gather mossy tumors from afflicted timberlings, so druids can study the poison and burn the growths safely. A strange affliction is twisting Teldrassil’s native plants and animals. Its timberlings, usually placid nature spirits with bark for skin, have grown hostile and erratic. Grotesque mossy tumors spread across their living wood and pulse with unnatural poison. Cenarion scholars Denalan and Rellian Greenspyre search for the cause. Timberlings already lost to the sickness must be culled to protect the rest of the boughs. Wellspring Lake in northern Teldrassil has become a focal point of the outbreak. Its timberlings are among the most tainted on the World Tree. Rellian Greenspyre asks you to kill these corrupted guardians and cut away their tumors. Bring the growths to the druids in Darnassus, where they can be burned safely. The night elves hope this will slow the contagion while they search for the disease’s source.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_923-7ec093d97fba793792df/1-0000.mp3", duration = 66.5077551, start = 0},
  },
}
P.transport["quest:924"] = {
  hash = "464f79",
  fullHash = "464f79",
  text = "The Demon Seed. Neeru Fireblade's orders reach Ak'Zeloth, and the orc sends Horde travelers against the Demon Seed atop Dreadmist Peak. A Flawed Power Stone can break the Burning Legion's conduit before its influence spreads farther through the Barrens. You carry an unstable Flawed Power Stone to a cave high on Dreadmist Peak. There, the Demon Seed hangs above an altar of fire. The artifact anchors the Burning Legion's demonic power in the heart of the Barrens. Ak'Zeloth prepared the stone to break its link to the Nether, but its energy will not last long.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_924-a0cc99ae28c162770b70/1-0000.mp3", duration = 34.8473469, start = 0},
  },
}
P.transport["quest:92460"] = {
  hash = "129acb",
  fullHash = "129acb",
  text = "Coming of Age. In Thendal Village, young Skyborne begin the rite that welcomes them into service to the shen'dorei. Ailee Farheart leads them to Rorian the Dayseeker, who gives each initiate an ancestral relic and hears their pledge to aid their people. Ailee Farheart guides young Skyborne from Thendal Village toward adulthood. They travel just west to the greatfather tree, where the village elder waits. For the shen'dorei, the rite marks a passage into adulthood and a pledge to serve their community. Local troubles are rising. At the entrance to the greatfather tree, Rorian the Dayseeker leads the ceremony. He gives each initiate an ancestral relic, an heirloom passed through generations of shen'dorei. The relic is a token of the winds of home. It stays with its bearer until their ashes are scattered to the breeze.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92460-66332b05ed90daf0bea6/1-0000.mp3", duration = 50.9910204, start = 0},
  },
}
P.transport["quest:92461"] = {
  hash = "cb1ebb",
  fullHash = "cb1ebb",
  text = "Harmony in Balance. On Zephras Isle, Rorian the Dayseeker gives fledgling adventurers an early rite of duty. You thin the vuldren in Thendal Grove to protect the island’s natural balance, for its beasts feel magic shifting in the winds. In Thendal Grove, vuldren have grown too numerous for the island to sustain. Their numbers threaten the environmental harmony that supports Zephras Isle’s wildlife. Rorian the Dayseeker gives young protectors the duty of thinning the herd before it strains the grove and the life around it. Vuldren are usually docile, yet the beasts of Zephras Isle are sensitive to the island’s atmosphere. When magic carried on the winds falls out of balance, they respond sharply. Keeping their numbers in check helps prevent them from becoming unpredictable and dangerous pests.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92461-7d36eb449dc71f03a643/1-0000.mp3", duration = 48.1959184, start = 0},
  },
}
P.transport["quest:92462"] = {
  hash = "2456d5",
  fullHash = "2456d5",
  text = "Infestation Investigation. In Thendal Grove, cirrusflies swarm the eastern woods. Ranger Elatrell Featherlight sends young defenders to thin their growing numbers before nearby settlements are at risk. Local rangers report a sudden rise in cirrusflies along Thendal Grove’s eastern edge. One is a minor pest, but a swarm grows aggressive and destructive. So Ranger Elatrell Featherlight sends capable youths to cull the insects before they overwhelm the grove. After coming of age, young defenders help keep Zephras Isle safe. Clearing pests protects nearby settlements from outbreaks in the woods. Yet entrails and insects clinging to returning hunters show the swarm is far larger than first feared.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92462-1a2d284d38ed9dee3e42/1-0000.mp3", duration = 43.3371429, start = 0},
  },
}
P.transport["quest:92463"] = {
  hash = "d553e4",
  fullHash = "d553e4",
  text = "The Cirrusfly Queen. In Thendal Grove, cirrusflies threaten the rangers of Zephras Isle. Their swarm has spread far, so Elatrell Featherlight sends you to hunt its queen and thin the flies at their source. You have seen that killing worker cirrusflies does little to curb the swarm spreading through Thendal Grove. Elatrell Featherlight sends you to the grove’s southeastern reaches, where the main hive lies. The queen directs the colony and heavier soldier drones guard her. From afar, cirrusflies may seem like petty pests. Yet the larger breeds threaten anyone who passes beneath Zephras’s boughs. Hunt down the matriarch and withstand her guards, and you prove your skill in battle. Featherlight’s rangers will give you praise and respect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92463-b6ad6045543fb24cddbf/1-0000.mp3", duration = 44.6955102, start = 0},
  },
}
P.transport["quest:92464"] = {
  hash = "f60c2a",
  fullHash = "f60c2a",
  text = "Elemental Unrest. Near the Thendal Standing Stones, lesser wind spirits have grown restless. Their sentient elemental benefactors have departed Zephras Isle, and Rorian the Dayseeker sends you into Thendal Grove to find his apprentice, Yala Windwatcher, and learn what troubles the breeze. For generations, powerful wind spirits lived beside the people of Zephras. They were sentient, and they guided and protected the islanders. Now those elemental benefactors have departed, leaving Zephras in lasting imbalance. Without them to tend the air, simple sprites reflect the volatile feelings and forces that linger across the land. Northeast of Rorian's post, the air near the ancient Thendal Standing Stones has turned hostile. The lesser wind spirits lack true self-awareness, so they act in reaction, not malice. Rorian sent his apprentice, Yala Windwatcher, to watch their erratic behavior from the grove's edge. She is to discover what unseen tension disturbs them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92464-ff4a773b3d27084d979a/1-0000.mp3", duration = 60.2644898, start = 0},
  },
}
P.transport["quest:92465"] = {
  hash = "00e7f0",
  fullHash = "00e7f0",
  text = "Agitators. On Zephras Isle, unrest in Thendal Grove draws Yala Windwatcher's concern. The Al'Aketh cult has stirred peaceful wind sprites into hostile elementals, and its converts now threaten the grove. Cultists of Al'Aketh have pushed into Thendal Grove and stirred the wind spirits who dwell there. Once peaceful, the sprites now rage as roiling winds, threatening anyone who passes through. Yala Windwatcher asks you to subdue the enraged elementals and the Al'Aketh converts behind the unrest. Quieting the wind creatures may restore a fragile calm to the grove.\n\nYala grieves at the thought of shen'dorei blood shed among her own people. Yet while the cult remains, she sees little choice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92465-2681461fa9620b0138ff/1-0000.mp3", duration = 45.6620408, start = 0},
  },
}
P.transport["quest:92469"] = {
  hash = "7fdf2d",
  fullHash = "7fdf2d",
  text = "Return to Rorian. Yala Windwatcher sends you to Thendal Grove with urgent news from the field. After you help drive back the agitators on Zephras Isle, she reports that the Al'Aketh have disturbed the local wind spirits. Yala Windwatcher remains on Zephras Isle to face the hostiles still there. She sends you to Thendal Grove with word that the Al'Aketh are no longer working only in the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92469-87a46b18501a988f2ce0/1-0000.mp3", duration = 24.2416327, start = 0},
  },
}
P.transport["quest:92470"] = {
  hash = "c49d67",
  fullHash = "c49d67",
  text = "Foul Matriarch. In the caves south of Thendal Village, Aetheen of the Gales tests new initiates against the ursera. They must thin the packs and slay their den mother, Urs'anah, to prove they can face greater perils across Zephras Isle. Around Thendal Village, Aetheen of the Gales watches newcomers find their footing. When an initiate shows early skill, Aetheen sends them into the southern caves for a dangerous rite of passage. There, they thin the local ursera packs and face the broodmother who threatens the village's edge. Local rangers know the ursera are fierce, but Urs'anah is the greatest threat to the haven. Deep in Thendal Cave, the formidable matriarch directs her scavengers and guards her lair. Her severed head proves an adventurer can face ferocious beasts and is ready to venture beyond the starting grove.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92470-3808838e3b2a2595107c/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:92471"] = {
  hash = "51d856",
  fullHash = "51d856",
  text = "Aetheen of the Gales. On Zephras Isle, young adventurers who pass their first trials go to meet Aetheen of the Gales at Thendal Grove. There, the next generation faces her judgment. Young novices on Zephras Isle take on early duties that test their grit and spirit. The island's mentors watch for those ready to help defend their home. Rorian the Dayseeker notices youths prepared for greater responsibility. At Thendal Grove, Aetheen of the Gales reads the currents of the air. She belongs to the Council of Elders, which governs Zephras Isle, and assesses young shen'dorei as they come of age. Reporting to her takes you beyond minor duties along the island's perimeter and toward threats facing the community.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92471-655fb5e836846508f2cd/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["quest:92472"] = {
  hash = "841720",
  fullHash = "841720",
  text = "The Next Step. Elder Aetheen turns south after the beasts near Thendal Village are dealt with. The Al'Aketh Cult's zealots threaten Shen'dar Village. Elder Aetheen of the Gales sees danger growing across Zephras Isle. The predators and matriarchs of the northern wilderness have been dealt with, but that was only the lesser trouble. Outlying settlements still need defenders. The Al'Aketh Cult is the chief danger in southern Zephras. Its ruthless zealots worship Al'Akir the Windlord, ruler of Skywall in the elemental realm. Their growing power threatens Shen'dar Village. Aetheen sends travelers south along the road, past ambushers in the highlands, to aid Constable Aonda's local guard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92472-695fe54da39262bbba1a/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["quest:92473"] = {
  hash = "d656b4",
  fullHash = "d656b4",
  text = "Aggressive Encroachment. At the village, starving ursera now threaten the settlement. Valreaa Valewind calls for a cull after one beast nearly attacked a child at the elder tree. Ursera from dens southwest of the village have become dangerous to its people. A hungry adolescent reached the base of the central elder tree and nearly mauled a child at play. The settlement's rangers killed the beast before anyone was hurt. The rangers believe hunger is driving ursera toward settled ground. They have ordered a cull of the scrawniest beasts prowling outside their dens in Thendal Grove. The Rangers of the Grove hope this will stop further incursions while they seek the cause of the wildlife's distress.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92473-b3504843bd545f25d902/1-0000.mp3", duration = 39.7583673, start = 0},
  },
}
P.transport["quest:92474"] = {
  hash = "eddb4e",
  fullHash = "eddb4e",
  text = "Falling With Style. At Thendal Village, Myriaal Mistwake sends young Skyborne from a watchtower to test their falling skill. They glide down to Rorian the Dayseeker below. High above Thendal Village on Zephras Isle, Myriaal Mistwake invites young Skyborne to test their heritage with a daring leap. She urges newcomers to step from the watchtower ledge and trust their gift for slowing a fall. The practice is playful, yet it prepares them to walk on air when danger comes beyond the grove. Myriaal delights in sudden descents that startle onlookers, while Rorian the Dayseeker favors caution. As novices glide down to land before him, he warns that careless use of their magic may leave travelers helpless in danger. Still, he accepts that controlled practice within the village has its place.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92474-6372bd6ddb0e5c1cbc4b/1-0000.mp3", duration = 47.0987755, start = 0},
  },
}
P.transport["quest:92481"] = {
  hash = "e5d31d",
  fullHash = "e5d31d",
  text = "A Student of the Arcane. On Zephras Isle, Rorian the Dayseeker calls novice spellcasters to A Student of the Arcane. After newcomers prove their mettle, they review a Glowing Recall Crystal and report to Dorii Brightwhisper, the local mentor. After helping with the troublesome vuldren near Thendal Grove, fledgling mages receive a curious artifact: a Glowing Recall Crystal. Dorii Brightwhisper, the island’s arcane instructor, left it behind. Its recorded message tests an initiate’s aptitude and welcomes them into deeper study of magic. Dorii Brightwhisper says arcane mastery has slowly faded among their people. For millennia, they lived secluded high in the clouds. So Dorii sees each new practitioner as a pioneer who can recover lost knowledge and restore their people’s once-mighty magical heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92481-8ab2cbfb288dcea4d77e/1-0000.mp3", duration = 51.435102, start = 0},
  },
}
P.transport["quest:92482"] = {
  hash = "7ef883",
  fullHash = "7ef883",
  text = "The Way of the Hunter. Young hunters in Thendal Grove begin training after driving back the local vuldren. Now Rorian the Dayseeker summons them to meet Tai'ree Farsight and begin formal tutelage. After thinning the disruptive vuldren on Thendal Grove's outskirts, young hunters return to find their practical skills have drawn attention. Rorian the Dayseeker gives them a scribbled summons from Tai'ree Farsight, the grove's resident hunter trainer. For novice rangers preparing to explore Zephras Isle, the meeting turns their work from defending the island to learning martial skills and survival. Near the center of the village, Tai'ree Farsight welcomes promising pupils with stern realism. Thriving in untamed nature demands sharp senses and lightning reflexes. Her guidance comes from her long years of experience, giving island trackers a foundation for honing their marksmanship and survival skills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92482-70ddeb84a3513e66a2fd/1-0000.mp3", duration = 53.3420408, start = 0},
  },
}
P.transport["quest:92483"] = {
  hash = "a87a4e",
  fullHash = "a87a4e",
  text = "At Home in the Shadows. Rorian sends you to meet Akeri Duskblade in Thendal Grove, where rogue training begins. The summons marks a change from village chores to stealth and combat. Akeri Duskblade has noticed young rogues dealing with threats around Thendal Grove. The grove's rogue trainer avoids an open meeting in the settlement, so he sends a note through Rorian the Dayseeker. Though Akeri keeps his reasons close, Rorian sees that he knows the skills a rogue needs beyond the grove's sheltered bounds. Akeri Duskblade waits in the Thendal Grove village watchtower. He judges each newcomer’s footing and awareness, then warns that careless steps beyond the grove can lead to an early grave. Passing his scrutiny begins formal training in stealth, precision, and survival on Zephras Isle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92483-30302bb92ddf43b2032b/1-0000.mp3", duration = 47.1771429, start = 0},
  },
}
P.transport["quest:92484"] = {
  hash = "2c7c0f",
  fullHash = "2c7c0f",
  text = "Embracing the Elements. In Thendal Grove, Rorian the Dayseeker calls young shamans to begin their elemental training. Windshaper Boro’s message speaks of a silence between the people and the spirits of the winds. Rorian the Dayseeker comes to you after you help with the vuldren around the village. Windshaper Boro left a humming recall crystal while you were away. Its message calls you to the center of the grove, where formal elemental instruction begins. Windshaper Boro tells you the spirits of the four winds ended all communication years ago. They left behind the communion they once shared with the people. Now the shamans of Zephras study the natural world and train hard, hoping to bridge the silence and speak with the spirits again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92484-00c56f63c6bb8dc20d35/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["quest:92485"] = {
  hash = "ac613d",
  fullHash = "ac613d",
  text = "A Student of Nature. On Zephras Isle, A Student of Nature begins with a summons to novice druids. After they help restore local harmony, Xyton Silverwind calls them beneath the boughs of Thendal Grove to learn the isle's natural balance. After local disturbances caused by overzealous wildlife are resolved, Rorian the Dayseeker brings a personal summons to young initiates. The folded parchment was left by Xyton Silverwind. It invites aspiring druids to step forward and study the deeper mysteries of the wild, for their natural talents have caught the grove elders' attention. Meeting Xyton Silverwind on the lower level of the great tree in Thendal Grove marks a novice's first step in their calling. To Silverwind, Zephras Isle's plants and animals form an intricate living whole that needs constant care and watchful balance. The path of fang, claw, feather, and branch calls for lasting mentorship, and this meeting begins a lifetime of stewardship.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92485-48ad20ff145443a81e0d/1-0000.mp3", duration = 58.7232653, start = 0},
  },
}
P.transport["quest:92532"] = {
  hash = "fdf4d3",
  fullHash = "fdf4d3",
  text = "The Warrior's Path. Rorian the Dayseeker sends you to Blademaster Ren in Thendal Village. She offers young warriors instruction and discipline to defend their people. After restoring balance nearby, you return to Rorian the Dayseeker in Thendal Village. The village blademaster has noticed you, and Rorian gives you a crumpled note written by Ren herself. She asks you to come to her directly.\n\nRen waits in the village watchtower, high above the settlement. From there, she watches the island's borders and the recruits who may one day defend them. Inside the watchtower, Blademaster Ren teaches you that combat takes more than brute strength. A warrior must lead, endure, and protect as the world grows more uncertain. Ren pledges to guide you as you hone your skills. Her rigorous training prepares you for the greater dangers threatening your home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92532-d25e1086e79a536a377d/1-0000.mp3", duration = 51.6179592, start = 0},
  },
}
P.transport["quest:92544"] = {
  hash = "2d5669",
  fullHash = "2d5669",
  text = "Al'Aketh Thugs. At the temple ruins near Thendal Grove, Al'Aketh cultists threaten travelers. Sent from the Shrine of Akir under High Priestess Lorthuna's orders, they harass wayfarers and force recruits into their ranks. Hanaa Nightwind asks you to break their hold and slay their commander. Just southwest of Thendal Grove, ancient temple ruins have become dangerous for travelers. The Al'Aketh have seized the grounds and prey on people near the grove. Rangers stationed nearby suspect High Priestess Lorthuna sent the ruffians from the Shrine of Akir. They bully the people and force them to submit to the cult. At the ruins, Malduko Cloudcrush rules through violence and fear. Brutes and newly indoctrinated neophytes obey him, making the temple an aggressive outpost at Thendal Grove's doorstep. Hanaa Nightwind hopes that striking down Cloudcrush and scattering his followers will break the cult's confidence. It will warn them that coercion will not be tolerated in these lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92544-00c7aa3781b427e9eaae/1-0000.mp3", duration = 60.8130612, start = 0},
  },
}
P.transport["quest:92597"] = {
  hash = "6e883c",
  fullHash = "6e883c",
  text = "Reading the Ley Lines. On Zephras Isle, young Skyborne seek the arcane currents beneath their feet. Falorne Fallwind sends them to Thendal Grove to feel power rising through the elemental plane. Ley lines run beneath Zephras Isle, even through the elemental plane. Strange elementals and the hostile Al'Aketh cross the island as these buried currents rise toward the surface. For those with the bloodline and knowledge to channel them, the exposed lines open a path to raw arcane power. Falorne Fallwind urges initiates to claim their Highborne ancestry instead of seeking favor from wind spirits. The local Windshapers and the Al'Aketh both look to such spirits. Fallwind believes survival amid the elemental plane's harsh powers depends on mastering the arcane force beneath the ground, rather than asking foreign creatures for mercy. Northeast of the settlement, Thendal Grove's ancient standing stones mark a powerful meeting of ley lines. Roiling winds and Al'Aketh converts surround this exposed place. There, initiates can attune their senses to the ley line's pulse and unleash the full potential of their natural racial abilities.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92597-56ec32a55d2d6755d1ce/1-0000.mp3", duration = 71.7844898, start = 0},
  },
}
P.transport["quest:92598"] = {
  hash = "cc39de",
  fullHash = "cc39de",
  text = "The Gift of Skysight. On Zephras Isle, Ventaari Brightwish guides young Windshapers toward Skysight. At an Elemental Convergence, they awaken their perception and listen to the spirits. Windshapers are born with a bond to the elemental forces that shape their world. They call its sacred faculty Skysight. This gift attunes mortal senses to the spiritual realm and reaches across the divide between the living and the unseen. In the wilds, a Windshaper can call on this inner vision. Near concentrated power, the bond grows stronger, bringing boons and wisdom whispered by the spirits. Northeast of the settlement, ancient standing stones mark an Elemental Convergence in Thendal Grove. Raw energies gather at such places, where spirits linger. Ventaari Brightwish sends novices there to test their spiritual strength. Skysight grows with practice, like a faculty of body or mind. Windshapers must learn to read the elements' changing omens, for their people's survival depends on it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92598-b102e176eac9d46752a8/1-0000.mp3", duration = 60.6563265, start = 0},
  },
}
P.transport["quest:926"] = {
  hash = "9237fe",
  fullHash = "9237fe",
  text = "Flawed Power Stone. Across the Barrens, flawed stones sit charged with arcane energy on ritual tables. Their makers left them unstable, and they consume their power soon after they are moved. Across the Barrens, flawed power stones hold arcane essence in compromised structures. Their makers left them unstable, so they decay into inert matter moments after someone handles them. A stone starts consuming its power as soon as it leaves the ritual table where it rests. Its energy burns away too quickly for anyone to carry it far.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_926-deee357c9129f56f5e87/1-0000.mp3", duration = 34.3510204, start = 0},
  },
}
P.transport["quest:9260"] = {
  hash = "39529a",
  fullHash = "39529a",
  text = "Investigate the Scourge of Stormwind. Lieutenant Orrin calls Stormwind's defenders to drive back Scourge forces pressing against the city. Necropolises loom beyond its walls, and he asks them to gather Necrotic Stones and study the runes around enemy camps. Scourge forces have reached the outskirts of Stormwind City. Necropolises float overhead as undead and cultists take hold near the kingdom’s greatest bastion. Lieutenant Orrin gathers defenders outside the city to drive them back before they threaten the capital. Glowing runes mark the dirt around Scourge camps, but their purpose remains unclear. The circles crackle with magic like that of the necropolises and carry eerie whispers. Lieutenant Orrin can only guess who, if anyone, hears those unnatural voices.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9260-9cd82c06941338806878/1-0000.mp3", duration = 47.8040816, start = 0},
  },
}
P.transport["quest:9261"] = {
  hash = "8634c1",
  fullHash = "8634c1",
  text = "Investigate the Scourge of Ironforge. The Scourge presses against Ironforge’s gates, and Lieutenant Nevell calls for defenders. Undead troops gather beneath a hovering necropolis while glowing runic circles mark their camps. Lieutenant Nevell and the Argent Dawn watch the undead at Ironforge’s mountain entrance. Necropolises hover above Dun Morogh’s frigid heights, far from Lordaeron and the plagued lands of the north. They mean to stop the Scourge before it reaches the Bronzebeard fortress.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9261-076b9aea245777334b48/1-0000.mp3", duration = 29.3093878, start = 0},
  },
}
P.transport["quest:9262"] = {
  hash = "3bb572",
  fullHash = "3bb572",
  text = "Investigate the Scourge of Darnassus. At Darnassus, Lieutenant Beitha calls for help as Scourge encampments press close. The Argent Dawn needs defenders to strike the undead and learn what the runes outside the gates are for. The Scourge has reached Teldrassil. Floating necropolises loom over invasion camps near Darnassus, and ghouls, skeletons, and other undead horrors spill from them. Lieutenant Beitha of the Argent Dawn coordinates the city's defense. She calls on volunteers to slow the attack and gather information before the undead overwhelm the night elven homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9262-534eafb5b76d2163a7ba/1-0000.mp3", duration = 34.9257143, start = 0},
  },
}
P.transport["quest:9263"] = {
  hash = "6669ec",
  fullHash = "6669ec",
  text = "Investigate the Scourge of Orgrimmar. Outside Orgrimmar, the Scourge presses its attack beneath a floating necropolis. Lieutenant Dagel calls on defenders to repel the undead, recover necrotic stones, and examine runic circles charged with necromantic energy. The assault brings the Lich King's reach to Durotar. The Scourge now threatens lands far from Lordaeron and the northern ice. Its floating necropolises cast shadows across Azeroth, even over Durotar. Undead forces have gathered at Orgrimmar's threshold and raised camps that threaten the Horde capital. Lieutenant Dagel and the Argent Dawn coordinate the defense, calling on local champions to drive the invaders back before they can secure a siege.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9263-012376b2c6f6fcfec072/1-0000.mp3", duration = 43.2326531, start = 0},
  },
}
P.transport["quest:927"] = {
  hash = "f5c9a7",
  fullHash = "f5c9a7",
  text = "The Moss-twined Heart. Near Lake Al'Ameth, Denalan studies a heart taken from Blackmoss the Fetid. Dark, oily moss covers the core, yet it keeps beating after it is cut from the timberling. Blackmoss the Fetid's heart still beats after it is cut from the timberling. Dark, oily moss hides nearly all of the core, but a slow rhythm continues within. That pulse points to a corruption beyond ordinary rot in Teldrassil's wild plants. Denalan studies local flora near Lake Al'Ameth, and the heart commands his keen interest. He recognizes its troubling corruption. Timberlings should be gentle beings tied to the boughs of the World Tree, yet this core bears a virulent blight.\n\nTroubled by what he sees and eager to understand it, Denalan plans to plant and study the organ. He hopes to learn how foul moss takes root in the island's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_927-0102ae531c1f017cb9ca/1-0000.mp3", duration = 54.5697959, start = 0},
  },
}
P.transport["quest:92742"] = {
  hash = "5a0786",
  fullHash = "5a0786",
  text = "Testing the Wells. Across Westfall, Alba Fairmoon sends you to test the farm wells. Their samples may show what is poisoning the soil and groundwater. Alba Fairmoon asks you to test the water beneath Westfall. Neglect and banditry have already harmed the open plains. Now poison below the earth threatens the farmland that remains. You gather samples from farm wells so Alba can learn what is tainting the soil and water. You gather samples from the wells at Jansen Stead and Molsen Farm. These homesteads lie among scattered farms, exposed to Defias outlaws and feral wildlife. Their water may show whether the blight rises from the ground, comes from magic, or was put there deliberately.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92742-3e5f930c84b93b372998/1-0000.mp3", duration = 43.2326531, start = 0},
  },
}
P.transport["quest:92744"] = {
  hash = "6683b8",
  fullHash = "6683b8",
  text = "Murloc Gills. At Westfall's Longshore, Alba Fairmoon seeks murloc gills to test the sea. She fears the crop blight may reach the Great Sea, and the gills could show whether the coastal waters are tainted. Westfall is close to ruin. Crops fail, farmers leave their homes, and bandits roam the roads. Alba Fairmoon fears the blight may drain from inland fields into the Great Sea. If it taints the coast, fish that feed Westfall's poor and fill Stormwind City's tables could vanish. Then an already strained kingdom may face famine. Murlocs are stubborn and violent, but their amphibious bodies can reveal the water's condition. As they breathe, their gills filter seawater and readily take in poisons, blight, and unnatural pollutants. Alba Fairmoon hopes fresh gills from murlocs prowling the Longshore will show how far the contamination has spread.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92744-0f1793c81ccae0732890/1-0000.mp3", duration = 54.7787755, start = 0},
  },
}
P.transport["quest:92745"] = {
  hash = "6e345d",
  fullHash = "6e345d",
  text = "The State of the Mines. Toxic metals are turning up in Westfall's wells, and Alba Fairmoon fears for the farmland. She suspects the Defias mines and warns that the soil could fail for decades. You head to Jangolode Mine and Gold Coast Quarry to disrupt the mining. Alba Fairmoon finds dangerous levels of toxic metals in Westfall's wells. Once Stormwind's main breadbasket, the region now faces a threat to its crops. Alba suspects the Defias Brotherhood is poisoning the water through the mines it seized. If the contamination continues, the surrounding earth could lie barren for decades. The Defias put local creatures to work alongside their highwaymen, stripping Westfall of its resources. Riverpaw gnolls dig for stone and minerals at Gold Coast Quarry, while kobold diggers tunnel through Jangolode Mine. Disrupting their labor weakens the Defias' ability to process and distribute contaminated minerals.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92745-3e97ebc675fa245bb1c3/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["quest:92747"] = {
  hash = "0fe942",
  fullHash = "0fe942",
  text = "Moonbrook Espionage. In Moonbrook, Alba Fairmoon follows signs of industry trouble in Westfall. The poison found across the region does not seem to come from the smaller mines, so the Deadmines beneath the town draw her attention. The mines already searched across Westfall have yielded no answer to the poison spreading through the region. No known surface excavation seems to be its source. One great site remains unexplored: the Deadmines, whose vast shafts lie beneath Moonbrook’s ruined streets.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92747-3aeae5973746c6ce9ec3/1-0000.mp3", duration = 30.6677551, start = 0},
  },
}
P.transport["quest:92748"] = {
  hash = "8325d5",
  fullHash = "8325d5",
  text = "Explosive Consultation. Alba Fairmoon sends you to find a way to stop the poison spreading from the Deadmines into Westfall's fields. In Stormwind's Dwarven District, you seek an engineer who can make the heavy explosives the work requires. Westfall's poisoned fields lead back to caustic toxins and industrial refuse in the Deadmines. Reinforced machinery guards the underground works, and ordinary weapons cannot disable it. Heavy explosives could break through that machinery and halt the poisoning. In Stormwind's Dwarven District, you seek Sprite Jumpsprocket, an engineer able to devise the needed explosives. Roaring forges, tinkerers, and merchants selling blasting powder fill the district. Its craftsmen may know how to stop the Deadmines operation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92748-b17b0705ec8cdb8c67e9/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:92749"] = {
  hash = "048589",
  fullHash = "048589",
  text = "A Dynamite Plan. In Stormwind's Dwarven District, Sprite Jumpsprocket is eager to begin a plan sparked by talk of industrial sabotage. She wants ten sticks of coarse dynamite. Sprite Jumpsprocket is a gnome engineer in Stormwind's Dwarven District. She welcomes talk of industrial sabotage and asks passing mercenaries to bring her a bundle of coarse dynamite. You can make coarse dynamite at an engineering workbench or trade with the city's craftsmen. Sprite asks for ten sticks, enough to disrupt industrial schemes unfolding in the surrounding territories. Her plan shows the practical, perilous methods gnomes favor when facing mechanical and political disruptions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92749-e4fd435ff56e9fd326b5/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["quest:92750"] = {
  hash = "947a71",
  fullHash = "947a71",
  text = "Detonation at a Distance. Sprite Jumpsprocket needs a safer way to set off explosives, and sends you to Stormwind Intelligence for a remote detonator. Volatile chemicals are handled recklessly by goblins and gnomes, though some blasts call for care. A standard fuse can put you in danger. Ordinary tinkerers do not keep the special trigger Sprite needs for a controlled explosion. Sprite sends you to Stormwind Intelligence in Old Town, rather than to local dwarven blasters or ordinary engineering suppliers. Its agents, known as SI:7, work in sabotage, stealth, and targeted demolitions. Jasper Fel serves among them in the capital and can provide discreet, dangerous equipment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92750-43cb5530c4fd2a3a8cea/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["quest:92751"] = {
  hash = "565cfa",
  fullHash = "565cfa",
  text = "Detonation at a Distance. In Moonbrook, blasts beneath Westfall have drawn SI:7's attention. Jasper Fel, a Stormwind operative, sends a remote detonator kit to let you handle the work from a safe distance. Jasper Fel and SI:7 watch events across Stormwind's lands, including Westfall's troubled border. When word reaches him of explosive work in Moonbrook, Fel already knows what is happening in the abandoned mining tunnels beneath the countryside.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92751-e0fa2acab7124f6c8794/1-0000.mp3", duration = 27.5330612, start = 0},
  },
}
P.transport["quest:92752"] = {
  hash = "9c9146",
  fullHash = "9c9146",
  text = "Explosive Consultation. In Westfall, Sprite Jumpsprocket sends a volatile charge to Alba Fairmoon. The primed explosives must reach her safely, with the detonator undisturbed. Sprite Jumpsprocket has finished a bundle of Extra-Destructive Explosives for Alba Fairmoon. In wartime Westfall, the road is already threatened by Defias bandits and feral beasts. Carrying a live charge makes the journey more dangerous. Sprite Jumpsprocket warns you to guard the detonator. The explosives are meant to destroy the hidden industrial operation in the Deadmines, which is poisoning Westfall's farmland. Alba Fairmoon needs the explosives intact before she can use them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92752-e8eb732796319fa94068/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["quest:92753"] = {
  hash = "1962bb",
  fullHash = "1962bb",
  text = "Destruction in Deadmines. In the Deadmines beneath Moonbrook, Defias industry blights the land. Alba Fairmoon suspects their metallurgical forge is the source and sends you to destroy it with explosives. Beneath Moonbrook, the Deadmines hold a fortified complex that powers the Defias Brotherhood. Its heavy forge smelts metal and builds machinery. Alba Fairmoon believes the forge is the likely origin of the contamination blighting the area. She wants it destroyed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92753-30c1e06db90309f11e2c/1-0000.mp3", duration = 29.3877551, start = 0},
  },
}
P.transport["quest:928"] = {
  hash = "a250ea",
  fullHash = "a250ea",
  text = "Crown of the Earth. In Shadowglen, you carry moonwell water south to Corithras Moonrage in Dolanaar. The journey takes you from sheltered training into the wider work of protecting Teldrassil. You have tasted the enchanted water of Shadowglen's moonwell. At the crown of Aldrassil, Tenaron Stormgrip seals the gathered water in a larger vessel and sends you beyond the sheltered glade. The road runs south to Dolanaar, through woods where danger has grown harder to predict. Dolanaar is the first major village beyond Shadowglen, along the cobblestone paths through central Teldrassil. Its moonwell lies at the village's heart. Corithras Moonrage, an elder who oversees preservation across the boughs, waits there. The vessel you carry joins you to the wider effort to protect the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_928-21665f710c8b69bc5435/1-0000.mp3", duration = 50.1289796, start = 0},
  },
}
P.transport["quest:92819"] = {
  hash = "33132e",
  fullHash = "33132e",
  text = "Destruction in Deadmines. Alba Fairmoon sends you against the Defias forge beneath Westfall. The explosives are planted, and she waits in the hills behind Moonbrook with the detonator. Beneath Westfall, the Deadmines hold the Defias Brotherhood's strength. Alba Fairmoon sends you to sabotage the forge hidden in the mines. The explosives are planted beside it. You return to Alba in the hills behind Moonbrook, where you can set them off from a safe distance. She hopes the blast will let Westfall's poisoned land begin to heal. Deep in the Deadmines, the charge waits beside the forge. After you rejoin Alba Fairmoon in the hills behind Moonbrook, a remote detonator lets you set it off from outside the caves. She hopes the destroyed forge will let Westfall's poisoned land begin to heal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92819-d4387698d5f5577a554a/1-0000.mp3", duration = 47.882449, start = 0},
  },
}
P.transport["quest:929"] = {
  hash = "c192b8",
  fullHash = "c192b8",
  text = "Crown of the Earth. Near Starbreeze Village, you draw sacred water for Darnassus. Corithras Moonrage in Dolanaar sends young night elves to replenish the city's moonwell and teaches them why their people tend Teldrassil's great boughs. Druids have made you a jade phial for the journey to Starbreeze Village. There, a lesser moonwell holds sanctified water. The phial's refined craft lets you draw the luminous water and carry it without disturbing its purity.\n\nDarnassus's central moonwell depends on scattered fonts like this one. Elders send initiates on foot to keep the city's fountains full of Elune's grace. The journey teaches the young what it takes to nourish Teldrassil. Corithras Moonrage tells you of the sorrow that followed the Battle of Mount Hyjal. The night elves sacrificed Nordrassil, their ancestral World Tree, and lost their immortality. Illidan Stormrage was unleashed amid the ruin, while Shan'do Malfurion Stormrage disappeared.\n\nGrief and isolation marked the days that followed. The kaldorei turned to Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_929-51c8b5bddfab8fe26d2c/1-0000.mp3", duration = 66.2465306, start = 0},
  },
}
P.transport["quest:930"] = {
  hash = "af7089",
  fullHash = "af7089",
  text = "The Glowing Fruit. A strange fruit shines among Teldrassil's trees, and its growth troubles those who find it. You carry it to Denalan at Lake Al'Ameth, where the herbalist can study the unfamiliar plant. In Teldrassil's misty boughs, you may find plants bearing large, round fruit that shine with their own light. The World Tree's balance is delicate, and its wildlife has behaved strangely of late. So unusual plants call for care. You gather the glowing fruit to bring it to someone who knows the wild flora.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_930-2c21aff5991cfd3885ae/1-0000.mp3", duration = 31.1379592, start = 0},
  },
}
P.transport["quest:931"] = {
  hash = "7799a9",
  fullHash = "7799a9",
  text = "The Shimmering Frond. A curious plant shimmers among Teldrassil's roots and canopy. Travelers carry a cutting to Denalan at Lake Al'Ameth, hoping the botanist can explain where it came from. A strange plant catches the light in Teldrassil's boughs. Its fronds twist with a pulsing shimmer unlike the island's usual foliage. The glow draws the eye among the young forest's plants.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_931-dba7eca5e42276b66da6/1-0000.mp3", duration = 23.2228571, start = 0},
  },
}
P.transport["quest:932"] = {
  hash = "939b84",
  fullHash = "939b84",
  text = "Twisted Hatred. Near Teldrassil’s settlements, Lord Melenas has rallied the grell at Fel Rock. Tallonkai Swiftroot sends trusted champions to stop the satyr before he threatens the night elves. Satyrs carry an ancient betrayal in kaldorei history. During the War of the Ancients, they were Highborne who gave themselves to the Burning Legion. Now one has taken hold on Teldrassil, the young World Tree meant as a sanctuary. For Tallonkai Swiftroot and the defenders who stand with him, that presence is a bitter disgrace. North of the nearby paths, Fel Rock’s corrupted caverns crawl with feral grell. Lord Melenas has gathered the chaotic creatures into a hostile force under his will. Tallonkai fears what the satyr may unleash upon the World Tree’s boughs, and demands a swift, quiet end. He wants Melenas slain and his severed head brought back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_932-93a0e0335cc4019cabff/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["quest:933"] = {
  hash = "13b0f0",
  fullHash = "13b0f0",
  text = "Crown of the Earth. At the Pools of Arlithrien, Corithras Moonrage asks you to fetch water as Gnarlpine furbolgs turn violent. His account of Teldrassil begins with Malfurion Stormrage's disappearance after the Third War. Corithras Moonrage gives you a tourmaline phial and sends you to a moonwell southeast of Darnassus's entrance, along the Pools of Arlithrien. The Gnarlpine furbolgs were once peaceful, but now they lash out without warning. They ambush travelers and harry Sentinel patrols across the region. These skirmishes have become a threat to the night elves' new home. When you return with the filled phial, Corithras tells you how Teldrassil began. After the Third War, Shan'do Malfurion Stormrage vanished, leaving the Cenarion druids without a leader and divided. Arch Druid Fandral Staghelm took the mantle of leadership in his absence. He urged the Circle of Ancients in Darkshore to set aside their mourning. The night elves, he argued, had to regain their lost immortality and heal their civilization by planting a vast new World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_933-07cf914f57ca7710f1e7/1-0000.mp3", duration = 68.3102041, start = 0},
  },
}
P.transport["quest:934"] = {
  hash = "0eb55a",
  fullHash = "0eb55a",
  text = "Crown of the Earth. At the Oracle Glade, Corithras Moonrage sends you to gather water from Teldrassil’s sacred moonwell. The journey begins to reveal why the World Tree’s creation went awry. Corithras Moonrage sends you northwest across Teldrassil to the Oracle Glade. Beneath the Oracle Tree’s great boughs lies the island’s first and most powerful moonwell. You draw water from its sacred pool into an Amethyst Phial. Druids and the tree itself watch over their new homeland’s health from this sanctuary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_934-195afb49b9d88b39ed78/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:935"] = {
  hash = "3e5594",
  fullHash = "3e5594",
  text = "Crown of the Earth. In Teldrassil, moonwell waters are gathered to ease the World Tree’s sickness. The rites carry the samples to Arch Druid Fandral Staghelm in Darnassus, where worry grows over a tree raised without blessings. Teldrassil rose after the Third War to give the night elves a new home and restore their lost immortality. Yet the Great Aspects Alexstrasza and Nozdormu withheld their blessings and would not sanction its making. Without their protection, sickness spreads through the tree. Strange creatures emerge from its boughs, and furbolg tribes once at peace fall into madness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_935-4fc517e341d98a618946/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["quest:93552"] = {
  hash = "2d39d2",
  fullHash = "2d39d2",
  text = "Harvesting Windstones. At Thendal Grove, Dalia the Collector asks you to gather raw windstones before their power fades. The ancient elemental energies of Zephras Isle are slowly dwindling. Zephras Isle still draws on wind magic, but its natural defenses are failing. Centuries ago, the wind elementals who shared the island with its elves vanished. Since then, the magic that sustains the land and its great anchor pylons has weakened. So Thendal Grove’s residents need every reserve of raw energy they can secure. Blue crystalline windstones lie scattered through Thendal Grove. Their brittle shells hold dense wind magic from ages past. They cannot sustain the island forever, yet they give its elves a dependable source of arcane power. Gathering raw clusters remains vital to daily life.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93552-08c5b7e29ec1259d0f31/1-0000.mp3", duration = 50.677551, start = 0},
  },
}
P.transport["quest:937"] = {
  hash = "b1a764",
  fullHash = "b1a764",
  text = "The Enchanted Glade. In northwestern Teldrassil, Bloodfeather harpies threaten the Oracle Glade and its ancient Oracle Tree. After they kill a runner bound for Darnassus, Sentinel Arynia Cloudsbreak calls for their nests to be thinned and their belts brought back as proof. Sentinel Arynia Cloudsbreak guards the Oracle Glade with an escort of warriors. At its heart stands the colossal Oracle Tree, an ancient rooted among Teldrassil's boughs. Bloodfeather harpies have spread through the surrounding canopy. They nest in its hollows and threaten anyone who comes near. A runner carrying an urgent report from the Oracle Tree never reaches Darnassus. Bloodfeather harpies ambush and kill the messenger before the runner can leave the glade. Arynia calls on you to thin their flock and bring back Bloodfeather belts as proof that their nests have been weakened.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_937-c833b151bc272192e75e/1-0000.mp3", duration = 52.6889796, start = 0},
  },
}
P.transport["quest:93746"] = {
  hash = "7b734e",
  fullHash = "7b734e",
  text = "A Firm Response. Ayessa Dawnsinger answers the High Order’s intrusion on Zephras Isle with force. She sends you after Belathaan Brightwish on the road north to the Shrine of Akir, to make the Windshapers’ boundaries clear. The Windshapers of Zephras Isle will not accept the High Order’s secretive scrutiny. Their warnings have gone unheeded, so Ayessa Dawnsinger escalates the dispute. She sends you to intercept Belathaan Brightwish on the lonely road north to the Shrine of Akir, away from prying eyes in town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93746-ab8a949bd55bdc7fa9f5/1-0000.mp3", duration = 31.5036735, start = 0},
  },
}
P.transport["quest:938"] = {
  hash = "224d61",
  fullHash = "224d61",
  text = "Mist. In Teldrassil's shaded boughs, Mist lies wounded and apart from her companion. She needs a safe path to Sentinel Arynia Cloudsbreak at a nearby moon well. Mist lies wounded in Teldrassil's undergrowth, her gray coat marked by deep slashes across her back and belly. Her blue eyes remain bright, and she stays calm instead of acting like a feral beast. She looks to friendly travelers for guidance and protection.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_938-2ab32cc756222534b44c/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["quest:93963"] = {
  hash = "e2dbf8",
  fullHash = "e2dbf8",
  text = "Exploring the Alliance. In Stormwind Keep, you begin a journey to meet the rulers of Ironforge and Darnassus. Their lands show you the breadth of the Alliance before you turn toward Westfall. Randal Emerson, an attendant in Stormwind Keep’s southern antechamber, sends you beyond the human capital. Newly arrived on Azeroth, you are invited to see the Alliance’s allied peoples firsthand. The journey takes you beyond the keep to learn the distinct cultures, traditions, and strength of those who stand with Stormwind. Your travels cross land and sea to the leaders of the Alliance. In Ironforge, you meet King Magni Bronzebeard in the mountain halls and High Tinker Gelbin Mekkatorque, leader of the displaced gnomes. In Darnassus atop Teldrassil, you meet High Priestess Tyrande Whisperwind. Their cities and peoples reveal the ties among humans, dwarves, gnomes, and night elves. After the long journey, you return to Stormwind. Knowing more of Azeroth helps you aid your own people, while your order prepares to establish itself in Dalaran. For now, the troubled territories near the capital need help, beginning with Westfall’s struggling farmlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93963-3f8a1cb3ab23e5be032c/1-0000.mp3", duration = 71.4710204, start = 0},
  },
}
P.transport["quest:940"] = {
  hash = "ad1d70",
  fullHash = "ad1d70",
  text = "Teldrassil. After the harpies are driven back, Arynia Cloudsbreak sends you to Darnassus with news for the kaldorei leadership. The inscribed bark tells Arch Druid Fandral Staghelm what troubles Teldrassil's boughs. Sentinel Arynia Cloudsbreak gives you a piece of inscribed bark after you clear the harpies from their nests in the Oracle Glade. The Oracle Tree watches over the forest, and now Arynia can send word to the kaldorei leadership. You carry her report through the wilderness to Darnassus, the great forest of stone, and deliver it to Arch Druid Fandral Staghelm. Fandral Staghelm receives the report with gratitude and frustration. The harpies have been pushed back, yet one threat gives way to another across Teldrassil. Staghelm championed the planting of the new World Tree to reclaim the night elves' lost immortality. The afflictions in its boughs remind him that his work is far from finished.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_940-8df71050831f6f4eae2a/1-0000.mp3", duration = 58.1485714, start = 0},
  },
}
P.transport["quest:941"] = {
  hash = "414709",
  fullHash = "414709",
  text = "Planting the Heart. At Lake Al'Ameth, you help Denalan care for a wooden heart taken from a corrupted timberling. He clears away its moss, then asks you to place it in his planter and see if it can be healed. Denalan has scraped the foul moss from the wooden heart taken from Blackmoss the Fetid, a corrupted timberling. Yet an unnatural taint still pulses within the wood. So the herbalist trusts his years of tending plants and soil. He asks you to bury the heart in his personal planter, hoping his enriched soil can draw its remaining natural vitality back toward health.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_941-7dcc0be618f93583b36c/1-0000.mp3", duration = 34.7167347, start = 0},
  },
}
P.transport["quest:944"] = {
  hash = "ad5604",
  fullHash = "ad5604",
  text = "The Master's Glaive. At the Master's Glaive in southern Darkshore, Onu fears the Twilight's Hammer cult has reached the fallen ancient horror. He sends Alliance scouts to investigate. Onu sees corruption linger along Darkshore, driving wildlife from its homes. The naga on the coast trouble him, but signs of the Twilight's Hammer trouble him more. Its followers worship primal lords who ruled the world before their overthrow in ages past. South of Onu, a grim excavation surrounds a colossal creature pierced by a great stone weapon. Onu gives you a Phial of Scrying and asks you to enter the pit and learn whether cultists have gathered there. The behemoth has been dead for eons, yet corruptive power still clings to its bones. The Twilight's Hammer may seek to claim it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_944-b25aa0abf438cdd5d1c2/1-0000.mp3", duration = 48.7706122, start = 0},
  },
}
P.transport["quest:94414"] = {
  hash = "3c77c4",
  fullHash = "3c77c4",
  text = "The Anchors of Zephras. On Zephras Isle, Halaan Hawk-Eye asks you to watch the ancient anchor pylons that hold the island aloft. Their magic has begun to waver, and the wind spirits' blessing may no longer be steady. Wind spirits gave Zephras's ancient anchor pylons the power to bind and sustain the floating island. Their magic keeps the land steady amid the churning skies. From afar, the towering monoliths look untouched. Yet the island depends on the wind spirits' continuing blessing. The anchor pylons look proud and undamaged, yet their magic has grown erratic. Halaan Hawk-Eye says the harmony that sustains them has become unstable and uncertain. No clear sign of physical harm appears. Those who watch over the groves have reason to fear what threatens the isle. Halaan Hawk-Eye cannot use skysight to peer between worlds, nor can he tap Zephras's deep ley lines. His gift is natural vision sharp enough to reach immense distances. He lends that sight to newcomers, so they can study the distant pylons and watch for changes in their homeland's fate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94414-8b8566cbf0c026f055ad/1-0000.mp3", duration = 67.8661224, start = 0},
  },
}
P.transport["quest:945"] = {
  hash = "f1e7d5",
  fullHash = "f1e7d5",
  text = "Therylune's Escape. At the Master's Glaive in southern Darkshore, Therylune needs help reaching safety. She wandered into the dig sites, and her sister Therysil waits at the Shrine of Aessina, worried for her. At the Master's Glaive, Twilight's Hammer cultists have pinned Therylune down. An ancient monstrosity's skull dominates the ravine, pierced by a huge stone blade. Despite the dread around it, Therylune wandered into the valley's heart. She survives by reacting quickly and hiding among the rough terrain. Therysil waits far to the south at the Shrine of Aessina. Her adventurous sister Therylune rarely minds getting dirt on her clothes, but even Therysil was shocked to hear she had ventured into the unwholesome excavations at the Master's Glaive. Tell her Therylune is safe, and her worry will ease. Therysil knows the dark forces digging through Darkshore's ancient earth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_945-870b8fcd13fef5eb3789/1-0000.mp3", duration = 51.9836735, start = 0},
  },
}
P.transport["quest:947"] = {
  hash = "64fd15",
  fullHash = "64fd15",
  text = "Cave Mushrooms. In Darkshore, Cave Mushrooms are needed for a potion Barithras Moonshade prepares in Auberdine. He asks you to gather rare fungi behind Cliffspring Falls and investigate warnings from the Grove of the Ancients. Barithras Moonshade needs scaber stalks and a death cap for a potent mixture. Both grow in a damp cavern behind Cliffspring Falls in northeastern Darkshore. Gathering them is more dangerous than picking ordinary woodland herbs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_947-908e55edc622570b762b/1-0000.mp3", duration = 26.8016327, start = 0},
  },
}
P.transport["quest:948"] = {
  hash = "4e991c",
  fullHash = "4e991c",
  text = "Onu. Barithras Moonshade sends you south from Auberdine to consult Onu. Your findings at Cliffspring Falls have caught the notice of one of Darkshore’s oldest guardians. Barithras Moonshade sees more than strange fungi in the samples you brought to Auberdine. The caves beneath Cliffspring Falls are tainted, and word of them has reached Onu, an Ancient of Lore in the Grove of the Ancients south of town. Darkshore’s waterways may be corrupted beyond anything a naturalist can explain. Onu seeks counsel, and even an Ancient’s patience cannot hide the weight of his summons. The road south from Auberdine turns inland, away from the coastal ruins and toward the mountain slopes. The Grove of the Ancients shelters an old refuge of nature, apart from the decay along the shore. Onu waits among stone barrows and kindred spirits. He is ready to guide allies toward the blights stirring at the edge of the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_948-7decc12f84a8e053fdf7/1-0000.mp3", duration = 56.9469388, start = 0},
  },
}
P.transport["quest:949"] = {
  hash = "427e88",
  fullHash = "427e88",
  text = "The Twilight Camp. At the Master's Glaive in southern Darkshore, cultists gather while Alliance scouts seek their purpose. A scrying bowl has revealed their ritual site. Now you enter the excavation to learn what the Twilight's Hammer seeks beneath the earth. The Twilight's Hammer has made the Master's Glaive a threat. A scrying bowl revealed the cultists' fortifications. You enter their camp to learn their designs before the Alliance can prepare its defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_949-c1780f3fea458dd8f10f/1-0000.mp3", duration = 26.9583673, start = 0},
  },
}
P.transport["quest:950"] = {
  hash = "2e035f",
  fullHash = "2e035f",
  text = "Return to Onu. You bring a torn page from the Twilight Tome to Onu in Darkshore. The cultists' writing is all you could bear to take from their book. The Twilight Tome overwhelms anyone who tries to read it. Its words swim across the page, and its ornate scrollwork twists into grotesque figures. You tear out a page of scribbles before the strain brings on vertigo.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_950-35a4ea6c48b39db591e8/1-0000.mp3", duration = 21.3942857, start = 0},
  },
}
P.transport["quest:95041"] = {
  hash = "e13a5c",
  fullHash = "e13a5c",
  text = "Data Hoarders. Outside Gnomeregan, Jemma Quikswitch searches the snow for lost punch cards. The exiled gnome lives in Ironforge, and the cards hold her family's archives, from submarine designs to family recipes. Without them, the records she still has remain unreadable. When troggs invaded Gnomeregan and radiation struck, thousands of gnomes fled with what they could carry. A damaged satchel spilled several of Jemma's cards into the snow around the fallen city. Without them, her surviving records read as gibberish, and her family's knowledge risks being lost. The Quikswitch archives hold arcanotechnical field equations and submarine hull blueprints from the Second War. They also preserve Grandma Quikswitch's secret chili recipe. For refugees in Ironforge, the comforts of home matter as much as engineering marvels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95041-ceb845cab97181cbb7f4/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:95065"] = {
  hash = "8a0323",
  fullHash = "8a0323",
  text = "Fishin' Time. At Stormwind harbor, Gilbert Gray keeps to his fishing line while the fish are biting. His supplies run low, so he asks passersby to fetch nightcrawlers and a shiny bauble from a shop along the city canals. Gilbert Gray watches his bobber dance on the water. The elderly angler will not leave his prized perch while the fish are biting. His supplies have run out, and he needs help so he can stay at his line instead of returning to the city. Catherine Leland runs a tackle shop beside Stormwind's stone canals, just west of the Trade District. Fishermen across the city come to her for lures and bait. Her shop can replenish what Gilbert Gray needs to keep fishing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95065-d405eecd42b65839e154/1-0000.mp3", duration = 41.8742857, start = 0},
  },
}
P.transport["quest:952"] = {
  hash = "03055e",
  fullHash = "03055e",
  text = "Grove of the Ancients. An urgent dispatch takes you from Darnassus to Darkshore, where Onu waits in the Grove of the Ancients. Arch Druid Fandral Staghelm sends you across the sea with a message for the Ancient of Lore, who lives south of Auberdine. After you help at the Oracle Glade atop Teldrassil, Arch Druid Fandral Staghelm calls you to another duty. He sends you across the sea to Darkshore with an urgent dispatch for Onu. From Darnassus, you can take a hippogryph flight. South of Auberdine, you reach the Grove of the Ancients and deliver the message to Onu. The towering Ancient of Lore accepts it quietly and remarks on Staghelm's impatience. Onu and the forest's ancient keepers believe all things unfold in their proper time. Shan'do Malfurion Stormrage embodied that patient wisdom, while Staghelm lacks it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_952-97b83a1dd71820f683d8/1-0000.mp3", duration = 52.1142857, start = 0},
  },
}
P.transport["quest:953"] = {
  hash = "43271e",
  fullHash = "43271e",
  text = "The Fall of Ameth'Aran. At Ameth'Aran in Darkshore, you search the ruins and read their ancient stone tablets for Sentinel Tysha Moonblade. Their words tell how the Highborne city fell in the Sundering, preserving history largely lost in the War of the Ancients for the Circle of Ancients in Auberdine. Ameth'Aran was home to Queen Azshara's elite sorcerers, who wielded powerful arcane magic. When the Well of Eternity was destroyed ten thousand years ago, the city fell to broken marble and cracked pillars. The Highborne who died there still haunt the ruins as restless, anguished spirits. Few written accounts survived the Great Sundering intact. The War of the Ancients drove night elves into a struggle for survival, and much of their history was lost. Sentinel Tysha Moonblade surveyed Ameth'Aran and found two large engraved tablets, the Lay of Ameth'Aran and the Fall of Ameth'Aran.\n\nGhostly Highborne specters drove Tysha from the ruins. Their readings can carry the disaster's history to the scholars of the Circle of Ancients in Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_953-541ad120edd30c245c0f/1-0000.mp3", duration = 66.1159184, start = 0},
  },
}
P.transport["quest:95314"] = {
  hash = "be76bf",
  fullHash = "be76bf",
  text = "That Shadowvale Green Elixir. In Brill, That Shadowvale Green Elixir draws buyers despite the old ban. Shadowvale's secluded villagers once brewed Whispering Elixir from local herbs, and the Scourge left the village in ruins. Before the Scourge came, Shadowvale's villagers brewed Whispering Elixir from rare herbs found only in Tirisfal Glades. The draught grew known across northern Lordaeron. The Capital City outlawed it, yet mystics, poisoners, and apothecaries still sought its unusual properties, defying royal decrees. Shadowvale lies deep in the Whispering Forest of western Tirisfal. Its people were insular and distrustful, and rarely welcomed outsiders. The Scourge invasion left the settlement in ruins, though forgotten stores of aged green elixir remain among the wreckage.\n\nCarolai Anise works from Brill. The underworld still wants the brew, so she pays adventurers willing to brave the forest's unsettling silence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95314-d4c75701fefa9d953605/1-0000.mp3", duration = 61.3877551, start = 0},
  },
}
P.transport["quest:954"] = {
  hash = "2ee21d",
  fullHash = "2ee21d",
  text = "Bashal'Aran. An eerie blue aura burns above a shrine in Bashal'Aran, where satyrs and grells will not go. Thundris Windweaver, Auberdine's elder, asks you to find its source. Bashal'Aran once flourished under the ancient Kaldorei Empire. Now demonic taint fills its broken marble halls and overgrown arches. Twisted satyrs and corrupt grells feed on the ruins' lingering magic, growing more malicious by the day. Yet Thundris Windweaver in Auberdine has noticed a mystery: atop a western bluff, a blue aura shines above a shrine that no demon will approach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_954-875a7f1ad26337067050/1-0000.mp3", duration = 37.4334694, start = 0},
  },
}
P.transport["quest:955"] = {
  hash = "ea1404",
  fullHash = "ea1404",
  text = "Bashal'Aran. Magic still binds Asterion beneath Bashal'Aran's broken stones. The ancient night elf seeks release from his ghostly form and suspects the grells have touched the seal that holds him. He asks travelers to gather their earrings and trace its lingering magic. For centuries, Asterion has waited among Bashal'Aran's shattered marble. The ancient night elf spirit remains caught between life and true death beneath Darkshore's canopy. Arcane craft binds him to the ruined settlement, and he cannot break free alone. Solitude and despair have worn down his mind. Asterion believes an ancient seal hidden in the ruins may hold the key to his release. He cannot search the brush and fallen stones himself. The feral grells of Bashal'Aran forage there and steal small baubles, so he asks travelers to gather their earrings. He hopes the trinkets' lingering magic will lead him to the seal that torments his soul.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_955-4018e785d89fd36e3e97/1-0000.mp3", duration = 56.2155102, start = 0},
  },
}
P.transport["quest:956"] = {
  hash = "b6d7d4",
  fullHash = "b6d7d4",
  text = "Bashal'Aran. Among the ruined pillars of Bashal'Aran, Asterion seeks release from his prison. He has traced the binding magic to the satyrs who command the grells. Now he asks travelers to recover the Ancient Moonstone Seal. For more than a thousand years, Asterion has been bound within the ruins of Bashal'Aran. The marble pillars mark the bounds of his prison. His strength and ancient magic cannot carry him beyond them. A cursed relic holds him there.\n\nThrough the centuries, Asterion has watched Darkshore's canopy. He wonders if the worn stone around him might ever set him free. Nearby grells bore traces of the magic binding Asterion. From them, he reasoned that the Ancient Moonstone Seal was the enchantment's source. The satyrs who command the grells hold the seal now. These demonic night elves roam the ancient groves and keep watch over the relic. Asterion needs travelers to recover the seal so its binding power can be broken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_956-91c2a38b207cc48cf0ed/1-0000.mp3", duration = 62.3020408, start = 0},
  },
}
P.transport["quest:957"] = {
  hash = "8d0082",
  fullHash = "8d0082",
  text = "Bashal'Aran. At Bashal'Aran, Asterion's spirit remains bound by an ancient seal. You carry the seal south to Ameth'Aran, where an old flame may break his bonds. The Ancient Moonstone Seal was forged by Highborne sorcerers before the Great Sundering, and no ordinary strength can break its power. Bashal'Aran and Ameth'Aran were sister settlements of the kaldorei under Queen Azshara, when the Well of Eternity anchored their empire. Now both are overgrown, haunted ruins, where ghosts linger and arcane power remains volatile. At Ameth'Aran, a mystical brazier burns with cyan fire in a stone gazebo; that is the sole flame able to consume the Ancient Moonstone Seal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_957-06855e2a7af05a75211e/1-0000.mp3", duration = 45.5053061, start = 0},
  },
}
P.transport["quest:959"] = {
  hash = "d57e05",
  fullHash = "d57e05",
  text = "Trouble at the Docks. In Ratchet, a stolen bottle puts Bigglefuzz's job at risk. Mad Magglish fled inland with a 99-Year-Old Port, a gift from Baron Revilgaz to Gazlowe, and now hides in the Wailing Caverns. Ratchet's docks carry sea trade with Booty Bay across the Great Sea. One morning, a huge shipment arrived, and Crane Operator Bigglefuzz overloaded his crane to unload it faster. The crane dropped the whole load across the docks. In the confusion, Mad Magglish, a local nuisance, snatched a valuable bottle of liquor and fled inland. The bottle is a 99-Year-Old Port, a personal diplomatic gift from Baron Revilgaz, Booty Bay's ruler, to Gazlowe, Ratchet's chief engineer and overseer. Its loss could humiliate Bigglefuzz and anger both trade leaders. Fearing for his job or worse, Bigglefuzz followed the thief to the mouth of the Wailing Caverns. But fear stopped him from going inside. Mad Magglish hides in damp natural tunnels outside the Wailing Caverns' inner gateway, not deep in the corrupted dreamscape. The thief relies on clumsy stealth and dark alcoves, hoping pursuers will give up. Find Magglish in the outer caverns before the port is uncorked or destroyed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_959-c3b453ddd2bdee4e465c/1-0000.mp3", duration = 78.3934694, start = 0},
  },
}
P.transport["quest:960"] = {
  hash = "88c5c8",
  fullHash = "88c5c8",
  text = "Onu is meditating. At the Master's Glaive in southern Darkshore, Onu enters a deep trance as a threat grows. The ancient of lore weighs the alliance and motives of the Twilight's Hammer cult and the naga. If you lose your scrying phial, speak to him for another. In the Grove of the Ancients, Onu holds Kalimdor's history in his ancient memory. Ominous reports of dark excavations at the Master's Glaive draw his vast consciousness inward. He considers what brings the fanatical Twilight's Hammer cultists and the naga to the petrified remains of an ancient behemoth. As you carry out his reconnaissance, Onu remains within reach and can replace a scrying phial misplaced in the wild. Onu uses nature-attuned divination to watch the ruins without risking his physical presence. He entrusts you with a scrying phial, which conjures a scrying bowl at the excavation site and lets him commune from afar. The journey south through Darkshore is perilous, with hostile wildlife and cultist patrols, so mishaps can happen.\n\nOnu's trance is an attentive vigil, not unbroken slumber. He readily offers another vial of sacred waters so you can continue the investigation of the Master's Glaive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_960-a636f0e9c0f0f8ed117d/1-0000.mp3", duration = 77.1395918, start = 0},
  },
}
P.transport["quest:96047"] = {
  hash = "0e2ed3",
  fullHash = "0e2ed3",
  text = "Camping 101: First Aid. In Kharanos, Thamner Pol teaches you to prepare First Aid Kits for camps in Dun Morogh. With these supplies, travelers can stay alive in the field. You can build on your basic bandaging skills by learning to prepare supplies for a resting site. Thamner Pol shows you how raw medical supplies become complete kits, ready for use at camp when travelers need care far from shelter. Thamner Pol teaches you practical ways to outfit expedition sites with emergency supplies. A proper field kit lets a group bind wounds and regain strength together by the hearth before heading back into the cold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96047-7abcc4ff9c0d2e191011/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["quest:96139"] = {
  hash = "077908",
  fullHash = "077908",
  text = "The Valor Family. In Darkshire, Sirra Von'Indi seeks records of Raven Hill's lost people. The village remembers their courage, but her library holds little of Raven Hill's history. Sirra Von'Indi says brave people helped Darkshire endure. Lady Althea was among them, as were those who died at Raven Hill. You are asked to search for anything that might preserve their memory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96139-6f3531cb9b0374c7928f/1-0000.mp3", duration = 22.7526531, start = 0},
  },
}
P.transport["quest:962"] = {
  hash = "5a06a0",
  fullHash = "5a06a0",
  text = "Serpentbloom. Deep in the Wailing Caverns, Serpentbloom draws Apothecary Zamah’s attention. She seeks more specimens for the Royal Apothecary Society’s research and the Forsaken. Apothecary Zamah watches the Pools of Vision beneath Thunder Bluff’s Spirit Rise. She came from the Undercity as an envoy of the Royal Apothecary Society. Her tauren hosts tend to spiritual balance and the wounded land, while Zamah studies rare and virulent materials. She has isolated a sample of Serpentbloom and seeks more for Lady Sylvanas Windrunner and the Forsaken’s research. Serpentbloom grows in the damp, twisting grottos of the Wailing Caverns, far from the Barrens’ open sun. The corrupted druids of the Fang have twisted these humid depths, where serpentine denizens guard the plant. Many scouts sent by Zamah failed to return. Now she seeks hardy adventurers to gather more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_962-5b7048202da07a0cd4ed/1-0000.mp3", duration = 56.9730612, start = 0},
  },
}
P.transport["quest:963"] = {
  hash = "1fb053",
  fullHash = "1fb053",
  text = "For Love Eternal. In Auberdine, Cerellean Whiteclaw asks you to ease Anaya Dawnrunner's torment in Ameth'Aran. His grief has lasted since the city fell. Ten thousand years ago, the War of the Ancients tore Kalimdor apart around the Well of Eternity. Ameth'Aran fell, and Anaya Dawnrunner was lost to Cerellean Whiteclaw. Grief-stricken, Cerellean joined Shan'do Malfurion Stormrage in the druids' long hibernation. He hoped the ages spent walking the Emerald Dream would quiet his heart, but his sorrow endured. When he awoke, Cerellean wandered Darkshore in a stupor. At last he came to the melancholy ruins of Ameth'Aran, where he saw Anaya's tortured ghost. He cannot raise a weapon against the woman he loved. So he asks passing travelers to destroy her tormented form, retrieve her pendant, and bring peace to her troubled soul.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_963-aa9a158bb0448c371ebb/1-0000.mp3", duration = 55.3534694, start = 0},
  },
}
P.transport["quest:96390"] = {
  hash = "62d45d",
  fullHash = "62d45d",
  text = "Nip 'Em in the Bud. Dark Iron spies move through Dun Morogh, and Earthseer Farsen calls for help. Near Ironband's Compound, their presence threatens the Bronzebeard homeland. Dark Iron spies have crossed Dun Morogh's high passes and snowy crags. They hide near settlements and excavations, where even a few watchers may signal a strike. Earthseer Farsen sees the danger and calls on Alliance defenders to find them before their plans advance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96390-5856501c11324404bbd2/1-0000.mp3", duration = 28.6302041, start = 0},
  },
}
P.transport["quest:96391"] = {
  hash = "d218fc",
  fullHash = "d218fc",
  text = "Underground Map. Near Ironband's Compound, the Underground Map points toward chambers beneath Ironforge. Recovered from Dark Iron spies, its runes trace a hidden route piercing toward ancient halls beneath the mountain. You bring it to Earthseer Farsen to begin learning what lies below. You find the parchment near Ironband's Compound after dealing with Dark Iron spies. Its diagrams lay out an intricate maze of roads beneath the earth. Harsh, jagged runes mark passages that run deep underground and converge beneath Ironforge. Their course suggests a possible threat beneath the Bronzebeard capital, though the Dark Iron notes remain uncertain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96391-bfca91deda07b3f32dc2/1-0000.mp3", duration = 39.5493878, start = 0},
  },
}
P.transport["quest:96392"] = {
  hash = "a66264",
  fullHash = "a66264",
  text = "Farsen's Watch. Near Gol'Bolar Quarry, Earthseer Farsen watches for Dark Iron movement close to Ironforge. The Wildhammer shaman lends you his farsight, revealing a threat that calls for swift action. From his post above Gol'Bolar Quarry, Farsen watches the lower reaches of Dun Morogh. He came south from the crags of Aerie Peak, bringing a Wildhammer's spiritual awareness with him. His clan's old arts let him sense tremors underground and watch for sudden movement along the hillsides. Farsen lends you his farsight, a shamanic gift that carries sight across great distances. Through it, you see danger beyond troggs and wild beasts. Dark Iron dwarves have drawn close to Ironforge's industrial center and are digging in. Their foothold must be confronted before it takes root.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96392-d005f21fe0a9ff6e5d65/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["quest:96393"] = {
  hash = "3beda8",
  fullHash = "3beda8",
  text = "Old Ironforge Incursion. Beneath Ironforge, Earthseer Farsen sends you to the Hall of Thanes for the last part of the investigation. There, you face the Dark Iron threat and report to King Magni Bronzebeard. The underground map reveals Dark Iron movements, and Earthseer Farsen identifies the mastermind behind the intrusion. The entrance to the Hall of Thanes lies deep within Old Ironforge's ancient stone halls. While the upper city tends to matters on the surface, Dark Iron forces slip into caverns that lie dormant beneath the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96393-a8cb00d138642c1f2be3/1-0000.mp3", duration = 33.7240816, start = 0},
  },
}
P.transport["quest:96395"] = {
  hash = "056699",
  fullHash = "056699",
  text = "An Ancient Grudge. Within the Hall of Thanes, Faldrim Anvilmar's spirit remains troubled by an old grievance. His ghostly attendant asks travelers to bring him peace. A ghostly attendant remains in the Hall of Thanes, where Faldrim Anvilmar once ruled. The spirit can barely speak across the veil between the living and the dead. It asks you to quiet its master's restless spirit. It seeks peace for him, not freedom for itself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96395-24aa793b340f7149b883/1-0000.mp3", duration = 26.9322449, start = 0},
  },
}
P.transport["quest:96408"] = {
  hash = "dd2fa6",
  fullHash = "dd2fa6",
  text = "A Visitor to Dun Morogh. Beldin Steelgrill sends you to learn who has lit a fire above Gol'Bolar Quarry. The camp overlooks the excavation, and the dwarves fear its visitor may mean them harm. High on the snowy ridges east of Kharanos, a stranger's campfire burns above the quarry. The unfamiliar fire has worried the folk of Kharanos. There, the Mountaineers watch the heights for danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96408-e01d1158d1f5e8d47ca9/1-0000.mp3", duration = 23.797551, start = 0},
  },
}
P.transport["quest:965"] = {
  hash = "75988e",
  fullHash = "75988e",
  text = "The Tower of Althalaxx. North of Auberdine, Sentinel Elissa Starbreeze fears trouble at an ancient ruin. She sent Balthule Shadowstrike to watch the Tower of Althalaxx, but his report has not come. Sentinel Elissa Starbreeze keeps watch for danger around Auberdine. Suspicious activity near the Tower of Althalaxx in northern Darkshore caught her attention, so she sent Balthule Shadowstrike to watch the ancient ruin. Days have passed without word. Elissa asks you to travel north, find Balthule, and make sure he has not met an untimely end.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_965-1913623114269fdd76f6/1-0000.mp3", duration = 33.515102, start = 0},
  },
}
P.transport["quest:966"] = {
  hash = "99d69d",
  fullHash = "99d69d",
  text = "The Tower of Althalaxx. Warlocks gather at the Tower of Althalaxx in northern Darkshore, drawing Balthule Shadowstrike's watchful eye. He asks travelers to recover scraps of parchment from the fanatics camped outside the ruins, hoping to learn who they are and what they seek. Balthule Shadowstrike watches the misty shore of northern Darkshore and keeps the ancient Tower of Althalaxx in sight. Auberdine sent him to watch the ruin and warn Delgren the Purifier if danger grows. Yet leaving his post to report might let the dark spellcasters among the stones slip from view. So Balthule asks passing travelers to scout the camps around the tower.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_966-2fc3295a007ec9e164f2/1-0000.mp3", duration = 38.2955102, start = 0},
  },
}
P.transport["quest:96607"] = {
  hash = "83be2d",
  fullHash = "83be2d",
  text = "The Great Outdoors. Beyond city walls, The Great Outdoors teaches you to meet the wild with care. Seasoned travelers begin with a campfire and the habits that make each journey safer. A sharp blade or potent magic will not save you if you neglect the basics. Near roadside clearings, seasoned wanderers teach travelers leaving their home valleys to rest by a campfire. Its warmth eases sore boots, settles the mind, and prepares you for the harsh road ahead. Rest and preparation improve your chance of surviving long enough to find fortune and glory. Your instructors also send you to town tradesfolk, because a field camp needs more than an ember and a bedroll. You can forge replacement rivets, cook trail rations, or stitch torn gear beneath the stars. Each profession offers camp fixtures that help turn a bare hillside into a self-sufficient outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96607-2c8377485568eddb51ba/1-0000.mp3", duration = 52.1926531, start = 0},
  },
}
P.transport["quest:96627"] = {
  hash = "643bc6",
  fullHash = "643bc6",
  text = "The Adventurer. From Northshire Valley, Marshal McBride sends you toward Goldshire to find Sam Sarsaparilla. You have proved your skill defending the abbey, and now he wants you to look into a newcomer. With the Defias and vermin threats easing, McBride turns his attention to the road beyond the valley. His garrison needs promising fighters to watch travelers and wanderers in the surrounding woods. Marshal McBride asks you to check on Sam Sarsaparilla, who was spotted near Goldshire. This is neither a military order nor a hunt for a bounty. The newcomer draws you from Northshire’s secluded valley into Elwynn’s wider wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96627-b0a11807292b5c87b977/1-0000.mp3", duration = 38.0342857, start = 0},
  },
}
P.transport["quest:96628"] = {
  hash = "0c55ad",
  fullHash = "0c55ad",
  text = "The Adventurer. At Dun Morogh’s southern gate, The Adventurer carries supplies toward Kharanos. Mountaineer Thalos asks travelers to bring provisions to Eric Brighthammer, a newcomer camped just outside the village. Mountaineer Thalos keeps watch at Dun Morogh’s southern gate, where the trail leaves Coldridge Valley. Guarding the high passes and tunnels keeps the Mountaineers busy. Thalos also watches for dangers and travelers on the road. When a lone adventurer arrives near Kharanos, he asks trusted passersby to carry supplies onward. The bundle is meant to help newcomers venturing into the frozen crags. The road from the southern pass winds down to Kharanos, a center of dwarven craft and travel in central Dun Morogh. Eric Brighthammer has recently made camp just outside the village. Carrying the Mountaineers’ provisions to him links the sentries on the ridge with those walking the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96628-ff907c4e3b7c7a3df41b/1-0000.mp3", duration = 53.002449, start = 0},
  },
}
P.transport["quest:96630"] = {
  hash = "f64e2a",
  fullHash = "f64e2a",
  text = "The Adventurer. In Teldrassil, you find a lost journal meant for Lyreena Duskblade near Dolanaar. Its pages follow an unknown traveler's quiet journeys and camping outings. Among Teldrassil's boughs and roots, you find a journal left behind. Its nameless writer tells of modest wanderings and the simple pleasure of camping beneath the twilight canopy. You can carry the journal toward Dolanaar instead of leaving it in the wilderness. Lyreena Duskblade waits near the night elf settlement to receive its lost pages.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96630-2de5fd2ecb343d2e9da3/1-0000.mp3", duration = 31.8693878, start = 0},
  },
}
P.transport["quest:96638"] = {
  hash = "ab8316",
  fullHash = "ab8316",
  text = "The Adventurer. On Zephras Isle, The Adventurer leaves Thendal Grove for the road to Shen'dar Village. Aetheen of the Gales sends newly seasoned wanderers southwest to meet Raan Wildwind, a veteran camper who knows the wilds. Thendal Grove offers shelter, but Zephras Isle beyond it remains wild and perilous. Aetheen of the Gales watches over the initiates and knows when a traveler is ready to leave familiar ground. Those seeking fame, fortune or purpose have outgrown the grove's sheltered bounds. Raan Wildwind has made camp southwest of Thendal Grove, along the road to Shen'dar Village. He has spent time facing the dangers beyond the safe haven. For wanderers setting out from the grove, Raan offers practical counsel on surviving the open roads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96638-b0a185870b3002b459fe/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:96652"] = {
  hash = "96fd2c",
  fullHash = "96fd2c",
  text = "The Adventurer. On Durotar’s red wastes, The Adventurer finds a lost journal meant for Brakk near Razor Hill. Its pages remember quiet travels and nights beneath the stars. A lost journal lies in Durotar’s red dirt, far from the battles and campaigns that mark the land. An unknown traveler fills its pages with daily journeys and the pleasure of making camp beneath the open sky. The journal offers a quiet glimpse of life on the road through harsh country. The journal is meant for Brakk, an adventurer camped near Razor Hill. Its pages link an unknown traveler to someone watching the dusty roads. Carrying it to Brakk may keep the writer’s travels remembered.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96652-74bc663552982dfeae58/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["quest:96656"] = {
  hash = "90611b",
  fullHash = "90611b",
  text = "The Adventurer. Near Deathknell, The Adventurer is sent to investigate a stranger on the road to Brill. Scarlet Crusaders threaten the region, but the stranger is Eleanor Shackleton, a Forsaken traveler who can teach wilderness skills. Executor Arren watches Deathknell and the roads around it. Scarlet Crusaders spy on the region and infiltrate northern Lordaeron, so an unfamiliar figure near Brill draws his suspicion. You have proved your dedication by striking at Crusader threats along the border. Now Arren asks you to investigate the stranger quietly and learn whether she threatens the Forsaken. By the roadside near Brill, you find Eleanor Shackleton. She is a Forsaken traveler, pausing before another journey into the wilds. She has no Crusader plot or Scourge necromancy in mind. Seeing a fellow adventurer in those sent to check on her, Eleanor offers to teach you how to survive in open country and make camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96656-a40458bbb683564558ef/1-0000.mp3", duration = 57.4171429, start = 0},
  },
}
P.transport["quest:96658"] = {
  hash = "160584",
  fullHash = "160584",
  text = "Camping 101: Cooking. As you learn to cook, a basic campfire gives you a hearth for camping beyond fortified walls. Across Alliance and Horde lands, cooking trainers show new adventurers how to kindle one and prepare for life in the wild. Beyond fortified walls, a campfire boils water and roasts meat. Its flames give you a hearth when you travel through unfamiliar country and make camp. Apprentice cooks kindle small fires with few surroundings. As your cooking grows, you can light larger fires for more elaborate campsites. Other practical trades teach you to make useful furnishings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96658-7c1a1acd85e8c8db778a/1-0000.mp3", duration = 37.6685714, start = 0},
  },
}
P.transport["quest:96659"] = {
  hash = "b5bc5c",
  fullHash = "b5bc5c",
  text = "The Adventurer. From Red Cloud Mesa, Chief Hawkwind sends young travelers with supplies for Kaga Wildhoof near Bloodhoof Village. She aided him long ago, and he means to repay her kindness. Chief Hawkwind asks you to carry provisions to Kaga Wildhoof near Bloodhoof Village. Long ago, she helped him when he was in need, and he remembers her kindness. Now she has made camp outside the village. So Hawkwind entrusts young travelers leaving the mesa with supplies for his old benefactor. The trail runs from Red Cloud Mesa toward Bloodhoof Village, across the plains of Mulgore. With Hawkwind's bundle, you travel beyond Camp Narache, where young tauren have trained. The path leads into the wider lands of the United Tauren Tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96659-22bdde2b45d7981e8ce5/1-0000.mp3", duration = 46.1583673, start = 0},
  },
}
P.transport["quest:967"] = {
  hash = "073102",
  fullHash = "073102",
  text = "The Tower of Althalaxx. At the Tower of Althalaxx, Dark Strand cultists gather, and Balthule Shadowstrike needs help. He sends a warning with an Alliance courier to Maestra's Post in Ashenvale for his mentor, Delgren the Purifier. Balthule Shadowstrike sees that one scout cannot face the Dark Strand threat alone. After clashing with cultists near the Tower of Althalaxx, he writes a report for his master, Delgren the Purifier, and gives it to an Alliance messenger. The cult's summoners grow bolder. Balthule needs seasoned leaders to direct a response. Balthule's dispatch sends you south along Darkshore's coastal road, then across the wooded border into Ashenvale. Delgren the Purifier is stationed at Maestra's Post beside the western road. The human paladin works to cleanse demons and undead from the woodland. Night elven customs once seemed strange to him, but he has earned the Sentinels' deep respect as an indispensable ally.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_967-6e915bb583ea9852fbe3/1-0000.mp3", duration = 59.5853061, start = 0},
  },
}
P.transport["quest:968"] = {
  hash = "a8d99b",
  fullHash = "a8d99b",
  text = "Tools of the Highborne. Thundris Windweaver sends you from Auberdine to Ameth'Aran. Highborne spirits still haunt the ruins with enchanted relics in their hands, and he wants them taken away. Ameth'Aran lies south of Auberdine and east of the coastal highway. Its stone foundations are overgrown. Ten thousand years ago, it was a stronghold of the Highborne, the privileged aristocracy of the ancient night elven empire.\n\nTheir unchecked arcane magic helped bring about the Sundering, which shattered the settlement. Yet its inhabitants never truly left. Sentinels patrolling Darkshore report Highborne ghosts in the sunken plazas, still clutching the enchanted tools and trinkets they held in life. For the kaldorei, arcane magic recalls a danger that nearly destroyed life on Azeroth. Thundris Windweaver fears that the Highborne implements could invite corruption if they remain in ghostly hands. So he sends you to wrest the relics from the restless spirits. He intends to have them destroyed before their tainted magic can fuel another disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_968-6282e0c30598f3cce5f7/1-0000.mp3", duration = 63.8171429, start = 0},
  },
}
P.transport["quest:97279"] = {
  hash = "dc4cfe",
  fullHash = "dc4cfe",
  text = "Wayward Weapons. At the Valley of Trials, Gornek sends fresh arrivals to recover weapons for the encampment. Young warriors keep coming to serve the Horde, and Kzan Thornslash needs old arms returned to use. Young recruits face harsh trials in Durotar's red wastes. Many arrive ready to pledge their blades to the warchief, leaving the encampment short of weapons. Weaponsmith Kzan Thornslash struggles to meet demand. Early lessons can end in death or humiliation for those unready. Overseer Gornek turns the shortage into a practical trial. He sends fresh arrivals to recover abandoned blades and blunt training weapons left by recruits who fell or fled. Kzan can repair and temper the recovered arms for the next wave. The recruits learn that survival in the Horde calls for scavenging as well as swinging steel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97279-0b86f65ddb4ec7f76ff3/1-0000.mp3", duration = 51.3306122, start = 0},
  },
}
P.transport["quest:97558"] = {
  hash = "691c94",
  fullHash = "691c94",
  text = "Hides for the Forsaken. In Tirisfal, the Forsaken gather hides to keep their bodies intact. Shelene Rhobart asks you to bring darkhound hides, duskbat wing membranes, and murloc skin. Forsaken flesh cannot mend itself. When they are wounded, the gap rots and stays open. So they stitch living tissue over their injuries to hold their forms together and keep their corpses working. Each kind of material mends a different part of the body. Thick darkhound hide holds firm over broad wounds. Duskbat wing membranes are thin and pliable, so they cover faces and fingers without stiffening them. Vile Fin murloc skin lines inner membranes and sensitive places such as cheeks and mouths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97558-e16acf8253c0416c44f2/1-0000.mp3", duration = 44.0685714, start = 0},
  },
}
P.transport["quest:97894"] = {
  hash = "664384",
  fullHash = "664384",
  text = "Business in Auberdine. In Stormwind, Borgus Steelhand waits for news of his brother Gorbold in Auberdine. You can reach Gorbold by sailing west from Stormwind Harbor to northern Kalimdor. Gorbold crossed the Great Sea to keep a merchant stall in auberdine. He hoped to profit by supplying ships that call at Darkshore. Weeks have passed without word, and Borgus worries for his brother so far from Ironforge and Stormwind. The passage to Kalimdor once led through Menethil Harbor or neutral goblin ports such as Booty Bay. Borgus sends you to the vessel at stormwind harbor's southern-most dock. Its direct sailing ends at Auberdine's long wooden piers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97894-3b9c828598fc4f7bc291/1-0000.mp3", duration = 40.437551, start = 0},
  },
}
P.transport["quest:97914"] = {
  hash = "5f7c45",
  fullHash = "5f7c45",
  text = "Expanding Horizons. Thundris Windweaver sends word from Auberdine to Stormwind. He wants the settlement's work and its home known beyond Darkshore. Auberdine's sea passage now joins Darkshore directly to Stormwind. Its leaders want the shipping route kept safe and the coastal settlement linked to the wider Alliance. Nearby, the ruined cities of Ameth'Aran and Bashal'Aran have long drawn more notice than Auberdine and its living people. Baros Alexston oversees Stormwind's construction and infrastructure. His duties include public works and logistics. Thundris Windweaver's letter crosses the Great Sea to the official charged with the human capital's building needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97914-f81d591118257cb345c7/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["quest:97919"] = {
  hash = "8f857f",
  fullHash = "8f857f",
  text = "Camping 101: First Aid. At the Lion's Pride Inn, Michelle Belle shows you how to prepare First Aid Kits for camping. You need enough First Aid skill to learn how to ready these supplies for the road ahead. Travel through Elwynn can leave you wounded, far from a town healer or inn. First Aid lets you tend your own injuries without relying on anyone else. Bandages help with bleeding and trauma, without arcane rites or holy prayers. At Goldshire's Lion's Pride Inn, Michelle Belle teaches skilled practitioners to assemble First Aid Kits. Keep medical supplies at camp so a weary party can treat injuries and regain strength before facing the dangers ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97919-894ecf4351376bbe5d8c/1-0000.mp3", duration = 41.1689796, start = 0},
  },
}
P.transport["quest:97920"] = {
  hash = "536961",
  fullHash = "536961",
  text = "Camping 101: Fishing. Lee Brown teaches novice anglers near Goldshire how to use their fishing skill around camp. With simple catches and basic materials, they can make useful additions for a campsite. Fishing can feed you on the road and add comfort to camp. A fish bowl lifts the spirits of weary travelers between excursions. A sound mind and high spirits help make formidable fighters. Lee Brown waits beside the waters outside Goldshire for fishermen ready to broaden their craft. Show him your skill with rod and line, and he can teach you to make useful additions for camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97920-13e7533147118b79a69d/1-0000.mp3", duration = 36.3885714, start = 0},
  },
}
P.transport["quest:97926"] = {
  hash = "f7a1f0",
  fullHash = "f7a1f0",
  text = "Making Do. Auberdine waits for word from Stormwind, but no aid is coming. Making Do carries Alexston's Reply across the sea to Elder Thundris Windweaver. You carry Alexston's Reply across the sea to Elder Thundris Windweaver in Auberdine. The letter brings no troops or relief. Stormwind's representative explains that the kingdom's treasury is nearly empty. What wealth remains must stretch across its own struggling territories.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97926-b7ccc8d27981f6360168/1-0000.mp3", duration = 27.0889796, start = 0},
  },
}
P.transport["quest:97957"] = {
  hash = "1e97c7",
  fullHash = "1e97c7",
  text = "Camping 101: Herbalism. In Tirisfal, Eleanor Shackleton sends new herbalists to Faruza in Brill to learn a useful craft. Incense Candles help spellcasters rest at camps in the wild. Herbalism gives alchemists their first materials. Travelers also rely on gathered roots and blossoms. Across the regions, master herbalists teach foragers to prepare Incense Candles. In Tirisfal Glades, Eleanor Shackleton sends promising foragers to Faruza in Brill once they show basic skill. Long journeys wear on spellcasters and spiritualists. Incense Candles release restorative fragrances that lift spirits and soothe tired minds. Gatherers infuse dried plants into the candles, helping healers and mages whose magical reserves falter on the road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97957-fd072ec77aece1d5e88e/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["quest:97960"] = {
  hash = "5474aa",
  fullHash = "5474aa",
  text = "Camping 101: Skinning. In Tirisfal Glades, Camping 101: Skinning sends new skinners to learn a useful craft. They learn to make a camp chair from harvested hides and where to find teachers across Azeroth. A sharp blade alone will not carry you through the wilds. You also need a way to rest between trials. In the field, skinners can learn the basics and use treated skins to make a chair for camp. It gives weary travelers a place to recover before danger calls again. Young Forsaken skinners in Tirisfal Glades are sent to Rand Rhobart once they reach their first measure of skill. He works along the road between Brill and the Capital ruins of the Undercity. Rhobart teaches practical ways to turn rough leather into a seat for camp. Skinning masters across the lands of the Horde and Alliance teach the same craft.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97960-53fd4da3d4ab85857a14/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["quest:982"] = {
  hash = "619300",
  fullHash = "619300",
  text = "Deep Ocean, Vast Sea. North of Auberdine, two night elf vessels lie beneath the waves. Murlocs ambushed the Silver Dawning and Mist Veil as they sailed into port, and the surviving crews seek a way to mourn their lost captains. Murlocs overwhelmed the Silver Dawning and Mist Veil as they neared Auberdine. Both ships sank in the shallows north of the settlement. Their surviving crews reached shore, but the loss of the vessels and their captains still weighs on the port. Gorbold Steelhand, a dwarf in Auberdine, seeks to honor the fallen night elf captains. Murlocs now occupy the underwater wrecks, though the captains' lockboxes remain in the flooded holds. Their logs and personal effects could help the surviving sailors mourn their commanders and lay their spirits to rest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_982-8331a4c3be7a9a2d0328/1-0000.mp3", duration = 48.4310204, start = 0},
  },
}
P.transport["quest:98219"] = {
  hash = "59b6ed",
  fullHash = "59b6ed",
  text = "The Shamed Lieutenant. A Stormwind guard asks you to check on Lieutenant Farren Orinelle in Southshore. His reassignment is meant to teach him a lesson, but the guard hopes he can still succeed. You've safely delivered the statuette. Now your contact asks you to speak with Lieutenant Farren Orinelle, a city guard sent to Southshore in Hillsbrad Foothills. Farren's father was a friend of the guard, who believes he could benefit from help. If you are passing through, a boat bound for Southshore leaves from Menethil Harbor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98219-17add3bb30f9e4668473/1-0000.mp3", duration = 30.2236735, start = 0},
  },
}
P.transport["quest:98247"] = {
  hash = "128b95",
  fullHash = "128b95",
  text = "Shipping Label. A damaged Shipping Label leads you to the Azeroth Commerce Authority's trade hub at Three Corners in the Redridge Mountains. It marks a supply crate as the authority's property and shows where to report it. A damaged label marks a stocked supply crate as freight belonging to the Azeroth Commerce Authority. The destination and recipient are torn away. Anyone who finds the cargo can return it or report it to the authority's trade outpost in the Redridge Mountains. Beside the formal text, a rough map shows the roads toward the Three Corners intersection. At Three Corners, representatives of the Azeroth Commerce Authority enlist travelers as independent couriers. The authority asks no strict merchant contracts of its haulers. Instead, it runs an informal network and gives Merchant's Favor to couriers who recover missing cargo or complete abandoned deliveries along the highway.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98247-24c7ac99bde149a7190b/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:983"] = {
  hash = "fe006a",
  fullHash = "fe006a",
  text = "Buzzbox 827. Along Darkshore's coast, repairs are needed at Buzzbox 827. Wizbang Cranktoggle built it as the first link in a chain of voice relays, each made to use parts from local wildlife. Restoring it lets Wizbang test his network from Auberdine. In Auberdine, gnomish engineer Wizbang Cranktoggle is linking Darkshore's wild coast with a chain of voice relays called Buzzboxes. Their levers and gears carry speech across great distances, a sharp contrast with the ancient ruins and somber forests around them. The machines break down often, so each needs constant care to keep working. Buzzbox 827 lies on the shore just south of Auberdine. Wizbang built each relay to use parts from nearby wildlife, so repairs do not depend on carrying refined iron gears and copper pins through the wilderness. This unit takes the sturdy, jointed legs of local tide and reef crawlers. Put the legs in its receiver hopper, and the machine assembles itself and carries Wizbang's voice through its speakers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_983-73db1c8bf107a837436b/1-0000.mp3", duration = 63.5297959, start = 0},
  },
}
P.transport["quest:98386"] = {
  hash = "786626",
  fullHash = "786626",
  text = "Alther's Mill. At Alther's Mill, giant spiders have stopped the timber shipments Lakeshire needs for its bridge. Foreman Oslow is waiting for the lumber so the work can continue. Foreman Oslow is trying to keep Lakeshire's bridge repairs on schedule. Blackrock orcs, gnoll packs, and murlocs along Lake Everstill already strain his workforce. Now giant tarantulas have overrun Alther's Mill to the east, stopping the timber shipments the bridge needs. Greater tarantulas lurk among the timber stacks, leaving Alther's Mill useless. Foreman Oslow cannot risk sending laborers into their nest, so he hires capable adventurers to clear the spiders and destroy their egg clutches. He is irritated that Alther let the mill fall into disarray, but Lakeshire needs the lumber before the bridge work can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98386-a6579b17ba38b6398c6c/1-0000.mp3", duration = 50.5208163, start = 0},
  },
}
P.transport["quest:98389"] = {
  hash = "b6e8f7",
  fullHash = "b6e8f7",
  text = "A Light in the Darkness. In Deathknell, Aramis Hammerhand asks you to save newly raised Forsaken from Night's Web Hollow. Your aid may prove that those who wield the Holy Light stay loyal to Sylvanas and their people. Some Forsaken still wield the Holy Light they knew in life, though it pains their undead flesh. In Deathknell, Aramis Hammerhand and others hope to prove their faith has not set them against their own people. They use their gifts to protect the Forsaken and ease fears that they see their kin as monsters. Northwest of Deathknell, newly raised Forsaken wander into Night's Web Hollow, a dank cavern crawling with vicious spiders. Disoriented and unable to defend themselves, they become trapped in sticky webs. Saving them brings new recruits to the Dark Lady and may convince Executor Arren that wielders of the Light serve the Forsaken faithfully.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98389-aa8b013be30e8cae7a0c/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["quest:984"] = {
  hash = "341be9",
  fullHash = "341be9",
  text = "How Big a Threat?. In Auberdine, Terenthis asks scouts to learn whether furbolg corruption has reached Darkshore. Madness has taken hold among furbolgs in Teldrassil, and the night elf druid now sends them to inspect mainland settlements across the sea. Night elves across northern Kalimdor have long lived peacefully with the furbolg tribes. Since the Third War, strange corruption has unhinged furbolg minds in Teldrassil. They have kidnapped and attacked their former allies. Terenthis, the druid in Auberdine, fears the affliction has spread to mainland tribes along Darkshore’s coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_984-a06af7c31cdffbe5ab81/1-0000.mp3", duration = 35.8922449, start = 0},
  },
}
P.transport["quest:98407"] = {
  hash = "689e51",
  fullHash = "689e51",
  text = "Show of Force. Deputy Feldon sends you against gnoll packs closing on Lakeshire. The town's guards need proof that the thrashers have been beaten. Gnoll packs have grown bolder in the Redridge Mountains. Their camps now lie close to Lakeshire and the human homesteads beyond. Stormwind has too few soldiers for the borderlands, so local folk rely on travelers to hold the perimeter. The gnolls have not struck the town, but their camps bring them within reach of its homes. Deputy Feldon knows the gnolls respect strength above all. He sends you after their fiercest fighters, the gnoll thrashers, and asks you to bring back their spiked collars as proof. Lakeshire's defenders hope that breaking the front line and showing these trophies will frighten the surviving packs into retreating to the highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98407-b6a6bb958f342f9bd2a1/1-0000.mp3", duration = 46.9942857, start = 0},
  },
}
P.transport["quest:985"] = {
  hash = "7d9b58",
  fullHash = "7d9b58",
  text = "How Big a Threat?. In Darkshore, Terenthis sends you against the Blackwood furbolgs south of Auberdine. Their corrupted camp threatens the settlement, and the Sentinels seek to cull its pathfinders and windtalkers. The Sentinels see the Blackwood furbolgs as an immediate danger to Darkshore’s refugees and defenders. After you scout south of Auberdine, Terenthis sends you to strike their camp. Kill Blackwood Pathfinders and Windtalkers to hinder their attack before it reaches the settlement. Night elves have long counted furbolgs as spiritual kin and allies of the wilderness. Fel moss and demonic taint have spread across northern Kalimdor, driving the Blackwood tribe mad. No known remedy can restore their minds. So Auberdine’s defenders face a grim choice: stop the furbolgs before innocent people die.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_985-7c43f2639d79bcea7375/1-0000.mp3", duration = 49.0057143, start = 0},
  },
}
P.transport["quest:98576"] = {
  hash = "482ca6",
  fullHash = "482ca6",
  text = "Glyphic Parchment. In the Valley of Trials, Gornek sends young mages to Mai'ah for their first lessons. A runed notice points them to the mage near the Den, where their study of the arcane begins. New recruits face Durotar's local pests, but those drawn to magic need more than strength. Gornek gives them a notice marked with runes. It directs novice spellcasters to Mai'ah, who guides the Horde's newest recruits through their first lessons in magic. Just outside the Den, Mai'ah teaches young spellweavers to temper ambition with patience and thought. She urges them to choose their moment instead of casting raw sorcery without care. Her novices learn to weave delicate strands of the cosmos rather than unleash an unruly tempest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98576-33813fa49f843ee13863/1-0000.mp3", duration = 44.9306122, start = 0},
  },
}
P.transport["quest:98601"] = {
  hash = "598d24",
  fullHash = "598d24",
  text = "A Difficult Path. In Deathknell, a newly awakened Forsaken paladin begins training with the Light. After the undead outside the crypt are cleared, you go to the village church to meet Aramis Hammerhand and learn what holy power demands of the Forsaken. After you clear the feral undead outside the crypt, Shadow Priest Sarvis gives you an unexpected delivery. The Consecrated Scroll shines with holy energy, and Sarvis recoils before asking you to step aside. To one devoted to shadow and decay, the Holy Light burns like an open flame. Aramis Hammerhand waits in Deathknell’s desecrated church to train Forsaken paladins. Other races may wield the Light with ease and joy, but the undead endure searing agony when they call upon it. Aramis speaks plainly: channeling holy power through a rotting body is torment. He expects his disciples to face that pain instead of shrinking from it, and let it temper their resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98601-eac4b4e05b9c6afbe9d4/1-0000.mp3", duration = 57.0514286, start = 0},
  },
}
P.transport["quest:99"] = {
  hash = "61d5b5",
  fullHash = "61d5b5",
  text = "Arugal's Folly. In Pyrewood Village, Dalar Dawnweaver seeks the magic binding its people to a curse. He needs their enchanted shackles to study Archmage Arugal's work and understand their transformation into worgen. South of the Sepulcher, Pyrewood Village lives two lives. By day, its fearful and insular residents seem like ordinary human peasants. At twilight, their human forms break apart and become savage Moonrage worgen. Then they roam the streets under Arugal's sway. Dalar Dawnweaver seeks the arcane bindings behind this horror.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99-05103ce3bb3b53872c95/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["quest:990"] = {
  hash = "560380",
  fullHash = "560380",
  text = "Trek to Ashenvale. Sentinel Selarin sends travelers south from Auberdine into Ashenvale. In Astranaar, you report to Raene Wolfrunner as the Sentinels face spreading corruption. From Auberdine on Darkshore's somber gray coast, Sentinel Selarin calls you south to aid the night elf lands. Selarin trusts capable fighters and scouts to journey into Ashenvale's heart. With local threats in Darkshore handled, greater perils now demand attention. An ancient night elf road winds south beneath Ashenvale's dense canopy. Raene Wolfrunner leads the Sentinels in Astranaar and has urgently called for reinforcements. Demonic taints, rampant wildlife, and incursions from beyond ancestral lands have stretched the defenders thin. They need outside aid to hold the sacred forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_990-66e53688df1f1a8adb04/1-0000.mp3", duration = 49.6587755, start = 0},
  },
}
P.transport["quest:991"] = {
  hash = "593c7d",
  fullHash = "593c7d",
  text = "Raene's Cleansing. In Ashenvale, Raene Wolfrunner asks you to find Teronis in Raene's Cleansing. He set out toward Lake Falathim to recover a magic gemstone and find a way to halt the furbolgs' growing aggression. Raene Wolfrunner serves with the Sentinels in Astranaar, defending Ashenvale from mounting threats. Teronis was among her closest companions. He set out to find a strong defense against the furbolg tribes as they grew more violent. Days passed without his return, and Raene feared the worst while duty kept her at her post. Teronis followed rumors of a powerful rod forged by a wicked wizard who had died. He believed its magic could calm the furbolg fury. To restore the rod, he needed an enchanted gem hidden in an elven shrine at Lake Falathim, near the mountains to the west. Yet aggressive murloc tribes had recently taken the lake's once-tranquil waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_991-a1752a805eb6ca0e85c9/1-0000.mp3", duration = 53.8122449, start = 0},
  },
}
P.transport["quest:99134"] = {
  hash = "fc244b",
  fullHash = "fc244b",
  text = "Discipline. In Tirisfal Glades, Executor Zygand calls on outsiders to keep the Deathguard alert. He trusts his garrison little and orders punishment for sentries who slacken. The Deathguard guard the Forsaken across Lordaeron. Freedom from the Lich King's control has brought apathy, fatigue, and neglect. Yet the Scarlet Crusade and Scourge prowl Tirisfal's borders, so the garrison must stay ready. Executor Zygand has little patience for sentries who let their discipline slip. The officers use force and close oversight to keep their troops alert. Executor Zygand chooses outsiders to punish negligent Deathguards instead of using soldiers from his own garrison. With the Executor's Motivator, you remind the sentries that service to the Dark Lady demands constant vigilance. Even in undeath, they face the consequences of neglecting their duties.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99134-89f0654cbdc614e7c878/1-0000.mp3", duration = 53.9167347, start = 0},
  },
}
P.transport["quest:99141"] = {
  hash = "4f3e62",
  fullHash = "4f3e62",
  text = "Patience. In Tirisfal Glades, Executor Zygand waits for field reports that have not arrived. He sends you to find Deathguards near Brill and a sentry by Stillwater Pond. Executor Zygand commands security in Tirisfal Glades and permits no lapse in vigilance. He serves Lady Sylvanas and expects every duty to be done. When scheduled field reports fail to reach his post, he counts the delay as a breach of duty. He holds his place and sends Forsaken agents to find the tardy subordinates and keep the borders secure. Zygand's sentries around Brill owe him their reports. Deathguard Dillinger watches the graveyard west of town, where rogue undead and Scourge remnants stir. East of Brill, Deathguard Kristof guards a waystation on the approaches to the Capital City and the eastern roads. Gordo is the strangest sentry: a hulking abomination who wanders near Stillwater Pond, where military record-keeping seems beyond his simple mind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99141-0b4a8d3884d9a427d2ea/1-0000.mp3", duration = 60.1861224, start = 0},
  },
}
P.transport["quest:99142"] = {
  hash = "7b1d83",
  fullHash = "7b1d83",
  text = "Tomb Weed. At Balnir Farmstead, Holland's altered doom weed has drawn the Scourge. The crop now bears the name tomb weed, and Holland wants it for his experiments. Junior Apothecary Holland seeks more than a place in the Royal Apothecary Society. He gathers doom weed, alters it through alchemy, then plants it again in Balnir Farmstead's soil. From that work comes a new strain: tomb weed. Holland sees it as the heart of his experiments and a path to the future he wants for himself. Holland expected his altered plants to grow stronger in alchemical use. Instead, the Scourge wandering Balnir Farmstead have taken an interest in them. Now he relies on travelers to get past the undead and gather the mature crop, so his experiments can go on.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99142-121917bf1ffa3c9d0d41/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["quest:99156"] = {
  hash = "a4456a",
  fullHash = "a4456a",
  text = "Rear Guard Patrol. In Tirisfal Glades, Deathguard Linnea calls the patrollers to defend the border. She sends them after Riptear, an abomination roaming near Venomweb Vale that should never have passed the Bulwark. The Bulwark is the only fortified barrier between Tirisfal Glades and the horrors of the Western Plaguelands. Forsaken strategy depends on holding one front. If mindless undead slip behind the lines, they can choke the supply routes that feed it. Spirits and ghouls sometimes get past the barricades, but an abomination roaming the glades means containment has failed badly.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99156-7a8869e7b4b40c35e52b/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["quest:997"] = {
  hash = "e429fa",
  fullHash = "e429fa",
  text = "Denalan's Earth. In Dolanaar, Syral Bladeleaf seeks a courier for rare earth bound south to Denalan at Lake Al'Ameth. The night elf researcher studies Teldrassil's young plants. In Dolanaar, Syral Bladeleaf has a shipment of rare earth for Denalan. The soil came from Darnassus to aid his botanical studies, but delays held it back. Now Syral seeks a courier to carry it south along the forest trail to Denalan's campsite by Lake Al'Ameth. At a station on Lake Al'Ameth's eastern shore, Denalan works alone and watches Teldrassil's young ecosystem take root. The tree grew quickly after the Battle of Mount Hyjal, and its plants behave in unexpected ways.\n\nDenalan tests the vitality and behavior of timberlings and native plants with unique soil mixtures and specimens. The rare earth shipment will support those experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_997-d805a386be1aa43b1d46/1-0000.mp3", duration = 53.3159184, start = 0},
  },
}
P.transport["quest:cutting-teeth"] = {
  hash = "f8e0b6",
  fullHash = "f8e0b6",
  text = "Cutting Teeth. In the Valley of Trials, fresh recruits face their first test against mottled boars. Overseer Gornek sends warriors and spellcasters to thin the herds around the cactus dirt farms and prove they can fight for the Horde. Young recruits may dream of hunting great beasts in the Barrens or winning glory on a battlefield. Overseer Gornek starts them at the farms instead. Thinning the mottled boars tests their first skill with a weapon or spell. It shows whether they can face a wild attacker and survive their first skirmish. Feral swine roam the dirt farms north and northeast of camp. They root through cactus patches and threaten the few supplies grown in Durotar’s harsh soil. Clearing them keeps local pests in check. It also shapes young orcs and trolls into defenders of their new nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_cutting-teeth-42844df8c1214f6ac2a3/1-0000.mp3", duration = 47.4906122, start = 0},
  },
}
P.transport["quest:galgar-s-cactus-apple-surprise"] = {
  hash = "85291e",
  fullHash = "85291e",
  text = "Galgar's Cactus Apple Surprise. In the Valley of Trials, Galgar sends new recruits to gather cactus apples for a cooling treat. Foraging helps them learn to live in Durotar's dry land. Young orcs and Darkspear trolls begin their work as defenders of the Horde in the Valley of Trials. Combat drills and fierce trials against native beasts leave them tired and thirsty. Learning to live off the land matters as much as learning to swing an axe. Across the valley, cacti bear ripe apples rich with water, a welcome relief from the desert sun. Galgar cooks in the training grounds and knows how to forage. His Cactus Apple Surprise is said to cool a person faster than a plunge into river water. He sends eager recruits to gather prickly fruit from nearby cacti. That keeps his kitchen stocked and ensures new wanderers do not set out into Durotar hungry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_galgar-s-cactus-apple-surprise-c91b21e018c6fd0598a9/1-0000.mp3", duration = 49.9722449, start = 0},
  },
}
P.transport["quest:lazy-peons"] = {
  hash = "fb0e65",
  fullHash = "fb0e65",
  text = "Lazy Peons. Foreman Thazz'ril sends new Horde recruits across the Valley of Trials to rouse sleeping peons. Their labor keeps timber moving to Durotar's settlements. Durotar's new homes need timber, stone, and hard labor. Peons have little skill in battle, so they carry much of that burden and keep the Horde supplied with workers. In the Valley of Trials, heat and grueling work drive Foreman Thazz'ril's crews beneath the trees for unauthorized naps. Foreman Thazz'ril gives new Horde recruits his blackjack and sends them across the valley to wake the sleeping workers. Startled, the peons return to chopping wood. Their labor keeps lumber flowing for Durotar's survival.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_lazy-peons-42434482c19d298dc27c/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:sarkoth"] = {
  hash = "80323b",
  fullHash = "80323b",
  text = "Sarkoth. On a southern plateau in the Valley of Trials, Sarkoth has left a young Darkspear hunter near death. Beneath a tree, Hana'zua asks a passing warrior to kill the scorpid and bring back its mangled claw, so his last strike will count for something. The Valley of Trials puts aspiring Horde warriors against Durotar's harsh desert. While hunting its venomous creatures, young troll scout Hana'zua met a scorpid far larger and deadlier than the rest. He struck hard enough to mangle one pincer. Then Sarkoth drove its tail into his chest. Now Hana'zua bleeds in the red dirt and fears his life is near its end. He wants the beast dead before it outlives him. Sarkoth roams a high mesa above the southern Valley of Trials. Hana'zua shattered one claw, but the scorpid still rules the ridge and attacks anyone climbing the rocky path. Bring the scarred claw back to the wounded scout. Then he will know his last strike weakened the monster enough for someone to bring it down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_sarkoth-c0aab6ea207bbdb82dab/1-0000.mp3", duration = 60.1077551, start = 0},
  },
}
P.transport["quest:your-place-in-the-world"] = {
  hash = "c5581b",
  fullHash = "c5581b",
  text = "Your Place In The World. Kaltunk sends new recruits in the Valley of Trials to Gornek for training. There, young orcs and Darkspear trolls begin their service to the Horde and learn what honor and survival demand in Durotar. Young orcs and Darkspear trolls prove their worth in Durotar's arid Valley of Trials before they enter the wider world. Under Warchief Thrall, life demands strength, vigilance, and discipline. Kaltunk tests each eager recruit and turns their dreams of wrestling demons and dragons toward the practical duties ahead. In the canyon, training begins with humility before glory. Gornek waits beside the camp fire, only steps from Kaltunk. The gruff veteran regards fresh arrivals with a skeptical eye and grumbles about the meager stock reaching camp. He hardens young fighters through trials, beginning with the vermin that threaten the encampment's supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_your-place-in-the-world-9f6c4b5b6e39b572342c/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
